INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105724, 'user2', 'f668be5f-112f-4d11-b2a6-35c0538e7fdd', 'Hi there, sir! How are you today?', 990328529359, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105725, 'user1', 'f668be5f-112f-4d11-b2a6-35c0538e7fdd', 'Hello! I am good.', 990328532935, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105726, 'user1', 'f668be5f-112f-4d11-b2a6-35c0538e7fdd', 'Thank you. I have two brothers, one whom I don''t speak to very much anymore. I don''t know if he has any health problems. My other brother is healthy with no issues. Both my uncles on my mother''s side had polio, I think.', 990328558711, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105727, 'user2', 'f668be5f-112f-4d11-b2a6-35c0538e7fdd', 'Tell me more about your uncles with polio. They both had polio?', 990328564562, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105728, 'user1', 'f668be5f-112f-4d11-b2a6-35c0538e7fdd', 'One of them had to wear crutches due to how bad his leg deformans were and then the other had leg deformities in only one leg.  I am fairly certain that they had polio.', 990328549450, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105729, 'user2', 'f668be5f-112f-4d11-b2a6-35c0538e7fdd', 'Do you know of any other family member with neurological conditions?', 990328551411, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105730, 'user1', 'f668be5f-112f-4d11-b2a6-35c0538e7fdd', 'No. None that I know of.', 990328558182, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105731, 'user2', 'f668be5f-112f-4d11-b2a6-35c0538e7fdd', 'Do you have any children?', 990328557393, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105732, 'user1', 'f668be5f-112f-4d11-b2a6-35c0538e7fdd', 'Yes. I have one child.', 990328573503, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105733, 'user2', 'f668be5f-112f-4d11-b2a6-35c0538e7fdd', 'Is your child healthy and well?', 990328597688, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105734, 'user1', 'f668be5f-112f-4d11-b2a6-35c0538e7fdd', 'Yes.', 990328551933, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105735, 'user1', 'f668be5f-112f-4d11-b2a6-35c0538e7fdd', 'My mother and father both had heart disease. Well, my mother had complication from her heart disease and that is how she passed.  My father was only in his forty''s when he died.', 990328545797, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105736, 'user2', 'f668be5f-112f-4d11-b2a6-35c0538e7fdd', 'I am so sorry the hear that.', 990328546559, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105737, 'user2', 'f668be5f-112f-4d11-b2a6-35c0538e7fdd', 'I would like to start with your family medical history today. What do you know about their medical history?', 990328540280, 2);
