INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105739, 'user1', 'c57e02c3-6ab3-4501-9ca9-7fd26947723b', 'Sure, my brother has a prostate cancer.', 1383723436638, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105740, 'user1', 'c57e02c3-6ab3-4501-9ca9-7fd26947723b', 'Then on both sides of my family there are many heart related issues.', 1383723445524, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105741, 'user2', 'c57e02c3-6ab3-4501-9ca9-7fd26947723b', 'Okay.', 1383723468538, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105742, 'user1', 'c57e02c3-6ab3-4501-9ca9-7fd26947723b', 'And my brother and sister both have diabetes.', 1383723464698, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105743, 'user2', 'c57e02c3-6ab3-4501-9ca9-7fd26947723b', 'Okay.', 1383723472539, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105744, 'user1', 'c57e02c3-6ab3-4501-9ca9-7fd26947723b', 'Yes, that''s it.', 1383723476992, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105745, 'user1', 'c57e02c3-6ab3-4501-9ca9-7fd26947723b', 'My father had brain cancer.', 1383723450199, 3);
