INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105748, 'user2', '05b98fa9-008c-43d7-8aa8-bde697fca675', 'Good afternoon, ma''am. Welcome to A B C D General Hospital. Before we begin, I just need to confirm some background information on you.', 1694315275389, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105749, 'user2', '05b98fa9-008c-43d7-8aa8-bde697fca675', 'First, how old are you?', 1694315284093, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105750, 'user1', '05b98fa9-008c-43d7-8aa8-bde697fca675', 'Yes, sir, that''s correct.', 1694315304990, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105751, 'user2', '05b98fa9-008c-43d7-8aa8-bde697fca675', 'Great, what seems to be problem today, ma''am?', 1694315299746, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105752, 'user1', '05b98fa9-008c-43d7-8aa8-bde697fca675', 'I''ve had this bunion on my foot for such a long time.', 1694315292413, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105753, 'user2', '05b98fa9-008c-43d7-8aa8-bde697fca675', 'How long has this bunion been present?', 1694315298043, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105754, 'user1', '05b98fa9-008c-43d7-8aa8-bde697fca675', 'At this point, um, I don''t even remember how long it''s been.', 1694315290954, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105755, 'user2', '05b98fa9-008c-43d7-8aa8-bde697fca675', 'Do you have any other conditions that I should be aware of?', 1694315299033, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105756, 'user1', '05b98fa9-008c-43d7-8aa8-bde697fca675', 'Actually, yes. I have a history of, um, Charcot Marie tooth disease.', 1694315336832, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105757, 'user2', '05b98fa9-008c-43d7-8aa8-bde697fca675', 'That''s good to know, thank you.', 1694315317340, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105758, 'user1', '05b98fa9-008c-43d7-8aa8-bde697fca675', 'I would like to have surgery to cut this bunion off, I can''t take it anymore.', 1694315301004, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105759, 'user1', '05b98fa9-008c-43d7-8aa8-bde697fca675', 'Good afternoon, doctor. Absolutely, that''s no problem.', 1694315279214, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105760, 'user2', '05b98fa9-008c-43d7-8aa8-bde697fca675', 'Good, and your chart says you identify as Caucasian. Is that correct?', 1694315283037, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105761, 'user1', '05b98fa9-008c-43d7-8aa8-bde697fca675', 'I''m nineteen, sir.', 1694315292728, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105762, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'I hear someone has a birthday coming up, how old are you turning, ma''am?', 1415091392718, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105763, 'user1', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'I''ll be ninety later this month, doctor.', 1415091396849, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105764, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'You''re here for a follow up not very long after your first visit. What seems to be the problem today?', 1415091404576, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105765, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'How did you tolerate the higher dose?', 1415091414037, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105766, 'user1', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'I didn''t feel well at all, so I just went back to the old dose.', 1415091415617, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105767, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'That was one M G per day, correct?', 1415091434973, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105768, 'user1', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'Yes, doctor. I do think I could have some white coat high blood pressure. Doctors'' offices make me nervous.', 1415091432095, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105769, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'That does happen. Here, try this sample of Tarka, please.', 1415091425302, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105770, 'user1', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'What is this for, doctor?', 1415091444033, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105771, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'Well, since you''re taking the Mavik plus verapamil, you can switch over to Tarka, which is the combined version of the two drugs.', 1415091413358, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105772, 'user1', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'I can''t take these, doctor. They''re too big.', 1415091442975, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105773, 'user1', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'Hello doctor, I''m her daughter. Just so you know, we check her blood pressure at home periodically and it''s always similar to that reading.', 1415091473795, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105774, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'Good, so back to that right arm, how is that doing today?', 1415091478584, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105775, 'user1', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'Well, that pain is basically gone now, I think it had to do with that muscle problem back in my right shoulder blade.', 1415091467470, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105776, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'Did you have x rays taken today?', 1415091427985, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105777, 'user1', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'Yes, the tech brought me back right before you came in.', 1415091478907, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105778, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'Good, I have the images right here.', 1415091482961, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105779, 'user1', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'What do they show, doctor?', 1415091489110, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105780, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'Well, these x rays of the neck and right shoulder show some degenerative changes, and possibly some kind of rotator cuff injury.', 1415091496448, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105781, 'user1', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'What makes you think there''s an injury?', 1415091491146, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105782, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'Well, look right here. The humeral head is pretty high in the glenoid in the right shoulder, but do you have any pain here?', 1415091522414, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105783, 'user1', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'No, none.', 1415091443939, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105784, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'Then we won''t worry about it.', 1415091451495, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105785, 'user1', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'I am having this stomach pain though, doctor.', 1415091449337, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105786, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'How has this pain developed and progressed recently?', 1415091527583, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105787, 'user1', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'Well, it''s improved somewhat with me not taking Aleve anymore.', 1415091498452, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105788, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'What medicines are you taking right now, then?', 1415091513401, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105789, 'user1', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'Right know, I''m just taking Tylenol as needed. That seems to be enough for me.', 1415091546826, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105790, 'user2', 'ce8825e8-6b93-4542-98db-5b6ff1fbedda', 'Do you think this could be acid reflux, or heartburn?', 1415091498066, 31);
