INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105988, 'user1', '7b502a41-e307-4509-88e6-5be2b99abe93', 'I used to smoke a pack a day.  I quit that awful habit in nineteen eighty five.', 1410632355197, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105989, 'user1', '7b502a41-e307-4509-88e6-5be2b99abe93', 'Yes. We both are. I cannot imagine working a full time job at seventy six years old.', 1410632372768, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105990, 'user1', '7b502a41-e307-4509-88e6-5be2b99abe93', 'I am retired.', 1410632365605, 3);
