INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105993, 'user3', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'Hi there, how are you?', 973408661930, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105994, 'user1', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'I am okay.', 973408666312, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105995, 'user3', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'So, I see you turned eighty-eight yesterday, happy birthday!', 973408668308, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105996, 'user3', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'Hm he mentioned that it''s chronic lymphocytic leukemia.', 973408669168, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105997, 'user1', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'Yes.', 973408691024, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105998, 'user3', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'Okay.', 973408699216, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (105999, 'user3', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'And you are also seeing Doctor Z for your heart related problems.', 973408689935, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106000, 'user1', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'That is correct.', 973408712609, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106001, 'user3', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'So, tell me what is happening with you?', 973408695212, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106002, 'user1', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'For the past one week I am having this increased shortness of breath and having difficulty breathing from past few nights while sleeping.', 973408720194, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106003, 'user1', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'Correct! I am also seeing Doctor Y for my leukemia.', 973408680106, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106004, 'user1', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'And this morning I was having difficulty catching my breath. I am also having wheezing since morning.', 973408696680, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106005, 'user3', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'Let me examine you, can you come forward and sit-up here? Any chest discomfort or acute chest pain or anything of that sort? Any pain of the left arm?', 973408705866, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106006, 'user1', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'No.', 973408697868, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106007, 'user3', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'Any dizziness, feeling like fainting or light headedness or losing control?', 973408736757, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106008, 'user1', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'No.', 973408705435, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106009, 'user3', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'Well, I don''t think there is any sign of cardiovascular accident or heart attack, so that''s that. You do have mild peripheral edema. We need to treat that.', 973408759977, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106010, 'user1', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'Okay.', 973408780065, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106011, 'user3', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'Okay.', 973408731147, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106012, 'user1', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'Thank you!', 973408668130, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106013, 'user3', 'd2033c00-08ce-4bd4-bf30-fd7df1c470bd', 'And you are referred by Doctor X, he is your primary physician, right?', 973408681749, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106014, 'user2', 'a9cd3a33-2129-4d7c-9d3d-6ddc7de4a78b', 'Ready to go home?', 1722445554297, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106015, 'user1', 'a9cd3a33-2129-4d7c-9d3d-6ddc7de4a78b', 'I just can''t wait.', 1722445555485, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106016, 'user2', 'a9cd3a33-2129-4d7c-9d3d-6ddc7de4a78b', 'Sure. I can understand.', 1722445560196, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106017, 'user1', 'a9cd3a33-2129-4d7c-9d3d-6ddc7de4a78b', 'Bye Doctor.', 1722445571681, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106018, 'user2', 'a9cd3a33-2129-4d7c-9d3d-6ddc7de4a78b', 'Yes. See you soon.', 1722445564632, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106019, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Hello, sir. How are you today? Can you confirm your age?', 1267465256129, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106020, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Fifty eight. I feel like my balance is off, and I''ve been feeling tired and weak.', 1267465259397, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106021, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'I haven''t, but this might not be related. I had pneumonia ten days before this all started.', 1267465279045, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106022, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Interesting. Did you take any medication for that?', 1267465275319, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106023, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'I did, but I don''t know how to pronounce it. I wrote it down for you to read. Here it is.', 1267465266634, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106024, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Let me take a look. I see you took a full course of amoxicillin, right?', 1267465285676, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106025, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Yeah, that''s right.', 1267465279603, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106026, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'How did you feel after you finished the antibiotics?', 1267465311681, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106027, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Terrible. I felt like I couldn''t control my body. My balance got even worse, and I felt even more tired and weak.', 1267465301180, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106028, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Oh, wow. Do you know why your balance and coordination worsened?', 1267465287754, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106029, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'I did fall recently, but I know for a fact my balance was off before my fall.', 1267465309516, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106030, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'How high were you when you fell?', 1267465282682, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106031, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'I think I was three or five feet high when I fell.', 1267465334342, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106032, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Did you fall on your back?', 1267465312837, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106033, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'No, I fell on my feet. Just kidding, I fell on my back.', 1267465273556, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106034, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Funny. Did anything hurt after your fall?', 1267465287099, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106035, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Not really, but I''ve been having some back pain in my lower and mid back.', 1267465278949, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106036, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Did you always have that pain?', 1267465320202, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106037, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'No, I haven''t. It comes and goes.', 1267465370332, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106038, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'I started to see a chiropractor like five days ago. He adjusts my neck and lower back.', 1267465326267, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106039, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Have you done anything to treat it?', 1267465373371, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106040, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'I see. Did you start having problems with your balance after this?', 1267465391037, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106041, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'No. I was still having problems with that before I saw the chiropractor.', 1267465370002, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106042, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Okay. So, it wasn''t the result of the adjustments. Is there anything else that may have caused it?', 1267465334453, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106043, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'I was taking this other medicine for ten days, but I don''t remember what it was for. Here is the name of the medication. I wrote it on another paper.', 1267465283634, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106044, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'It looks like you took Cipro. This is usually used to treat a U T I. Were you aware you had a U T I?', 1267465361978, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106045, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Oh, yeah. I forgot about that. I thought I had one, so I went to another doctor to get some medication.', 1267465344789, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106046, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'I see. I have one more question. Do you have any trouble controlling your bowel movements or attempting to go to the bathroom?', 1267465412387, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106047, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'Nope. I feel like I''m able to go to the bathroom whenever I want.', 1267465428460, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106048, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'How long have you been experiencing this?', 1267465267610, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106049, 'user1', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'It''s been going on for six to eight weeks.', 1267465266014, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106050, 'user2', '0f423890-1b1a-4430-ba24-d8f996e36f8b', 'I see. Did you feel any other symptoms?', 1267465269104, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106051, 'user2', '8176405e-2a1b-4f3b-ab07-0d169e961562', 'Have you had any illnesses in the past?', 1208568230515, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106052, 'user1', '8176405e-2a1b-4f3b-ab07-0d169e961562', 'Nope.', 1208568232854, 1);
