INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106056, 'user2', '8176405e-2a1b-4f3b-ab07-0d169e961562', 'Anything that is worth mentioning?', 1208568233678, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106057, 'user2', '327d24e7-02b1-4836-97ff-dfdf1345051a', 'Good afternoon, sir. My nurse tells me you''re twenty eight years old, is that correct?', 1689915264709, 0);
