INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106094, 'user2', 'ae47fb48-7428-4e0b-9a95-282ede57cc89', 'How did the patient do on the activity test?', 1004818641716, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106095, 'user2', 'ae47fb48-7428-4e0b-9a95-282ede57cc89', 'Patient was good. I have advised him to continue with his normal activities as long as he is feeling fine.', 1004818646634, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106096, 'user2', '1e5e3ac1-6e8c-43c5-a662-2eb80211a20e', 'How old was he when he were first evaluated in the other hospital?', 1451466022951, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106097, 'user2', '1e5e3ac1-6e8c-43c5-a662-2eb80211a20e', 'So what exactly happened?', 1451466046434, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106098, 'user2', '1e5e3ac1-6e8c-43c5-a662-2eb80211a20e', 'Which hospital was that again?', 1451466028522, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106099, 'user2', '1e5e3ac1-6e8c-43c5-a662-2eb80211a20e', 'Did the intensity change?', 1451466044984, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106100, 'user1', '1e5e3ac1-6e8c-43c5-a662-2eb80211a20e', 'Oh yes. This, these spells, they became more frequent, and they were now for longer periods. By the time we came for the first evaluation, they were like two to three times per day.', 1451466034983, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106101, 'user2', '1e5e3ac1-6e8c-43c5-a662-2eb80211a20e', 'How long were they in the duration?', 1451466063237, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106102, 'user1', '1e5e3ac1-6e8c-43c5-a662-2eb80211a20e', 'They lasted for like two to three minutes.', 1451466039565, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106103, 'user2', '1e5e3ac1-6e8c-43c5-a662-2eb80211a20e', 'Was there any other associated disorder or anything?', 1451466044253, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106104, 'user1', '1e5e3ac1-6e8c-43c5-a662-2eb80211a20e', 'Yeah, around three months before his evaluation his hands, they started becoming stressed, like stiffer and felt tighter during these spells. He also felt very weak and tired after these episodes.', 1451466074852, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106105, 'user1', '1e5e3ac1-6e8c-43c5-a662-2eb80211a20e', 'He was doing all good like seven months before his evaluation, then he started having some dizzy spells, which like stayed for several seconds to a minute. They were not regular, but he was able to continue his activity immediately after these dizzy spells.', 1451466029883, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106106, 'user1', '1e5e3ac1-6e8c-43c5-a662-2eb80211a20e', 'It was at U I H C.', 1451466037580, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106107, 'user1', '1e5e3ac1-6e8c-43c5-a662-2eb80211a20e', 'He was seven.', 1451466028946, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106108, 'user3', '069cfd97-d02a-4a59-a69d-9924862891a6', 'Do you have major illnesses in the family like diabetes or high B P?', 1173364818744, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106109, 'user1', '069cfd97-d02a-4a59-a69d-9924862891a6', 'No nothing. No major illnesses.', 1173364824292, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106110, 'user3', '069cfd97-d02a-4a59-a69d-9924862891a6', 'Okay.', 1173364830221, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106111, 'user1', '069cfd97-d02a-4a59-a69d-9924862891a6', 'Yes.', 1173364822779, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106112, 'user2', '42b440a2-950c-4a62-8852-56fd4b2ad205', 'Good morning, sir.', 1411992281779, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106113, 'user1', '42b440a2-950c-4a62-8852-56fd4b2ad205', 'Good morning, doctor.', 1411992286891, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106114, 'user1', '42b440a2-950c-4a62-8852-56fd4b2ad205', 'Yeah, actually I''ve had it on my knee, a nose job, and, um, carotid sinus surgery.', 1411992295218, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106115, 'user1', '42b440a2-950c-4a62-8852-56fd4b2ad205', 'Sure.', 1411992289238, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106116, 'user2', '42b440a2-950c-4a62-8852-56fd4b2ad205', 'Good, have you ever had surgery, sir?', 1411992305439, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106117, 'user2', '42b440a2-950c-4a62-8852-56fd4b2ad205', 'I just need some background information before we begin today.', 1411992292283, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106118, 'user2', '993ecd53-25a5-455f-9866-2fac96587559', 'Are you still working?', 949187054001, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106119, 'user1', '993ecd53-25a5-455f-9866-2fac96587559', 'No, I am retired now. I used to work for the U S postal service as an electronic technician but took retirement one year earlier due to my disability.', 949187055094, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106120, 'user2', '993ecd53-25a5-455f-9866-2fac96587559', 'Ah okay. And who is in your family?', 949187063009, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106121, 'user2', '993ecd53-25a5-455f-9866-2fac96587559', 'How about alcohol?', 949187071947, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106122, 'user1', '993ecd53-25a5-455f-9866-2fac96587559', 'I use to drink occasionally, that too very rare, but after my symptoms stated I stopped completely.', 949187072286, 7);
