INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106126, 'user1', '993ecd53-25a5-455f-9866-2fac96587559', 'No, it''s been really long since I traveled anywhere.', 949187101925, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106127, 'user1', '993ecd53-25a5-455f-9866-2fac96587559', 'No.', 949187076609, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106128, 'user1', '993ecd53-25a5-455f-9866-2fac96587559', 'Well, I stay with my wife and daughter in our apartment.', 949187066572, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106129, 'user2', '993ecd53-25a5-455f-9866-2fac96587559', 'Okay. Do you smoke?', 949187073588, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106130, 'user2', '7ac395eb-9f29-4c47-bde0-7ec3263fab83', 'Good afternoon, how are you today?', 1470231964928, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106131, 'user2', '7ac395eb-9f29-4c47-bde0-7ec3263fab83', 'Thank you.', 1470231973339, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106132, 'user2', '7ac395eb-9f29-4c47-bde0-7ec3263fab83', 'This is my colleague Doctor White, and she will be taking the notes. Is it okay if she joins us?', 1470231975797, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106133, 'user1', '7ac395eb-9f29-4c47-bde0-7ec3263fab83', 'Nice to meet you too.', 1470231997484, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106134, 'user2', '7ac395eb-9f29-4c47-bde0-7ec3263fab83', 'Okay, can you breathe in and out for me? Deep breaths please.', 1470231977260, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106135, 'user1', '7ac395eb-9f29-4c47-bde0-7ec3263fab83', 'Okay.', 1470231997955, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106136, 'user2', '7ac395eb-9f29-4c47-bde0-7ec3263fab83', 'Okay breath sounds are clear. Lung function looks good. Symmetrical rise and fall in chest as patient breathes. I am going to palpate your chest, it''s just a routine exam.', 1470231979516, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106137, 'user1', '7ac395eb-9f29-4c47-bde0-7ec3263fab83', 'Sure.', 1470232001103, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106138, 'user2', '7ac395eb-9f29-4c47-bde0-7ec3263fab83', 'Doctor White can you make a note, no egophony or tactile fremitus.', 1470231992427, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106139, 'user2', '7ac395eb-9f29-4c47-bde0-7ec3263fab83', 'Sure.', 1470232011715, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106140, 'user2', '7ac395eb-9f29-4c47-bde0-7ec3263fab83', 'Hello, I am Doctor White, nice to meet you.', 1470231979775, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106141, 'user1', '7ac395eb-9f29-4c47-bde0-7ec3263fab83', 'Oh sure, no problem.', 1470231968285, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106142, 'user1', '7ac395eb-9f29-4c47-bde0-7ec3263fab83', 'I am good Doctor, thanks for asking.', 1470231968704, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106143, 'user2', '7b51815f-0370-488b-aa98-448af47dbec6', 'Where do you live?', 1169749256558, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106144, 'user1', '7b51815f-0370-488b-aa98-448af47dbec6', 'I live in a board and care. It is a nice small care home with some very nice and supportive people. It is just next to the Safeway on Village Drive.', 1169749260550, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106145, 'user1', '7b51815f-0370-488b-aa98-448af47dbec6', 'No Sir.', 1169749270657, 5);
