INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106147, 'user1', '7b51815f-0370-488b-aa98-448af47dbec6', 'Never in my life.', 1169749285414, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106148, 'user2', '7b51815f-0370-488b-aa98-448af47dbec6', 'Did you ever try any kind of illicit drugs? Any I V drugs?', 1169749270835, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106149, 'user1', '7b51815f-0370-488b-aa98-448af47dbec6', 'No. I have always kept myself away from all those things.', 1169749273418, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106150, 'user1', '7b51815f-0370-488b-aa98-448af47dbec6', 'Oh yes. I feel very relaxed there.', 1169749260052, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106151, 'user2', '7b51815f-0370-488b-aa98-448af47dbec6', 'Did you consume alcohol in any way?', 1169749267249, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106152, 'user2', '7b51815f-0370-488b-aa98-448af47dbec6', 'Nice. It looks like you love living there.', 1169749263021, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106153, 'user2', 'd3522db6-965b-4c3c-858d-17c3c498c874', 'Have you had any surgeries in the past?', 1447809561785, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106154, 'user1', 'd3522db6-965b-4c3c-858d-17c3c498c874', 'Actually, yes, I had my gallbladder removed in nineteen ninety two.', 1447809564634, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106155, 'user2', 'd3522db6-965b-4c3c-858d-17c3c498c874', 'Great, any other surgeries? Think back a little further?', 1447809569673, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106156, 'user1', 'd3522db6-965b-4c3c-858d-17c3c498c874', 'Oh yeah, I had my appendix out in nineteen eighty eight.', 1447809573915, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106157, 'user3', '9b6491b1-b6a6-4d4b-b837-7bf478dbe498', 'How are feeling now after the treatment?', 1478855137892, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106158, 'user1', '9b6491b1-b6a6-4d4b-b837-7bf478dbe498', 'I am feeling pretty fair, improving slowly.', 1478855141687, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106159, 'user3', '9b6491b1-b6a6-4d4b-b837-7bf478dbe498', 'Okay?', 1478855147073, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106160, 'user1', '9b6491b1-b6a6-4d4b-b837-7bf478dbe498', 'Okay.', 1478855147523, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106161, 'user3', '6c8add9c-71ac-4035-a7ed-c508650427cf', 'Sir? Can you hear me? Are you Mister Smith''s wife?', 1416550072874, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106162, 'user1', '6c8add9c-71ac-4035-a7ed-c508650427cf', 'Yes. I am his wife.', 1416550076158, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106163, 'user1', '6c8add9c-71ac-4035-a7ed-c508650427cf', 'He fell off his wheelchair.', 1416550080465, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106164, 'user3', '6c8add9c-71ac-4035-a7ed-c508650427cf', 'The Adult Protective Services said they found your husband in the home barley conscious. How long had he been that way?', 1416550085289, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106165, 'user1', '6c8add9c-71ac-4035-a7ed-c508650427cf', 'All day.', 1416550106651, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106166, 'user3', '6c8add9c-71ac-4035-a7ed-c508650427cf', 'Do you know what other medications your husband has taken other than the Xanax?', 1416550083369, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106167, 'user1', '6c8add9c-71ac-4035-a7ed-c508650427cf', 'He didn''t take his regular medications for two days.', 1416550122233, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106168, 'user1', '6c8add9c-71ac-4035-a7ed-c508650427cf', 'He is eighty five. He took the entire M G of Xanax. He is only supposed to take point one twenty five M G of Xanax.  That is why he is like this.', 1416550084329, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106169, 'user3', '6c8add9c-71ac-4035-a7ed-c508650427cf', 'It looks like your husband was admitted to the emergency room the night before.  How did these injuries to his face happen?', 1416550080491, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106170, 'user3', '6c8add9c-71ac-4035-a7ed-c508650427cf', 'How old is he? Can you tell me a little bit of how your husband''s condition has come to this point? His level of consciousness is concerning.', 1416550077763, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106171, 'user2', '52b609a3-835f-4ea8-a631-fa047ee987c3', 'How have you been feeling? Is the Wellbutrin keeping your mood stabilized?', 1404758666318, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106172, 'user1', '52b609a3-835f-4ea8-a631-fa047ee987c3', 'I have been feeling good. The Wellbutrin is working well for me.', 1404758667595, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106173, 'user2', '52b609a3-835f-4ea8-a631-fa047ee987c3', 'It is important to not consume any alcohol or recreational drugs while taking Wellbutrin.', 1404758674294, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106174, 'user1', '52b609a3-835f-4ea8-a631-fa047ee987c3', 'I don''t drink or do drugs.', 1404758683258, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106175, 'user2', '19914e6b-cdb8-46fa-9a13-66bd2f6c593c', 'Tell me a little bit about your family history.', 1622757569945, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106176, 'user2', '19914e6b-cdb8-46fa-9a13-66bd2f6c593c', 'How about cancer?', 1622757577527, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106177, 'user1', '19914e6b-cdb8-46fa-9a13-66bd2f6c593c', 'Two of my cousins had breast cancer.', 1622757591100, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106178, 'user1', '19914e6b-cdb8-46fa-9a13-66bd2f6c593c', 'No.', 1622757573924, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106179, 'user1', '19914e6b-cdb8-46fa-9a13-66bd2f6c593c', 'My dad and grandpa both had type two diabetes. My son is struggling with type one diabetes at the moment.', 1622757573075, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106180, 'user2', '19914e6b-cdb8-46fa-9a13-66bd2f6c593c', 'I''m sorry to hear that. Does anyone in your family have heart problems?', 1622757579089, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106181, 'user3', 'c97d43b4-6222-4bdb-a329-92cdc864f8a9', 'Where do you work, miss?', 1237142225729, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106182, 'user1', 'c97d43b4-6222-4bdb-a329-92cdc864f8a9', 'Well, you see, I am a civil engineer. Right now, due to pandemic like everyone else I am working from home.', 1237142229663, 1);
