INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106202, 'user2', '8d1a1fb9-a022-40fb-ae7e-4af41d3a5544', 'How is the home exercise program going?', 1405093256530, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106203, 'user1', '8d1a1fb9-a022-40fb-ae7e-4af41d3a5544', 'I am loving pool therapy. I really feel like that is helping. I do the home exercises sometimes twice a day. I really want to get back to normal.', 1405093263152, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106204, 'user1', '8d1a1fb9-a022-40fb-ae7e-4af41d3a5544', 'Yes. I am quite happy that I can do my daily activities. I can get up with minimal assistance and do many activities out of the house. I think I am gaining muscle from moving around more too.', 1405093245239, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106205, 'user1', '8d1a1fb9-a022-40fb-ae7e-4af41d3a5544', 'Yeah. Still a good amount of pain. I did not take my pain medication this morning though. Not sure if that will make a huge difference.', 1405093239657, 1);
