INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106234, 'user1', 'e6b71b40-27e7-4e59-8ca8-ed71bf8cc46a', 'I had my tonsils taken out when I was a kid. I also had my uterus removed along with my ovaries and fallopian tubes. The list goes on. I had my appendix removed and two or three of my parathyroids taken out. Despite getting some of my parathyroids removed, I still have borderline high calcium levels according to my endocrinologist.', 1353179095506, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106235, 'user3', 'e6b71b40-27e7-4e59-8ca8-ed71bf8cc46a', 'Did you experience any complications during or after surgery?', 1353179089140, 6);
