INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106256, 'user2', 'fb5b7482-ffab-4470-9345-d89a5c3642a2', 'I''m just checking for lymph nodes. Whenever there is an infection those guys are the first ones to be noticed with swelling.', 980408374339, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106257, 'user2', 'fb5b7482-ffab-4470-9345-d89a5c3642a2', 'Okay, so let''s first check your neck area. It looks good. I don''t feel any inflamed lymph node. Your armpits look good too and the last place to check is your groin area. It is all good. No sign of infection.', 980408374649, 3);
