INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106480, 'user1', '6eb0470a-1959-48f0-b7c3-86f6083e479a', 'I am alright. I am here for a check up since I am feeling kind of dizzy lately.', 1638738871074, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106481, 'user2', '0537fcf3-2ff5-4e67-a71a-61e3ffbb2151', 'Do you know anyone in your family whose had cancer?', 1567523517742, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106482, 'user1', '0537fcf3-2ff5-4e67-a71a-61e3ffbb2151', 'No one that I know.', 1567523521746, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106483, 'user2', '66b849de-d645-47ae-b212-3609a2b3eaf0', 'Okay so your blood report is back and the cardiac enzyme we were looking for are negative.', 1554458286451, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106484, 'user1', '66b849de-d645-47ae-b212-3609a2b3eaf0', 'Okay.', 1554458292269, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106485, 'user2', '66b849de-d645-47ae-b212-3609a2b3eaf0', 'Your blood urea nitrogen, also known as B U N, is within normal limits and hydrogen is stable. Creatinine is also within the normal range.', 1554458298024, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106486, 'user1', '66b849de-d645-47ae-b212-3609a2b3eaf0', 'Great!', 1554458299465, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106487, 'user2', '32e282c9-2af1-498f-bd46-4bcaee7f3937', 'Are you on any medications?', 1121840237546, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106488, 'user1', '32e282c9-2af1-498f-bd46-4bcaee7f3937', 'No, not taking any medications.', 1121840242239, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106489, 'user2', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'Hi, how are you doing today?', 1268572128796, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106490, 'user1', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'I''ve been better. Thank you.', 1268572131013, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106491, 'user1', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'I''m not taking any medicine now. I just wanted to let you know.', 1268572138203, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106492, 'user2', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'Yeah, I can see it in your record. It says that you are off of all the immunosuppression. So, just let me check. It says here that you do have mild chronic G V H D. It is not that bad that I should be worried about any therapy or anything else. How long ago did you get that transplant?', 1268572146549, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106493, 'user1', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'I think it was around four and a half years ago. I''m feeling much better after that. I do have complaints of blood in my stool. But after you sent me to that doctor, that gastro doctor, I feel good. I know they said that they removed something, but I''m not sure, but after that it has been improved a lot.', 1268572144303, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106494, 'user2', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'Okay, let me see in my chart. You had some rectal bleeding issues because of which I referred you to the gastroenterologist. A complete endoscopy was performed, which was both on the upper and the lower side. There was no evidence of ulcers or any other abnormality. That''s  good news, right?', 1268572172122, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106495, 'user2', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'So, you are here for your follow up right? Remind me how often are you coming here?', 1268572131651, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106496, 'user2', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'They did find some polyps and they removed it. They turned out to be benign, so nothing to worry about there.', 1268572149107, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106497, 'user1', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'Yeah, I remember this said they removed something, but I forgot the name.', 1268572162770, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106498, 'user2', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'Is there any other issue that I can help you with?', 1268572194389, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106499, 'user1', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'I don''t know. I feel a lot of fatigue and like I''m not able to do things like I used to do before. I get tired very easily. I don''t know if it is related to something or not, but things have been weird. I''m not able to do even the minor things like I lift two boxes and I''m done for the day. Is it something that I should be worried about?', 1268572174320, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106500, 'user2', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'It looks like you have a mild iron deficiency. I will work on that with you, don''t worry.', 1268572165137, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106501, 'user2', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'Yeah, it''s every four to eight weeks.', 1268572151711, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106502, 'user1', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'Yeah, I agree. That was a relief.', 1268572149808, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106503, 'user1', '02abe2ef-17b7-4656-88c3-b36d1c1796ac', 'That''s right. I''m coming around between a month or two.', 1268572139216, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106504, 'user2', '77bdae89-b879-4bc4-82d8-7e099d2d5707', 'Are you feeling any pain?', 1083953312657, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106505, 'user1', '77bdae89-b879-4bc4-82d8-7e099d2d5707', 'No, I feel great.', 1083953316866, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106506, 'user2', '77bdae89-b879-4bc4-82d8-7e099d2d5707', 'Is there any other medical issue that we should be worried about?', 1083953321484, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106507, 'user1', '77bdae89-b879-4bc4-82d8-7e099d2d5707', 'No, it feels like I''m young again. I''m able to do all my activities.', 1083953329321, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106508, 'user3', '6aa2cb09-5672-42a4-a24c-e7fc022f6b67', 'Thank you for coming in to see us at A B C D General Hospital today.', 1307542948405, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106509, 'user1', '6aa2cb09-5672-42a4-a24c-e7fc022f6b67', 'I wish I wasn''t here right now.', 1307542953685, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106510, 'user1', '6aa2cb09-5672-42a4-a24c-e7fc022f6b67', 'I''m an African American woman.', 1307542975981, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106511, 'user3', '6aa2cb09-5672-42a4-a24c-e7fc022f6b67', 'What''s seems to be causing you pain today?', 1307542971912, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106512, 'user1', '6aa2cb09-5672-42a4-a24c-e7fc022f6b67', 'I''ve had this bunion on my foot for as long as I can remember.', 1307542959180, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106513, 'user3', '6aa2cb09-5672-42a4-a24c-e7fc022f6b67', 'Is the pain worsening?', 1307542972512, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106514, 'user1', '6aa2cb09-5672-42a4-a24c-e7fc022f6b67', 'Yes, it is so painful, I''ve tried to avoid surgery for so long, but I want this bunion gone.', 1307542967273, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106515, 'user3', '6aa2cb09-5672-42a4-a24c-e7fc022f6b67', 'How have you managed this bunion in the past?', 1307542985184, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106516, 'user1', '6aa2cb09-5672-42a4-a24c-e7fc022f6b67', 'I''ve used antiinflammatories, rested, changed my activities, I''ve done everything, but this pain is getting worse and worse.  I need it gone.', 1307542992992, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106517, 'user3', '6aa2cb09-5672-42a4-a24c-e7fc022f6b67', 'I understand, before we begin, how old are you?', 1307542955557, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106518, 'user1', '6aa2cb09-5672-42a4-a24c-e7fc022f6b67', 'I''m seventy seven years young.', 1307542953077, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106519, 'user3', '6aa2cb09-5672-42a4-a24c-e7fc022f6b67', 'Which race, and gender do you identify with?', 1307542952762, 4);
