INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106522, 'user2', '761bf69d-a8ac-425b-85c6-448da65217ba', 'Alright.', 1042443661272, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106523, 'user3', '94223951-fe14-4c5e-a40d-cf02b4283257', 'How are you dealing with your pain now?', 1272235309466, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106524, 'user1', '94223951-fe14-4c5e-a40d-cf02b4283257', 'Oh no, I have no issues with my pain. Today I''m here for a different cause. I''m having this weakness all around on my left side, especially in my arm. I feel like I cannot lift anything like even a glass of water. It''s hard for me to lift it up. I''m not able to walk properly, let alone the balancing and everything else. It''s just that my whole left side seems to be weak.', 1272235310584, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106525, 'user3', '221662ca-985e-4bb8-9892-f83a450de262', 'Did you have any medical disorders previously, sir?', 1112819040481, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106526, 'user3', '221662ca-985e-4bb8-9892-f83a450de262', 'How many cigarettes do you take in a day?', 1112819050090, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106527, 'user1', '221662ca-985e-4bb8-9892-f83a450de262', 'I have diabetes. Also, I was quite overweight.', 1112819042891, 1);
