INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106532, 'user1', '221662ca-985e-4bb8-9892-f83a450de262', 'Yes, I was still taking something called Zyprexa, but I stopped it after my last regular weight check. Also, I never took anything for diabetes. I also have chronic bronchitis for… I don''t know… many years.', 1112819048103, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106533, 'user2', '794a4f4e-8c39-488a-b16d-e5bf0171504d', 'Lets talk about your ears. Any continuous ringing or thumping noises you may hear?', 1402127245153, 0);
