INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106539, 'user2', 'd886f336-8c32-4879-a42e-792c5cfb94f9', 'Good morning, ma''am. You''re eighty two years old, is that correct?', 1283390371865, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106540, 'user1', 'd886f336-8c32-4879-a42e-792c5cfb94f9', 'Good morning, doctor. Yes, that''s correct.', 1283390377821, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106541, 'user1', 'd886f336-8c32-4879-a42e-792c5cfb94f9', 'Doctor, I''ve had years of pain in this shoulder.', 1283390395937, 5);
