INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106547, 'user2', 'd886f336-8c32-4879-a42e-792c5cfb94f9', 'Good, so what seems to be the problem today?', 1283390384777, 4);
