INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106549, 'user1', '99be47bc-c7e3-46e9-8bc9-efc3dc51b359', 'What, like a joint replacement?', 1009343449802, 1);
