INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106562, 'user3', '93b1df24-d088-416d-b158-d4d325e991d6', 'Okay, back to diabetes, how has that been progressing?', 1450017306875, 12);
