INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106565, 'user1', '93b1df24-d088-416d-b158-d4d325e991d6', 'No, doctor, I haven''t been. When I check them, it''s normal though.', 1450017270688, 15);
