INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106569, 'user1', '93b1df24-d088-416d-b158-d4d325e991d6', 'No, I can''t think of anything.', 1450017285448, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106570, 'user3', '93b1df24-d088-416d-b158-d4d325e991d6', 'Okay. I''m looking at your charts, and I see you had a benign breast biopsy done on June eleventh two thousand four. Did you have a repeat done after six months like they asked?', 1450017295584, 20);
