INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106577, 'user2', '9285bd29-2bd6-4eda-892f-6a941ffb810e', 'Do you mind giving me a run down of his past medical history? I want to make sure it''s all in his chart.', 1138003452161, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106578, 'user1', '9285bd29-2bd6-4eda-892f-6a941ffb810e', 'Sure. I''ll start with his surgeries. If I remember correctly, he had back surgery, a couple knee surgeries, and coronary artery bypass surgery with angioplasty.', 1138003454827, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106579, 'user1', '9285bd29-2bd6-4eda-892f-6a941ffb810e', 'Oh, he has high P S A levels, too. I think that''s related to the prostate.', 1138003460153, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106580, 'user2', '9285bd29-2bd6-4eda-892f-6a941ffb810e', 'Is he currently experiencing any symptoms?', 1138003478896, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106581, 'user1', '9285bd29-2bd6-4eda-892f-6a941ffb810e', 'He was complaining of pain earlier. He does have a history of fatigue, tiredness, and shortness of breath though. So far, he hasn''t complained about the usual.', 1138003487152, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106582, 'user2', '9285bd29-2bd6-4eda-892f-6a941ffb810e', 'I see. When did he have these done?', 1138003462489, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106583, 'user1', '9285bd29-2bd6-4eda-892f-6a941ffb810e', 'I''d have to check, but I know he had back surgery in O nine. He has a history of high blood pressure and high cholesterol. He was recently diagnosed with B P H potentially linked to cancer. It''s B P H, right? Or is it B H P?', 1138003462478, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106584, 'user2', '9285bd29-2bd6-4eda-892f-6a941ffb810e', 'If it''s his prostate, then B P H is correct.', 1138003475249, 4);
