INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106671, 'user1', '73ac5f3f-f2a5-4aab-a189-7624433c9f02', 'I have a long history of lung disease. COPD to be exact. Recently, I was experiencing a lot of coughing and shortness of breath even on walking from one room to another. All the time I felt sleepy, tired, or confused.', 1587094114776, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106672, 'user1', '73ac5f3f-f2a5-4aab-a189-7624433c9f02', 'I was also diagnosed with pneumonia; I was on trip and there they found it. It is also getting a lot better now, but doctor said to continue taking oxygen for some more time.', 1587094119059, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106673, 'user2', '73ac5f3f-f2a5-4aab-a189-7624433c9f02', 'Oh wow!', 1587094134038, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106674, 'user1', '73ac5f3f-f2a5-4aab-a189-7624433c9f02', 'With everything going on, I felt weak and tired and it looks like I have lost all my strength and muscle.', 1587094124780, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106675, 'user1', '73ac5f3f-f2a5-4aab-a189-7624433c9f02', 'I also felt very instable and had a fall. I did not call for any assistance but now I think I should have called someone. Everyone including my family and nurses all tell me all the time to call for assistance. I was just being stubborn and hurt myself.', 1587094151674, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106676, 'user2', '73ac5f3f-f2a5-4aab-a189-7624433c9f02', 'Did you use a wheelchair?', 1587094146061, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106677, 'user1', '73ac5f3f-f2a5-4aab-a189-7624433c9f02', 'No.', 1587094158848, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106678, 'user2', '73ac5f3f-f2a5-4aab-a189-7624433c9f02', 'You know I would agree with everyone else; you should call for assistance if you need help like getting out of bed or need to use the restroom.', 1587094171050, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106679, 'user2', '73ac5f3f-f2a5-4aab-a189-7624433c9f02', 'How is it now?', 1587094122039, 2);
