INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106724, 'user3', '3c5c0837-e19c-4449-a642-1fcc1d870266', 'Ha, I will take that as a positive answer then. I have my resident here with me, Doctor Helm, she will be representing your case today.', 1335092543674, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106725, 'user3', '3c5c0837-e19c-4449-a642-1fcc1d870266', 'The patient is a sixty one year old female. She was diagnosed with non small cell lung cancer stage one A in the upper right lobe. She was treated with CyberKnife and the treatment was completed one month ago. This is her first visit after the CyberKnife treatment.', 1335092566815, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106726, 'user3', '3c5c0837-e19c-4449-a642-1fcc1d870266', 'Thank you Doctor Helm. So, Miss Sherry, how are you doing after the treatment?', 1335092560693, 7);
