INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106801, 'user2', '67c4e392-611e-4021-b261-b30f92afcdec', 'Hello sir, what brings you here today? Also, please confirm your age for the records.', 1147302574097, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106802, 'user1', '67c4e392-611e-4021-b261-b30f92afcdec', 'I am seventy years old. I am here for nothing particular but I just have discomfort on the right side.', 1147302579969, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106803, 'user1', '67c4e392-611e-4021-b261-b30f92afcdec', 'That sounds right. Nothing seems to help me to get rid of this discomfort.', 1147302591164, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106804, 'user2', '67c4e392-611e-4021-b261-b30f92afcdec', 'How often do you check your sugar levels?', 1147302607698, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106805, 'user1', '67c4e392-611e-4021-b261-b30f92afcdec', 'I do it at home. Mainly two to three times a day. I increase or decrease the amount of insulin that I take based on my numbers.', 1147302592317, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106806, 'user2', '67c4e392-611e-4021-b261-b30f92afcdec', 'Don''t you consult anyone before doing that?', 1147302588369, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106807, 'user1', '67c4e392-611e-4021-b261-b30f92afcdec', 'It''s been so many years now. I do it all by myself.', 1147302623070, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106808, 'user2', '67c4e392-611e-4021-b261-b30f92afcdec', 'We did reevaluations of your symptoms. It turned out to be all negative. Do you smoke?', 1147302625106, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106809, 'user1', '67c4e392-611e-4021-b261-b30f92afcdec', 'I used to chew tobacco a lot and then there were drinks. I used to drink at least half a bottle of single malt in one night. I quit everything five years ago after my stroke.', 1147302596084, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106810, 'user2', '67c4e392-611e-4021-b261-b30f92afcdec', 'We did electromyography study. This was to assess the health of muscles and the nerves in your body. When did you first notice this discomfort?', 1147302582524, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106811, 'user1', '67c4e392-611e-4021-b261-b30f92afcdec', 'About five years ago. After my stroke. I''ve been to a neurologist before.', 1147302578231, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (106812, 'user2', '67c4e392-611e-4021-b261-b30f92afcdec', 'Yeah, I can see that you have taken different kinds of medications, but nothing seems to help you.', 1147302592806, 4);
