INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107021, 'user1', '1f90d351-b06a-4b33-be0e-c381f77582b7', 'Okay nice.', 1160377789558, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107022, 'user2', 'ac7baf1c-691b-4836-9679-7642fc099fd3', 'You have an infection that has become septic. We are going to have to start you on intravenous antibiotics.', 1548333399750, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107023, 'user1', 'ac7baf1c-691b-4836-9679-7642fc099fd3', 'Okay.', 1548333402994, 1);
