INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107043, 'user2', '39da7aaf-cf6e-4048-b478-4902ac205159', 'So, what brings you in today?', 1491423060107, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107044, 'user1', '39da7aaf-cf6e-4048-b478-4902ac205159', 'I have been under tremendous stress for the last five to ten years. I am currently working for T mobile customer service and my work is really hectic. It requires a lot of technical knowledge with project deadlines which is adding to my stress.', 1491423072103, 5);
