INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107047, 'user1', '39da7aaf-cf6e-4048-b478-4902ac205159', 'I did my M B A in business for a reason, I wanted to make a good career, but this job is very demanding and stressful. I previously worked at a bank in Conway Springs, Norwich. I have worked many jobs around accounting and management services, but my current job is a high stress one.', 1491423088268, 8);
