INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107063, 'user1', '095ae4bf-7aff-4892-bd20-90e42a1396a8', 'Thank you.', 1190286836485, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107064, 'user3', '095ae4bf-7aff-4892-bd20-90e42a1396a8', 'Doctor Murphy sent your records over. I reviewed the ultrasound, and we did find a kidney stone that has become stuck in the ureter on the left side. The stone is large enough to block the flow of urine from the kidney to the bladder.  How much pain are you having and where is the pain located?', 1190286844490, 2);
