INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107074, 'user1', '1d4f9de7-0aec-4e14-9696-32e28c88f33b', 'I will keep an eye on it.', 1285591160173, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107075, 'user2', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'Can you tell me more about your daughter''s injury?', 1010330078653, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107076, 'user1', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'Well, we came in in November, and she was diagnosed with an acute on chronic right slipped capital femoral epiphysis.', 1010330081545, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107077, 'user2', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'Did she have surgery on this?', 1010330083051, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107078, 'user2', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'Okay, thank you. So, um, if you look her at the x rays, it appears that the screw is now going into the hip joint.', 1010330091825, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107079, 'user1', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'They didn''t see that before. What can we do about this?', 1010330099090, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107080, 'user2', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'We''ll need to do another operation in order to remove this screw and put a shorter one in. We need to do the surgery because this can cause further joint damage.', 1010330108011, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107081, 'user1', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'Are there any risks of infection from this surgery?', 1010330120994, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107082, 'user2', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'Overall, the risk of infection is very low, honestly its less than one percent.', 1010330119018, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107083, 'user1', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'That''s good to hear, will she go to sleep during surgery?', 1010330142163, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107084, 'user2', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'Yes, we''ll use anesthesia the entire time. She won''t feel a thing.', 1010330099478, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107085, 'user1', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'What does recovery look like for this surgery?', 1010330118168, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107086, 'user2', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'I expect her to heal up very well, but there''s always a risk of some changes in sensation and motion, and she may be stiff for some time following everything. Other risks include bleeding, but I would not worry about these things.', 1010330123261, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107087, 'user1', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'Okay, how does that sound, honey? Would you like to do this?', 1010330159248, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107088, 'user1', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'Yeah, I want to get back to playing sports with my friends.', 1010330150863, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107089, 'user1', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'I agree, Doctor, we''ll do the surgery.', 1010330115120, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107090, 'user1', 'd671e383-0bbc-4874-9f59-71fc8dfd570e', 'Yes, let me look at my notes, I have it written down here, um, a situ pinning.', 1010330083500, 3);
