INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107186, 'user3', '142fe47f-1ef5-47da-b96f-0f95a33c8441', 'Hello how are you? Doctor Mina is an intern working with me. She will be taking notes and discussing your case today.', 1181578533542, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107187, 'user1', '142fe47f-1ef5-47da-b96f-0f95a33c8441', 'That''s okay.', 1181578536958, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107188, 'user1', '142fe47f-1ef5-47da-b96f-0f95a33c8441', 'I am doing fine. I do get some headaches and it feels like somebody is ringing bells in my ears. My eyesight has improved a lot.', 1181578547842, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107189, 'user3', '142fe47f-1ef5-47da-b96f-0f95a33c8441', 'This is a sixteen year old right handed boy. He is studying in eleventh grade. He is having some difficulties with vision like blurring and focusing. He was diagnosed with a suprasellar tumor. Later on, January fourth, he underwent a surgery for his tumor. Biopsy reports said that it was craniopharyngioma. Even after the surgery, there was some residual disease left and his visual apparatus was decompressed.', 1181578551527, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107190, 'user3', '142fe47f-1ef5-47da-b96f-0f95a33c8441', 'Thank you Doctor.  Tell me how are you doing young man? Are there any difficulties going back to school?', 1181578550836, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107191, 'user3', '142fe47f-1ef5-47da-b96f-0f95a33c8441', 'So, tell me Doctor Mina, what brings this young man today here?', 1181578535635, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107192, 'user3', '3ea460f6-91f9-4acc-ac06-76b5e142e4c1', 'Remind me, please, when was your surgery?', 1516981742892, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107193, 'user1', '3ea460f6-91f9-4acc-ac06-76b5e142e4c1', 'Well, it''s been about two and a half months now.', 1516981748649, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107194, 'user3', '3ea460f6-91f9-4acc-ac06-76b5e142e4c1', 'Great, we repaired that slipped capital femoral epiphysis on both sides, we call it S C F E.', 1516981745390, 2);
