INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107250, 'user1', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'I''ve tried to increase how much I walk, but when I do I get spasms in my lower back.', 1699233890976, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107251, 'user2', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'I see, with ten being the worst pain of all time, how would you rate your pain today?', 1699233866260, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107252, 'user1', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'I''d say it''s a six out of ten today.', 1699233838329, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107253, 'user2', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'What adjectives would you use to describe the pain?', 1699233907416, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107254, 'user1', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'Um, I''d say its shooting, sharp, and, um, aching.', 1699233881887, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107255, 'user2', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'Specifically, what activities make the pain worse?', 1699233846734, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107256, 'user1', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'It was in January of two thousand five. What was the name of the surgery, again?', 1699233797770, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107257, 'user2', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'Does anything make the pain better?', 1699233885994, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107258, 'user1', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'Um, sitting back, ice, and I guess there''s some improvement with the pain medication.', 1699233834391, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107259, 'user2', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'Is the pain constant, or does it come and go?', 1699233881762, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107260, 'user1', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'It''s constant now, but, um, the intensity of it comes and goes.', 1699233832558, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107261, 'user2', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'Are you able to sleep at night?', 1699233910658, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107262, 'user1', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'Not really, it is affecting my sleep, which in turn affects my mood.', 1699233908184, 35);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107263, 'user2', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'So, overall, I can summarize and say you''re not happy with your pain relief so far?', 1699233940442, 36);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107264, 'user1', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'Yes, doctor, that''s correct.', 1699233875454, 37);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107265, 'user1', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'I''m forty nine.', 1699233795128, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107266, 'user2', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'Also, I need you to remind me, when was your lower back surgery?', 1699233796171, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107267, 'user1', '803f43ec-07a7-4ffa-869e-4d3d9bb807bf', 'Well, lifting, standing for a long time, or, um, squatting. I can''t do that anymore.', 1699233827456, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107268, 'user2', 'f6d3267b-99de-46e1-a618-30212785ee7f', 'Do you have a family history of neurological conditions that I should know about?', 1008085668509, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107269, 'user1', 'f6d3267b-99de-46e1-a618-30212785ee7f', 'What exactly do you mean by that, doctor?', 1008085672006, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107270, 'user2', 'f6d3267b-99de-46e1-a618-30212785ee7f', 'Well, it could be anything from A D H D, to epilepsy, to Alzheimer''s.', 1008085677432, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107271, 'user1', 'f6d3267b-99de-46e1-a618-30212785ee7f', 'Oh, no.', 1008085682247, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107272, 'user2', '4f608bf9-b187-4632-8305-cc663364b487', 'Are you on any medications?', 1066350049660, 0);
