INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107274, 'user2', '4f608bf9-b187-4632-8305-cc663364b487', 'Do you find that it''s helping?', 1066350057678, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107275, 'user1', '4f608bf9-b187-4632-8305-cc663364b487', 'A little, yeah.', 1066350056069, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107276, 'user2', 'eb66eb0c-a003-49db-a282-f175db2c92c7', 'Your culture results came back positive for Streptococcus pneumoniae. This is a bacterial infection. I would like to take a course of antibiotics.  This should start to improve your symptoms with in three to four days.', 1380191213742, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107277, 'user1', 'eb66eb0c-a003-49db-a282-f175db2c92c7', 'Okay.', 1380191215331, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107278, 'user2', 'eb66eb0c-a003-49db-a282-f175db2c92c7', 'Please let me know if your symptoms have not improved or becomes worse.', 1380191215835, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107279, 'user1', 'eb66eb0c-a003-49db-a282-f175db2c92c7', 'I will. Thank you.', 1380191218646, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107280, 'user1', '5d72a8e2-59ac-45ed-a156-636bb7d32b88', 'I had a lung transplant in two thousand and four because of Pulmonary Fibrosis.', 1332251096149, 0);
