INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107291, 'user2', 'b741289b-5e01-46b9-a6c5-338ac5057a26', 'Can you move your arms? I would like to see how your range of motion is.', 1068343008429, 0);
