INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107312, 'user3', '949fd201-9f7b-4aa4-b611-071374c51991', 'Are you married?', 1534829405824, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107313, 'user3', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Good morning, young lady. Is this your mother?', 1382438583984, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107314, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Yes, this is my mommy.', 1382438587216, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107315, 'user3', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Good morning, mom. Can you tell me more about your daughter, please?', 1382438589474, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107316, 'user3', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Okay, how has she been since that procedure?', 1382438618383, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107317, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Well, just look at her heel, doctor.', 1382438594437, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107318, 'user3', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Yes, I see. She has pretty significant calcaneal valgus deformity.', 1382438614162, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107319, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'What does that mean, doctor?', 1382438633227, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107320, 'user3', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Your heel is out of alignment, sweetie. Do you have pain?', 1382438639336, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107321, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Yes, I have a lot of pain, doctor.', 1382438619098, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107322, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'What can we do about this, doctor?', 1382438626375, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107323, 'user3', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Well, given all of her symptoms, I think we should do a calcaneal osteotomy and Achilles lengthening procedure.', 1382438648316, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107324, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'What does that procedure entail?', 1382438660354, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107325, 'user3', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Well, in short, we''ll go in there and straighten everything out, and get everything lined back up.', 1382438665851, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107326, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'What''s the risk of infection with the surgery, sir?', 1382438665763, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107327, 'user3', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Actually, it''s less than one percent, so it''s extremely low.', 1382438668741, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107328, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'How is this possible, doctor?', 1382438609573, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107329, 'user3', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'We use antibiotics to control for infection the entire time.', 1382438613514, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107330, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'That''s great. Will she be asleep for this procedure?', 1382438638414, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107331, 'user3', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Yes, we''ll use anesthesia the entire time. She won''t feel a thing.', 1382438614432, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107332, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Okay, that''s good too. What about after the procedure? What''s the protocol?', 1382438632030, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107333, 'user3', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Well, I''ll need your help. We have to be strict about her being nonweightbearing for six weeks at minimum.', 1382438682594, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107334, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Will she need a brace too?', 1382438652634, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107335, 'user3', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Yes, at least for six months, but if she does everything I ask of her, it will be only six months.', 1382438668957, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107336, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Okay, yes, I think we should do the procedure. What do you think, honey?', 1382438738562, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107337, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Yes, I want to get back to playing sports with my friends.', 1382438617167, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107338, 'user3', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'The other risks include bleeding; changes in sensation in most of extremity; hardware failure; need for later hardware removal; possible nonunion; possible failure to correct all the deformity; and need for other surgical procedures.  I would not worry about these issues, though. It is quite rare. So, looking at her radiographs, the spinal arch is definitely collapsed. I think you guys are making the right decision.', 1382438622190, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107339, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Well, she had bilateral feet corrections when she was a year old.', 1382438601435, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107340, 'user1', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'Good morning, doctor. Well, she''s thirteen now, but she''s had feet problems all her life.', 1382438597060, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107341, 'user3', '3fd55b0a-1f8b-4ad5-8506-61687e0a49ca', 'What''s been the problem with her feet?', 1382438596882, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107342, 'user2', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'Good morning, young man. Are these your parents?', 976002938394, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107343, 'user1', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'Yes.', 976002943000, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107344, 'user1', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'We went to the E D right after he fell, and they said he had complete fractures of both bones in the arm.', 976002950804, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107345, 'user2', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'Yes, I see that here, he also has shortening bayonet apposition.', 976002951598, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107346, 'user1', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'What can we do for this?', 976002946072, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107347, 'user2', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'There''s actually a few options here. First we can cast it and see how he heals, generally, children heal up very well from fractures.', 976002968640, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107348, 'user1', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'That''s good, we like that option more than any kind of surgery.', 976002973694, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107349, 'user2', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'However, surgery is also an option here as well.', 976002991898, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107350, 'user1', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'Yeah, to be completely sure we fix this, I think we should opt for the surgery, what do you think, honey?', 976002977513, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107351, 'user1', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'Yes, I agree. What are the risks of infection for this surgery?', 976002986506, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107352, 'user2', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'The risk of infection is very low, generally less than one percent. We use antibiotics to control for infection.', 976002993757, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107353, 'user1', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'Will he be asleep for the surgery?', 976003004910, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107354, 'user2', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'Absolutely, he won''t feel a thing. Other risks include bleeding, changes in sensation and motion of the extremity, hardware failure, and need for later hardware removal, and cast tightness. I would not worry about these risks. We have great results with these surgeries.', 976003003990, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107355, 'user1', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'Then yes, we''d like to do the surgery.', 976002983972, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107356, 'user2', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'Good, can you tell me more about your son, please?', 976002942633, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107357, 'user1', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'Well, he''s five now, and he fell onto his right arm on December fifth two thousand seven.', 976002954254, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107358, 'user2', 'fc088196-68af-4fc2-b851-aa6d825b2393', 'After he fell, how was he treated?', 976002946429, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107359, 'user3', 'd4ff2c12-6bcd-4c80-93fb-2ee42c191a76', 'Hello. Are you a new patient?', 1451690498457, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107360, 'user1', 'd4ff2c12-6bcd-4c80-93fb-2ee42c191a76', 'I am. I''ve been traveling a lot, so I don''t have a local doctor I usually see.', 1451690503156, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107361, 'user3', 'd4ff2c12-6bcd-4c80-93fb-2ee42c191a76', 'That''s fine. What is the reason for your visit?', 1451690508897, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107362, 'user3', 'd4ff2c12-6bcd-4c80-93fb-2ee42c191a76', 'That''s good. I think I''ll be able to remove it surgically. Before I go over the procedures, have you had a surgery before?', 1451690515801, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107363, 'user1', 'd4ff2c12-6bcd-4c80-93fb-2ee42c191a76', 'Yeah, I have. I had surgery on my back and to remove my appendix.', 1451690540337, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107364, 'user3', 'd4ff2c12-6bcd-4c80-93fb-2ee42c191a76', 'Sounds good. Other than that dark spot, you seem to be very healthy.', 1451690535177, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107365, 'user1', 'd4ff2c12-6bcd-4c80-93fb-2ee42c191a76', 'Not that I know of.', 1451690526247, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107366, 'user1', 'd4ff2c12-6bcd-4c80-93fb-2ee42c191a76', 'I''ve had this dark spot on my leg for a long time.', 1451690507849, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107367, 'user3', 'd4ff2c12-6bcd-4c80-93fb-2ee42c191a76', 'I see. Do you know if your family has any chronic medical problems?', 1451690511957, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107368, 'user2', '6f5ddd48-5e41-4686-a05a-43021050db56', 'It''s surgery day! How are you feeling?', 1438977373419, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107369, 'user1', '6f5ddd48-5e41-4686-a05a-43021050db56', 'Hi Doctor. I''m the mother. He had a chest port placement.', 1438977388492, 4);
