INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107413, 'user2', 'fc115b1d-144a-4553-af3e-788a09abf6b9', 'Hello! What brings you back into the clinic today?', 1037501883872, 0);
