INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107416, 'user2', 'fc115b1d-144a-4553-af3e-788a09abf6b9', 'I would like to get some bloodwork done. I would also recommend we decrease your dosage back to your previous amount. I would also like to see you back in two weeks to see how you are doing.', 1037501898852, 6);
