INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107418, 'user2', 'fc115b1d-144a-4553-af3e-788a09abf6b9', 'I am sorry. It is likely that the increased dosage of your methothrexate is the cause of the mouth sores. Have you experienced a decreased appetite, nausea, abdominal discomfort or diarrhea?', 1037501895443, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107419, 'user1', 'fc115b1d-144a-4553-af3e-788a09abf6b9', 'No. It is painful to eat with the sores, but I still have an appetite.', 1037501892031, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107420, 'user1', 'fc115b1d-144a-4553-af3e-788a09abf6b9', 'I came back because I increased my methothrexate as we discussed the last time I was here. A few days later I started getting multiple canker sores in my mouth. They hurt.', 1037501888143, 1);
