INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107444, 'user1', '2effcde9-00e7-4da4-8de9-193d1e1c6db8', 'Two Persian cats and one Chartreux.', 1308184309591, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107445, 'user3', '2effcde9-00e7-4da4-8de9-193d1e1c6db8', 'Are you currently working?', 1308184314614, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107446, 'user2', '049ca8f7-b34e-4637-a1f0-685100f07c1b', 'Hi there! What brings you in today?', 1559678885571, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107447, 'user2', '049ca8f7-b34e-4637-a1f0-685100f07c1b', 'Do you have a picture of it?', 1559678906768, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107448, 'user1', '049ca8f7-b34e-4637-a1f0-685100f07c1b', 'Yes. It is in my phone.', 1559678913590, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107449, 'user1', '049ca8f7-b34e-4637-a1f0-685100f07c1b', 'It was the one with Borax in it.', 1559678891405, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107450, 'user1', '049ca8f7-b34e-4637-a1f0-685100f07c1b', 'I think my baby got into the ant bait. I am not sure if he consumed any of it but he was under the counter and it was in his hands.', 1559678887803, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107451, 'user2', '049ca8f7-b34e-4637-a1f0-685100f07c1b', 'What kind ant bait did he get into?', 1559678893801, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107452, 'user2', '03219044-dec9-4d58-9167-9fdc3a611adf', 'Good morning, ma''am. I just need to confirm some information about you before we begin today.', 1086519754707, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107453, 'user1', '03219044-dec9-4d58-9167-9fdc3a611adf', 'Good morning, doctor. Sure, that''s no problem.', 1086519757782, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107454, 'user1', '03219044-dec9-4d58-9167-9fdc3a611adf', 'Um, I''ve had six, I''m here for a follow up today.', 1086519772733, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107455, 'user2', '03219044-dec9-4d58-9167-9fdc3a611adf', 'Yes, I see here that your last chemo treatment on January eighteenth two thousand eight.', 1086519771101, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107456, 'user1', '03219044-dec9-4d58-9167-9fdc3a611adf', 'Yes, I remember that. Can you remind me the full name of my cancer?', 1086519776412, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107457, 'user2', '03219044-dec9-4d58-9167-9fdc3a611adf', 'It''s a uterine papillary serous carcinoma.', 1086519790865, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107458, 'user1', '03219044-dec9-4d58-9167-9fdc3a611adf', 'Thank you, doctor.', 1086519767682, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107459, 'user2', '03219044-dec9-4d58-9167-9fdc3a611adf', 'Sure, do you have any problems today?', 1086519810769, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107460, 'user1', '03219044-dec9-4d58-9167-9fdc3a611adf', 'Well, I just have some numbness in my right upper arm today.', 1086519799072, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107461, 'user2', '03219044-dec9-4d58-9167-9fdc3a611adf', 'Has this gotten worse recently?', 1086519775390, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107462, 'user1', '03219044-dec9-4d58-9167-9fdc3a611adf', 'Well, no, not really.', 1086519805453, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107463, 'user1', '03219044-dec9-4d58-9167-9fdc3a611adf', 'Yes, that''s right doctor.', 1086519768286, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107464, 'user1', '03219044-dec9-4d58-9167-9fdc3a611adf', 'No, there''s no numbness there.', 1086519820814, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107465, 'user2', '03219044-dec9-4d58-9167-9fdc3a611adf', 'Good, do you have any tingling or burning to speak of?', 1086519823335, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107466, 'user1', '03219044-dec9-4d58-9167-9fdc3a611adf', 'No, thankfully no.', 1086519835350, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107467, 'user2', '03219044-dec9-4d58-9167-9fdc3a611adf', 'That''s good. Do you feel this in your toes at all?', 1086519804791, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107468, 'user2', '03219044-dec9-4d58-9167-9fdc3a611adf', 'Thank you. Do you remember how many cycles of carboplatin and Taxol you''ve had for your cancer, ma''am?', 1086519776062, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107469, 'user2', '03219044-dec9-4d58-9167-9fdc3a611adf', 'Great, so you''re sixty seven years old, and White, correct?', 1086519758225, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107470, 'user3', '7accd244-1935-4a2c-8d1e-0b42d21b835c', 'How long has she had difficulty swallowing?', 1270484823945, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107471, 'user3', '7accd244-1935-4a2c-8d1e-0b42d21b835c', 'We''ll have to see, but chances are higher since she''s experiencing symptoms due to her thyroid.', 1270484841339, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107472, 'user1', '7accd244-1935-4a2c-8d1e-0b42d21b835c', 'When will we find out?', 1270484843477, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107473, 'user3', '7accd244-1935-4a2c-8d1e-0b42d21b835c', 'I''d like to get some imaging done and see if we can get a consult in first.', 1270484833495, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107474, 'user1', '7accd244-1935-4a2c-8d1e-0b42d21b835c', 'A while now. We scheduled her to see an endocrinologist, but she''s not able to get in until Monday. I wanted to see if we could get to the bottom of it now.', 1270484827793, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107475, 'user3', '7accd244-1935-4a2c-8d1e-0b42d21b835c', 'It does appear that her thyroids are fairly enlarged. I believe that''s where most of her symptoms, if not all, are stemming from.', 1270484830218, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107476, 'user1', '7accd244-1935-4a2c-8d1e-0b42d21b835c', 'Does that mean she''ll need surgery?', 1270484841537, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107477, 'user3', '78b6dd89-05cd-469b-b7e8-f2482d7827dd', 'Do you have any significant medical conditions that run in your family that I should be aware of?', 1640714568265, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107478, 'user1', '78b6dd89-05cd-469b-b7e8-f2482d7827dd', 'Yes, um, I know some of my relatives have had coronary artery disease, and, um, high blood pressure.', 1640714569701, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107479, 'user3', '78b6dd89-05cd-469b-b7e8-f2482d7827dd', 'What about cancer? Does anyone in your family have a history of cancer?', 1640714574448, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107480, 'user1', '78b6dd89-05cd-469b-b7e8-f2482d7827dd', 'No, that doesn''t ring any bells.', 1640714574896, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107481, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'When was your injury, sir?', 1137227162972, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107482, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Um, if I recall, it was on November twentieth two thousand eight.', 1137227166245, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107483, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Well, an inmate broke some of the overhead sprinklers, and I slipped on all the water and I landed on the back of my head, and then onto my back.', 1137227182531, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107484, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Which side took most of the hit?', 1137227170202, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107485, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'It was mostly on my left side.', 1137227197025, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107486, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'How were you after the fall?', 1137227182798, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107487, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Well, I was pretty stunned, mostly. I didn''t want to come in, but my employers asked me to just to be sure.', 1137227179521, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107488, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Who has evaluated you to date?', 1137227222676, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107489, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Um, I went to Gig Harbor Urgent Care, and then they sent me to Tacoma General Hospital. At Tacoma they said I have a whiplash and concussion.', 1137227221099, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107490, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'What did they do at the hospital?', 1137227204018, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107491, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Um, they did a C T scan, and they found a dark spot on my brain.', 1137227210868, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107492, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'What did they recommend about the spot?', 1137227244524, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107493, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'They said I should have another M R I and they diagnosed an, um, recurrent acoustic neuroma.', 1137227226631, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107494, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'So, you''ve had this before? How did they know you had it?', 1137227212413, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107495, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'I used to see a chiropractor, and they suggested that I get a scan and that''s how they found it before.', 1137227192979, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107496, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'When was this?', 1137227256846, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107497, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Um, it was in October of two thousand five.', 1137227200678, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107498, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Did you have surgery on this?', 1137227253392, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107499, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Yes, I''m recovering now.', 1137227276781, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107500, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Are they still considering radiation?', 1137227235415, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107501, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Yes, it''s under consideration but there''s no final decision yet.', 1137227240986, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107502, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Okay, what does the chiropractor do for you?', 1137227249590, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107503, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'You know, the usual, adjustments and massages, stuff like that.', 1137227269216, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107504, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Has there been any improvement?', 1137227221620, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107505, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Overall, my spine pain has improved a lot.', 1137227276067, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107506, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'That''s good. Okay, so after your fall, what other treatments did you have?', 1137227283618, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107507, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'I went to Prompt Care in Bremerton, and saw Doctor X Y Z. She''s an osteopathic doctor.', 1137227282369, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107508, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'How did she treat you?', 1137227269325, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107509, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'She ordered an M R I of my neck, I have the report right here.', 1137227327548, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107510, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Okay, this shows some mild disc bulge at C four C five. Did she let you go back to work?', 1137227263995, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107511, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Yes, she released me back to full duty. I was doing fine after the neurosurgical treatment.', 1137227243696, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107512, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Do you have any other treatment planned?', 1137227307794, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107513, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Some radiation.', 1137227285316, 35);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107514, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'What else has she treated you for?', 1137227358501, 36);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107515, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'Oh, you know, just general aches and pains on my back and neck. I have been seeing her since two thousand and two.', 1137227206183, 37);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107516, 'user1', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'I work at the Purdy Correctional Facility, doctor.', 1137227178163, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107517, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'How did you get hurt?', 1137227180893, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107518, 'user3', 'a5789254-c2c7-4b61-bdc7-c6d569fe471c', 'What do you do for a living, sir?', 1137227171568, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107519, 'user3', 'b9f1dab5-faeb-4c6d-9928-9487f369f291', 'Any past medical problems or surgeries that I should know of?', 1660155677494, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107520, 'user1', 'b9f1dab5-faeb-4c6d-9928-9487f369f291', 'Nope, none that I can think of.', 1660155681491, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107521, 'user2', 'dbe26974-a86f-48bc-b0a9-5038a2f412c2', 'So, I see here in your reports you have arthritis in you both knees.', 1019804361189, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107522, 'user1', 'dbe26974-a86f-48bc-b0a9-5038a2f412c2', 'Yes.', 1019804364847, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107523, 'user2', 'dbe26974-a86f-48bc-b0a9-5038a2f412c2', 'And you got a tear in your eye in the past, right?', 1019804371445, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107524, 'user2', 'dbe26974-a86f-48bc-b0a9-5038a2f412c2', 'Are you taking any medications?', 1019804370114, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107525, 'user1', 'dbe26974-a86f-48bc-b0a9-5038a2f412c2', 'Yes, I am on anticoagulants.', 1019804372819, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107526, 'user2', 'dbe26974-a86f-48bc-b0a9-5038a2f412c2', 'Okay.', 1019804386909, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107527, 'user1', 'dbe26974-a86f-48bc-b0a9-5038a2f412c2', 'That''s correct.', 1019804381193, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107528, 'user1', 'dbe26974-a86f-48bc-b0a9-5038a2f412c2', 'Ah yes, I got a tear in my retina.', 1019804375203, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107529, 'user2', 'dbe26974-a86f-48bc-b0a9-5038a2f412c2', 'Right. Also, it''s mentioned here that you have atrial fibrillation.', 1019804369512, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107530, 'user2', 'dc942ed9-e053-4cda-b3f6-ee3eb05fd98f', 'Have you had any procedures in the past?', 1674174517209, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107531, 'user1', 'dc942ed9-e053-4cda-b3f6-ee3eb05fd98f', 'No.', 1674174518238, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107532, 'user3', '6175c468-04d0-41f5-a3b5-16caae96387f', 'Do you have any medical conditions that run in your family that I should know about, ma''am?', 1547511550430, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107533, 'user1', '6175c468-04d0-41f5-a3b5-16caae96387f', 'Um, yeah, my dad had prostate cancer.', 1547511552335, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107534, 'user3', '6175c468-04d0-41f5-a3b5-16caae96387f', 'What about your mother, or the rest of your family?', 1547511559454, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107535, 'user1', '6175c468-04d0-41f5-a3b5-16caae96387f', 'Um, my mom''s brother had Hodgkin''s disease, melanoma, and prostate cancer.', 1547511566824, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107536, 'user2', '2e980ec4-6173-4b19-a5d8-68a02146a963', 'Do you drink?', 1026292822197, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107537, 'user1', '2e980ec4-6173-4b19-a5d8-68a02146a963', 'Not really, no.', 1026292827330, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107538, 'user2', '2e980ec4-6173-4b19-a5d8-68a02146a963', 'Any drugs?', 1026292832875, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107539, 'user2', '2e980ec4-6173-4b19-a5d8-68a02146a963', 'That''s wonderful. How''s work going for you?', 1026292836621, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107540, 'user1', '2e980ec4-6173-4b19-a5d8-68a02146a963', 'I actually got promoted last month so it''s been going well. I''ve had a lot more time to spend with my family as a result.', 1026292857420, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107541, 'user2', '2e980ec4-6173-4b19-a5d8-68a02146a963', 'That''s great to hear. Congratulations!', 1026292838082, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107542, 'user1', '2e980ec4-6173-4b19-a5d8-68a02146a963', 'Thank you so much.', 1026292832756, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107543, 'user1', '2e980ec4-6173-4b19-a5d8-68a02146a963', 'No.', 1026292834671, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107544, 'user2', '2e980ec4-6173-4b19-a5d8-68a02146a963', 'Do you get a chance to exercise during the week?', 1026292838286, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107545, 'user1', '2e980ec4-6173-4b19-a5d8-68a02146a963', 'I like to go on walks with my dog every day. I''m also eating a lot healthier these days.', 1026292830201, 5);
