INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107547, 'user1', '92f53bc6-239e-454d-8615-627ae425c2e8', 'No, I do not have any allergies.', 1246587544793, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107548, 'user2', '92f53bc6-239e-454d-8615-627ae425c2e8', 'Great.', 1246587550408, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107549, 'user2', 'a8d41436-4832-4b76-b905-31bc7009eeb3', 'What do you do in the hospital?', 1008781663790, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107550, 'user1', 'a8d41436-4832-4b76-b905-31bc7009eeb3', 'I work as a phlebotomist and respiratory therapist.', 1008781666363, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107551, 'user1', 'a8d41436-4832-4b76-b905-31bc7009eeb3', 'Thank you!', 1008781673734, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107552, 'user1', 'a8d41436-4832-4b76-b905-31bc7009eeb3', 'So, as you remember I was trying to measure blood gas as I was working with a patient and I accidently jammed that needle inside my right hand index finger.', 1008781699511, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107553, 'user1', 'a8d41436-4832-4b76-b905-31bc7009eeb3', 'I am coming for regular screening.', 1008781702426, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107554, 'user2', 'a8d41436-4832-4b76-b905-31bc7009eeb3', 'Were you wearing gloves?', 1008781703657, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107555, 'user1', 'a8d41436-4832-4b76-b905-31bc7009eeb3', 'Yes, I had gloves and protective clothing.', 1008781676422, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107556, 'user2', 'a8d41436-4832-4b76-b905-31bc7009eeb3', 'Yes, thank you for that. Did they screen patient?', 1008781712111, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107557, 'user1', 'a8d41436-4832-4b76-b905-31bc7009eeb3', 'Yes, he got negative HIV but positive Hep C.', 1008781725127, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107558, 'user2', 'a8d41436-4832-4b76-b905-31bc7009eeb3', 'Ok.', 1008781726524, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107559, 'user1', 'a8d41436-4832-4b76-b905-31bc7009eeb3', 'I am scared.', 1008781717098, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107560, 'user1', 'a8d41436-4832-4b76-b905-31bc7009eeb3', 'I am fifty four.', 1008781675983, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107561, 'user2', 'a8d41436-4832-4b76-b905-31bc7009eeb3', 'You are very young.', 1008781673524, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107562, 'user2', 'a8d41436-4832-4b76-b905-31bc7009eeb3', 'Ok, how old are you?', 1008781670597, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107563, 'user2', '36ddcb61-3dfc-480c-8b07-48ea671433a1', 'They took some fluid out of your back remember?', 1322866481732, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107564, 'user1', '36ddcb61-3dfc-480c-8b07-48ea671433a1', 'Yes actually.', 1322866487253, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107565, 'user1', '36ddcb61-3dfc-480c-8b07-48ea671433a1', 'I got albuterol nebulizer treatment too.', 1322866510974, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107566, 'user2', '36ddcb61-3dfc-480c-8b07-48ea671433a1', 'That is good. but did that help you?', 1322866488834, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107567, 'user1', '36ddcb61-3dfc-480c-8b07-48ea671433a1', 'No, it did not.', 1322866511206, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107568, 'user2', '36ddcb61-3dfc-480c-8b07-48ea671433a1', 'Oh I am sorry.', 1322866512684, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107569, 'user1', '36ddcb61-3dfc-480c-8b07-48ea671433a1', 'It is okay.', 1322866529808, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107570, 'user2', '36ddcb61-3dfc-480c-8b07-48ea671433a1', 'I see that they gave you some antibiotics in E R?', 1322866513871, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107571, 'user1', '36ddcb61-3dfc-480c-8b07-48ea671433a1', 'Yes, Ampicillin and Cefotaxime.', 1322866531273, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107572, 'user1', '36ddcb61-3dfc-480c-8b07-48ea671433a1', 'They checked my urine and blood too.', 1322866492219, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107573, 'user2', '36ddcb61-3dfc-480c-8b07-48ea671433a1', 'We got the results back for that and it looks like it was clear then it turned bloody.', 1322866488990, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107574, 'user2', '36ddcb61-3dfc-480c-8b07-48ea671433a1', 'Yes, they did. I see the orders for urine culture, B M P, C B C, C R P, and blood culture as well.', 1322866505034, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107575, 'user2', '84ed6859-51cb-4c25-9135-31ae6654fb5f', 'Tell me about your medical history. Did you have any surgeries? Any medical issues in the past?', 1053914977832, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107576, 'user1', '84ed6859-51cb-4c25-9135-31ae6654fb5f', 'I had my tonsils removed when I was a kid, maybe around eight. I was hospitalized for the heart attack in ninety six. They did some surgery to check how my heart is functioning and then they did a bypass I guess.', 1053914982737, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107577, 'user1', '84ed6859-51cb-4c25-9135-31ae6654fb5f', 'Yes I had so many surgeries, it''s hard to keep a track of all those complex names. That''s why I keep those papers with me all the time if I go to any new doctor.', 1053914989133, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107578, 'user2', '84ed6859-51cb-4c25-9135-31ae6654fb5f', 'I will add all these surgeries into my record. Thank you.', 1053915012930, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107579, 'user2', '84ed6859-51cb-4c25-9135-31ae6654fb5f', 'That is awesome. Let me have a look. So, according to this you had L I M A to L A D coronary bypass graft. You also had had three saphenous vein grafts performed.', 1053914989706, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107580, 'user2', '84ed6859-51cb-4c25-9135-31ae6654fb5f', 'Do you have some record of those surgeries?', 1053914985045, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107581, 'user1', '84ed6859-51cb-4c25-9135-31ae6654fb5f', 'Oh yes, I got it with me. Here it is.', 1053914983581, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107582, 'user2', '46e7495c-7e66-4367-87f5-1734c2606a26', 'How''s everyone in your family?', 1052480869445, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107583, 'user1', '46e7495c-7e66-4367-87f5-1734c2606a26', 'My mom, dad and siblings are good.', 1052480873674, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107584, 'user2', '46e7495c-7e66-4367-87f5-1734c2606a26', 'They are well, that is good. That''s what we want.', 1052480880829, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107585, 'user1', '46e7495c-7e66-4367-87f5-1734c2606a26', 'Yes.', 1052480874163, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107586, 'user2', '93fcb0a9-502e-4157-aa32-8355059d2c3d', 'So, what do you do for a living, sir?', 1608739222438, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107587, 'user1', '93fcb0a9-502e-4157-aa32-8355059d2c3d', 'I work at A B C store, doctor.', 1608739224993, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107588, 'user1', '93fcb0a9-502e-4157-aa32-8355059d2c3d', 'I''d say I drink socially, like if I''m at a party, or something.', 1608739243256, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107589, 'user1', '93fcb0a9-502e-4157-aa32-8355059d2c3d', 'No, I don''t smoke at all.', 1608739240101, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107590, 'user2', '93fcb0a9-502e-4157-aa32-8355059d2c3d', 'How about alcohol? Do you drink?', 1608739234523, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107591, 'user2', '93fcb0a9-502e-4157-aa32-8355059d2c3d', 'That''s great, do you smoke?', 1608739231410, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107592, 'user3', '286fbced-8470-4ab3-bc0b-fd0246569957', 'Do you take any daily medications or supplements?', 1695867987389, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107593, 'user1', '286fbced-8470-4ab3-bc0b-fd0246569957', 'Nope.', 1695867990950, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107594, 'user2', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Good afternoon, sir, how are you today?', 1030767972354, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107595, 'user1', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Good afternoon, Doctor, my knees are in a lot of pain today.', 1030767977844, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107596, 'user2', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Is the pain equal? Or is one knee worse than the other?', 1030767975561, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107597, 'user2', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Are you able to go up and down stairs?', 1030767998787, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107598, 'user1', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'I have to take them one at a time.', 1030768007591, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107599, 'user2', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'I see you have degenerative joint disease of both knees, does that ring any bells?', 1030768013143, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107600, 'user1', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Yes, but what does that mean?', 1030767985314, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107601, 'user2', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'You have arthritis in both of your knees, sir.', 1030767984341, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107602, 'user1', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Ah, yes.', 1030768030192, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107603, 'user2', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Have you had surgery on these knees?', 1030768036370, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107604, 'user1', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Um, I had surgery on both of these knees, let me check my notes. It was an, um, arthroscopy.', 1030768028211, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107605, 'user2', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'When were these surgeries?', 1030768020803, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107606, 'user1', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'They were in the nineteen ninety one nineteen ninety two time frame, somewhere in there.', 1030768057680, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107607, 'user2', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'How have you managed this since the surgeries?', 1030768026490, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107608, 'user1', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'I''ve taken antiinflammatories, had injections, and I''ve even used narcotics.', 1030768005894, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107609, 'user2', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'I see. If those haven''t helped, I think you''d be a good candidate for knee replacements.', 1030768076383, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107610, 'user1', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Can we do both at the same time?', 1030768051605, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107611, 'user2', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'No, let''s do the left since that one hurts more. Do you have any other conditions I should know about?', 1030768008997, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107612, 'user1', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'I''ve had a lot of back surgeries, I have spinal stenosis.', 1030768054423, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107613, 'user2', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Do you know what surgeries you''ve had?', 1030768012099, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107614, 'user1', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Let me check my notes, um, I''ve had a spinal decompression and epidural steroids injection.', 1030768000852, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107615, 'user2', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Who has prescribed you narcotics for this pain?', 1030768035289, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107616, 'user1', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'The pain is so bad, but Doctor X has handled those.', 1030768028393, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107617, 'user1', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Um, the left knee hurts more than the right, but there''s pretty significant pain with both.', 1030767986336, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107618, 'user2', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Is it interfering with your ability to walk?', 1030767990165, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107619, 'user1', 'dfba03dd-e38e-4dcd-a121-beceeee39691', 'Yes, I can walk like, maybe a half a mile a day, then the pain gets too bad.', 1030767997710, 5);
