INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107624, 'user1', '69c56530-ac7b-457a-9610-cb16f0fb4d61', 'No, I don''t drink.', 1659262475413, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107625, 'user2', '69c56530-ac7b-457a-9610-cb16f0fb4d61', 'How much?', 1659262478940, 2);
