INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107627, 'user2', '69c56530-ac7b-457a-9610-cb16f0fb4d61', 'Okay that is not bad, but try quitting.', 1659262488411, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107628, 'user2', '8def371a-093d-4824-9f8b-efd45343e945', 'Hi Ryan, what brings you here today?', 1336502555746, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107629, 'user1', '8def371a-093d-4824-9f8b-efd45343e945', 'Well, you told me to follow up if my cough doesn''t get better. Also, I started having several other issues.', 1336502557575, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107630, 'user1', '8def371a-093d-4824-9f8b-efd45343e945', 'It''s about the same but not getting better.', 1336502565344, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107631, 'user2', '8def371a-093d-4824-9f8b-efd45343e945', 'Hm. And what about your diarrhea and stomach pain?', 1336502573351, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107632, 'user1', '8def371a-093d-4824-9f8b-efd45343e945', 'No more diarrhea and no pian.', 1336502573214, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107633, 'user2', '8def371a-093d-4824-9f8b-efd45343e945', 'Bowel movement?', 1336502571966, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107634, 'user1', '8def371a-093d-4824-9f8b-efd45343e945', 'Normal.', 1336502607283, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107635, 'user2', '8def371a-093d-4824-9f8b-efd45343e945', 'Any pain while peeing? Are you able to empty your bladder completely?', 1336502608340, 10);
