INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107666, 'user1', 'eb71b2b7-285e-403b-8cb9-621e59e3eb9e', 'They asked me to go to the physical therapy for all the problems I was having after my brain surgery. I went from November fifth to the fourteenth of last year. I did therapy for around two weeks starting on November fifth. My problems were not solved so I went to the hospital and then they did some tests and they found out something was wrong. They said there is swelling in my brain so they admitted me there and then I had my second surgery.', 965357049800, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107667, 'user1', 'eb71b2b7-285e-403b-8cb9-621e59e3eb9e', 'He is my husband, Al.', 965357036160, 6);
