INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107670, 'user3', 'eb71b2b7-285e-403b-8cb9-621e59e3eb9e', 'Was there any other issue?', 965357040252, 12);
