INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107736, 'user1', 'e64ed5f9-ff17-4837-ae39-01a6ac713e8d', 'Ah yes, in the beginning of May, I got a spell of severe cough and because of continuous coughing I think I developed pain in my hip which travels down to my legs.', 1320888598087, 32);
