INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107752, 'user2', '340bb91d-334a-4d6e-a099-ddae139c138c', 'So, you saw Doctor X?', 1309878064546, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107753, 'user2', '340bb91d-334a-4d6e-a099-ddae139c138c', 'Yeah, I couldn''t get hold of Doctor Z but here is the phone number. You should book the appointment.', 1309878087974, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107754, 'user1', '340bb91d-334a-4d6e-a099-ddae139c138c', 'Okay I will do that.', 1309878081213, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107755, 'user2', '340bb91d-334a-4d6e-a099-ddae139c138c', 'Also, I would like to follow up with your endocrinologist that is Doctor A for adjustments that is needed in your insulin pump.', 1309878076092, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107756, 'user1', '340bb91d-334a-4d6e-a099-ddae139c138c', 'And you want me to see my gastro doc too?', 1309878085508, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107757, 'user2', '340bb91d-334a-4d6e-a099-ddae139c138c', 'Yes, please follow up with Doctor B for issues with your J tube.', 1309878088392, 8);
