INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107759, 'user2', '340bb91d-334a-4d6e-a099-ddae139c138c', 'Lastly, I want you to see Doctor Y if your condition changes regarding colon cancer.', 1309878089851, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107760, 'user1', '340bb91d-334a-4d6e-a099-ddae139c138c', 'Yes, seven days back. I went to get my blood work done and then I followed up with Doctor Y.', 1309878069442, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107761, 'user2', '340bb91d-334a-4d6e-a099-ddae139c138c', 'Yes, I will look at C B C diff and C M P profile.', 1309878069567, 2);
