INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107808, 'user1', 'eec530c0-2b59-46e1-8762-93e591d06f37', 'Uh no. I''ve lost about eighteen pounds in the last month but other than that everything else seems to be fine.', 964979102947, 19);
