INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107833, 'user3', '3af6f058-48f5-43f8-9f06-93b9b89e6151', 'Great, does he have any difficulty urinating?', 979502861610, 12);
