INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107835, 'user3', '3af6f058-48f5-43f8-9f06-93b9b89e6151', 'Bowel movements? How are they?', 979502834162, 14);
