INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107845, 'user1', '868510da-1399-41a2-a527-60341c72f287', 'I am fifty four years old.', 1439672420730, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107846, 'user1', '868510da-1399-41a2-a527-60341c72f287', 'I feel like my tongue is swollen.', 1439672411391, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107847, 'user3', '92cba721-1f41-4908-907f-328114a39c43', 'So, I think we need to start you on antibiotics for that ulcer on your right foot and possible osteomyelitis. I will send a prescription to your pharmacy.', 973197269780, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107848, 'user1', '92cba721-1f41-4908-907f-328114a39c43', 'Sure.', 973197271073, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107849, 'user3', 'a2ef9745-91b5-43b5-a9bc-3b08088ee812', 'Your condition is improved, and you look pretty stable.', 1513346800547, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107850, 'user1', 'a2ef9745-91b5-43b5-a9bc-3b08088ee812', 'Yeah, I feel much better.', 1513346805101, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107851, 'user2', 'a3fbc0cf-9a20-4b91-a871-816cc14cb82d', 'Do you have any allergies to medications?', 1181085544987, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107852, 'user1', 'a3fbc0cf-9a20-4b91-a871-816cc14cb82d', 'Yes. Penicillin.', 1181085546042, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107853, 'user2', 'd4cfe95d-7e41-4954-898d-926a6fad3fe2', 'Looks like you have a U T I and I need to give you some antibiotics to treat it.', 1432699350773, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107854, 'user2', 'd4cfe95d-7e41-4954-898d-926a6fad3fe2', 'Are you taking any other medications?', 1432699370794, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107855, 'user1', 'd4cfe95d-7e41-4954-898d-926a6fad3fe2', 'Yes, I am taking quite a few. I always carry the list of my medications, let me tell you the names.  Yeah, so I take Dilantin for my seizures, Toprol for my high blood pressure and Pravachol for my cholesterol.', 1432699375226, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107856, 'user2', 'd4cfe95d-7e41-4954-898d-926a6fad3fe2', 'Pravachol for my cholesterol. Wow, thank you for that, it helps a lot. Let me make a note of it.', 1432699379935, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107857, 'user1', 'd4cfe95d-7e41-4954-898d-926a6fad3fe2', 'Sure.', 1432699386471, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107858, 'user2', 'd4cfe95d-7e41-4954-898d-926a6fad3fe2', 'I will write you a prescription for Macrobid. Are you still using the Walgreens pharmacy at Thrashers Corner?', 1432699352978, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107859, 'user1', 'd4cfe95d-7e41-4954-898d-926a6fad3fe2', 'Yes.', 1432699358357, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107860, 'user1', 'd4cfe95d-7e41-4954-898d-926a6fad3fe2', 'Okay.', 1432699352606, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107861, 'user2', '478790c0-67f4-4b04-8402-37c433c9c2e5', 'Have you had any operations in the-', 1431818406979, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107862, 'user1', '478790c0-67f4-4b04-8402-37c433c9c2e5', 'Nope. No surgeries.', 1431818409075, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107863, 'user1', '478790c0-67f4-4b04-8402-37c433c9c2e5', 'Nope.', 1431818422240, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107864, 'user2', '478790c0-67f4-4b04-8402-37c433c9c2e5', 'How about any past injuries or illnesses?', 1431818417545, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107865, 'user3', '71a47e81-87e7-4afc-87de-27498e67bb52', 'What is going on?', 1171804743192, 0);
