INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107868, 'user1', '71a47e81-87e7-4afc-87de-27498e67bb52', 'Not that bad.', 1171804750226, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107869, 'user3', '48651bc7-8e16-4199-bb98-c3fae1c7ba79', 'Have you taken any medications in the past?', 1103595001708, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107870, 'user1', '48651bc7-8e16-4199-bb98-c3fae1c7ba79', 'Do you mean prescription, or over the counter?', 1103595006510, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107871, 'user3', '48651bc7-8e16-4199-bb98-c3fae1c7ba79', 'Either of those.', 1103595004916, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107872, 'user1', '48651bc7-8e16-4199-bb98-c3fae1c7ba79', 'Oh, I haven''t taken anything in the past.', 1103595015459, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107873, 'user1', '6cfc4ac2-dfe4-4a06-9e4c-747d6ce80213', 'I''ve been following the A D A diet online and maxing out at around eighteen hundred calories per day.', 1674034614262, 1);
