INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107875, 'user2', '6cfc4ac2-dfe4-4a06-9e4c-747d6ce80213', 'Any changes to your diet?', 1674034609963, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107876, 'user1', '6cfc4ac2-dfe4-4a06-9e4c-747d6ce80213', 'A lot better actually. My blood sugar isn''t as high as it used to be.', 1674034616682, 3);
