INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107878, 'user2', 'e567e544-4c9f-40ff-9f0e-fc3effb8d6c3', 'Are you still undergoing treatment?', 1201816754688, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107879, 'user1', 'e567e544-4c9f-40ff-9f0e-fc3effb8d6c3', 'Yes.', 1201816747757, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107880, 'user2', 'e567e544-4c9f-40ff-9f0e-fc3effb8d6c3', 'Do you have any other medical conditions?', 1201816762166, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107881, 'user1', 'e567e544-4c9f-40ff-9f0e-fc3effb8d6c3', 'Have a heart murmur. It has not been an issue. I also have acid reflux.', 1201816770893, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107882, 'user2', 'e567e544-4c9f-40ff-9f0e-fc3effb8d6c3', 'Do you take medication for the G E R D?', 1201816772077, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107883, 'user1', 'e567e544-4c9f-40ff-9f0e-fc3effb8d6c3', 'Yes. I take omeprazole.', 1201816787156, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107884, 'user1', 'e567e544-4c9f-40ff-9f0e-fc3effb8d6c3', 'I was diagnosed with stage three ovarian cancer two years ago. They found a tumor in my upper abdomen. I had surgery and they removed everything. Doctor King is my oncologist.', 1201816749419, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107885, 'user1', 'e567e544-4c9f-40ff-9f0e-fc3effb8d6c3', 'I am doing okay.', 1201816738476, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107886, 'user2', 'e567e544-4c9f-40ff-9f0e-fc3effb8d6c3', 'Tell me about your past medical history.', 1201816746519, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107887, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Hello, miss. Before we begin your physical, could you verify your age and ethnicity for me, please?', 1498394038448, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107888, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Oh, no. Has anything changed that may have made your allergies worse?', 1498394052280, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107889, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Well, my husband has been hauling more corn in since it''s busy season. I think that might have made it worse.', 1498394050721, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107890, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Are you taking any medications to alleviate your asthma and allergies?', 1498394073820, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107891, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'I''m using my inhaler every day for my asthma. Here are the other medications and treatments I''ve been using. I know I wouldn''t have remembered, so I put them on a paper for you to see.', 1498394078040, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107892, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Let me take a look. I see you have been taking Allegra for your allergies. Has that been helping?', 1498394052988, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107893, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Eh. It kind of helps when I do take it.', 1498394064811, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107894, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'You don''t take it every day then?', 1498394048542, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107895, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Nope. Only when I feel like I need to.', 1498394065694, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107896, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'I see. What about the Flonase? Has that been helping?', 1498394061756, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107897, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'I''m not taking that right now, but it helped me in the past.', 1498394083374, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107898, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'I also see you took Advair in the past, correct? Do you still take it?', 1498394077433, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107899, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'I did, but I stopped taking it because it started to annoy my private area.', 1498394079619, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107900, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'I understand. Speaking more on this. Let''s begin your physical. Do you have anything you''d like to add that you''re starting to notice more?', 1498394120953, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107901, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Oh, yeah. I feel like I''m easily annoyed right before my period. It could also be my husband, but he likes to say it''s because I''m about to start my period.', 1498394058784, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107902, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'I see. Do you see any other increased symptoms right before your menstrual cycle?', 1498394066597, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107903, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Yeah. I feel like I''ve seen an increase in all the signs before my period. I''m also getting more impatient around that time, but when I''m not on my period, I feel like my mood is better.', 1498394131582, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107904, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'When do you see your mood change?', 1498394123750, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107905, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'My husband says it''s bad the week before I start my period, but I think it gets better a day after I start.', 1498394119702, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107906, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Have you seen any bleeding during your cycle?', 1498394126530, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107907, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Not as much anymore. Just some spots here and there.', 1498394110555, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107908, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'I see. What about hot flashes or night sweats?', 1498394085842, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107909, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Nope. I feel fine most of the time.', 1498394071481, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107910, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'That''s good. I''m looking at your chart right now and it says you showed a U T I present, correct? Your test showed blood in your urine.', 1498394156049, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107911, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Yeah, that''s correct.', 1498394094632, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107912, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Has your urine been checked since then?', 1498394076932, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107913, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Nope.', 1498394106126, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107914, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'I see. I''ll order another urine test along with additional lab tests so that we can complete your physical.', 1498394192680, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107915, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'I actually just had some lab work done because it was required for a life insurance application. Crazy, right? Here''s the form with all the details for the lab work.', 1498394087090, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107916, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Oh, perfect. I see they looked at your cholesterol and other areas. Could you send that to me when you get the results?', 1498394150966, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107917, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Of course. I''ll get that sent to you A S A P.', 1498394094113, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107918, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'That''s right. Oh, man. My asthma has been getting worse over the last three months. My allergies are also acting up again.', 1498394047217, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107919, 'user1', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'I''m forty two years old and identify as white.', 1498394043760, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107920, 'user3', 'a2c1db0b-41d3-4571-ba04-618be6e7c176', 'Thank you. I also see that you''re here for a follow up for your asthma, correct? How is your asthma?', 1498394044881, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107921, 'user2', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'How are your parents doing, sir?', 1025399605331, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107922, 'user2', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'Remind me, please, how old are they?', 1025399628341, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107923, 'user1', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'One of them is sixty eight, and the other is seventy seven. I''m in the middle.', 1025399625761, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107924, 'user2', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'That''s great. Do you have any medical conditions that run in your family?', 1025399636344, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107925, 'user1', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'Well, I''m not sure if it counts, but I had a brother and sister, they were twins, they died at birth.', 1025399646476, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107926, 'user2', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'Oh no, thank you for telling me.', 1025399637901, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107927, 'user1', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'Yes, I thought it would be important.', 1025399646421, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107928, 'user2', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'Do you have any children, sir?', 1025399623757, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107929, 'user1', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'Yes, I have two sons, they''re both doing very well.', 1025399664555, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107930, 'user2', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'How old are your sons?', 1025399637525, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107931, 'user1', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'One of them is fifty four, and the other is fifty seven.', 1025399640426, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107932, 'user2', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'In addition to the neonatal deaths, do you have any other conditions that I should know about?', 1025399655686, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107933, 'user1', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'Yeah, um, a lot of my family has diabetes, and a lot of them have had heart attacks as well.', 1025399646727, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107934, 'user2', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'I''m so sorry to hear that, sir. How about your brothers?', 1025399610682, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107935, 'user1', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'Thank you, doctor. Both of my brothers are doing very well.', 1025399611050, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107936, 'user1', '1cad43ee-04cf-46ef-8ae6-90d3498c5cc7', 'Well, doctor, I''ve lost both of them now.', 1025399608523, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107937, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'Hello, ma''am. What is the reason for your visit today?', 1384437605017, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107938, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'I was referred by a doctor to come see you so that you could check up on my nasal problems. Here is my report from my previous doctor who referred me to you.', 1384437609570, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107939, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'I see. Thank you for describing it to me.', 1384437622844, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107940, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'No problem. Would you be able to describe to me what you had been feeling two to three months ago?', 1384437612499, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107941, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'Yeah, I can. My face would feel uncomfortable, my nose was stuffy, my eyes hurt, and I felt something dropping in the back of my throat.', 1384437635541, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107942, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'Have you ever been prescribed any medication?', 1384437631740, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107943, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'Here''s the list of medicine I was taking.', 1384437642306, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107944, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'I see you were given antibiotics, correct?', 1384437630866, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107945, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'I was, but I don''t know what those are. Could you explain them to me?', 1384437634373, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107946, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'Antibiotics are usually used to fight infections.', 1384437621222, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107947, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'I had an infection? I thought I just had some nasal problems.', 1384437678414, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107948, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'Your report states you had a severe infection. Do you remember if the antibiotics helped?', 1384437682557, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107949, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'Not really. I felt like my symptoms were the same.', 1384437657117, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107950, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'I see. Did your doctor order any advanced imaging''s?', 1384437665573, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107951, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'Yeah. They did a C T scan of my nose. Here is the report from my C T scan.', 1384437639450, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107952, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'Let me take a look. It looks like you had some thickening of the mucosal layer in your right paranasal sinus. You also had some obstruction in your right ostiomeatal complex and excess growing of some of the bones in your nose. Uhm. Oh, one more thing. I see your nasal septum was shifted to the left.', 1384437626043, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107953, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'Oh, wow. Thank you for explaining everything to me.', 1384437639423, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107954, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'No problem. Going back to your list of medications, I know you took antibiotics for your infection, but did you take any medication for your sinuses?', 1384437723649, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107955, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'No, I haven''t. I did try this cream for my nose, but that didn''t work either. Nothing worked!', 1384437649858, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107956, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'I see. Looks like the cream you used was a topical nasal corticosteroid. Are there any other symptoms that you have been experiencing?', 1384437658483, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107957, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'I''ve had some trouble with my balance, and I feel like I''ve lost some of my hearing. I thought this was odd since I''m only fifty years old. I think my ears felt plugged or full of air, so they just needed to pop.', 1384437683214, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107958, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'I see. Let''s perform an audiogram test to check your ears.', 1384437643297, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107959, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'Sounds good.', 1384437708409, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107960, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'I''m seeing that you have some mild high frequency sensorineural hearing loss. Your tympanometry seems to be normal. Your speech discrimination was also normal.', 1384437642414, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107961, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'That''s reassuring.', 1384437726538, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107962, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'I want to ask a few more questions about your ears. Do you feel any fullness or pressure?', 1384437736344, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107963, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'No, I don''t feel anything like that right now.', 1384437671823, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107964, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'Do you hear any humming, buzzing, or roaring sounds?', 1384437781807, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107965, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'Nope. I don''t hear anything like that.', 1384437742035, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107966, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'We checked your ears and now understand more about the problem, but I wonder why your balance is affected. When did you start noticing your balance was affected?', 1384437769838, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107967, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'I think it could have been to this one medicine that starts with an A. I forgot the name, but it didn''t really help my nasal problems. It just made my balance worse.', 1384437762300, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107968, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'Was the medicine called Allegra?', 1384437691332, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107969, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'Oh, yeah. That''s what it was called. I thought I had some sort of allergy, so I thought it would help.', 1384437779631, 35);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107970, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'I see. Did you ever feel any dizziness too?', 1384437804381, 36);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107971, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'Yeah, I did.', 1384437693741, 37);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107972, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'I will have you do some movements to see if your dizziness occurs.', 1384437670972, 38);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107973, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'Sounds good.', 1384437783584, 39);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107974, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'Could you look to the left and then look to the right.', 1384437673667, 40);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107975, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'Oh, wow. That made me very dizzy.', 1384437780295, 41);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107976, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'Looks like sudden movements and head turning make your dizziness worse.', 1384437769098, 42);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107977, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'Yeah, it is. Sinusitis is the inflammation of your nasal airways.', 1384437613418, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107978, 'user3', '90445264-f8b5-450d-b521-10f319ecf942', 'Thank you. Let me take a look.  I see here it says you had severe sinusitis two to three months ago, correct?', 1384437613090, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107979, 'user1', '90445264-f8b5-450d-b521-10f319ecf942', 'Is that what they''re calling my nasal problems?', 1384437619085, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107980, 'user3', 'dca73548-f0fc-424f-bfd5-977eb12ab620', 'Is there anyone that lives with you at home? You are going to need someone to help you care for your wound.', 1572469052459, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107981, 'user1', 'dca73548-f0fc-424f-bfd5-977eb12ab620', 'My wife lives at home with me.  She can help me change my bandages.', 1572469055982, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107982, 'user2', '87684d3a-8656-416e-9491-5751a5b56a2e', 'Hello. Looks like you''re having surgery today.', 966469864384, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107983, 'user1', '87684d3a-8656-416e-9491-5751a5b56a2e', 'Yeah, I am. I forgot what the surgery was, but it says it in my report.', 966469870068, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107984, 'user2', '87684d3a-8656-416e-9491-5751a5b56a2e', 'I''m looking at it right now. Looks like you had a PermCath inserted three times and received peritoneal dialysis', 966469872050, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107985, 'user3', '59244f74-bf1b-4bfa-ace0-ba1f5a50cb73', 'So, what is happening with you?', 1131110077306, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107986, 'user1', '59244f74-bf1b-4bfa-ace0-ba1f5a50cb73', 'I had knee replacement for both my knees three years ago and now I am having some pain.', 1131110082644, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107987, 'user3', '59244f74-bf1b-4bfa-ace0-ba1f5a50cb73', 'Okay and in one or both knees?', 1131110086023, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107988, 'user1', '59244f74-bf1b-4bfa-ace0-ba1f5a50cb73', 'Both.', 1131110080990, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107989, 'user3', '59244f74-bf1b-4bfa-ace0-ba1f5a50cb73', 'Okay.', 1131110081538, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107990, 'user3', '4302aebb-7440-41d2-8e6e-3f904f69fef2', 'Hi!', 1002924980208, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107991, 'user1', '4302aebb-7440-41d2-8e6e-3f904f69fef2', 'Hello!', 1002924982415, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107992, 'user3', '4302aebb-7440-41d2-8e6e-3f904f69fef2', 'How are you feeling now?', 1002924991160, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107993, 'user1', '4302aebb-7440-41d2-8e6e-3f904f69fef2', 'I am feeling okay.', 1002924995632, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107994, 'user3', '4302aebb-7440-41d2-8e6e-3f904f69fef2', 'Yeah, looks like your condition is improving.', 1002924989018, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107995, 'user1', '4302aebb-7440-41d2-8e6e-3f904f69fef2', 'Yes, I think so too.', 1002925010084, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107996, 'user2', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'And who are we seeing today?', 1477489415964, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107997, 'user1', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'Hi Doctor, this my son J and that''s my wife.', 1477489418107, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107998, 'user1', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'Hi there', 1477489426740, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (107999, 'user1', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'Autism?', 1477489451883, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108000, 'user2', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'No, I mean when did he start complaining of stomach pain?', 1477489433290, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108001, 'user1', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'It started last night.', 1477489429702, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108002, 'user2', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'Oh okay, let me check him. Did he have any nausea or vomiting?', 1477489463512, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108003, 'user1', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'Yes, he threw up a lot and is refusing to eat or drink anything.', 1477489451008, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108004, 'user2', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'And then he is complaining of tummy pain?', 1477489481408, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108005, 'user1', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'Yes.', 1477489479337, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108006, 'user2', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'Well, the good part is he is not dehydrated.', 1477489458165, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108007, 'user2', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'Any diarrhea?', 1477489480146, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108008, 'user1', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'Yes, he went three to four times.', 1477489435183, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108009, 'user2', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'Hm, but no blood or anything in the stools or vomit?', 1477489452331, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108010, 'user1', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'No, nothing like that, we did not notice anything.', 1477489516405, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108011, 'user2', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'Okay good.', 1477489488459, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108012, 'user2', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'Well, let me run some tests but the signs and symptoms sound like he might have a stomach flu, also called as gastroenteritis in medical terms. I will start him on some medicines and hopefully that should help.', 1477489523804, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108013, 'user2', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'For how long now?', 1477489421989, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108014, 'user2', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'Well, hello young man how are you feeling today?', 1477489423102, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108015, 'user1', '319d2d85-6030-443a-8ea5-7c5a9f01f298', 'He has been complaining of severe tummy pain and was crying the whole time. We are worried as he is a special child. He has autism.', 1477489429347, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108016, 'user2', '37e79afd-d4b6-4bf9-9646-d2642d434452', 'Hello, nice to meet you, miss. I will be taking care of you today. Before we start, can I get to know you a bit? I like to know who I am treating.', 1225299108279, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108017, 'user1', '37e79afd-d4b6-4bf9-9646-d2642d434452', 'Hello, nice to meet you. Of course. Um, what can I say? I am a recent widow. My husband passed when we were married for only eight years. I am also retired and loving every minute of it.', 1225299110224, 1);
