INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108121, 'user2', 'a109a2df-8b31-4bc0-9b6c-32c6819086b2', 'Now, let''s talk about your family history. Have any of them had cancer?', 1732618966401, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108122, 'user1', 'a109a2df-8b31-4bc0-9b6c-32c6819086b2', 'Actually, yes, I know a few family members have, but I can''t remember who had what kind.', 1732618969801, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108123, 'user1', 'a109a2df-8b31-4bc0-9b6c-32c6819086b2', 'Yes, that rings some bells.', 1732618979696, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108124, 'user2', 'a109a2df-8b31-4bc0-9b6c-32c6819086b2', 'That''s okay. What about heart disease? Can you remember anyone having that?', 1732618973288, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108125, 'user2', 'a109a2df-8b31-4bc0-9b6c-32c6819086b2', 'Thank you, has anyone in your family had a joint replacement?', 1732618971532, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108126, 'user1', 'a109a2df-8b31-4bc0-9b6c-32c6819086b2', 'I know that a lot of my family has had arthritis in the past, but I can''t remember whether or not they had joint replacements, honestly.', 1732618988332, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108127, 'user3', 'c41e38f9-f054-47ab-bc81-4b90400440f3', 'Hi, how are you?', 1611341228008, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108128, 'user3', 'c41e38f9-f054-47ab-bc81-4b90400440f3', 'Oh, let me take a look. Which side?', 1611341248149, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108129, 'user1', 'c41e38f9-f054-47ab-bc81-4b90400440f3', 'On my right hip.', 1611341237085, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108130, 'user3', 'c41e38f9-f054-47ab-bc81-4b90400440f3', 'Okay, I see it. Looks like you have developed pressure ulcer.', 1611341263740, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108131, 'user1', 'c41e38f9-f054-47ab-bc81-4b90400440f3', 'I am good, how about you?', 1611341232611, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108132, 'user3', 'c41e38f9-f054-47ab-bc81-4b90400440f3', 'Well, I am good too, thank you for asking. So, what brings you here?', 1611341235547, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108133, 'user1', 'c41e38f9-f054-47ab-bc81-4b90400440f3', 'Um, I have developed this painful ulcer on my hip.', 1611341239109, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108134, 'user2', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'Okay, tell me what''s going on and what''s brought you here.', 1312731909620, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108135, 'user2', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'Did you get the test result?', 1312731928682, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108136, 'user1', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'I got it today. Here is the report.', 1312731925179, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108137, 'user2', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'Okay, let me have a look. It says she is having a growing M R S A.', 1312731933601, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108138, 'user1', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'Yeah, I''ve been diagnosed with that too. And I am on medications. I had it on my buttock area.', 1312731948489, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108139, 'user2', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'Okay, so you know about it, and I don''t have to explain it more.', 1312731957344, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108140, 'user1', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'Yeah.', 1312731933717, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108141, 'user2', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'So how is the blister on the umbilicus now?', 1312731925199, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108142, 'user1', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'I am her mother. She has this blister on the side of her head right above her ear, here. I was just worried and concerned about my baby.', 1312731913377, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108143, 'user2', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'You did good. I will start the treatment. How are her eating and sleeping habits?', 1312731958019, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108144, 'user1', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'She hasn''t missed any of her meals. She is taking around two ounces of milk in every feed. I don''t think I have any issues with her eating or sleeping.', 1312731941015, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108145, 'user2', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'Did she have any fever?', 1312731969814, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108146, 'user1', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'Not that I noticed.', 1312731973343, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108147, 'user2', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'Has she been lethargic or crying more than normal?', 1312732003874, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108148, 'user1', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'No.', 1312731963902, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108149, 'user2', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'Any other changes in her daily routine that you might have noticed?', 1312731999043, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108150, 'user1', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'No, I didn''t notice any changes.', 1312731981703, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108151, 'user2', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'How old is the baby? When did you first notice it?', 1312731921032, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108152, 'user1', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'She is just fourteen days old. Let me tell you from the beginning. On Friday, when I was taking her for a bath, I noticed a blister near her umbilicus area. We went to our doctor on Saturday, and they did a test.', 1312731926517, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108153, 'user1', '6f362ca4-dc66-46fd-96e2-9681a88c9816', 'She has been doing good. We put on some bacitracin ointment, and it almost healed up. But today I noticed that another small blister on her head. It really scared me, and I did not want to take any chance. That''s why I reached out to the Infectious Disease center. I know it is private. But still, I don''t want to take any chance with my baby''s health. I called the center directly and they asked me to come to the hospital.', 1312731936073, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108154, 'user1', '51e840aa-1003-44fe-9d48-e089b4ce3d37', 'I am in pain. I get these frequent episodes of pain and discomfort in my head.', 1651774433199, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108155, 'user1', '51e840aa-1003-44fe-9d48-e089b4ce3d37', 'Sometimes it is overall and other times just on any one side. Doctor: This sounds like it is a migraine headache.', 1651774435674, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108156, 'user2', '51e840aa-1003-44fe-9d48-e089b4ce3d37', 'Is it in any side of head or is it overall?', 1651774434835, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108157, 'user3', '55014417-6ef0-412d-bcbd-8c520318efd7', 'Good afternoon, young man. Is this your mother?', 1505071277181, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108158, 'user1', '55014417-6ef0-412d-bcbd-8c520318efd7', 'Hi, doctor. Yes, this is my mom.', 1505071278899, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108159, 'user3', '55014417-6ef0-412d-bcbd-8c520318efd7', 'Good, can you tell me more about your son, ma''am?', 1505071283068, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108160, 'user3', '55014417-6ef0-412d-bcbd-8c520318efd7', 'How has he responded to the Adderall?', 1505071304394, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108161, 'user3', '55014417-6ef0-412d-bcbd-8c520318efd7', 'He''s been taking Adderall, correct? How long has he been taking this?', 1505071290491, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108162, 'user3', '55014417-6ef0-412d-bcbd-8c520318efd7', 'That''s great!', 1505071321382, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108163, 'user1', '55014417-6ef0-412d-bcbd-8c520318efd7', 'Yes, but I have two concerns. When he takes the medicine first thing in the morning it seems to take a while to kick in, and then it wears off at about two P M and he has problems in the evening.', 1505071303098, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108164, 'user3', '55014417-6ef0-412d-bcbd-8c520318efd7', 'Has he had problems with his appetite?', 1505071336765, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108165, 'user1', '55014417-6ef0-412d-bcbd-8c520318efd7', 'Um, he did at first, but it''s been coming back. It''s more of a problem in the morning when he first takes the medicine in the morning, not so much in the afternoon after it wears off.', 1505071299131, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108166, 'user1', '55014417-6ef0-412d-bcbd-8c520318efd7', 'It''s been about a month now.', 1505071300812, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108167, 'user1', '55014417-6ef0-412d-bcbd-8c520318efd7', 'Sure, well, he''s six years old now, and we''re here to follow up his A D H D medicines.', 1505071280533, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108168, 'user3', '55014417-6ef0-412d-bcbd-8c520318efd7', 'Has he taken every dose?', 1505071292941, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108169, 'user1', '55014417-6ef0-412d-bcbd-8c520318efd7', 'Well, I missed one last weekend, and he was just horrible.', 1505071306632, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108170, 'user1', '55014417-6ef0-412d-bcbd-8c520318efd7', 'Yeah, mommy, I thought I needed it, but you didn''t give it to me.', 1505071324050, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108171, 'user1', '55014417-6ef0-412d-bcbd-8c520318efd7', 'They have seen a dramatic improvement with it.', 1505071344405, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108172, 'user1', '55014417-6ef0-412d-bcbd-8c520318efd7', 'The first day he took it, truthfully, he was wonderful. There''s been a lot of improvement in his behavior, and he''s really been doing well, so far.', 1505071289376, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108173, 'user3', '55014417-6ef0-412d-bcbd-8c520318efd7', 'Have you gotten any reports from his teachers?', 1505071341827, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108174, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Good afternoon, sir. Welcome in. Let''s get started, how old are you?', 1365122639352, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108175, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Good afternoon, doctor. I''m fifty two years old.', 1365122642467, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108176, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Right now, I''m a temporary employee for A B C A B C, I''ve worked for A B C D, too.', 1365122654050, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108177, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'What do you do there?', 1365122660857, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108178, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Mainly, I handle the loading and unloading of furniture and appliances for people''s houses.', 1365122651375, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108179, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'That''s hard work. When did you get hurt?', 1365122663372, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108180, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'It was about two and a half weeks ago now, back in October.', 1365122678322, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108181, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Do you have a history of back problems, like before this injury?', 1365122655817, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108182, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Yeah, I''ve had back pain for a long time.', 1365122696751, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108183, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'What happened when you got hurt this time?', 1365122688025, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108184, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'I was unloading one of the A B C eighteen wheelers, when I bent down to pick up some boxes, and I felt the pain.', 1365122712244, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108185, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'What kind of pain did you feel?', 1365122692688, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108186, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'I felt a sharp pain in my lower back right away when I tried to lift those boxes.', 1365122687134, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108187, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Does your pain go down your legs?', 1365122669797, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108188, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Yes, it goes into the right side of my butt, and then all the way down the outside of my right leg, like into the knee.', 1365122696869, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108189, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'How have your symptoms progressed since they began?', 1365122726420, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108190, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Doctor, they''ve only gotten worse.', 1365122694136, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108191, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Do you have any pain in your left leg?', 1365122745781, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108192, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'A little, not as bad as the right.', 1365122686896, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108193, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'What other symptoms are you having besides the pain down your leg?', 1365122745718, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108194, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'The muscles in my butt are spazzing, and it''s happening more and more.', 1365122722141, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108195, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Have you seen another doctor for this?', 1365122692400, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108196, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Yes, I saw Doctor Z at first.', 1365122744488, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108197, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'What did they do for you?', 1365122690275, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108198, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'He gave me some muscle relaxers, and some, um, Lidocaine patches.', 1365122755876, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108199, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Did this help at all?', 1365122788710, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108200, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'No, not at all.', 1365122770281, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108201, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Who else have you seen?', 1365122817936, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108202, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'I saw doctor X Y Z too, through worker''s comp.', 1365122818788, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108203, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'When did you see them?', 1365122715915, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108204, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'That was back in April.', 1365122743981, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108205, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'What did they recommend?', 1365122790455, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108206, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Um, he sent me for an M R I, and I have the report for that right here.', 1365122790690, 35);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108207, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Okay, this M R I report is basically negative, which is good. Did he give you any medications?', 1365122782408, 36);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108208, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Yes, he gave me some opioids.', 1365122796527, 37);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108209, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Wow, that''s strong stuff. What is your work status right now?', 1365122686268, 38);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108210, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'Doctor X Y Z put me on restricted duty status, doctor.', 1365122685478, 39);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108211, 'user3', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'I''m reading your notes from doctor X Y Z, he says he released you in June, and that you have reached maximum medical improvement.', 1365122870492, 40);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108212, 'user1', '1485153a-1fea-4e44-8567-ccb5e3c08c52', 'He told me that, but I still have pain, so I went back to see him.', 1365122689732, 41);
