INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108312, 'user2', '41093c59-a8b1-47a0-9d70-63b43b27c27c', 'Okay.  What brings you in today?', 1563983594693, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108313, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Good afternoon, dear, how old are you?', 1437392852907, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108314, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'I''m fourteen years old.', 1437392858069, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108315, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Good, and what brings you in for a visit today?', 1437392863635, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108316, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Have you seen another doctor for this?', 1437392888680, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108317, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Mom, can you tell the doctor?', 1437392892107, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108318, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Yes, actually, we went to another orthopedist in November of two thousand seven.', 1437392865865, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108319, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'I see, and what did this doctor recommend?', 1437392869535, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108320, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'We got an MRI, I have a disc with the images, and the report as well right here, if you want to take a look at it.', 1437392889443, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108321, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Thank you, yes, so this shows left patellar chondromalacia. Has she been to P T?', 1437392871993, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108322, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'We got a referral for P T, but they only wanted to do, um, let me look at my notes, patellar tracking exercises.', 1437392912377, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108323, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'I see, has she been wearing her brace?', 1437392905395, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108324, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Yes, she has been. I''ve been making sure of it.', 1437392923460, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108325, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'That''s good, and how is your pain today, dear?', 1437392900548, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108326, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'P T only made the pain much worse, it hurts so much.', 1437392922979, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108327, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Yes, she''s in a lot of pain, is there anything else we can do, besides P T?', 1437392906136, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108328, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Well, we''re in a pretty difficult spot here. The majority of my patients get significantly better by just going to P T.', 1437392873849, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108329, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Is there any surgery to fix this?', 1437392908774, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108330, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Usually, we manage this for six months without surgery, and she hasn''t reached that milestone yet. But, because her pain is getting so severe, I can do a lateral capsular release on this knee.', 1437392936568, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108331, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'What is that?', 1437392910927, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108332, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'It''s a small procedure, minimally invasive, and we can do it outpatient. Her kneecap is partially dislocating, so this surgery will get everything back into alignment.', 1437392885400, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108333, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Okay, what is the risk of infection?', 1437392988719, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108334, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'The risk of infection is actually less than one percent. We use antibiotics to control for infection.', 1437392892612, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108335, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Will I be asleep for this?', 1437392917347, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108336, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Yes, you won''t feel a thing.', 1437392879354, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108337, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Will I need to go back to P T?', 1437392894916, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108338, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Yes, you''ll need to go some after the surgery to make sure everything heals up okay. The other risks include bleeding, changes in sensation and motion extremity, failure of procedure to relieve pain, need for postoperative rehab, and significant postoperative swelling.', 1437392893238, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108339, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'I think we''d like to do the surgery. What do you think, honey?', 1437392917133, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108340, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Yeah, I think so too, I want to get back to playing soccer.', 1437392988332, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108341, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', '', 1437392985946, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108342, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Well, since the fall of two thousand seven.', 1437392860004, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108343, 'user1', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'My left knee hurts really bad.', 1437392857642, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108344, 'user2', '79cc99d0-6e63-4abe-98e8-5dbc7d8ac166', 'Oh no, how long has this knee been hurting you?', 1437392865026, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108345, 'user2', 'c8c5e2fd-6c7d-4d38-9f6c-37d92caa2739', 'What brings you here today?', 1668933791140, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108346, 'user1', 'c8c5e2fd-6c7d-4d38-9f6c-37d92caa2739', 'I have pain in my tummy.', 1668933792405, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108347, 'user2', 'c8c5e2fd-6c7d-4d38-9f6c-37d92caa2739', 'When did you first notice it?', 1668933796924, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108348, 'user1', 'c8c5e2fd-6c7d-4d38-9f6c-37d92caa2739', 'It started suddenly around noon.', 1668933800995, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108349, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Welcome to the clinic., ma''am', 1595151372424, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108350, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Thank you.', 1595151374269, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108351, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'What brings you into see me?', 1595151379162, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108352, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'In these past four months have your symptoms becomes worse or has it improved at all?', 1595151405076, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108353, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'It has been getting worse. The pain is worse at night. It wakes me up at night. I haven''t had a good night sleep in four months.', 1595151390290, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108354, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Have you experienced any pain or numbness in your arm, wrist, or hand?', 1595151395966, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108355, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Yes! About two weeks after the pain started, I was having some numbness and painful cramping in these two fingers here.', 1595151398744, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108356, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'The right hand and the first and second finger?', 1595151425249, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108357, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Yes.', 1595151428697, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108358, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'How old are you?', 1595151409691, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108359, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'I am forty six.', 1595151420495, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108360, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Are you left or right handed?', 1595151406614, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108361, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Right. It was a throbbing pain in my hand.', 1595151410925, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108362, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Have you had any other pain anywhere else in your body?', 1595151460572, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108363, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'I few times I had some numbness in both of my legs. It started with a pinching from my tailbone area.', 1595151464396, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108364, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Did you experience any trauma neck, head or back?', 1595151472908, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108365, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'No. I don''t know where this pain came from. Oh, every once and a while I have this electric shock like sensation shooting down my spine when move my neck certain way.', 1595151475198, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108366, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Any pain or symptoms in your left arm or shoulder?', 1595151480301, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108367, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'No.', 1595151398320, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108368, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Have you had any visual changes or disturbances?', 1595151422237, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108369, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'No.', 1595151467605, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108370, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Any difficulties with your bowels or your bladder?', 1595151396952, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108371, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'No.', 1595151466978, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108372, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Have you been taking any thing for the pain?', 1595151461380, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108373, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'I have been taking Naprosyn.', 1595151443235, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108374, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Has the Naprosyn help relieve your pain?', 1595151536106, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108375, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Only a little bit.', 1595151516249, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108376, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Okay.', 1595151410137, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108377, 'user2', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'How long has this been going on for?', 1595151381066, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108378, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'Maybe for about four months.', 1595151401765, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108379, 'user1', '4fd97ec2-5844-4bcc-a7cf-240821282f82', 'I have been struggling with pain and stiffness in my right neck and shoulder.', 1595151375490, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108380, 'user2', '7d4b5221-321e-48fc-9be1-2b6144973270', 'Is this baby number two?', 992585955277, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108381, 'user2', '7d4b5221-321e-48fc-9be1-2b6144973270', 'When was your last period?', 992585969913, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108382, 'user1', '7d4b5221-321e-48fc-9be1-2b6144973270', 'About a month ago.', 992585963394, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108383, 'user2', '7d4b5221-321e-48fc-9be1-2b6144973270', 'And how would you describe your periods? Light, normal, heavy?', 992585968401, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108384, 'user1', '7d4b5221-321e-48fc-9be1-2b6144973270', 'Pretty normal.', 992585977106, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108385, 'user2', '7d4b5221-321e-48fc-9be1-2b6144973270', 'Any abnormal pap smears?', 992585983032, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108386, 'user1', '7d4b5221-321e-48fc-9be1-2b6144973270', 'No, fortunately they''ve all been normal.', 992585990899, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108387, 'user2', '7d4b5221-321e-48fc-9be1-2b6144973270', 'That''s wonderful to hear. And my last question for you is if you''ve ever gotten a mammogram?', 992585993329, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108388, 'user1', '7d4b5221-321e-48fc-9be1-2b6144973270', 'I haven''t gotten one before. Do I need to get one? I just turned thirty nine. What''s the recommended age again?', 992586000990, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108389, 'user2', '7d4b5221-321e-48fc-9be1-2b6144973270', 'It depends. For example, the recommended age would be younger for someone who has a family history of breast cancer. Given that you don''t have a positive family history of breast cancer, I''d advise getting one in a few years at the age of forty five.', 992585999429, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108390, 'user2', '7d4b5221-321e-48fc-9be1-2b6144973270', 'How many times have you been pregnant, including miscarriages or abortions if any?', 992585959243, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108391, 'user1', '7d4b5221-321e-48fc-9be1-2b6144973270', 'I''ve been pregnant two times in total. No miscarriages or abortions.', 992585968923, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108392, 'user1', '7d4b5221-321e-48fc-9be1-2b6144973270', 'Yes, this is baby number two.', 992585959354, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108393, 'user2', '275797aa-15b6-4267-a06c-4aede5716a3b', 'Okay, I want you to follow up with our hand therapist Doctor X at her A B C D office in one to two weeks.', 1649430838472, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108394, 'user1', '275797aa-15b6-4267-a06c-4aede5716a3b', 'Okay, I will make an appointment today.', 1649430842384, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108395, 'user2', 'caa4de22-57d3-436d-91ff-f68db4689eff', 'So we''re here to follow up on a few things. I''d like to know how you''re keeping up with your blood sugar checks.', 1532168780157, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108396, 'user1', 'caa4de22-57d3-436d-91ff-f68db4689eff', 'I''ve been checking my blood sugar one to two times a day.', 1532168782313, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108397, 'user1', 'caa4de22-57d3-436d-91ff-f68db4689eff', 'Yep, in fact it''s right here. Let me grab it for you.', 1532168795191, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108398, 'user2', 'caa4de22-57d3-436d-91ff-f68db4689eff', 'Great.', 1532168814782, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108399, 'user1', 'caa4de22-57d3-436d-91ff-f68db4689eff', 'Here ya go.', 1532168813452, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108400, 'user2', 'caa4de22-57d3-436d-91ff-f68db4689eff', 'Thank you. And have you been watching your cholesterol intake since getting blood work done? Your labs show your cholesterol levels are a bit elevated. I''d like for you to monitor your cholesterol and go in for another set of labs before our next visit.', 1532168822363, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108401, 'user1', 'caa4de22-57d3-436d-91ff-f68db4689eff', 'Do I need to fast for it again?', 1532168817411, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108402, 'user2', 'caa4de22-57d3-436d-91ff-f68db4689eff', 'Yes, you''ll need to fast. I''d recommend going in early in the morning before eating any breakfast.', 1532168833058, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108403, 'user1', 'caa4de22-57d3-436d-91ff-f68db4689eff', 'That sounds like a good plan.', 1532168793996, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108404, 'user2', 'caa4de22-57d3-436d-91ff-f68db4689eff', 'And as for your sinusitis, how have you been feeling since finishing your course of antibiotics?', 1532168839105, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108405, 'user1', 'caa4de22-57d3-436d-91ff-f68db4689eff', 'Much better. No more headaches and a stuffy nose.', 1532168797502, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108406, 'user1', 'caa4de22-57d3-436d-91ff-f68db4689eff', 'Uh yeah, but I need to be better at it.', 1532168796773, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108407, 'user2', 'caa4de22-57d3-436d-91ff-f68db4689eff', 'Do you have the log with you today?', 1532168798636, 4);
