INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108430, 'user1', 'aefa8c61-441a-4dd8-b13d-50c337cb766f', 'I am not exactly sure because the other doctors said a bunch of medical terms. I have had laser in my eyes though. That was for macular degeneration. Doctor X said I had neurovascular age-related macular degeneration.', 1232025883105, 3);
