INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108452, 'user1', '0f346523-a74d-4b3a-9e1b-256ff6cef95a', 'Yes. I used to take pills, but I never got into needle drugs. Thank God.  I went through treatment, all those years back. I started going to A A and got my life together.', 962470430761, 15);
