INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108468, 'user3', '78a9d6e3-42cc-4a6a-9246-2010da0bfd3a', 'Was the loss sudden or gradual?', 1109686245809, 4);
