INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108472, 'user3', '78a9d6e3-42cc-4a6a-9246-2010da0bfd3a', 'Is the blurred vision an all blur or is there a blind spot of blurred vision.', 1109686249635, 8);
