INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108481, 'user1', '78a9d6e3-42cc-4a6a-9246-2010da0bfd3a', 'No.', 1109686281454, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108482, 'user3', '78a9d6e3-42cc-4a6a-9246-2010da0bfd3a', 'Any other health concerns or complains?', 1109686335691, 18);
