INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108484, 'user3', '78a9d6e3-42cc-4a6a-9246-2010da0bfd3a', 'Alright! Let me take a look here.', 1109686336798, 20);
