INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108498, 'user1', 'f25accc1-77e2-48c8-b206-0d8a3922dd2e', 'Well, I have a history of systemic lupus erythematosus.', 1577665268368, 3);
