INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108500, 'user2', 'f25accc1-77e2-48c8-b206-0d8a3922dd2e', 'Did they give you any topical creams?', 1577665272174, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108501, 'user1', 'f25accc1-77e2-48c8-b206-0d8a3922dd2e', 'Yeah, they gave me a prescription for Zostrix but I couldn''t fill it because of my insurance.', 1577665286220, 13);
