INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108601, 'user3', 'e7005490-5257-470d-b073-2e9fa6b61967', 'How''s your wife doing? I think the last time I saw her was two weeks ago. She was telling me about the remodeling you''ve been doing around the house.', 1635380803559, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108602, 'user1', 'e7005490-5257-470d-b073-2e9fa6b61967', 'She''s doing well, thanks for asking. Oh yeah, the remodeling has been a lot. I didn''t think it''d take as long as it has.', 1635380805007, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108603, 'user1', 'e7005490-5257-470d-b073-2e9fa6b61967', 'Nope.', 1635380820635, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108604, 'user3', 'e7005490-5257-470d-b073-2e9fa6b61967', 'How''s work been treating ya?', 1635380814631, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108605, 'user1', 'e7005490-5257-470d-b073-2e9fa6b61967', 'Pretty darn well actually. I go into the allergy and immunology clinic four days outta the week. I like that my hours are flexible. My patients also haven''t run away from me yet, which is always a good sign.', 1635380845347, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108606, 'user3', 'e7005490-5257-470d-b073-2e9fa6b61967', 'Yeah, it can take some time. We remodeled our kitchen three years ago and it turned our lives upside down. So tell me, how''s training going for you? I believe you were telling me that you have a five k coming up.', 1635380810291, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108607, 'user1', 'e7005490-5257-470d-b073-2e9fa6b61967', 'Yeah, it''s two weeks away. I''ve been jogging and doing cross country track about five times a week. I also lift twice a week on my better days.', 1635380808743, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108608, 'user3', 'e7005490-5257-470d-b073-2e9fa6b61967', 'That''s great! And no smoking or drinking, correct?', 1635380815570, 4);
