INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108911, 'user3', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'I just need to confirm some information before we begin sir, you''re forty one, correct?', 1179446889259, 0);
