INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108913, 'user3', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'Good, so what happened?', 1179446891993, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108914, 'user3', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'Where is your left shoulder pain?', 1179446904525, 6);
