INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108916, 'user1', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'I fell with both my arms outstretched, but I fell mostly on my left shoulder.', 1179446911099, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108917, 'user1', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'Well, I work at A B C, and about two days ago I slipped on some oil that had spilled.', 1179446903954, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108918, 'user3', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'Good, do you have any pain in the front of the shoulder?', 1179446940269, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108919, 'user1', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'No sir, I don''t have anything there.', 1179446903051, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108920, 'user3', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'Good, how about weakness? Is there any shoulder weakness?', 1179446915445, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108921, 'user1', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'No, it''s not really weak at all.', 1179446940476, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108922, 'user3', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'How have your symptoms progressed over the last two days? Have they gotten better, or worse?', 1179446970316, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108923, 'user1', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'Um, overall, I''d say it''s gotten better. I have a little better range of motion.', 1179446963358, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108924, 'user3', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'Have you been able to do any activities?', 1179446909741, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108925, 'user1', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'I was able to get in the swimming pool with my kids, and I didn''t really have any trouble.', 1179446944710, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108926, 'user3', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'Good, what medicines have you taken for this?', 1179446994404, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108927, 'user1', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'I''ve just taken some Advil so far.', 1179446915989, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108928, 'user1', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'It hurt really bad yesterday, but that''s gone away now.', 1179446899047, 9);
