INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108930, 'user3', 'd2f216b8-8017-4cf4-b8bd-0056f72c8af6', 'Going backwards a little, how about the right shoulder?', 1179446912601, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108931, 'user2', '16018319-335f-4b68-9ef1-aa2c70a15d7d', 'Hi there! It is good to see you both. How has everything been going for the both of you?', 1224964599840, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108932, 'user1', '16018319-335f-4b68-9ef1-aa2c70a15d7d', 'Hi Doctor.', 1224964602966, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108933, 'user2', '16018319-335f-4b68-9ef1-aa2c70a15d7d', 'Is there any other concerns you have today?', 1224964629164, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108934, 'user1', '16018319-335f-4b68-9ef1-aa2c70a15d7d', 'Yes. She has this toenail that looks strange and discolored.', 1224964634266, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108935, 'user2', '16018319-335f-4b68-9ef1-aa2c70a15d7d', 'Let me look. Can you remove your socks for me?', 1224964608430, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108936, 'user1', '16018319-335f-4b68-9ef1-aa2c70a15d7d', 'Yes.', 1224964635859, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108937, 'user2', '16018319-335f-4b68-9ef1-aa2c70a15d7d', 'Is it this nail?', 1224964626738, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108938, 'user1', '16018319-335f-4b68-9ef1-aa2c70a15d7d', 'Yes.', 1224964617340, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108939, 'user2', '16018319-335f-4b68-9ef1-aa2c70a15d7d', 'This is very common. It is called Onychomycosis. It is nail fungus. Since only one nail is affected, I would recommend starting off with a topical treatment. I will send the drops to your pharmacy. You will put on drop on the affected nail, daily.', 1224964660165, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108940, 'user1', '16018319-335f-4b68-9ef1-aa2c70a15d7d', 'Things have been pretty good. She has been having some new emotional outbursts. I made an appointment with the down syndrome behavioral specialist that you recommended from the last time we were here.', 1224964605195, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108941, 'user2', '16018319-335f-4b68-9ef1-aa2c70a15d7d', 'That is great. Keep me updated on her progress.  Her bloodwork came back showing an underactive thyroid. This explains the recent weight gain and fatigue. I would like to start her on a medication called levothyroxine. We will need to check her bloodwork again in one month to see how her thyroid respond to the medication.', 1224964610380, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108942, 'user1', '16018319-335f-4b68-9ef1-aa2c70a15d7d', 'Okay.', 1224964615211, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108943, 'user2', 'e6c7bd4a-b309-4070-b027-964a7ff49cba', 'Good afternoon, ma''am.', 1730778451953, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108944, 'user1', 'e6c7bd4a-b309-4070-b027-964a7ff49cba', 'Good afternoon, doctor.', 1730778457846, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108945, 'user2', 'e6c7bd4a-b309-4070-b027-964a7ff49cba', 'Have you ever had surgery, ma''am?', 1730778460906, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108946, 'user1', 'e6c7bd4a-b309-4070-b027-964a7ff49cba', 'Actually, yes I have. I had pinning surgery done on both of my ears.', 1730778462025, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108947, 'user2', 'e6c7bd4a-b309-4070-b027-964a7ff49cba', 'Do you remember how old you were when you had surgery?', 1730778472508, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108948, 'user1', 'e6c7bd4a-b309-4070-b027-964a7ff49cba', 'Um, I was five or six years old. It was when I was a kid, I know that for sure.', 1730778474798, 5);
