INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108952, 'user2', 'c0e6f46f-67f7-43a9-8df7-2f8f42ec54d8', 'What is your family medical history?', 1677092134396, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108953, 'user1', 'c0e6f46f-67f7-43a9-8df7-2f8f42ec54d8', 'My dad has high blood pressure. My mom has had a ton of skin cancer removed.', 1677092137900, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108954, 'user2', 'c0e6f46f-67f7-43a9-8df7-2f8f42ec54d8', 'Do you know what type of skin cancer she has removed?', 1677092140453, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108955, 'user1', 'c0e6f46f-67f7-43a9-8df7-2f8f42ec54d8', 'I have no idea.', 1677092145787, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108956, 'user2', 'ee2409cd-3691-43c7-b60b-f8a0835a7d09', 'Hello, miss. Today we''re going to do a recheck for your hypertension. Sound good?', 1643649007699, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108957, 'user1', 'ee2409cd-3691-43c7-b60b-f8a0835a7d09', 'Yes, of course.', 1643649011173, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108958, 'user1', 'ee2409cd-3691-43c7-b60b-f8a0835a7d09', 'No, luckily I do not have that.', 1643649016072, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108959, 'user2', 'ee2409cd-3691-43c7-b60b-f8a0835a7d09', 'Is your heart beating alright? Do you feel like it is beating too fast or hard?', 1643649013716, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108960, 'user1', 'ee2409cd-3691-43c7-b60b-f8a0835a7d09', 'No. I can''t really feel my heart beat normally, but I guess that is better than feeling it beat constantly.', 1643649036159, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108961, 'user2', 'ee2409cd-3691-43c7-b60b-f8a0835a7d09', 'You are correct. You shouldn''t notice it. How is sleeping?', 1643649024547, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108962, 'user1', 'ee2409cd-3691-43c7-b60b-f8a0835a7d09', 'Sleeping has been fine. I sleep through the night.', 1643649039806, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108963, 'user2', 'ee2409cd-3691-43c7-b60b-f8a0835a7d09', 'Great. Any shortness of breath that causes you to wake up?', 1643649020506, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108964, 'user1', 'ee2409cd-3691-43c7-b60b-f8a0835a7d09', 'None. I don''t have shortness of breath at any other time of the day.', 1643649069192, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108965, 'user2', 'ee2409cd-3691-43c7-b60b-f8a0835a7d09', 'Are your legs doing well? Any swelling?', 1643649077664, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108966, 'user1', 'ee2409cd-3691-43c7-b60b-f8a0835a7d09', 'No. No swelling.', 1643649038480, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108967, 'user1', 'ee2409cd-3691-43c7-b60b-f8a0835a7d09', 'I have been coming to you for the last fifteen of my seventy eight years on Earth. I know how a follow up works.', 1643649024287, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108968, 'user2', 'ee2409cd-3691-43c7-b60b-f8a0835a7d09', 'You are a seasoned veteran. Alright. So how is your chest? Any pains or tightness?', 1643649022580, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108969, 'user2', 'ee2409cd-3691-43c7-b60b-f8a0835a7d09', 'I just want to check to see if you have any symptoms that can possibly raise alarm.', 1643649015197, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108970, 'user2', 'a3c45c12-de44-4ca6-a61f-a12b569f285e', 'Hello, it''s nice to meet you.', 1549784690269, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108971, 'user1', 'a3c45c12-de44-4ca6-a61f-a12b569f285e', 'It''s nice to meet you as well.', 1549784694915, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108972, 'user1', 'a3c45c12-de44-4ca6-a61f-a12b569f285e', 'Yes, I feel like I''ve tried everything in the book and I still can''t break the habit. One of my buddies was telling me about this medicine called Clantix or something like that.', 1549784712606, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108973, 'user2', 'a3c45c12-de44-4ca6-a61f-a12b569f285e', 'Yes, I''ve heard of Chantix. We can look into it and see what''s best fit.', 1549784712551, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108974, 'user1', 'a3c45c12-de44-4ca6-a61f-a12b569f285e', 'Okay, great. Since moving back home, I''ve ran out of Xanax.', 1549784713176, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108975, 'user2', 'a3c45c12-de44-4ca6-a61f-a12b569f285e', 'How long have you been taking it?', 1549784728644, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108976, 'user1', 'a3c45c12-de44-4ca6-a61f-a12b569f285e', 'Almost a year now. I usually take it on days where my anxiety is really bad.', 1549784723105, 9);
