INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108978, 'user1', 'a3c45c12-de44-4ca6-a61f-a12b569f285e', 'Yes, I need to find a new cancer specialist that''s closer to where I live.', 1549784739182, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108979, 'user2', 'a3c45c12-de44-4ca6-a61f-a12b569f285e', 'Are you currently experiencing any pain?', 1549784711398, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108980, 'user1', 'a3c45c12-de44-4ca6-a61f-a12b569f285e', 'Not at the moment, but I do get pain when I eat sometimes. Other times it''s when I''m not even doing anything. It''s been chronic so nothing new.', 1549784722518, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108981, 'user2', 'a3c45c12-de44-4ca6-a61f-a12b569f285e', 'Do you take anything for the pain?', 1549784739606, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108982, 'user1', 'a3c45c12-de44-4ca6-a61f-a12b569f285e', 'I haven''t in a while.', 1549784753785, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108983, 'user2', 'a3c45c12-de44-4ca6-a61f-a12b569f285e', 'When were you diagnosed with mesothelioma?', 1549784716440, 16);
