INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108995, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'It is nice to meet you to. I hear an accent. Where are you from?', 1495851909433, 2);
