INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (108999, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Thank you.', 1495851931984, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109000, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'So, your primary care physician sent you here for possible hydrocephalus.', 1495851924861, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109001, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Wow! Your English is excellent now.', 1495851908756, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109002, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Yes.', 1495851931012, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109003, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Then, yes.', 1495851928815, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109004, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Can you tell me about the symptoms that you have been having.', 1495851966099, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109005, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'I think I have been walking funny lately. I have also been losing my balance.', 1495851941164, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109006, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'How do you know that you have been walking funny?', 1495851983530, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109007, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Thank you.', 1495851905452, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109008, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'I am from Denmark. I speak Danish as my first language. Me and my husband have been in the States for many many years. When we first got here, we did not speak a word of English.', 1495851905694, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109009, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'She walks wider then she used to, and I noticed that she stooped over. She walks much slower than she did before. She is often losing her balance. I have noticed her touching the walls and furniture to stabilize herself.', 1495851929367, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109010, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Okay. Have you noticed her stabilizing herself all of a sudden?', 1495851931578, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109011, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'No. It has been happening more and more over the last six months or so.', 1495852013540, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109012, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'What else have you noticed about the way she walks?', 1495852000628, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109013, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'I noticed that she is having trouble stepping up onto things like a scale. She seems very unbalanced. She also seems to take her time as she walks. She can''t be hurried.', 1495851961548, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109014, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'That is good that you are taking your time. Do you use any devices to assist you to get around? Like a cane or a walker?', 1495851940961, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109015, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'No.', 1495852034234, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109016, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'I must help her get in and out of the car. Not every time but sometimes. I am very concerned because she has been falling more and more recently.', 1495851954673, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109017, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'I have had one emergency room visit.', 1495851956731, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109018, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'What happened that you had to go to the emergency room?', 1495852025099, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109019, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'I fell. I was walking to the bedroom. I lost my balance so I put my hand out to brace myself against the wall and my hand slipped. I fell on my wrist.', 1495851946780, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109020, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'She broke her wrist.', 1495851934343, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109021, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'When did this fall happen?', 1495852063876, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109022, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'March two thousand and seven.', 1495852074803, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109023, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'She has fallen a few times since she broke her wrist. It makes me so nervous.', 1495852055259, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109024, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'I can see why that would make you nervous. Have you had any headaches?', 1495852015563, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109025, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'No. I never get headaches.', 1495852101231, 35);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109026, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Aren''t you lucky.', 1495851958645, 36);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109027, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Yes, I guess so.', 1495851962318, 37);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109028, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Have you had any problems with your memory or cognitive abilities?', 1495852070531, 38);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109029, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'I am still able to pay the bills on time. I don''t feel as smart as I used to be.  I do feel like my thinking has slowed down over the last few months.', 1495852006418, 39);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109030, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'What is your perspective on her memory and her cognitive abilities?', 1495851987924, 40);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109031, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'I have noticed some changes. She will occasionally start a sentence and then not know what words to use to finish the sentence.', 1495852080298, 41);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109032, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Has she ever had trouble finishing a sentence the in the past?', 1495851972697, 42);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109033, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'No, she has always been very well spoken never has lost thoughts.', 1495852050425, 43);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109034, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Have you had any fainting or vertigo episodes?', 1495852132416, 44);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109035, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'I have not fainted. I have had some dizzy spells in the past but not recently.', 1495851950789, 45);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109036, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Have you had and problems with your bowel movements?', 1495852031361, 46);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109037, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'No.', 1495852151553, 47);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109038, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Any bladder issues or frequent urination?', 1495852161605, 48);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109039, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'No.', 1495852062743, 49);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109040, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Okey. Let us do some an exam.', 1495852105690, 50);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109041, 'user1', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'Okey.', 1495852001017, 51);
