INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109043, 'user2', 'fd28f7ed-f540-4ae7-8220-09c10d481b59', 'What do you notice about the way your wife''s walk that has changed?', 1495851923213, 18);
