INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109045, 'user2', '55a65237-f767-4d7d-80be-c13f903d1bb4', 'Refractory hypertension.', 1524413248653, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109046, 'user2', '55a65237-f767-4d7d-80be-c13f903d1bb4', 'But the good news is that it is getting better.', 1524413255659, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109047, 'user1', '55a65237-f767-4d7d-80be-c13f903d1bb4', 'Yes.', 1524413264028, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109048, 'user2', '55a65237-f767-4d7d-80be-c13f903d1bb4', 'Last time we talked about seeing the internal medicine doctor there at your senior center, right?', 1524413279099, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109049, 'user1', '55a65237-f767-4d7d-80be-c13f903d1bb4', 'Yes, I made an appointment last week, um, no week before that, but I completely forgot about it.', 1524413280955, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109050, 'user2', '55a65237-f767-4d7d-80be-c13f903d1bb4', 'Hm, okay we need to reschedule that.', 1524413263553, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109051, 'user1', '55a65237-f767-4d7d-80be-c13f903d1bb4', 'Yes, I will do it today.', 1524413297955, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109052, 'user2', '55a65237-f767-4d7d-80be-c13f903d1bb4', 'Okay, your reports look fine. G F R is below sixty percent, that''s a good sign.  Overall, Miss K, you look better, but we need to reschedule your appointment with the Internist. That''s kind of important.', 1524413294410, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109053, 'user1', '55a65237-f767-4d7d-80be-c13f903d1bb4', 'Okay, I will do that. Thank you!', 1524413258082, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109054, 'user2', '55a65237-f767-4d7d-80be-c13f903d1bb4', 'You are welcome.', 1524413300422, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109055, 'user1', '55a65237-f767-4d7d-80be-c13f903d1bb4', 'Oh yeah that!', 1524413249764, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109056, 'user2', '55a65237-f767-4d7d-80be-c13f903d1bb4', 'I mean, I am so happy to see your report today, your blood pressure looks much better. That''s amazing given your past few visits your B P was out of control and even with changing your medications we were having tough time bringing it down.', 1524413245961, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109057, 'user1', '55a65237-f767-4d7d-80be-c13f903d1bb4', 'Yeah, I feel much better, I read about my condition and it is called something as um refraction or--', 1524413248242, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109058, 'user3', '6881e213-c59b-4957-99ac-a1919a70bc9e', 'Did you ever visit any hospital for any kind of surgery?', 1529866077039, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109059, 'user1', '6881e213-c59b-4957-99ac-a1919a70bc9e', 'No.', 1529866080775, 1);
