INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109129, 'user1', '0b02fb2f-d0b8-4ffe-893c-4458afd5be7c', 'I am having mood swings, sometimes I feel super happy and sometimes I am just super sad and angry with myself. I find myself in tears thinking about things or situations which are not even real.', 1143882250564, 2);
