INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109142, 'user1', '0b02fb2f-d0b8-4ffe-893c-4458afd5be7c', 'Yes, I was doing better once I started taking that medicine regularly. I continued it even though I had to pay out of my pocket.', 1143882330753, 18);
