INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109174, 'user1', '0b591c48-48e6-45c1-9ce1-fc636f5ec69b', 'One of my uncles on my dad''s side was recently diagnosed with leukemia.', 1129911800968, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109175, 'user2', '0b591c48-48e6-45c1-9ce1-fc636f5ec69b', 'Oh, wow. I see.', 1129911808451, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109176, 'user1', '0b591c48-48e6-45c1-9ce1-fc636f5ec69b', 'Both my parents are deceased.', 1129911790613, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109177, 'user2', '0b591c48-48e6-45c1-9ce1-fc636f5ec69b', 'I''m so sorry to hear that. I offer you my sincerest condolences.', 1129911794933, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109178, 'user1', '0b591c48-48e6-45c1-9ce1-fc636f5ec69b', 'Thank you. My dad passed away at seventy five from leukemia and my mom fell victim to heart problems and alcoholism at thirty eight.', 1129911796766, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109179, 'user2', '8b03ab41-1d58-4940-8896-56d5e042670a', 'Any fever or chills?', 1222217079003, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109180, 'user1', '8b03ab41-1d58-4940-8896-56d5e042670a', 'No.', 1222217080218, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109181, 'user2', '8b03ab41-1d58-4940-8896-56d5e042670a', 'Any headache or body pains?', 1222217088878, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109182, 'user2', '8b03ab41-1d58-4940-8896-56d5e042670a', 'Did you observe any blood?', 1222217098662, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109183, 'user1', '8b03ab41-1d58-4940-8896-56d5e042670a', 'No.', 1222217104088, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109184, 'user2', '8b03ab41-1d58-4940-8896-56d5e042670a', 'Okay, any diarrhea?', 1222217120994, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109185, 'user1', '8b03ab41-1d58-4940-8896-56d5e042670a', 'No, on the contrary I am having constipation every now and then, it''s really bothering me now. I feel bloated all the time and don''t feel fresh in the morning or throughout the day.', 1222217107728, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109186, 'user2', '8b03ab41-1d58-4940-8896-56d5e042670a', 'Oh, how long have you had this problem?', 1222217089684, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109187, 'user1', '8b03ab41-1d58-4940-8896-56d5e042670a', 'Couple of months now.', 1222217143230, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109188, 'user2', '8b03ab41-1d58-4940-8896-56d5e042670a', 'Hm, I see, does it hurt you to pass stool? Did you notice any blood?', 1222217106181, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109189, 'user1', '8b03ab41-1d58-4940-8896-56d5e042670a', 'No. I use suppositories.', 1222217155297, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109190, 'user2', '8b03ab41-1d58-4940-8896-56d5e042670a', 'Oh, that''s great. You are doing the right thing. In addition to that I will prescribe you some strong laxative you can drink that in morning it should help.', 1222217119752, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109191, 'user1', '8b03ab41-1d58-4940-8896-56d5e042670a', 'Okay!', 1222217128712, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109192, 'user2', '8b03ab41-1d58-4940-8896-56d5e042670a', 'Any complains of heart burn or acidity or stomach pain?', 1222217150229, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109193, 'user1', '8b03ab41-1d58-4940-8896-56d5e042670a', 'No, not really. I do get this twisty pain in my stomach sometimes which I think is mainly due to my constipation.', 1222217173742, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109194, 'user2', '8b03ab41-1d58-4940-8896-56d5e042670a', 'Yeah, you can get that kind of pain with constipation. Any cough or cold like symptoms? Any cough with sputum?', 1222217118383, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109195, 'user1', '8b03ab41-1d58-4940-8896-56d5e042670a', 'No, I feel fine.', 1222217142755, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109196, 'user2', '8b03ab41-1d58-4940-8896-56d5e042670a', 'Okay, basically I don''t think you have any stomach ulcer or anything, but we need to treat your constipation because I know it can be really uncomfortable.', 1222217135285, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109197, 'user1', '8b03ab41-1d58-4940-8896-56d5e042670a', 'I had vomiting a few times.', 1222217107792, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109198, 'user1', '8b03ab41-1d58-4940-8896-56d5e042670a', 'No.', 1222217096277, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109199, 'user2', '8b03ab41-1d58-4940-8896-56d5e042670a', 'Any nausea vomiting?', 1222217083008, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109200, 'user2', '060aa896-8a4b-46cf-bde0-8d78d38fc1fb', 'Do you take Diovan, estradiol, Norvasc, Wellbutrin?', 1297833864062, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109201, 'user2', '060aa896-8a4b-46cf-bde0-8d78d38fc1fb', 'Do you take oxygen therapy at home?', 1297833868088, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109202, 'user1', '060aa896-8a4b-46cf-bde0-8d78d38fc1fb', 'Yes.', 1297833891902, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109203, 'user2', '060aa896-8a4b-46cf-bde0-8d78d38fc1fb', 'Okay.', 1297833899150, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109204, 'user1', '060aa896-8a4b-46cf-bde0-8d78d38fc1fb', 'Yes, and the Wellbutrin is an inhaler.', 1297833868627, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109205, 'user2', '060aa896-8a4b-46cf-bde0-8d78d38fc1fb', 'Okay so inhaler SR?', 1297833871882, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109206, 'user1', '060aa896-8a4b-46cf-bde0-8d78d38fc1fb', 'Yes.', 1297833874551, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109207, 'user3', '0a744044-29b6-4620-89b1-22690602d876', 'Good afternoon, ma''am.', 1013931486845, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109208, 'user3', '0a744044-29b6-4620-89b1-22690602d876', 'I assume you live together?', 1013931510084, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109209, 'user3', '0a744044-29b6-4620-89b1-22690602d876', 'How long have you and your husband been married?', 1013931490407, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109210, 'user3', '0a744044-29b6-4620-89b1-22690602d876', 'What do you do for a living?', 1013931507035, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109211, 'user1', '0a744044-29b6-4620-89b1-22690602d876', 'I''m a school nurse for the School Department. I love working with the children.', 1013931526874, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109212, 'user3', '0a744044-29b6-4620-89b1-22690602d876', 'That''s wonderful. Do you drink or smoke?', 1013931508219, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109213, 'user1', '0a744044-29b6-4620-89b1-22690602d876', 'No, I don''t drink, and I quit smoking cigarettes about twenty five years ago.', 1013931539873, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109214, 'user3', '0a744044-29b6-4620-89b1-22690602d876', 'Good for you.', 1013931531293, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109215, 'user1', '0a744044-29b6-4620-89b1-22690602d876', 'Good afternoon, doctor.', 1013931488309, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109216, 'user1', '0a744044-29b6-4620-89b1-22690602d876', 'Yes, we do.', 1013931503061, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109217, 'user1', '0a744044-29b6-4620-89b1-22690602d876', 'Oh, at this point I don''t even know how long its been.', 1013931490154, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109218, 'user3', 'f6db6ad5-8c9b-465d-851c-9408ff2031e2', 'Any past surgeries?', 1516187495320, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109219, 'user3', 'f6db6ad5-8c9b-465d-851c-9408ff2031e2', 'It looks like she had an appendectomy along with a total abdominal hysterectomy and bilateral salpingo oophorectomy sometime ago.', 1516187500341, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109220, 'user3', 'f6db6ad5-8c9b-465d-851c-9408ff2031e2', 'Okay, noted.', 1516187505903, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109221, 'user3', 'f6db6ad5-8c9b-465d-851c-9408ff2031e2', 'Oh and it looks like she had a right hip fracture back in O five after a fall.', 1516187511373, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109222, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Before we begin today, sir, I just need a few pieces of background information. I see here on my chart that you''re thirty years old, is that correct?', 993029738675, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109223, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Yes doctor, that''s correct.', 993029742021, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109224, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'I was doing well until July of nineteen ninety three.', 993029757602, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109225, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'What were your initial symptoms?', 993029773524, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109226, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'I began having weakness in my right arm, and there was some neck pain too.', 993029768113, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109227, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Okay, when these symptoms began, how did you manage them?', 993029771082, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109228, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'At first, I went to a chiropractor, but after a while my arm started atrophying, and my right hand felt tight. I couldn''t extend all my fingers out.', 993029748320, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109229, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Once you noticed the atrophy and contractures, that''s the tightness you were experiencing, how were you treated?', 993029781987, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109230, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'After that, I went to a neurosurgeon close to my house, and he ordered an, um, C T scan of my neck.', 993029780597, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109231, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Okay, do you have the report of that C T Scan with you today?', 993029793697, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109232, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Yes, doctor, I have it right here. They were one on the twenty fifth of September in ninety two.', 993029793481, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109233, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Thank you, okay, this shows an intramedullary lesion at C two three, and an extramedullary lesion at C six seven.', 993029778671, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109234, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'That means tumor, right?', 993029757580, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109235, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Yes sir. Did you have neck surgery?', 993029758065, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109236, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Yeah, I have the op notes right here.', 993029800387, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109237, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Okay, just so you know, you had a C six T one laminectomy, and they decompressed the spinal cord. How did you respond to this surgery?', 993029836063, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109238, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Well, honestly, I improved for about three months following the operation, but after that I just got worse and worse.', 993029845699, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109239, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Once your symptoms worsened, what happened?', 993029771996, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109240, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Um, I started having this burning sensation on my left side.', 993029829505, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109241, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Did you have any weakness, sir?', 993029825608, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109242, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Yeah, I had weakness in both my arms.', 993029844698, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109243, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Was one side worse than the other?', 993029787842, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109244, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Yes, my right side was worse than my left.', 993029814404, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109245, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'In addition to the burning and weakness, did you have any other symptoms?', 993029805834, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109246, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Um, I had really bad balance, I felt nauseous, like I was going to throw up at all times, which I did do some, and, um, my heart was beating really fast, and my blood pressure went up really high.', 993029800086, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109247, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'After all these symptoms began, how were you treated?', 993029807929, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109248, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'On, um, August thirty first nineteen ninety three I had an M R I of my neck, and I have that report right here, too.', 993029769110, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109249, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Thank you, this shows diffuse enlargement of the cervical and thoracic spine and multiple enhancing nodules in the posterior fossa.', 993029779124, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109250, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Sorry to interrupt, what does all that mean?', 993029864532, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109251, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Well, that''s more tumors in the spine. Did you have another surgery for this?', 993029817681, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109252, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Yeah, I had brain surgery. I have those notes right here, too.', 993029774208, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109253, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Okay, so you had a suboccipital craniotomy with tumor excision, decompression, and biopsy. The biopsy showed hemangioblastoma.', 993029805371, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109254, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'That''s cancer, right? This was all done on September first of nineteen ninety three.', 993029933870, 35);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109255, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Well no, not exactly, it''s a benign tumor. After this surgery how were your symptoms?', 993029802221, 36);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109256, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'I felt good, the doctors said I stabilized out. I went through some radiation procedures from September of ninety three to January nineteenth of ninety four.', 993029949528, 37);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109257, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'How have your symptoms progressed since?', 993029883717, 38);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109258, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'I went to the NeuroOncology clinic on October twenty sixth nineteen ninety five because I was having weakness in both arms and both legs, as well as trouble swallowing food.', 993029813607, 39);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109259, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'How much weakness was there?', 993029854141, 40);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109260, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'It was so bad I couldn''t even put on a shirt, or raise my arms, or even feed myself.', 993029947523, 41);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109261, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Can you go up and down stairs?', 993029935526, 42);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109262, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'No, not really, but I can climb them.', 993029806173, 43);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109263, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'How about going to the bathroom, is everything normal there?', 993029964797, 44);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109264, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Yeah, no problems there.', 993029850216, 45);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109265, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Good, and what did the doctor at that clinic recommend?', 993029999176, 46);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109266, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'They were considering doing chemo.', 993029849771, 47);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109267, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Okay, and which hand is your dominant hand?', 993029744810, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109268, 'user1', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'I use my right hand for everything.', 993029745962, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109269, 'user2', 'ccdfee40-43a9-4d91-8324-72cd212e993a', 'Now, take me through the timeline of your symptoms, please. When did everything start?', 993029751293, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109270, 'user3', 'ca561004-dd43-42a8-a16a-25ce2df94be0', 'Any other allergies besides Penicillin?', 1312336799110, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109271, 'user1', 'ca561004-dd43-42a8-a16a-25ce2df94be0', 'Um no.', 1312336802320, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109272, 'user3', 'ca561004-dd43-42a8-a16a-25ce2df94be0', 'I see here that you''ve previously tolerated Cephalosporins without any problems. Do you remember when you were last prescribed a Penicillin like antibiotic?', 1312336807349, 2);
