INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109470, 'user1', '951be383-a5c6-4d07-a38a-da3d59566cad', 'Yes, actually, my mom told me that someone had cervical cancer.', 1538929741868, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109471, 'user2', '951be383-a5c6-4d07-a38a-da3d59566cad', 'What about heart disease, does that sound familiar?', 1538929745132, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109472, 'user2', '5bc41907-483f-450d-b65e-33d9c1c0204d', 'Can you give me a quick run down of her medical history?', 1546387643175, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109473, 'user2', '5bc41907-483f-450d-b65e-33d9c1c0204d', 'When was she diagnosed with dementia?', 1546387660793, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109474, 'user2', '5bc41907-483f-450d-b65e-33d9c1c0204d', 'I''m sorry to hear that.', 1546387651195, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109475, 'user1', '5bc41907-483f-450d-b65e-33d9c1c0204d', 'She was recently diagnosed with dementia. She''s also suffered from high blood pressure for some time now.', 1546387654546, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109476, 'user1', '5bc41907-483f-450d-b65e-33d9c1c0204d', 'No, but she''s not able to control her bladder well which leads to her having frequent accidents. Oh and she''s had back pain for several years along with degenerative changes to her spine. Poor thing. I can''t help but feel so bad for her situation. It definitely hasn''t been easy.', 1546387656908, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109477, 'user1', '5bc41907-483f-450d-b65e-33d9c1c0204d', 'Six months ago.', 1546387664466, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109478, 'user2', '5bc41907-483f-450d-b65e-33d9c1c0204d', 'Any history of heart disease, diabetes, or stroke?', 1546387660263, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109479, 'user1', '5bc41907-483f-450d-b65e-33d9c1c0204d', 'Sure. It''s a bit long, sadly.', 1546387649017, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109480, 'user3', '94558dc0-8ad9-4ecb-aaa3-133bdea203f9', 'Hi, there. How are you both doing? What brings you two to the Emergency Department?', 1295895993716, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109481, 'user1', '94558dc0-8ad9-4ecb-aaa3-133bdea203f9', 'Hi, Doctor. We''re both doing fine. I brought my daughter in today because she''s been feeling sick.', 1295895998307, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109482, 'user1', '94558dc0-8ad9-4ecb-aaa3-133bdea203f9', 'Nope. My Mother has forbidden smoking in her home.', 1295896005728, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109483, 'user1', '94558dc0-8ad9-4ecb-aaa3-133bdea203f9', 'My mom can give you the address. I still live with her.', 1295896001142, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109484, 'user3', '94558dc0-8ad9-4ecb-aaa3-133bdea203f9', 'Thank you. One last question. Do you smoke?', 1295896001695, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109485, 'user3', '94558dc0-8ad9-4ecb-aaa3-133bdea203f9', 'I see. Let me ask your daughter a few questions before we start. Hi, ma''am. I understand you feel sick. Before we begin I just want to confirm some information with you. Where is your primary residency?', 1295895998042, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109486, 'user2', 'd655cd7c-07f4-43d8-986c-8b1e6781bbc5', 'Are you married, sir?', 1623590629714, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109487, 'user1', 'd655cd7c-07f4-43d8-986c-8b1e6781bbc5', 'Yes, I''m lucky to have, and live with my lovely wife.', 1623590632412, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109488, 'user1', 'd655cd7c-07f4-43d8-986c-8b1e6781bbc5', 'Thank you, Doctor.', 1623590648984, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109489, 'user1', 'd655cd7c-07f4-43d8-986c-8b1e6781bbc5', 'Yes, she was lovely as well, I hope you''re paying them well.', 1623590637561, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109490, 'user2', 'd655cd7c-07f4-43d8-986c-8b1e6781bbc5', 'We take good care of them. They''ll be happy to hear that. Let me look, she should have left me some notes, um, yep, these look good, I agree with all of this. This looks good.', 1623590642889, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109491, 'user2', 'd655cd7c-07f4-43d8-986c-8b1e6781bbc5', 'That''s very nice. Did you speak with the nurse before I came in here?', 1623590634157, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109492, 'user2', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'Hi. How are you doing, sir?', 1106633942729, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109493, 'user1', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'Hi. I am doing fine.', 1106633948257, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109494, 'user1', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'I worked on the pipeline. The accident was five years ago.', 1106633952965, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109495, 'user2', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'Which condition led to the disability?', 1106633976681, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109496, 'user1', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'I don''t know really. I sent in all the notes for my doctor for evaluation and they approved the disability.', 1106633952247, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109497, 'user2', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'Okay. Do you live alone or with family?', 1106633957614, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109498, 'user1', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'I live with my wife.', 1106633992110, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109499, 'user2', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'Are you a smoke or have you ever been?', 1106633975312, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109500, 'user1', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'I used to smoke. I quit years ago.', 1106633962785, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109501, 'user2', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'How long ago did you quit?', 1106633980807, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109502, 'user1', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'Oh, about twenty years ago.', 1106633957635, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109503, 'user2', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'How many years did you smoke? And how much did you smoke?', 1106633991760, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109504, 'user1', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'Probably twenty years. I was up to two packs a day. I feel way better now.', 1106634017483, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109505, 'user2', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'That''s great. Any use of alcohol or illicit drugs?', 1106633991384, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109506, 'user1', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'Nope.', 1106634014262, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109507, 'user2', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'What do you do for fun? Do you have any hobbies?', 1106633986831, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109508, 'user1', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'I don''t really do much these days. Work was my hobby.', 1106633979911, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109509, 'user2', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'Okay.', 1106634007164, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109510, 'user2', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'The nurse told me that you are on disability from work now. What happened?', 1106633950712, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109511, 'user1', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'I got hurt at work and now I am on disability.', 1106633948199, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109512, 'user2', '03818c2c-46c4-491d-83f6-bdde1be020fe', 'What did you do for work? How long ago was your injury?', 1106633958982, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109513, 'user2', 'c557da93-5dff-4ee2-9d3f-8f3f310d8145', 'How''re you doing today?', 997994359703, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109514, 'user2', 'c557da93-5dff-4ee2-9d3f-8f3f310d8145', 'Gotcha. That''s still nice. We used to have a golden when I was a kid. They''re the sweetest dogs.', 997994371693, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109515, 'user1', 'c557da93-5dff-4ee2-9d3f-8f3f310d8145', 'They are very sweet.', 997994373723, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109516, 'user2', 'c557da93-5dff-4ee2-9d3f-8f3f310d8145', 'Okay, so you''re in for a follow up for your neck and back pain.', 997994379580, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109517, 'user1', 'c557da93-5dff-4ee2-9d3f-8f3f310d8145', 'Yessir.', 997994379078, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109518, 'user2', 'c557da93-5dff-4ee2-9d3f-8f3f310d8145', 'Have you been going to pain management?', 997994384837, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109519, 'user1', 'c557da93-5dff-4ee2-9d3f-8f3f310d8145', 'Yeah, I go once every week or so.', 997994369359, 9);
