INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109522, 'user2', 'c557da93-5dff-4ee2-9d3f-8f3f310d8145', 'Is the pain still keeping you up at night?', 997994385684, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109523, 'user1', 'c557da93-5dff-4ee2-9d3f-8f3f310d8145', 'Not like it used to.', 997994419751, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109524, 'user2', 'c557da93-5dff-4ee2-9d3f-8f3f310d8145', 'Good, great to hear.', 997994442969, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109525, 'user1', 'c557da93-5dff-4ee2-9d3f-8f3f310d8145', 'Overall, pretty good.', 997994363264, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109526, 'user2', 'c557da93-5dff-4ee2-9d3f-8f3f310d8145', 'Any plans for the weekend?', 997994368482, 2);
