INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109530, 'user3', '737e3a37-0ac5-4ccf-91fc-d4897b868480', 'Do you smoke cigarettes?', 1284483551799, 0);
