INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109534, 'user1', '737e3a37-0ac5-4ccf-91fc-d4897b868480', 'Well, I don''t know very much about my dad''s side of the family but my dad did pass away from renal cancer.', 1284483593714, 7);
