INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109539, 'user1', '737e3a37-0ac5-4ccf-91fc-d4897b868480', 'No. It is very rare that I will have a drink.', 1284483571576, 5);
