INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109542, 'user2', '68016445-3036-490f-a883-b259f594213e', 'So, ma''am, what do you do for a living?', 1102906047842, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109543, 'user2', '68016445-3036-490f-a883-b259f594213e', 'That''s understandable. Do you have children?', 1102906062365, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109544, 'user1', '68016445-3036-490f-a883-b259f594213e', 'Yes, my husband and I were blessed with three wonderful children.', 1102906057236, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109545, 'user2', '68016445-3036-490f-a883-b259f594213e', 'Fantastic, do they live at home?', 1102906060493, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109546, 'user1', '68016445-3036-490f-a883-b259f594213e', 'Nope, we got them all out of there. They''re all grown now.', 1102906065186, 7);
