INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109550, 'user1', '68016445-3036-490f-a883-b259f594213e', 'No, absolutely not.', 1102906099519, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109551, 'user2', '68016445-3036-490f-a883-b259f594213e', 'Congratulations on your retirement. Where did you go to college?', 1102906054236, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109552, 'user1', '68016445-3036-490f-a883-b259f594213e', 'Oh, I didn''t go to college, I stopped after high school.', 1102906055696, 3);
