INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109562, 'user2', 'a6b2ce1d-b827-40f8-8b10-f29ae3bc8c00', 'How''s he feeling today?', 1148500981426, 0);
