INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109674, 'user2', 'cc047ed3-2079-4edb-aa1f-775b2a129be3', 'Hello, miss. It looks like you are here for your yearly physical. How is everything going?', 1192144621707, 0);
