INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109754, 'user3', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'Did you lose consciousness during any of your falls?', 1480991144851, 8);
