INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109756, 'user3', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'I''m sure that was difficult to experience.', 1480991140978, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109757, 'user1', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'It was very difficult. Two months prior to being diagnosed, I started to move much slower than before.', 1480991132567, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109758, 'user3', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'By slower, do you mean the movements of your arms and legs were slower and impaired?', 1480991176250, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109759, 'user1', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'Yes. I was prescribed Sinemet back in September of nineteen ninety five.', 1480991144177, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109760, 'user3', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'Did you notice any improvement while taking it?', 1480991164551, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109761, 'user1', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'None. I was pretty disappointed and discouraged as a result. I have problems with coordination and walking without staggering even today.', 1480991187467, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109762, 'user3', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'Noting that it''s February thirteenth nineteen ninety six.', 1480991181220, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109763, 'user1', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'I felt weak in the morning and worse as the day went on.', 1480991169355, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109764, 'user3', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'Are you experiencing any other symptoms, such as stroke like events, vision changes, seizures, or problems with moving and coordinating your arms?', 1480991185400, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109765, 'user1', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'No.', 1480991155043, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109766, 'user3', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'Any headache, nausea, vomiting, chills, or fever?', 1480991207675, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109767, 'user1', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'No.', 1480991132444, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109768, 'user1', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'Right.', 1480991111056, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109769, 'user1', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'A local doctor I was seeing at the time. A year before my diagnosis, I had a few falls and episodes of lightheadedness. I also noticed that I was staggering a lot more when walking.', 1480991118523, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109770, 'user1', 'a5bf0a63-20b8-4a0a-bb0a-8110340cfb0f', 'September first of nineteen ninety five.', 1480991113585, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109771, 'user2', '5f91c892-306a-4eae-801f-bfd039eb060b', 'Hi there! How are the both of you doing today?', 1730666429231, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109772, 'user2', '5f91c892-306a-4eae-801f-bfd039eb060b', 'During his coughing episode this morning, did you notice any loss of breath or gasping for air?', 1730666433534, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109773, 'user1', '5f91c892-306a-4eae-801f-bfd039eb060b', 'No.', 1730666453115, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109774, 'user2', '5f91c892-306a-4eae-801f-bfd039eb060b', 'Has he had a runny nose?', 1730666440076, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109775, 'user1', '5f91c892-306a-4eae-801f-bfd039eb060b', 'No.', 1730666470362, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109776, 'user2', '5f91c892-306a-4eae-801f-bfd039eb060b', 'Any fever?', 1730666466037, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109777, 'user1', '5f91c892-306a-4eae-801f-bfd039eb060b', 'No. He has not been eating much.', 1730666466803, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109778, 'user2', '5f91c892-306a-4eae-801f-bfd039eb060b', 'Is anyone else in the household sick?', 1730666456728, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109779, 'user1', '5f91c892-306a-4eae-801f-bfd039eb060b', 'No.', 1730666466082, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109780, 'user2', '5f91c892-306a-4eae-801f-bfd039eb060b', 'Is anyone in the household a smoker?', 1730666499515, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109781, 'user1', '5f91c892-306a-4eae-801f-bfd039eb060b', 'No.', 1730666480233, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109782, 'user1', '5f91c892-306a-4eae-801f-bfd039eb060b', 'He has a bad cough. He''s been sick for the last three or four days. It sounds like there is phlegm rattling around in there when he coughs. He had a bad coughing fit this morning. I got nervous and decided to bring him in.', 1730666437497, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109783, 'user1', '5f91c892-306a-4eae-801f-bfd039eb060b', 'I am doing well but my son is sick.  He is two and a half years old.', 1730666432157, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109784, 'user2', '5f91c892-306a-4eae-801f-bfd039eb060b', 'What are his symptoms?', 1730666437296, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109785, 'user2', '8f713185-9f60-4441-a426-8622e536d463', 'Any medical diseases in the family?', 1615384185233, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109786, 'user1', '8f713185-9f60-4441-a426-8622e536d463', 'Yeah, mainly heart issues. My father died from heart attack.', 1615384188878, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109787, 'user2', '8f713185-9f60-4441-a426-8622e536d463', 'What about your mother?', 1615384190283, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109788, 'user1', '8f713185-9f60-4441-a426-8622e536d463', 'She had the second type of diabetes.', 1615384188698, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109789, 'user2', 'abfee233-b5cb-4800-bd7d-222a7efd0c7e', 'So just to double check. No past medical history?', 1589162389134, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109790, 'user1', 'abfee233-b5cb-4800-bd7d-222a7efd0c7e', 'Yes, sir. None.', 1589162394686, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109791, 'user3', 'e852db4b-2495-4565-95ef-04574de95f79', 'Do you drink or smoke, ma''am?', 1192881436665, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109792, 'user3', 'e852db4b-2495-4565-95ef-04574de95f79', 'Very good. Do you have any history of S T D that you know about?', 1192881457024, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109793, 'user1', 'e852db4b-2495-4565-95ef-04574de95f79', 'No, there''s no history of any of that there.', 1192881449181, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109794, 'user1', 'e852db4b-2495-4565-95ef-04574de95f79', 'No, none of that either.', 1192881441960, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109795, 'user1', 'e852db4b-2495-4565-95ef-04574de95f79', 'No, I don''t do any of that.', 1192881438066, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109796, 'user3', 'e852db4b-2495-4565-95ef-04574de95f79', 'Good, what about harder drugs?', 1192881439061, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109797, 'user2', 'f7c680f0-faf8-4b98-afb0-8bb573cc968b', 'What medications are you taking?', 1354740592139, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109798, 'user1', 'f7c680f0-faf8-4b98-afb0-8bb573cc968b', 'I take Prilosec and Tramadol when I have back pain.', 1354740597707, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109799, 'user2', '5bd7c41f-05d9-42db-9b76-d86716afd238', 'Any drug allergies?', 1128169420423, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109800, 'user1', '5bd7c41f-05d9-42db-9b76-d86716afd238', 'No.', 1128169425003, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109801, 'user2', '57f3c5cf-3f74-4fbe-99ff-aa2a894f2c75', 'How often are you vomiting?', 1070604257178, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109802, 'user1', '57f3c5cf-3f74-4fbe-99ff-aa2a894f2c75', 'At least three times until my stomach is empty.', 1070604260899, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109803, 'user1', '57f3c5cf-3f74-4fbe-99ff-aa2a894f2c75', 'Yes.', 1070604274942, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109804, 'user2', '57f3c5cf-3f74-4fbe-99ff-aa2a894f2c75', 'Can you think of something this is related to?', 1070604262203, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109805, 'user2', '57f3c5cf-3f74-4fbe-99ff-aa2a894f2c75', 'Do you get belly pain?', 1070604272007, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109806, 'user1', '57f3c5cf-3f74-4fbe-99ff-aa2a894f2c75', 'Just when I eat raw carrots and celery.', 1070604269370, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109807, 'user2', '98777755-f81b-452a-8ed5-33b48836b3a9', 'Good morning, ma''am. Can you confirm your age for me?', 1152103723251, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109808, 'user2', '98777755-f81b-452a-8ed5-33b48836b3a9', 'Have you had any improvement with the rest and antiinflammatories we''ve talked about before?', 1152103732861, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109809, 'user1', '98777755-f81b-452a-8ed5-33b48836b3a9', 'No, they haven''t helped at all.', 1152103730403, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109810, 'user2', '98777755-f81b-452a-8ed5-33b48836b3a9', 'I see, you''d be a good candidate for a knee replacement.', 1152103731184, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109811, 'user1', '98777755-f81b-452a-8ed5-33b48836b3a9', 'What''s the risk of infection from the surgery?', 1152103753871, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109812, 'user2', '98777755-f81b-452a-8ed5-33b48836b3a9', 'Historically, it''s less than one percent, we use prophylactic antibiotics to control for infection the entire time.', 1152103760094, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109813, 'user1', '98777755-f81b-452a-8ed5-33b48836b3a9', 'Great, and will I be asleep for this?', 1152103740154, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109814, 'user2', '98777755-f81b-452a-8ed5-33b48836b3a9', 'Yes, you won''t feel a thing.', 1152103749984, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109815, 'user1', '98777755-f81b-452a-8ed5-33b48836b3a9', 'Well, doctor, I''m sixty six years old now.', 1152103725653, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109816, 'user2', '98777755-f81b-452a-8ed5-33b48836b3a9', 'Thank you, so, how is your knee doing today? Hope the osteoarthritis is getting better.', 1152103726076, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109817, 'user1', '98777755-f81b-452a-8ed5-33b48836b3a9', 'It''s so bad, doctor.', 1152103736957, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109818, 'user2', '3ececfc4-96e8-4b61-8792-e9c95d767d0e', 'How old are you?', 1235323574173, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109819, 'user1', '3ececfc4-96e8-4b61-8792-e9c95d767d0e', 'I am twenty four.', 1235323579438, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109820, 'user2', '3ececfc4-96e8-4b61-8792-e9c95d767d0e', 'What brings you in today?', 1235323579858, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109821, 'user1', '3ececfc4-96e8-4b61-8792-e9c95d767d0e', 'I have been having this back pain for a long time. I thought I should come and get it checked out because it has not gotten any better.', 1235323583961, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109822, 'user2', '3edbd0c3-d46a-4e1f-a96f-0331fdbf3fa5', 'Any medical issues running in your family?', 1270884073302, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109823, 'user1', '3edbd0c3-d46a-4e1f-a96f-0331fdbf3fa5', 'I don''t know anything about that.', 1270884074555, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109824, 'user2', '3edbd0c3-d46a-4e1f-a96f-0331fdbf3fa5', 'You know anyone in your family or relatives who ever had diseases like diabetes or any heart issues?', 1270884081148, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109825, 'user1', '3edbd0c3-d46a-4e1f-a96f-0331fdbf3fa5', 'Nope.', 1270884077713, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109826, 'user2', 'cdf81d0f-99f6-4867-9526-4e027f2d50a8', 'Hello, miss. Could you verify your age, please?', 1275498366641, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109827, 'user1', 'cdf81d0f-99f6-4867-9526-4e027f2d50a8', 'I''m fifty five years old.', 1275498369681, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109828, 'user1', 'cdf81d0f-99f6-4867-9526-4e027f2d50a8', 'Oh, it''s a long list. Here it is.', 1275498386273, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109829, 'user2', 'cdf81d0f-99f6-4867-9526-4e027f2d50a8', 'Thank you. Let me take a look. Looks like you have some general allergies and food allergies, loss of taste, problems with your G I tract, asthma, G E R D, and dry mouth or xerostomia.', 1275498384987, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109830, 'user1', 'cdf81d0f-99f6-4867-9526-4e027f2d50a8', 'Yeah, that sounds about right. I think I forgot to add it, but I also have bad allergies during the spring time.', 1275498395326, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109831, 'user2', 'cdf81d0f-99f6-4867-9526-4e027f2d50a8', 'Oh, I see. I would describe that as environmental inhalant allergies.', 1275498412104, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109832, 'user2', 'cdf81d0f-99f6-4867-9526-4e027f2d50a8', 'Great. What is the reason for your visit today?', 1275498376936, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109833, 'user1', 'cdf81d0f-99f6-4867-9526-4e027f2d50a8', 'I''ve been having a lot of problems recently, so I decided to come get it checked out by you.', 1275498374499, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109834, 'user2', 'cdf81d0f-99f6-4867-9526-4e027f2d50a8', 'I see. What kind of problems are you experiencing?', 1275498380390, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109835, 'user2', 'dc9f8f79-98d4-4d03-8e61-d2af0b2a2297', 'Are you a smoker?', 1397255047752, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109836, 'user1', 'dc9f8f79-98d4-4d03-8e61-d2af0b2a2297', 'Yes.', 1397255049489, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109837, 'user1', 'dc9f8f79-98d4-4d03-8e61-d2af0b2a2297', 'I did do a little bit of coke today.', 1397255056680, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109838, 'user2', 'dc9f8f79-98d4-4d03-8e61-d2af0b2a2297', 'Okay.', 1397255064371, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109839, 'user2', 'dc9f8f79-98d4-4d03-8e61-d2af0b2a2297', 'Any current use of drugs or alcohol?', 1397255064668, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109840, 'user2', 'dc9f8f79-98d4-4d03-8e61-d2af0b2a2297', 'Do you use alcohol or any recreational drugs?', 1397255058107, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109841, 'user1', 'dc9f8f79-98d4-4d03-8e61-d2af0b2a2297', 'I have been in treatment for heroin and alcohol in the past.', 1397255062283, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109842, 'user3', 'ac037c25-7ec0-4535-85a3-1df8aeca4bd7', 'Do you take any-', 1206040243404, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109843, 'user1', 'ac037c25-7ec0-4535-85a3-1df8aeca4bd7', 'Meds?', 1206040244884, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109844, 'user1', 'ac037c25-7ec0-4535-85a3-1df8aeca4bd7', 'Yes, that''s it! I keep that on hand in case my asthma gets outta control.', 1206040264714, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109845, 'user3', 'ac037c25-7ec0-4535-85a3-1df8aeca4bd7', 'Is it up to date?', 1206040275423, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109846, 'user1', 'ac037c25-7ec0-4535-85a3-1df8aeca4bd7', 'You mean is it expired? No, I don''t think so. It hasn''t been long since I visited the pharmacy.', 1206040267857, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109847, 'user3', 'ac037c25-7ec0-4535-85a3-1df8aeca4bd7', 'Good. I always like to advise my patients to check expiration dates.', 1206040283551, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109848, 'user3', 'ac037c25-7ec0-4535-85a3-1df8aeca4bd7', 'Yes.', 1206040246179, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109849, 'user1', 'ac037c25-7ec0-4535-85a3-1df8aeca4bd7', 'I do. I take Allegra for seasonal allergies. I also take something that starts with a P. I''m blanking on the name. My other doctor prescribed it to me for exercise induced asthma.', 1206040253627, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109850, 'user3', 'ac037c25-7ec0-4535-85a3-1df8aeca4bd7', 'Oh, do you mean Proventil?', 1206040262979, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109851, 'user2', 'a9b449c1-124c-4fc0-b103-f3fa04b4e3b8', 'Welcome into the office.', 1581665776987, 0);
