INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109853, 'user2', 'a9b449c1-124c-4fc0-b103-f3fa04b4e3b8', 'Let us start with your family medical history.', 1581665788806, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109854, 'user1', 'a9b449c1-124c-4fc0-b103-f3fa04b4e3b8', 'That is going to be a hard one. I was adopted and I do not know any family medical history.', 1581665781082, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109855, 'user1', 'a9b449c1-124c-4fc0-b103-f3fa04b4e3b8', 'Thank you.', 1581665781145, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109856, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'So, you are here to review your sleep study results, right?', 1734905658378, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109857, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'That''s right.', 1734905661042, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109858, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'First let''s go back to your medical history a little bit and then we will continue with the result. Patient: Sure.', 1734905661229, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109859, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'It is consistent. I go to bed anytime between nine to ten at night and wake up in the morning around five to six.', 1734905689812, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109860, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'Are you able to sleep as soon as you go to bed?', 1734905677012, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109861, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'No, it''s hard for me to start that sleeping process and then I''m awake in like every one or two hours throughout the night. I keep on tossing and turning throughout the night. I always find my sheets out of order when I wake up.', 1734905675453, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109862, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'How would you compare your sleep here in the lab and at your home?', 1734905700699, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109863, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'I would say I slept better in the laboratory than I do at home.', 1734905694016, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109864, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'How do you feel when you wake up in the morning?', 1734905709704, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109865, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'Honestly, I feel tired. Sometimes I also have this dull headache.', 1734905691416, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109866, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'Do you snore?', 1734905733937, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109867, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'I don''t know for myself, but yeah, my daughter was teasing me another day that I was snoring and was talking in my sleep.', 1734905742160, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109868, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'Did you ever feel that you have difficulty breathing while you are asleep?', 1734905681099, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109869, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'No. But I used to cough a lot in the middle of the night.', 1734905742827, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109870, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'You said you used to, so it is not anymore?', 1734905722747, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109871, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'Yeah, I haven''t been coughing for the last few weeks.', 1734905725565, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109872, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'How''s your daily routine? Do you nap in the daytime?', 1734905733282, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109873, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'I spent a lot of time reading and watching T V. Sometimes I doze off while doing that. Not regular, but I do take nap sometimes in between two to three in afternoon and also in the evening hours.', 1734905729178, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109874, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'Do you smoke?', 1734905763036, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109875, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'Oh yes, I take around one to two packs of cigarettes each day mainly after dinner.', 1734905694669, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109876, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'Have you noticed any change in your weight?', 1734905764383, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109877, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'My weight always keeps fluctuating. I remember I was at my maximum weight of two hundred and sixty pounds around one year ago.', 1734905722923, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109878, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'If that was your maximum how is your weight now?', 1734905725719, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109879, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'Now it is down by approximately thirty pounds.', 1734905760663, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109880, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'So, for your health care, you are coming here in the outpatient psychiatry and also going to your maintenance clinic, right?', 1734905712478, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109881, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'Yes, that''s right.', 1734905770129, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109882, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'Your current medications include Methadone, Trazodone, and Seroquel.', 1734905774786, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109883, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'That sounds right.', 1734905789433, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109884, 'user1', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'That''s right. I was then scheduled for the overnight sleep study to be evaluated for interruptions in my sleep and here we are today to discuss results.', 1734905667818, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109885, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'Sure. But first tell me, how is your sleeping routine like?', 1734905679604, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109886, 'user2', '20ce3c91-0822-442b-97f4-5d56e6ba23b1', 'So, you first came to our Pulmonary Clinic, and you were suffering with dyspnea even on minimal exertion. At that time, we evaluated you and we realized that there was some evidence of irregular sleep and daytime fatigue. At that time you also complained of nighttime choking episodes which got less intense over the past many months.', 1734905674136, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109887, 'user2', '890e74b8-bc5d-4c4c-bd7d-62594832a100', 'So, I see you were diagnosed with an acid reflux problem and high blood pressure twenty years back?', 1077740879080, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109888, 'user2', '890e74b8-bc5d-4c4c-bd7d-62594832a100', 'Also, you had a brain stroke?', 1077740889132, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109889, 'user1', '890e74b8-bc5d-4c4c-bd7d-62594832a100', 'Yes, both.', 1077740895977, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109890, 'user2', '890e74b8-bc5d-4c4c-bd7d-62594832a100', 'Ah, yes. We also call it as T I A.', 1077740901611, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109891, 'user1', '890e74b8-bc5d-4c4c-bd7d-62594832a100', 'Okay.', 1077740887918, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109892, 'user2', '890e74b8-bc5d-4c4c-bd7d-62594832a100', 'And currently are you on any medications?', 1077740903540, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109893, 'user1', '890e74b8-bc5d-4c4c-bd7d-62594832a100', 'Yes, mini stroke!', 1077740907770, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109894, 'user2', '890e74b8-bc5d-4c4c-bd7d-62594832a100', 'Yeah, atrial fibrillation.', 1077740908756, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109895, 'user1', '890e74b8-bc5d-4c4c-bd7d-62594832a100', 'Yes.', 1077740944566, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109896, 'user1', '890e74b8-bc5d-4c4c-bd7d-62594832a100', 'Just Coumadin, for my chronic A Fib. I have been on it three years.', 1077740894635, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109897, 'user2', '890e74b8-bc5d-4c4c-bd7d-62594832a100', 'And then you also have arthritis and Parkinson''s.', 1077740882399, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109898, 'user1', '890e74b8-bc5d-4c4c-bd7d-62594832a100', 'Yes.', 1077740880555, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109899, 'user3', 'e0bf6343-c569-4415-b235-c2b1e65f53c3', 'Good morning, ma''am.', 985658095771, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109900, 'user3', 'e0bf6343-c569-4415-b235-c2b1e65f53c3', 'That''s good to hear, ma''am.', 985658113239, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109901, 'user3', 'e0bf6343-c569-4415-b235-c2b1e65f53c3', 'How are you feeling today?', 985658099753, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109902, 'user1', 'e0bf6343-c569-4415-b235-c2b1e65f53c3', 'Honestly, I''m feeling a little bit better.', 985658106615, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109903, 'user1', 'e0bf6343-c569-4415-b235-c2b1e65f53c3', 'Good morning, doctor.', 985658096786, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109904, 'user3', 'abd1d230-6bce-4c99-9ad8-7b708f3cd901', 'I see here that he may need antibiotic therapy for possible cellulitis of his lower extremities.', 971043997859, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109905, 'user3', 'abd1d230-6bce-4c99-9ad8-7b708f3cd901', 'According to the patient, his symptoms started getting progressively worse over the past two days.', 971044001336, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109906, 'user3', 'abd1d230-6bce-4c99-9ad8-7b708f3cd901', 'Does he have a history of cellulitis?', 971044005460, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109907, 'user3', 'abd1d230-6bce-4c99-9ad8-7b708f3cd901', 'No.', 971044006212, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109908, 'user2', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'Welcome to the clinic.', 1358329534183, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109909, 'user1', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'Thank you.', 1358329537210, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109910, 'user2', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'Are you from the area?', 1358329541441, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109911, 'user1', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'No. I was born and raised in North Carolina. I am the sixth of nine siblings.', 1358329537639, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109912, 'user2', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'That is a lot. What is your medical history involving your parents?', 1358329555036, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109913, 'user1', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'My family has significant amount of diabetes, heart disease, high blood pressure, thyroid problems, autoimmune disease, possible multiple sclerosis, and depression issues.', 1358329540240, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109914, 'user1', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'No. I mostly got A''s and B''s.  My strongest subject was math, but my worst subject was spelling. My grades were still quite good in spelling, but I had to work hard at it.', 1358329561425, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109915, 'user2', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'Are you married?', 1358329590579, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109916, 'user1', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'I was married for two years. We had two children together. They are forty three and thirty now. My son is the youngest, lives nearby and calls me or stops by every day. My daughter calls me often but she lives in New York. We are close. Their dad, my exhusband passed away in nineteen eighty. He was an alcoholic. His pancreas had enough and shut down.', 1358329546395, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109917, 'user2', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'I am so sorry.', 1358329588388, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109918, 'user1', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'He did it to himself.', 1358329580761, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109919, 'user2', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'Are you working in health care with your nursing degree?', 1358329558637, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109920, 'user1', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'I worked for Hospital Center for four years. Prior to that, I worked for an outpatient mental health center. I was there for about two and a years. I was fired or laid off I guess? I was not sure why they let me go. I was given no explanation. And before that, I worked for Walter P. Carter Center for twenty one years. I also worked as an O B nurse.  Other than the two instances, I had never been fired or let go from a job.', 1358329559947, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109921, 'user2', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'What do you do in your spare time now?', 1358329597290, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109922, 'user1', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'I enjoy reading, doing puzzles, playing computer games. I joined a women''s support group for women my age. I keep myself, busy.', 1358329560231, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109923, 'user2', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'Tell me about you family medical history.', 1358329552451, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109924, 'user2', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'Did you have any problems in school such as learning disabilities, attentional problems, difficulty learning to read, failed grades, special help in school or behavioral problems?', 1358329559482, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109925, 'user1', 'ff7489fd-54b5-4b10-8628-985b467844f2', 'My dad died due to complications of his diabetes.  He passed when he was sixty. My dad was a chef. My mom is doing well. She is ninety three. Both my parents never finished high school. My dad had a third grade education and my mom made it through fourth grade. She was a janitor. She was a smart woman she just never finished her schooling. My parents encouraged me to finish school and to go to college. I got my Bachelor of Science in Nursing at the State University in nineteen seventy nine.', 1358329562841, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109926, 'user1', '81e12e96-2484-4450-90ce-c67bca1983bf', 'Good afternoon, doctor.', 1131709261992, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109927, 'user2', '81e12e96-2484-4450-90ce-c67bca1983bf', 'How old are you, sir?', 1131709269328, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109928, 'user1', '81e12e96-2484-4450-90ce-c67bca1983bf', 'Well, at first, we went to Sierra Pacific Orthopedic Group, and he had an M R I that showed, um, O C D in the left knee.', 1131709280175, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109929, 'user2', '81e12e96-2484-4450-90ce-c67bca1983bf', 'Yes, I see that from the report.', 1131709269109, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109930, 'user1', '81e12e96-2484-4450-90ce-c67bca1983bf', 'So, we''re here for a second opinion on that.', 1131709279922, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109931, 'user2', '81e12e96-2484-4450-90ce-c67bca1983bf', 'Yes, we should do surgery on this knee. There''s gross instability of the fragment, and we don''t want that get worse.', 1131709286620, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109932, 'user1', '81e12e96-2484-4450-90ce-c67bca1983bf', 'Okay, that''s about what we''ve heard so far. What are the risks of infection of the procedure?', 1131709296335, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109933, 'user2', '81e12e96-2484-4450-90ce-c67bca1983bf', 'It''s less than one percent. We use antibiotics to control for infection. Other risks include bleeding, changes in sensation of the limb, changes in motion, failure to relieve pain or restore the articular cartilage, the possible need for another procedure, and possible early arthritis. I would not worry, though. These things are rare.', 1131709276535, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109934, 'user1', '81e12e96-2484-4450-90ce-c67bca1983bf', 'Okay, will he be asleep the entire time?', 1131709314288, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109935, 'user2', '81e12e96-2484-4450-90ce-c67bca1983bf', 'Yes, he won''t feel a thing.', 1131709289079, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109936, 'user1', '81e12e96-2484-4450-90ce-c67bca1983bf', 'Okay, my husband agrees. We want to do the surgery.', 1131709294695, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109937, 'user2', '81e12e96-2484-4450-90ce-c67bca1983bf', 'Good afternoon, young man.', 1131709258510, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109938, 'user2', '81e12e96-2484-4450-90ce-c67bca1983bf', 'So, what brings you in today?', 1131709270903, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109939, 'user1', '81e12e96-2484-4450-90ce-c67bca1983bf', 'I''m thirteen.', 1131709269817, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109940, 'user2', '23f8b88f-23c4-49b0-ba38-d70ceb694bd1', 'Good afternoon, young lady.', 987748742474, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109941, 'user1', '23f8b88f-23c4-49b0-ba38-d70ceb694bd1', 'Good afternoon, doctor.', 987748748227, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109942, 'user2', '23f8b88f-23c4-49b0-ba38-d70ceb694bd1', 'Let''s get the personal questions out of the way to begin, shall we?', 987748748139, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109943, 'user2', '23f8b88f-23c4-49b0-ba38-d70ceb694bd1', 'Have you had any S T D s recently?', 987748764755, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109944, 'user1', '23f8b88f-23c4-49b0-ba38-d70ceb694bd1', 'No, not that I know of.', 987748762915, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109945, 'user2', '23f8b88f-23c4-49b0-ba38-d70ceb694bd1', 'I''m looking here, and your last P P D was negative, but we''ll do another one today.', 987748761742, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109946, 'user1', '23f8b88f-23c4-49b0-ba38-d70ceb694bd1', 'Okay, that''s fine, doctor.', 987748782417, 9);
