INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109966, 'user2', '6a5b17a5-9911-4a6d-bd45-57ee800f10f6', 'Hello, what brings you here today?', 1293463546364, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109967, 'user1', '6a5b17a5-9911-4a6d-bd45-57ee800f10f6', 'I fell four times on third of this month because my leg suddenly gave out.', 1293463551631, 1);
