INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109971, 'user2', '6a5b17a5-9911-4a6d-bd45-57ee800f10f6', 'So, you said that your legs suddenly gave out. What happened exactly? Was it sudden? Or were you noticing some weakness before as well?', 1293463562882, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109972, 'user1', '6a5b17a5-9911-4a6d-bd45-57ee800f10f6', 'Oh, I noticed weakness in my right leg before as well and sometimes, like, I have to give the support of my arm to actually move it. Sometimes during these episodes I just turn pale and it''s like overall weakness. I feel so tired. My husband, he gives me some sugar, three teaspoons, and then it helps a little bit but not completely.', 1293463595390, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109973, 'user2', '6a5b17a5-9911-4a6d-bd45-57ee800f10f6', 'So, is your weakness like overall in your legs or it is at any single point?', 1293463591064, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109974, 'user2', '6a5b17a5-9911-4a6d-bd45-57ee800f10f6', 'I know I''m in the wrong profession. I have to do that every time I meet someone. So how old are you?', 1293463551759, 4);
