INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109979, 'user2', '6a5b17a5-9911-4a6d-bd45-57ee800f10f6', 'Any difficulty in swallowing or eating? Any loss of consciousness?', 1293463626920, 16);
