INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (109983, 'user2', '6a5b17a5-9911-4a6d-bd45-57ee800f10f6', 'You said that these episodes have been happening for some time, so did you see anyone for those before?', 1293463595511, 20);
