INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110044, 'user1', '254bb853-1e6a-49e0-80ce-07639ea13df3', 'I try to, I know it is a good source of calcium and is very essential especially with my pregnancy, but I am not a big fan of drinking milk.', 1324466628761, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110045, 'user1', '254bb853-1e6a-49e0-80ce-07639ea13df3', 'It takes around twenty minutes on one side. So, everyday it is like forty minutes in the morning and same in the evening around four.', 1324466568511, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110046, 'user1', '254bb853-1e6a-49e0-80ce-07639ea13df3', 'No, this is my second pregnancy. I had gestational diabetes with my first one as well.', 1324466554110, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110047, 'user2', '254bb853-1e6a-49e0-80ce-07639ea13df3', 'Were you taking any insulin at that time?', 1324466563074, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110048, 'user2', '3759faf9-dbb0-4624-a124-20f508469196', 'Do you know of any family history of kyphosis?', 1099506148132, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110049, 'user1', '3759faf9-dbb0-4624-a124-20f508469196', 'I''m sorry, what''s that?', 1099506151161, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110050, 'user2', '3759faf9-dbb0-4624-a124-20f508469196', 'It has to do with rounding of the spine. Does anyone in your family have a rounded posture?', 1099506156725, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110051, 'user1', '3759faf9-dbb0-4624-a124-20f508469196', 'Actually, yeah, my great grandmother had that, and my mom would talk about my second cousin, he had it too.', 1099506156622, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110052, 'user2', '75e961aa-1c52-4830-a00a-bb349f4650d0', 'When did you retire from your job?', 1312145172589, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110053, 'user1', '75e961aa-1c52-4830-a00a-bb349f4650d0', 'About eleven years ago. It''s definitely been nice. I''m able to spend more time with my grandkids.', 1312145174097, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110054, 'user2', '75e961aa-1c52-4830-a00a-bb349f4650d0', 'Aw, how many grandkids do you have? And do you live alone?', 1312145183375, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110055, 'user1', '75e961aa-1c52-4830-a00a-bb349f4650d0', 'I have four grandkids between the ages of two and eleven. I live in the county with my wife and dog. My wife and I''ve been together for thirty some years now.', 1312145178068, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110056, 'user2', '75e961aa-1c52-4830-a00a-bb349f4650d0', 'That''s so wonderful to hear.', 1312145177570, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110057, 'user2', '5fcc46a7-967b-4a8d-a80a-20b813e4c133', 'Good afternoon, young lady.', 1616075623228, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110058, 'user2', '5fcc46a7-967b-4a8d-a80a-20b813e4c133', 'Well, it could be worse, but we''re at a plateau, I''d like to see you lose some more per month.', 1616075637131, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110059, 'user2', '5fcc46a7-967b-4a8d-a80a-20b813e4c133', 'How has your weight been since your last visit, with the phentermine?', 1616075632967, 2);
