INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110061, 'user1', '5fcc46a7-967b-4a8d-a80a-20b813e4c133', 'My lowest? That was one hundred thirty six. I''m just as frustrated as you are, doctor.', 1616075665182, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110062, 'user2', '5fcc46a7-967b-4a8d-a80a-20b813e4c133', 'Well, if this plateau continues, we should discontinue the phentermine.', 1616075643677, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110063, 'user1', '5fcc46a7-967b-4a8d-a80a-20b813e4c133', 'Why is that?', 1616075660948, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110064, 'user2', '5fcc46a7-967b-4a8d-a80a-20b813e4c133', 'It shouldn''t be used to maintain your weight, but only to get the weight down. So, if it''s not serving that purpose, we shouldn''t use it. There''s no real benefit there.', 1616075647097, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110065, 'user1', '5fcc46a7-967b-4a8d-a80a-20b813e4c133', 'Okay, yes, I agree.', 1616075669895, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110066, 'user1', '5fcc46a7-967b-4a8d-a80a-20b813e4c133', 'Yeah, I''ve been working really hard, but I haven''t been able to get the weight down any further so far.', 1616075633116, 5);
