INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110074, 'user1', 'ced2a6d5-331b-4cd5-8b7e-3a1e02e0520f', 'You know doctor, I was born in Munich, Germany.', 1066257481631, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110075, 'user3', 'ced2a6d5-331b-4cd5-8b7e-3a1e02e0520f', 'Wow, I cannot tell, you speak English so well, no German accent.', 1066257485098, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110076, 'user1', 'ced2a6d5-331b-4cd5-8b7e-3a1e02e0520f', 'I had a high school degree from Germany, and I could speak German and English fluently.', 1066257506178, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110077, 'user1', 'ced2a6d5-331b-4cd5-8b7e-3a1e02e0520f', 'As soon as I landed here in America, I started working. I started as a secretary at a private firm and later did clerical work at I B M. Now I am retired for almost twenty years due to my cancer complications.', 1066257501046, 6);
