INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110195, 'user2', '2b37fd57-7aa2-42b0-b4bc-4aa3da3c170c', 'Okay good. So, the neurological exam we did earlier, I have the results for it.', 1531287251155, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110196, 'user1', '2b37fd57-7aa2-42b0-b4bc-4aa3da3c170c', 'And?', 1531287241132, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110197, 'user2', '2b37fd57-7aa2-42b0-b4bc-4aa3da3c170c', 'Well, you were tested positive for Phalen''s test on your left hand.', 1531287250106, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110198, 'user1', '2b37fd57-7aa2-42b0-b4bc-4aa3da3c170c', 'What does that means?', 1531287198025, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110199, 'user2', '2b37fd57-7aa2-42b0-b4bc-4aa3da3c170c', 'It means that you have something called Carpal tunnel syndrome, which explains your numbness and tingling sensation in your left hand. It also explains your pain in the middle part of your hand as it''s caused due to pinching or compression of a nerve called median nerve.', 1531287206899, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110200, 'user1', '2b37fd57-7aa2-42b0-b4bc-4aa3da3c170c', 'Oh, how did that happen?', 1531287313499, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110201, 'user2', '2b37fd57-7aa2-42b0-b4bc-4aa3da3c170c', 'Well, it''s possible that your repetitive hand motion could have caused it or sometimes it''s just the anatomy of your wrist.', 1531287209585, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110202, 'user1', '2b37fd57-7aa2-42b0-b4bc-4aa3da3c170c', 'Oh, that explains my increased pain in the night after work.', 1531287185160, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110203, 'user2', '2b37fd57-7aa2-42b0-b4bc-4aa3da3c170c', 'Yeah.', 1531287323743, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110204, 'user1', '2b37fd57-7aa2-42b0-b4bc-4aa3da3c170c', 'Anything else came in the neuro test?', 1531287274367, 35);
