INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110284, 'user3', '98c900cd-4e3b-4fad-9005-09846fb6bfb5', 'So, looks like you have stones in your C B D. I am not hundred percent sure but most likely its stones.', 1564376826065, 0);
