INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110293, 'user2', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'Can you tell me more about your son, please?', 1579050088071, 0);
