INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110296, 'user2', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'Good, what seems to be the problem today?', 1579050113116, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110297, 'user1', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'He keeps complaining about the back of his legs being tight.', 1579050118365, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110298, 'user2', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'Can you sit on the table, young man? Yes, I''m bending his legs, we call this the popliteal angle, and both sides flex to only about twenty.', 1579050109639, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110299, 'user1', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'Where should that be normally?', 1579050126204, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110300, 'user2', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'He should be able to get to ninety.', 1579050119906, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110301, 'user1', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'What can we do about this?', 1579050115272, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110302, 'user2', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'I think we should do surgery on this leg. How does he walk? Can I see?', 1579050129007, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110303, 'user1', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'Well, just look at him.', 1579050132559, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110304, 'user2', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'Yes, he does not walk with a crouched pattern, but he is toe walking.', 1579050170438, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110305, 'user1', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'Can we correct that instead of the hamstring tightness?', 1579050177680, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110306, 'user2', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'Well, I believe he should have surgery on the hamstring, as well.', 1579050175377, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110307, 'user1', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'Okay, right now we want to do surgery to fix his walking. What are the risks of infection?', 1579050107604, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110308, 'user2', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'They''re low, historically, they''re less than one percent. The risks include anesthesia, infection, bleeding, changes in sensation and the motion of walking, and it may also not always cure the toe walking. There is also possible stiffness after wearing the cast and other cast issues.', 1579050135701, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110309, 'user1', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'Okay, and will be under anesthesia during this? Is this worth it?', 1579050109950, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110310, 'user2', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'Absolutely, he won''t feel a thing. It is worth it because the chances of the risks happening are low.', 1579050144630, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110311, 'user1', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'Yes, we''d like to do the procedure. Let me text my husband really quick. Okay, yes, my husband agrees.', 1579050110852, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110312, 'user1', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'Well, he''s been using that since he started walking.', 1579050102841, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110313, 'user2', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'How old was he when he started walking?', 1579050108141, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110314, 'user2', '42b7ff72-d183-4fed-8d65-b724a2fcd641', 'How long has he used his walker?', 1579050094522, 2);
