INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110337, 'user2', '2624a6d8-81d0-4373-a662-bcdb13d45276', 'Can you tell me what surgeries have you had in the past?', 1555701955150, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110338, 'user1', '2624a6d8-81d0-4373-a662-bcdb13d45276', 'I have had appendix surgery when I was twenty one years old and eight years back I had C Section.', 1555701957074, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110339, 'user1', '2624a6d8-81d0-4373-a662-bcdb13d45276', 'Yes, I get heavy periods because of fibroids in my uterus.', 1555701975761, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110340, 'user2', '2624a6d8-81d0-4373-a662-bcdb13d45276', 'Oh. When was your last menstrual period?', 1555701988487, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110341, 'user1', '2624a6d8-81d0-4373-a662-bcdb13d45276', 'Oh, you can say about three weeks back.', 1555701977170, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110342, 'user2', '2624a6d8-81d0-4373-a662-bcdb13d45276', 'Okay. Good.', 1555702001297, 8);
