INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110345, 'user2', '2624a6d8-81d0-4373-a662-bcdb13d45276', 'Okay. Do you have any issues with your periods?', 1555701975535, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110346, 'user3', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'Hello, sir. Before we begin your visit, could you verify your age and ethnicity for me, please?', 1351578312021, 0);
