INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110351, 'user3', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'I see. So just the leg?', 1351578352093, 8);
