INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110354, 'user1', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'It was a whole show. A helicopter came down and swooped me to X Y Z Hospital, where I got surgery.', 1351578365294, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110355, 'user3', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'I can see you still have an external fixation on your knee so that the fracture heals. Did the hospital give you a report on the surgery?', 1351578352915, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110356, 'user1', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'Yeah, they did. Here you go.', 1351578368779, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110357, 'user3', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'Thank you. Let me take a look. So, it looks like you underwent grafting and full thickness skin grafting for closure for a large defect in your left posterior thigh. That seems to be healed in the gluteal fold on the left area.', 1351578383847, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110358, 'user1', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'Yeah. Whatever that means.', 1351578376965, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110359, 'user3', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'Let me examine the area.', 1351578380214, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110360, 'user1', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'Go for it.', 1351578329760, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110361, 'user3', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'I can see several areas that have hypergranulation tissues around the graft site and low in the leg.', 1351578353324, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110362, 'user1', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'Is that bad?', 1351578424812, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110363, 'user3', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'I don''t think so. Are you feeling any symptoms of a fever or anything?', 1351578403308, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110364, 'user1', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'No, I''m not.', 1351578374227, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110365, 'user3', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'That''s good. You don''t have any infections then.', 1351578344948, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110366, 'user1', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'The back of my left thigh.', 1351578331282, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110367, 'user1', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'I hurt the back of my leg pretty bad this past year when I was in A B C D.', 1351578341528, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110368, 'user1', 'f9f69feb-b4f9-4b75-9fc4-2ccdcdf9cb9a', 'I was referred to you so that I could get whatever''s wrong with me under control.', 1351578320160, 3);
