INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110382, 'user2', '767ab5c5-969d-4c3f-804c-497b197595c8', 'Welcome to the clinic, ma''am. I am Doctor Smith.', 1525342047636, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110383, 'user2', '767ab5c5-969d-4c3f-804c-497b197595c8', 'It looks like you have a birthday coming up. Happy early birthday!', 1525342068327, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110384, 'user1', '767ab5c5-969d-4c3f-804c-497b197595c8', 'Thank you. Yes, I am going to be seventy seven.', 1525342077577, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110385, 'user2', '767ab5c5-969d-4c3f-804c-497b197595c8', 'Doctor Kim''s notes said that you have had pain in the left flank pain. Can you tell me more about the pain?', 1525342074247, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110386, 'user1', '767ab5c5-969d-4c3f-804c-497b197595c8', 'Yes. The pain started four or five days ago. It has been in my stomach and through to my back, on the left side. Right here.', 1525342071164, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110387, 'user2', '767ab5c5-969d-4c3f-804c-497b197595c8', 'Okay. Have you had any nausea or vomiting?', 1525342058106, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110388, 'user1', '767ab5c5-969d-4c3f-804c-497b197595c8', 'Yes. I had some nausea, and I threw up a few times.', 1525342086196, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110389, 'user2', '767ab5c5-969d-4c3f-804c-497b197595c8', 'Have you noticed any blood, pain and or burning during urination?', 1525342077647, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110390, 'user1', '767ab5c5-969d-4c3f-804c-497b197595c8', 'No.', 1525342097143, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110391, 'user2', '767ab5c5-969d-4c3f-804c-497b197595c8', 'Any fever or chills?', 1525342101163, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110392, 'user1', '767ab5c5-969d-4c3f-804c-497b197595c8', 'No.', 1525342101984, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110393, 'user2', '767ab5c5-969d-4c3f-804c-497b197595c8', 'I have the ultrasound results that Doctor X ordered the other day.  The ultrasound found a stone in your left ureteral. The stone is about one point three C M in size.', 1525342099316, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110394, 'user1', '767ab5c5-969d-4c3f-804c-497b197595c8', 'Is there some thing we can do to remove it? I really want this taken care of.', 1525342090590, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110395, 'user2', '767ab5c5-969d-4c3f-804c-497b197595c8', 'Yes. Let us go over the treatment options.', 1525342142374, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110396, 'user1', '767ab5c5-969d-4c3f-804c-497b197595c8', 'Yes. He is my primary care doctor.', 1525342059240, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110397, 'user1', '767ab5c5-969d-4c3f-804c-497b197595c8', 'Thank you. It is nice to meet you.', 1525342051321, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110398, 'user2', '767ab5c5-969d-4c3f-804c-497b197595c8', 'Doctor X referred you to us, is that correct?', 1525342054676, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110399, 'user2', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Good afternoon, ma''am. You''re forty one years old, correct?', 1334708089950, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110400, 'user2', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Oh, just because she referred you to me.', 1334708113221, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110401, 'user2', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Thank you, have you followed up with Doctor X since your surgery?', 1334708092237, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110402, 'user2', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'That''s fine. Have you heard the details behind your surgery?', 1334708117188, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110403, 'user1', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'I heard it once, but I can''t remember anything. Can you remind me?', 1334708128406, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110404, 'user2', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Well, you had a complicated case, but we did an anterior cervical discectomy, two level corpectomy, with a spinal decompression and fusion with fibular strut and machine allograft in your large cervical plate.', 1334708129464, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110405, 'user1', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Oh, that''s a lot, doctor.', 1334708126499, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110406, 'user2', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Yes, how are you doing today?', 1334708148311, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110407, 'user1', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Well, I''ve felt good for the last two days.', 1334708106894, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110408, 'user2', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Have you been able to move your arms and legs for the last few days?', 1334708131922, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110409, 'user1', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Yeah, I can actually move all four.', 1334708116189, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110410, 'user2', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Good, are you having any issues breathing?', 1334708127160, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110411, 'user1', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'No, nothing of note there.', 1334708114162, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110412, 'user2', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Okay, today, I think you''d be a good candidate for a halo vest placement.', 1334708131978, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110413, 'user1', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Yeah, doctor, I''m not going back to the O R.', 1334708177366, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110414, 'user2', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Okay, we can do it here.', 1334708114283, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110415, 'user1', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Okay doctor, I''d like to do it here.', 1334708116271, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110416, 'user2', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Let me get A B C to help me with this. Also, we''re going to move you to S I C U room one.', 1334708110256, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110417, 'user1', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Can you tell me the details about what you''re going to do?', 1334708138266, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110418, 'user2', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Well, this is a P M T halo, I like this one better than the Bremer halo vest, and I''ll use morphine and Versed.', 1334708114208, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110419, 'user1', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Are you going to use anesthesia?', 1334708186458, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110420, 'user2', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Yes, I have local anesthetic, it''s xylocaine and epinephrine, um, it''s somewhere between fifteen and twenty C C.', 1334708178696, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110421, 'user1', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Why would I do that?', 1334708093837, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110422, 'user1', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Good afternoon, doctor. Yes, that''s correct.', 1334708095626, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110423, 'user1', 'f4e0867b-5e22-48f9-93d5-3a54e29222a9', 'Oh, no, I haven''t yet.', 1334708111494, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110424, 'user2', '6ff69695-39c1-44de-b6dc-8617d0d44a54', 'Is everything fine?', 1360866654249, 0);
