INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110437, 'user1', '818da093-db6a-416a-a8f8-b11ec4b37057', 'No. I will probably look for a place back in Coolidge.', 1440796274295, 7);
