INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110439, 'user1', '818da093-db6a-416a-a8f8-b11ec4b37057', 'I recently separated from my wife. We lived in Coolidge together. Sacaton is too far away from everything, but it is fine for now.', 1440796274059, 9);
