INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110441, 'user1', '818da093-db6a-416a-a8f8-b11ec4b37057', 'Thank you. My sister has been a saint. I am not working right now so my sister is letting me stay with her for free. She gave up her home office and made me a nice room to stay in.', 1440796311972, 11);
