INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110458, 'user1', '818da093-db6a-416a-a8f8-b11ec4b37057', 'Well, right now I am living with my sister in Sacaton. I am currently looking for my own place, but I am staying with her for now.', 1440796262337, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110459, 'user2', '3fbedf76-a2fa-4cc4-83d8-0e122efe7ed5', 'How are you feeling after that insulin drip, Miss A B C?', 1021963631852, 0);
