INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110461, 'user2', '3fbedf76-a2fa-4cc4-83d8-0e122efe7ed5', 'Yes, between one hundred fifteen and one thirty four. So, on the second day after your admission they did laparoscopic removal of your gallstones. You were very difficult to intubate. But everything went well with surgery. There was some swelling and adhesions around your gallbladder, but all is well that ends well.', 1021963636001, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110462, 'user2', '3fbedf76-a2fa-4cc4-83d8-0e122efe7ed5', 'Yes, sliding scale insulin.', 1021963659626, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110463, 'user1', '3fbedf76-a2fa-4cc4-83d8-0e122efe7ed5', 'Can I go home?', 1021963664662, 7);
