INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110840, 'user1', '293c4f95-b91f-4151-aee9-9bd5f3761a69', 'I did a little heroin and some coke earlier today. I still feel high.', 1680896620734, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110841, 'user2', '293c4f95-b91f-4151-aee9-9bd5f3761a69', 'Okay. Any shortness of breath, chest pain, abdominal pain or back pain?', 1680896616942, 4);
