INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110847, 'user1', 'f738200f-cefa-4f55-af62-59837258d9cf', 'You know Doctor, I am widowed for eighteen years now. Never remarried, I live by myself in my house.', 1416374737293, 0);
