INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110854, 'user2', '45093dc9-1b37-4ff8-b925-e7bd6a76fcab', 'How old are you, sir?', 1183958830777, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110855, 'user2', '45093dc9-1b37-4ff8-b925-e7bd6a76fcab', 'When was your last stroke?', 1183958844067, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110856, 'user1', '45093dc9-1b37-4ff8-b925-e7bd6a76fcab', 'Well, it was on January seventeenth. I had these episodes where I was like always so confused and looks like I lost everything. All my memory and everything. And then they did a scan. It was verified that I was having a stroke on the same day.', 1183958841474, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110857, 'user2', '45093dc9-1b37-4ff8-b925-e7bd6a76fcab', 'Did they put you on some medications?', 1183958842983, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110858, 'user1', '45093dc9-1b37-4ff8-b925-e7bd6a76fcab', 'They gave me an anticonvulsant and aspirin.', 1183958853857, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110859, 'user2', '45093dc9-1b37-4ff8-b925-e7bd6a76fcab', 'Are you taking them regularly?', 1183958865095, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110860, 'user1', '45093dc9-1b37-4ff8-b925-e7bd6a76fcab', 'There have a few times like one or two days that I forgot to take my, uh, dyphenhydramine, but even when I''m taking it regularly, I''m still having all those symptoms or forgetfulness, confusion, and everything.', 1183958852710, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110861, 'user2', '45093dc9-1b37-4ff8-b925-e7bd6a76fcab', 'Do you feel anything else along with these episodes like a urine urgency, tendency to bite your tongue, headaches, any visual change, or your heart is beating very fast? Any kind of weakness or numbness or shortness of breath?', 1183958862871, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110862, 'user1', '45093dc9-1b37-4ff8-b925-e7bd6a76fcab', 'No nothing else, just the confusion and forgetfulness.', 1183958866155, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110863, 'user2', '45093dc9-1b37-4ff8-b925-e7bd6a76fcab', 'How frequent are these episodes?', 1183958846349, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110864, 'user1', '45093dc9-1b37-4ff8-b925-e7bd6a76fcab', 'Well, they occur like two or three times in a week. Each one of the episodes lasts for like one or two minutes.', 1183958890828, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110865, 'user1', '45093dc9-1b37-4ff8-b925-e7bd6a76fcab', 'I''m right handed.', 1183958838930, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110866, 'user1', '45093dc9-1b37-4ff8-b925-e7bd6a76fcab', 'I''m sixty five years old.', 1183958835175, 1);
