INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110868, 'user3', '512030f7-4888-4f9e-bda7-e5b52dfd494c', 'Any medical disorders in the family?', 1407338984168, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110869, 'user1', '512030f7-4888-4f9e-bda7-e5b52dfd494c', 'Yeah, my father had a special kind of tumor, which doctors said is very rare.', 1407338988667, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110870, 'user3', '512030f7-4888-4f9e-bda7-e5b52dfd494c', 'Do you know the name of the tumor?', 1407338996050, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110871, 'user1', '512030f7-4888-4f9e-bda7-e5b52dfd494c', 'I don''t remember the exact name of the disease, but it was a big name and it started with something with V.', 1407338997505, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110872, 'user3', '5e670599-2fcf-4eb5-87e2-201dec0cabd2', 'Do you have any major medical conditions that I should know about?', 1159006802875, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110873, 'user1', '5e670599-2fcf-4eb5-87e2-201dec0cabd2', 'Actually, I have a whole list of conditions. I have them written down here.', 1159006808382, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110874, 'user3', '5e670599-2fcf-4eb5-87e2-201dec0cabd2', 'Thank you, so I see congestive heart failure, chronic renal insufficiency, azotemia, hyperglycemia, coronary artery disease, and a history of paroxysmal atrial fibrillation. Oh, and azotemia.', 1159006812288, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110875, 'user3', '5e670599-2fcf-4eb5-87e2-201dec0cabd2', 'I see, what about any neurological or psychological conditions?', 1159006826302, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110876, 'user1', '5e670599-2fcf-4eb5-87e2-201dec0cabd2', 'Well, I have depression, and I''ve had panic attacks while taking Doxepin before.', 1159006810155, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110877, 'user3', '5e670599-2fcf-4eb5-87e2-201dec0cabd2', 'I see here that you also have perioperative anemia, does that sound familiar?', 1159006837335, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110878, 'user1', '5e670599-2fcf-4eb5-87e2-201dec0cabd2', 'Yes, another doctor told me about that.', 1159006846988, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110879, 'user3', '5e670599-2fcf-4eb5-87e2-201dec0cabd2', 'Do you have any other symptoms you''d like to report today?', 1159006851768, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110880, 'user1', '5e670599-2fcf-4eb5-87e2-201dec0cabd2', 'Um, I''m having some difficulty swallowing.', 1159006844945, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110881, 'user1', '5e670599-2fcf-4eb5-87e2-201dec0cabd2', 'Well, they wanted me to take Coumadin but I had, um, a subdural hematoma so they would let me.', 1159006811988, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110882, 'user1', '5e670599-2fcf-4eb5-87e2-201dec0cabd2', 'Yes, I told you I have a lot going on.', 1159006813622, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110883, 'user3', '5e670599-2fcf-4eb5-87e2-201dec0cabd2', 'Are you taking any medications?', 1159006817142, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110884, 'user2', 'd5ea51ab-358d-48c1-990c-1b5faee5ea4e', 'Doctor Shami, can you please take down the notes as I examine the patient?', 1387072935827, 0);
