INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110911, 'user3', '8b150097-63aa-4e93-93c4-bd1ca3cc4a79', 'How are you, Mary?', 1611143238228, 0);
