INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110915, 'user1', '8b150097-63aa-4e93-93c4-bd1ca3cc4a79', 'I am just so frustrated sitting in my wheelchair. I am spending around sixteen hours a day in this wheelchair.', 1611143254631, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110916, 'user3', '8b150097-63aa-4e93-93c4-bd1ca3cc4a79', 'I think, that is the reason you developed this pressure ulcer. It appears to be on the right trochanter area. In simple terms you have developed a pressure sore on the outer part of your hip.', 1611143261677, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110917, 'user1', '8b150097-63aa-4e93-93c4-bd1ca3cc4a79', 'Yeah, I recently celebrated my thirtieth birthday just sitting in my wheelchair the whole day.', 1611143276562, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110918, 'user3', '8b150097-63aa-4e93-93c4-bd1ca3cc4a79', 'Oh, I am sorry dear. So, how long since you have had this ulcer?', 1611143294001, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110919, 'user1', '8b150097-63aa-4e93-93c4-bd1ca3cc4a79', 'It''s been several weeks, so I thought I should get it checked.', 1611143278862, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110920, 'user3', '8b150097-63aa-4e93-93c4-bd1ca3cc4a79', 'Yeah, good thing you came. We need to treat it. Did you experience any chills or fever?', 1611143273060, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110921, 'user1', '8b150097-63aa-4e93-93c4-bd1ca3cc4a79', 'No.', 1611143278809, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110922, 'user3', '8b150097-63aa-4e93-93c4-bd1ca3cc4a79', 'Any other symptoms?', 1611143271121, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110923, 'user1', '8b150097-63aa-4e93-93c4-bd1ca3cc4a79', 'No.', 1611143318265, 15);
