INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110925, 'user1', '8b150097-63aa-4e93-93c4-bd1ca3cc4a79', 'Pretty much.', 1611143250662, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110926, 'user3', '8b150097-63aa-4e93-93c4-bd1ca3cc4a79', 'Oh, I remember that one. It took almost three treatment cycles to get resolved.', 1611143249091, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110927, 'user2', '62fb2c60-6935-4086-9496-adb31bb35d01', 'Do you have any history of heart disease that you know of?', 1124629040132, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110928, 'user2', '62fb2c60-6935-4086-9496-adb31bb35d01', 'Good, and how about your lungs? Do they work well.', 1124629059944, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110929, 'user1', '62fb2c60-6935-4086-9496-adb31bb35d01', 'Absolutely, they''re in great shape. There''s nothing like that here.', 1124629069971, 5);
