INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110933, 'user3', '95288d23-ff71-4bb8-9e7f-5e792c06c5e0', 'How about allergies to medications?', 1133591270882, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110934, 'user1', '95288d23-ff71-4bb8-9e7f-5e792c06c5e0', 'Nope.', 1133591273825, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110935, 'user2', 'ab120870-d125-42c6-8c21-8ee1b1267356', 'Your chest x ray showed diffuse pulmonary edema. This means that you have fluid in your lungs. That would explain your chest pain and the difficulies with your breathing. I would like to start you off with a course of antibiotics to prevent any possible infection. I will also send in a prescription for Furosemide. It will reduce the fluid accumulation in your lungs. Do you have any questions?', 1033708398531, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110936, 'user1', 'ab120870-d125-42c6-8c21-8ee1b1267356', 'When should I start to feel better?', 1033708402794, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110937, 'user2', 'ab120870-d125-42c6-8c21-8ee1b1267356', 'You should start to feel better within three to five days.', 1033708403235, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110938, 'user3', 'd72d985a-61f5-43b0-b1c1-8f21859c4cad', 'Any headaches?', 1395166853860, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110939, 'user1', 'd72d985a-61f5-43b0-b1c1-8f21859c4cad', 'No.', 1395166855432, 1);
