INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110944, 'user1', 'd72d985a-61f5-43b0-b1c1-8f21859c4cad', 'No, no such history.', 1395166870044, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110945, 'user1', 'd72d985a-61f5-43b0-b1c1-8f21859c4cad', 'No.', 1395166867212, 3);
