INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110947, 'user1', 'd72d985a-61f5-43b0-b1c1-8f21859c4cad', 'Um, no.', 1395166870785, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110948, 'user3', '8ed4345e-d325-41be-a4ef-8ecc848833a5', 'Are there any known disease running in your family?', 1034398659551, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110949, 'user3', '8ed4345e-d325-41be-a4ef-8ecc848833a5', 'What about your mom? How old is she?', 1034398663230, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110950, 'user1', '8ed4345e-d325-41be-a4ef-8ecc848833a5', 'My mom is eighty years old. She does have sugar issues.', 1034398673046, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110951, 'user1', '8ed4345e-d325-41be-a4ef-8ecc848833a5', 'My dad has high blood pressure, and he takes medication for it. He is now eighty two years old. He had a stroke around two years ago. This was his second stroke. First one he had when he was forty five.', 1034398664943, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110952, 'user2', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'Are you currently living alone?', 1196740164467, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110953, 'user2', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'Nice. Where do you work?', 1196740173444, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110954, 'user1', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'Mostly in the city.', 1196740185949, 5);
