INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110959, 'user2', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'That sounds nice. How was your trip?', 1196740192917, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110960, 'user1', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'Relaxing. Much needed.', 1196740229443, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110961, 'user2', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'Great to hear. I have a few more questions I need to ask so bear with me. How is your sexual history? Are you sexually active?', 1196740218379, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110962, 'user1', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'I''m sexually active with women, but my sex life isn''t as good as it was in Japan. Over there, I would mix and mingle with prostitutes.', 1196740216385, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110963, 'user2', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'Did you use protection?', 1196740237754, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110964, 'user1', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'I don''t really remember.', 1196740220698, 15);
