INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110966, 'user1', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'Yep. I''m negative for right now.', 1196740231727, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110967, 'user2', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'Have you ever been incarcerated?', 1196740197970, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110968, 'user1', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'Nope.', 1196740269161, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110969, 'user2', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'One last question. Have you ever been in need of a blood transfusion?', 1196740209359, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110970, 'user1', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'No, thank God.', 1196740226650, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110971, 'user1', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'I''ve been working as a plumber for the last five years.', 1196740177342, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110972, 'user1', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'Yep. Just me, myself, and I.', 1196740169752, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110973, 'user2', 'fdce64ea-1d46-491b-9d30-c1a11695f6c1', 'What do you do for a living?', 1196740175625, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110974, 'user2', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Good afternoon, champ, how you holding up?', 1219805146585, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110975, 'user1', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Good afternoon, Doctor, I have a lot of lower back pain.', 1219805149087, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110976, 'user1', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'It''s been about ten days now.', 1219805154357, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110977, 'user2', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Have your symptoms improved at all since they began?', 1219805160707, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110978, 'user1', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'No, they keep getting worse.', 1219805175085, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110979, 'user2', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Does the pain radiate into your legs?', 1219805184420, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110980, 'user1', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Yes, it started radiating down my right leg three days after the lower back pain began, and then the left leg three days after the right. The next day I could barely walk, the pain was so severe.', 1219805165202, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110981, 'user2', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Do you remember the initial date of the beginning of your low back pain?', 1219805167325, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110982, 'user1', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Um, it was on December third nineteen ninety five.', 1219805198587, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110983, 'user2', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Have you seen another doctor for this pain?', 1219805201438, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110984, 'user2', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Oh no, before we begin, how old are you, sir and which hand do you write with?', 1219805150742, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110985, 'user2', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'What kind of treatments did he recommend?', 1219805187090, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110986, 'user1', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'He gave me some antiinflammatories and sent me on my way.', 1219805201982, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110987, 'user2', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Did you drive yourself?', 1219805226260, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110988, 'user1', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Yes, I did.', 1219805198311, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110989, 'user2', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'How did the antiinflammatories work?', 1219805200462, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110990, 'user1', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Um, by the time I got home, I could hardly walk due to the back pain, and I had weakness in my legs. I was, however, able to feed my dogs, and I fixed myself some dinner.', 1219805251705, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110991, 'user2', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Was there any leg numbness?', 1219805239966, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110992, 'user1', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Yes. Since December eleventh.', 1219805255264, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110993, 'user2', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Have you seen an orthopedist for this pain?', 1219805275094, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110994, 'user1', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Yes, I saw one the day after my primary care physician, but my legs gave out and I fell while walking to my car because of the leg weakness and back pain.', 1219805190738, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110995, 'user2', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'What kind of imaging studies did that orthopedist do?', 1219805201561, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110996, 'user1', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'He did a C T and x rays of my lower back, but he didn''t see anything wrong. He recommended I follow up at U I H C. The imaging was on my L S Spine.', 1219805208820, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110997, 'user2', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Great, so tell me, how long have you had this lower back pain?', 1219805152549, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110998, 'user1', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'Yes, I saw my local physician, um, it was on December eleventh, but he wasn''t able to pinpoint what was going on.', 1219805187946, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (110999, 'user1', '7a540089-bcc3-48a8-8c03-33148fab3d59', 'I''m seventy five now. Right.', 1219805163103, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111000, 'user3', 'bbcd402b-dcc6-4437-8a44-0f2c83fbc20a', 'Alright. So this is going to be a complex case. Your wound is complicated by methicillin-resistant staphylococcus aureus cellulitis.', 1362808252584, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111001, 'user1', 'bbcd402b-dcc6-4437-8a44-0f2c83fbc20a', 'Is there a treatment for my right leg?', 1362808255440, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111002, 'user3', 'bbcd402b-dcc6-4437-8a44-0f2c83fbc20a', 'There is. It will be more aggressive, but we can do it.', 1362808263483, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111003, 'user2', '8f373457-6e17-4730-b9c7-594353566300', 'What is going on with him?', 1642298854109, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111004, 'user1', '8f373457-6e17-4730-b9c7-594353566300', 'He is complaining of chest pain.', 1642298856978, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111005, 'user3', 'e9f8615e-6b0a-409a-8009-0b6fe783be17', 'Good morning, young man. You''re a patient of Doctor X Y Z, correct?', 1212028367062, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111006, 'user1', 'e9f8615e-6b0a-409a-8009-0b6fe783be17', 'Yes sir, that''s right. I''ve seen him for years.', 1212028372999, 1);
