INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111008, 'user3', 'e9f8615e-6b0a-409a-8009-0b6fe783be17', 'Do you have a lot of swelling?', 1212028383882, 6);
