INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111021, 'user3', 'e9f8615e-6b0a-409a-8009-0b6fe783be17', 'Great, thank you. So, what seems to be the problem today?', 1212028388918, 4);
