INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111038, 'user1', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'I have stomach cancer. They also did a total abdominal hysterectomy.', 1241510007940, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111039, 'user2', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'Did they put you on an anticoagulant medication for the blood clotting?', 1241510001107, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111040, 'user1', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'Yes. I took it for six months. I stopped taking it and then I had the stroke.', 1241510002186, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111041, 'user2', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'Have you had any other surgeries?', 1241510018337, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111042, 'user2', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'Let''s start with your medical history. What medical conditions do you have?', 1241509986376, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111043, 'user2', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'How are you feeling today?', 1241510026870, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111044, 'user1', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'I am still having weakness in my left leg. That is why I still have to us my walker, but I have been able to get around easier.', 1241510007196, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111045, 'user2', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'Have you been experiencing any daytime fatigue?', 1241510015519, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111046, 'user1', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'No. I have been falling asleep at work. I think it is from looking at my computer screen all day. My supervisor caught me snoring one day and forgot where I was at. My supervisor offered to give me a coffee. This has happened more than once.', 1241510046642, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111047, 'user2', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'This could be due to your sleep apnea. Who is treating you for your sleep apnea?', 1241510047779, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111048, 'user1', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'Doctor X did a consult and had me do one of those sleep test about two years ago. I only get sleepy when I look at my computer screen.', 1241510064847, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111049, 'user2', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'Did Doctor X recommend a C P A P machine to use at night?', 1241510058233, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111050, 'user1', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'Yes, but I never used to use it. I had another follow up visit with her and she told me that I need to use it every night. I have been using it every other night.', 1241510052933, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111051, 'user2', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'How much uninterrupted sleep do you think that you get per night?', 1241510054412, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111052, 'user1', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'Maybe two to five hours, on a good night.', 1241510037488, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111053, 'user2', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'That is not enough sleep. No wonder you are falling asleep at work. I recommend following up again with Doctor X regarding your sleep apnea. You are at a much higher risk for obesity and high cholesterol if you continue to not address the issues you have been having with the lack of sleep and sleep apnea.', 1241510027459, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111054, 'user1', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'Okay. I will make a follow up visit with her.', 1241510056375, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111055, 'user1', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'Okay. I have high blood pressure, asthma and sleep apnea. I had blood clots in my left leg about six months ago. I also have cancer.', 1241509989736, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111056, 'user2', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'What kind of cancer do you have?', 1241509988662, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111057, 'user1', '4f3ea20d-417e-4020-a120-d13875fd4c67', 'Yes. I had a colonic resection to remove benign polyps. I had another benign lump removed from my breast.', 1241509996451, 9);
