INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111069, 'user3', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'Okay, now tell me what are you afraid of?', 1732897216326, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111070, 'user1', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'No matter what I eat, my number goes up and I just, I''m so afraid of eating anything now.', 1732897232754, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111071, 'user3', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'Do you work?', 1732897235135, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111072, 'user1', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'I do, at Walmart. I try not to eat anything whenever I''m on the third shift.', 1732897230424, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111073, 'user3', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'Tell me about the eating habits. Do you prepare meals at home, or do you order from outside?', 1732897226233, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111074, 'user1', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'Well, before all this, I mean this gestational diabetes and pregnancy, I used to eat out a lot. Almost like every day. I like to eat rice a lot. It is like the staple food for me.', 1732897213454, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111075, 'user3', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'You said you don''t try to eat, so are you facing any symptoms because of not eating?', 1732897213969, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111076, 'user1', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'Yeah, whenever I''m on my late shift, I work from ten in the night to seven in the morning. I try to avoid eating. And then I feel very fatigued and tired all the time. I also have young kids at home, so after finishing my duty here at in the morning I go home and then there are young children who keep me busy.', 1732897270015, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111077, 'user3', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'What is your sleeping pattern? How much are you sleeping throughout the day?', 1732897253775, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111078, 'user1', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'Around two to four hours at a time.', 1732897266535, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111079, 'user3', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'When do you test for ketones?', 1732897251659, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111080, 'user1', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'Normally, it is the first thing that I do when I reach back home from my shift in the morning.', 1732897297887, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111081, 'user1', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'I have gestational diabetes and I''m here for consultation related to my diet. No matter what I eat, I''m kind of scared that it will spike up my numbers.', 1732897216257, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111082, 'user3', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'Hold on, hold on. First, tell me how old are you?', 1732897205678, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111083, 'user3', 'fc7b25e0-d4b9-46d0-9950-f0cb5da177fa', 'Tell me how can I do that? What''s bothering you?', 1732897203936, 2);
