INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111085, 'user2', '98905833-70e0-4f10-bba5-aef55a2a5c1f', 'Is it only in your legs or it starts there and goes somewhere else as well?', 1614156444406, 4);
