INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111088, 'user1', '98905833-70e0-4f10-bba5-aef55a2a5c1f', 'It all started after taking that medication. What is it called? Something with L? Yeah, Lipitor.', 1614156444444, 7);
