INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111098, 'user1', '98905833-70e0-4f10-bba5-aef55a2a5c1f', 'Yeah. I have a request to make. I will be coming for my diabetic checkup in one month. Can we do all the labs before that?', 1614156491392, 17);
