INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111100, 'user2', '98905833-70e0-4f10-bba5-aef55a2a5c1f', 'Anything else going on? How is everything else?', 1614156531060, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111101, 'user1', '98905833-70e0-4f10-bba5-aef55a2a5c1f', 'I tried to control my cholesterol with diet, but it didn''t help. I cannot keep on dieting. It is just not my thing. I have started eating more meat though. I feel full after that.', 1614156526292, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111102, 'user1', '98905833-70e0-4f10-bba5-aef55a2a5c1f', 'They have been low for quite some time. You know, I have started going to Genesis in Wichita and I''ve been doing water aerobics. And you know what? Surprisingly, I have lost thirty pounds.', 1614156499647, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111103, 'user1', '98905833-70e0-4f10-bba5-aef55a2a5c1f', 'Yeah, it helps. Whenever I stand it just goes away.', 1614156440993, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111104, 'user1', '98905833-70e0-4f10-bba5-aef55a2a5c1f', 'I am fifty six years old. I am here for this pain in my legs. It hurts mostly in the night.', 1614156432235, 1);
