INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111115, 'user3', '7115269f-e13b-488e-8b18-0eea479c8468', 'Is patient allergic to any medication?', 1371749147099, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111116, 'user3', '7115269f-e13b-488e-8b18-0eea479c8468', 'That''s quite a lot, we need to be careful while making his treatment plan.', 1371749163350, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111117, 'user3', '7115269f-e13b-488e-8b18-0eea479c8468', 'Yeah.', 1371749169763, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111118, 'user3', '7115269f-e13b-488e-8b18-0eea479c8468', 'Yeah, and Dilatrate and cyclobenzaprine.', 1371749152334, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111119, 'user3', '7115269f-e13b-488e-8b18-0eea479c8468', 'Yes, actually he is allergic to quite a few medicines. I have noted them down, here is the list.', 1371749149820, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111120, 'user3', '7115269f-e13b-488e-8b18-0eea479c8468', 'Okay, so he is allergic to Lamisil, Equagesic. Oh, he is allergic to Bactrim too.', 1371749155440, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111121, 'user2', '062987c4-d89a-4b7f-bc32-4de1acbc6158', 'Hi there! I am Doctor Smith.', 1147914261005, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111122, 'user1', '062987c4-d89a-4b7f-bc32-4de1acbc6158', 'Hello! It is nice to meet you.', 1147914262826, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111123, 'user1', '062987c4-d89a-4b7f-bc32-4de1acbc6158', 'Thank you. She was eighty one when she passed. I am an orphan now. My only living sibling died at forty. He had a hard life. He struggled with mental illness.', 1147914272314, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111124, 'user2', '062987c4-d89a-4b7f-bc32-4de1acbc6158', 'How did your brother pass away?', 1147914280162, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111125, 'user1', '062987c4-d89a-4b7f-bc32-4de1acbc6158', 'He had pancreatitis. Oh, my dad had glaucoma.', 1147914295856, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111126, 'user2', '062987c4-d89a-4b7f-bc32-4de1acbc6158', 'You have had a lot of loss.', 1147914291937, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111127, 'user1', '062987c4-d89a-4b7f-bc32-4de1acbc6158', 'Yes, I have. My good friend passed away a year and a half ago. It has been a lot.', 1147914277630, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111128, 'user2', '062987c4-d89a-4b7f-bc32-4de1acbc6158', 'I have a support group I can refer you to for people to have been through loss. Would you be interested a referral, sir?', 1147914291634, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111129, 'user1', '062987c4-d89a-4b7f-bc32-4de1acbc6158', 'Yes. I would like that. Thank you.', 1147914320848, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111130, 'user2', '062987c4-d89a-4b7f-bc32-4de1acbc6158', 'Let''s start with your family medical history.', 1147914272695, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111131, 'user1', '062987c4-d89a-4b7f-bc32-4de1acbc6158', 'My mother had breast cancer. My father had lung cancer that ended up taking his life. He was seventy nine when he passed. My mother also passed but not from an illness but from an infection she got after having an elective surgery.', 1147914265533, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111132, 'user2', '062987c4-d89a-4b7f-bc32-4de1acbc6158', 'I am so sorry for your loss. How old was your mother when she passed?', 1147914272869, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111133, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'I will ask some simple questions, okay?', 1289394115215, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111134, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Hm', 1289394118582, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111135, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'I had a blood test before and then it came out to be high potassium. I also went to a regular clinic the other day as I was feeling very weak and extremely tired.', 1289394121681, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111136, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Okay.', 1289394139833, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111137, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'My potassium came out to be seven and it was highlighted in red. That really scared me, so I wanted to know everything what''s going on inside me. I told the emergency doctors too that all these weakness and tiredness is going on for more than half a year.', 1289394146560, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111138, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Did you noticed any other symptoms other than weakness?', 1289394155722, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111139, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Yes, there was the fever and chills. I was sweating a lot in the nights, and I also had weight loss of around twenty pounds. During that time, I sometimes have nausea and was throwing up a lot. I was not eating. I always felt dizzy every time I tried to stand.', 1289394125471, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111140, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Did you have wet cough?', 1289394136725, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111141, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'No, not wet cough but I did notice back pain gets intense on the upper side whenever I coughed, like in my ribs. I normally massage that area and it gets better.', 1289394166862, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111142, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'How old are you and how would you define yourself in terms of ethnicity?', 1289394126198, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111143, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Nope.', 1289394156309, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111144, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'How about while sleeping or doing something else?', 1289394129612, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111145, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Not while sleeping, but I did notice that if I''m walking for two to three blocks then I get out of breath easily. Previously it was not like this. I used to jog for two to three miles without even a single breath loss.', 1289394150710, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111146, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'I noticed one more thing. I feel like my balls on one side are getting big.', 1289394173362, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111147, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Well, I am forty seven and would proudly call myself as Latin American.', 1289394119084, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111148, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'I think its left.', 1289394197540, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111149, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'For how long?', 1289394163089, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111150, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'I guess over the past year. I did see someone when all of this started, and he put me on some antibiotics, but nothing changed. For last few months there is yellow fluid coming out of it too.', 1289394183692, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111151, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Did you ever get any type of injury in the area?', 1289394227704, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111152, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'No.', 1289394190266, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111153, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'What about your bowel movements?', 1289394187372, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111154, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Nope everything is as usual.', 1289394206030, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111155, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Any change in urinary habits?', 1289394176322, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111156, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Nope.', 1289394158912, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111157, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Any changes in your skin? Any rash? Any kind of eyesight issue?', 1289394198695, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111158, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Nope, no changes.', 1289394204797, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111159, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'What about pain? Like headache or any joint pain?', 1289394205246, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111160, 'user1', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Nope, no pain anywhere.', 1289394168779, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111161, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Any shortness of breath?', 1289394163758, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111162, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Which side left or right?', 1289394176770, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111163, 'user2', '36daaee8-fac8-4a31-a222-427225b2c88e', 'Great. What brings you to the emergency room?', 1289394128336, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111164, 'user3', 'a2272f12-b40a-4c6a-b808-54308587601c', 'Have you ever had surgery, ma''am?', 1191360146053, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111165, 'user3', 'a2272f12-b40a-4c6a-b808-54308587601c', 'Great, thank you. What else have you had done?', 1191360152884, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111166, 'user1', 'a2272f12-b40a-4c6a-b808-54308587601c', 'I had a breast biopsy in nineteen eighty nine, and a colonoscopy in two thousand seven.', 1191360157145, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111167, 'user3', 'a2272f12-b40a-4c6a-b808-54308587601c', 'Thank you, do you have any children?', 1191360177356, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111168, 'user1', 'a2272f12-b40a-4c6a-b808-54308587601c', 'Well, doctor, I''ve been pregnant four times, but I''ve had three children.', 1191360165984, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111169, 'user3', 'a2272f12-b40a-4c6a-b808-54308587601c', 'I''m so sorry to hear that. Did you have a C section with any of them?', 1191360157823, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111170, 'user1', 'a2272f12-b40a-4c6a-b808-54308587601c', 'No, doctor. I had a natural birth for all of them.', 1191360172633, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111171, 'user1', 'a2272f12-b40a-4c6a-b808-54308587601c', 'That was in, um, nineteen seventy nine.', 1191360159725, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111172, 'user1', 'a2272f12-b40a-4c6a-b808-54308587601c', 'Yeah, I''ve had a few. First, I had, um, tubal ligation, and three milk ducts removed.', 1191360151734, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111173, 'user3', 'a2272f12-b40a-4c6a-b808-54308587601c', 'What year was that in?', 1191360157699, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111174, 'user3', '949d1700-91df-476e-ae0b-fc60942d6412', 'Did you had any surgery in the past?', 1072038241807, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111175, 'user1', '949d1700-91df-476e-ae0b-fc60942d6412', 'No.', 1072038245917, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111176, 'user3', 'ddef7ba6-ff44-4502-9867-b09ed9d76e80', 'Any allergies?', 1198598394728, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111177, 'user3', 'ddef7ba6-ff44-4502-9867-b09ed9d76e80', 'Okay so molds reaction.', 1198598399463, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111178, 'user1', 'ddef7ba6-ff44-4502-9867-b09ed9d76e80', 'Yes just molds.', 1198598397211, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111179, 'user2', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'Hi there, how are you dear?', 1156519497050, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111180, 'user1', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'I am fine, thank you.', 1156519500880, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111181, 'user2', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'Okay, so you noticed some behavioral problems with your daughter and reported to her, is that right?', 1156519514300, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111182, 'user1', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'Yes, I have been noticing them for a while. She loses her focus quickly. We also got a few complaints from school regarding her behavior. We also met a couple of other doctors but they diagnosed her with Attention Deficit Hyperactivity Disorder.', 1156519511419, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111183, 'user2', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'Well, looking at her reports I am afraid it looks like she does have A D H D, but the good news is we can treat her, so don''t worry.', 1156519530829, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111184, 'user1', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'Okay.', 1156519517687, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111185, 'user1', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'Hi Doctor, I am her mother.', 1156519507357, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111186, 'user1', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'Thank you.', 1156519552341, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111187, 'user2', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'So, I will write her a prescription for Adderall and Clonidine. They have some really good results in treating A D H D. Which pharmacy do you go to?', 1156519513973, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111188, 'user1', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'We go to Costco pharmacy by the X Y Z corner.', 1156519555196, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111189, 'user2', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'Okay, I will send it there.', 1156519533966, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111190, 'user1', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'Thank you doctor, it was nice meeting you.', 1156519530878, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111191, 'user2', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'Nice meeting you too, take care.', 1156519543579, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111192, 'user2', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'I am going to prescribe her some medicines which will help her deal with this.', 1156519529146, 9);
