INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111194, 'user1', 'f9cf92fe-098f-4021-8d8b-c409473cd5a6', 'Yes, she is our family doctor.', 1156519511721, 4);
