INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111199, 'user2', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Good morning, sir. You''re sixty one years old, correct?', 1404542792444, 0);
