INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111203, 'user1', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Well, I''ve had diabetes for a long time but had never been treated for it.', 1404542826895, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111204, 'user2', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Okay, thank you for telling me. What seems to be the problem today?', 1404542814238, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111205, 'user1', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'I''ve been working in my garage over the past few days, and I have this redness and swelling in my right foot.', 1404542837924, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111206, 'user2', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Do you have any itchiness or pain?', 1404542803705, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111207, 'user1', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Yes, and it''s getting worse.', 1404542811609, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111208, 'user2', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Have you seen any other doctors about this?', 1404542825074, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111209, 'user1', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Um, yes. I went to the A B C D General Hospital E R and they gave me an evaluation there.', 1404542866111, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111210, 'user2', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Do you have any images from this visit?', 1404542856021, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111211, 'user1', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Um, yes. I have them right here.', 1404542848476, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111212, 'user2', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Okay, these show a foreign body in the foot.', 1404542857683, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111213, 'user1', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'But what about all the stuff on the outside of my foot?', 1404542815833, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111214, 'user2', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Well, that''s consistent with cellulitis.', 1404542862075, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111215, 'user1', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'What''s that?', 1404542905647, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111216, 'user2', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'It''s a skin infection we clean it up in surgery.', 1404542813729, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111217, 'user1', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'What kind of procedure can we do?', 1404542864747, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111218, 'user2', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'We should do an irrigation debridement for the cellulitis, and remove the foreign body. I think that will really help.', 1404542923225, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111219, 'user1', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Yes, I agree, doctor.', 1404542843908, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111220, 'user2', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Great, and you identify as Caucasian, right?', 1404542801105, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111221, 'user1', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Yes, that''s correct as well.', 1404542803144, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111222, 'user2', '4efee52a-d70e-4ee5-a0dc-6a1b5535fd9a', 'Thank you, do you have any medical conditions that I should know about?', 1404542797199, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111223, 'user2', 'f908a03c-cf74-48b5-809e-ae0947ef211c', 'Hello, sir. How are you doing today?', 1233444272223, 0);
