INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111226, 'user1', 'f908a03c-cf74-48b5-809e-ae0947ef211c', 'He''s been having some problems with his skin in his private region. He''s too shy to talk about it himself.', 1233444277156, 3);
