INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111228, 'user3', '8921da1e-4f36-4ac0-81ac-c967d95de43b', 'So, do you drink or smoke?', 1128007779487, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111229, 'user1', '8921da1e-4f36-4ac0-81ac-c967d95de43b', 'No, I don''t do any of that.', 1128007780655, 5);
