INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111233, 'user1', '8921da1e-4f36-4ac0-81ac-c967d95de43b', 'Yes, he is just wonderful.', 1128007769186, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111234, 'user3', '8921da1e-4f36-4ac0-81ac-c967d95de43b', 'Does he help you out around the house?', 1128007769332, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111235, 'user2', 'efca695d-e602-4b06-8b64-43e9b183e2ac', 'Anything else going on from head to toe?', 1162972760874, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111236, 'user1', 'efca695d-e602-4b06-8b64-43e9b183e2ac', 'No doctor, everything else is fine.', 1162972766265, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111237, 'user2', 'efca695d-e602-4b06-8b64-43e9b183e2ac', 'Are you sure?', 1162972771714, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111238, 'user1', 'efca695d-e602-4b06-8b64-43e9b183e2ac', 'Yes I am sure.', 1162972764894, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111239, 'user1', 'b7014b96-c1db-4b88-afcb-e7fd7f3fe392', 'How''s my husband doing? Sorry, I had to take a call outside.', 1595589145437, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111240, 'user1', 'b7014b96-c1db-4b88-afcb-e7fd7f3fe392', 'Great. Can we make the appointment right now?', 1595589157274, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111241, 'user3', 'b7014b96-c1db-4b88-afcb-e7fd7f3fe392', 'Yes, the front desk will be able to help you with that.', 1595589170804, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111242, 'user3', 'b7014b96-c1db-4b88-afcb-e7fd7f3fe392', 'However, I''d like to still see him in the office next week for a reevaluation.', 1595589159556, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111243, 'user3', 'b7014b96-c1db-4b88-afcb-e7fd7f3fe392', 'He''s doing much better. He''ll be going home today with a prescription for Zithromax.', 1595589148981, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111244, 'user1', 'b7014b96-c1db-4b88-afcb-e7fd7f3fe392', 'I''m glad he''s able go home and get some rest.', 1595589153970, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111245, 'user2', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'How long have you been running a fever?', 1132785157972, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111246, 'user2', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'When was the last time you took your temperature?', 1132785165175, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111247, 'user1', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'An hour ago. The thermometer read one O one point four.', 1132785172645, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111248, 'user2', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'Are you experiencing any other symptoms, such as shortness of breath, nausea, vomiting, diarrhea, or others?', 1132785169513, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111249, 'user1', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'I''ve been having a stronger urge to pee a lot more than usual. Not sure if that''s related.', 1132785195803, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111250, 'user2', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'It could be. We''re still waiting on your urine results. Do you have a history of cataracts or glaucoma?', 1132785194337, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111251, 'user1', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'No.', 1132785185566, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111252, 'user2', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'Okay, great. Any signs of pneumonia or valley fever?', 1132785200749, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111253, 'user1', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'Nothing of the sort.', 1132785219673, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111254, 'user2', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'What about blood in your vomit or feces?', 1132785204226, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111255, 'user1', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'Nope.', 1132785175641, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111256, 'user2', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'Any neurological symptoms like T I A or C V A? That is slurred speech or stroke symptoms.', 1132785210796, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111257, 'user1', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'Luckily, no. I don''t have seizures or anything like that.', 1132785239017, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111258, 'user2', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'Great to here. With the pandemic I wanted to check on your mental health too. Any depression or anxiety?', 1132785174943, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111259, 'user1', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'I have always been a homebody. This is normal for me. Nothing like that in my head.', 1132785247800, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111260, 'user2', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'Cool. Do you have any issues with blood disorders?', 1132785249830, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111261, 'user1', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'Nothing like that.', 1132785252827, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111262, 'user2', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'Have you taken anything for the fever?', 1132785163896, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111263, 'user1', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'Tylenol and Advil. I''ve been taking them interchangeably.', 1132785166537, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111264, 'user1', 'dd5df8ee-d10b-406c-87f6-697a10a907ec', 'It''s been on and off for a few days now. I''m also having chills.', 1132785163171, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111265, 'user3', '3d608c75-c3cb-4fc6-a1f5-ba17262190b1', 'Hello, miss. It looks like some information is missing for your profile. Is it fine if I ask you a few questions?', 1367159320280, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111266, 'user3', '3d608c75-c3cb-4fc6-a1f5-ba17262190b1', 'Did you smoke before?', 1367159342268, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111267, 'user1', '3d608c75-c3cb-4fc6-a1f5-ba17262190b1', 'I did. I smoked a half a pack for about twenty years.', 1367159342762, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111268, 'user3', '3d608c75-c3cb-4fc6-a1f5-ba17262190b1', 'Well, it''s good to hear that you''ve stopped. I encourage you to continue to not smoke.', 1367159334312, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111269, 'user1', '3d608c75-c3cb-4fc6-a1f5-ba17262190b1', 'I agree. I need to change up my lifestyle.', 1367159347745, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111270, 'user3', '3d608c75-c3cb-4fc6-a1f5-ba17262190b1', 'Last question. Do you drink alcohol?', 1367159339193, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111271, 'user1', '3d608c75-c3cb-4fc6-a1f5-ba17262190b1', 'No, I don''t. I don''t like anything that has alcohol. I can''t stand the taste of it. If I do it is rare.', 1367159357906, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111272, 'user1', '3d608c75-c3cb-4fc6-a1f5-ba17262190b1', 'No, I finally stopped smoking cigarettes.', 1367159328226, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111273, 'user1', '3d608c75-c3cb-4fc6-a1f5-ba17262190b1', 'Of course. Go ahead.', 1367159323564, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111274, 'user3', '3d608c75-c3cb-4fc6-a1f5-ba17262190b1', 'Do you currently smoke?', 1367159326565, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111275, 'user2', '97351197-e595-47d5-aca7-4c52550ee2f1', 'Hello, sir. So, remind me, how long ago was your procedure?', 953159935627, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111276, 'user2', '97351197-e595-47d5-aca7-4c52550ee2f1', 'You broke your second and fifth toes.', 953159945453, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111277, 'user1', '97351197-e595-47d5-aca7-4c52550ee2f1', 'Do you have the x rays? Can I see where the breaks are?', 953159943084, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111278, 'user2', '97351197-e595-47d5-aca7-4c52550ee2f1', 'Absolutely, if you look here, right here is where the breaks are. These are called the metatarsal heads.', 953159955892, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111279, 'user1', '97351197-e595-47d5-aca7-4c52550ee2f1', 'Wow, that''s right where it hurts.', 953159952372, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111280, 'user2', '97351197-e595-47d5-aca7-4c52550ee2f1', 'Yep, and where are you living now?', 953159970552, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111281, 'user1', '97351197-e595-47d5-aca7-4c52550ee2f1', 'Thankfully, I left the nursing home, and I''m back in my own house now.', 953159973702, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111282, 'user2', '97351197-e595-47d5-aca7-4c52550ee2f1', 'That''s really good. Are you in any pain today?', 953159982029, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111283, 'user1', '97351197-e595-47d5-aca7-4c52550ee2f1', 'No, not today.', 953159980446, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111284, 'user2', '97351197-e595-47d5-aca7-4c52550ee2f1', 'Great, have you been going to P T?', 953159979686, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111285, 'user1', '97351197-e595-47d5-aca7-4c52550ee2f1', 'Yeah, I''ve been going about two or three times a week.', 953160013588, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111286, 'user2', '97351197-e595-47d5-aca7-4c52550ee2f1', 'Are there any signs of infection, like drainage from the incision?', 953159955945, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111287, 'user1', '97351197-e595-47d5-aca7-4c52550ee2f1', 'Nope, the wound healed up nicely. I''ll be able to wear shorts again.', 953159956133, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111288, 'user2', '97351197-e595-47d5-aca7-4c52550ee2f1', 'Great, are you having any fever symptoms, like cough, runny nose, sore throat, fatigue, anything like that?', 953159957635, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111289, 'user1', '97351197-e595-47d5-aca7-4c52550ee2f1', 'No, but I have had some tingling in both my feet. I don''t know if its related to surgery. If I''m remembering the names right, um, I have a history of spinal stenosis and neuropathy in my legs.', 953159960099, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111290, 'user2', '97351197-e595-47d5-aca7-4c52550ee2f1', 'With your history of spinal stenosis, the broken toes, and the surgery, that''s a pretty normal side effect.', 953160028989, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111291, 'user1', '97351197-e595-47d5-aca7-4c52550ee2f1', 'Let me think. Now, it''s been about four months. I just turned fifty nine.', 953159937861, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111292, 'user2', '97351197-e595-47d5-aca7-4c52550ee2f1', 'Okay, and just to refresh your memory, we did a percutaneous screw fixation of a Schatzker I V tibial plateau fracture, and we''ve managed those toe fractures nonoperatively.', 953159937700, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111293, 'user1', '97351197-e595-47d5-aca7-4c52550ee2f1', 'Which toes did I break?', 953159945180, 3);
