INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111300, 'user2', '6a28d6a3-2e52-46c8-90ed-00ded633793a', 'Hello. Are you ready for your surgery today?', 1551754465124, 0);
