INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111320, 'user2', '2bfc5060-79bb-4898-8110-3331a46e7842', 'Good, thank you, what seems to be the problem today?', 1492333412750, 6);
