INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111394, 'user1', '24b13933-98d0-4e89-9dba-ecc2b234030b', 'Actually, I had two c sections for both of my sons.', 1165290148517, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111395, 'user1', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'I''m right handed.', 1631655795511, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111396, 'user1', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'Around three times a week.', 1631655809136, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111397, 'user2', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'What do you do when you have these cramps?', 1631655820056, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111398, 'user1', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'I try to stand and it helps me relieve some of the discomfort. I noticed my toes are kind of extended. Whenever I step on the ground, it seems to pop into place. With all these cramps, I''ve started having pain in my calf. Sometimes because of that I could not sleep, or it wakes me up in the night. Similar to my toes, these cramps have also started coming up in my hands. They are not that strong or frequent. They''re completely random and not in the nighttime. Sometimes my thumb gets so flexed that I have to move it to bring it to the right position and to relieve the cramp.', 1631655809715, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111399, 'user2', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'Did you ever have this symptom before?', 1631655810547, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111400, 'user1', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'No, not like this.', 1631655842181, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111401, 'user2', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'Are you taking any medications?', 1631655816390, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111402, 'user1', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'Yeah, I took an antibacterial called Bactrim around nine months ago. I was taking it briefly before, but now I''m taking it consistently. I cannot think of anything that is causing it.', 1631655850520, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111403, 'user2', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'Do you have any other medical condition?', 1631655813158, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111404, 'user1', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'I have H I V for the last twenty one years and I was taking antiretroviral medications for it. I stopped those medications around six or seven years ago.', 1631655827563, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111405, 'user2', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'Why did you stop the medications?', 1631655818608, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111406, 'user2', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'How frequent is it?', 1631655800042, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111407, 'user2', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'Do you know your C D four count?', 1631655830643, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111408, 'user1', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'It was three hundred and twenty six. I never developed autoimmune deficiency syndrome. I think I should restart my medicines.', 1631655831493, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111409, 'user1', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'I''m having these cramps in my feet, in my hand and I just wanted to get checked. It has been happening for like six months. I develop muscle contractions in my toes and both feet. It only happens in night.', 1631655801862, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111410, 'user1', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'I could not tolerate them. They were making my stomach weak.', 1631655814016, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111411, 'user2', 'bbcac99f-61fc-4fd3-9eb0-5c245bdc9977', 'Tell me what brings you here, sir?', 1631655800363, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111412, 'user3', '7bf4e816-08e3-40d3-bc9f-cf242240091b', 'So, this is your follow up? How are you doing so far with Lamictal?', 956117884855, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111413, 'user1', '7bf4e816-08e3-40d3-bc9f-cf242240091b', 'Yes, it''s the follow up. Lamictal was okay. There was no side effect with that. But I had twitching in my muscles a lot of times. It was not generalized, but I was very afraid that this will happen.', 956117886958, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111414, 'user1', '7bf4e816-08e3-40d3-bc9f-cf242240091b', 'I have been taking my medications very regularly and  I was getting a good amount of sleep as well.', 956117908315, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111415, 'user3', '7bf4e816-08e3-40d3-bc9f-cf242240091b', 'Are you able to drive?', 956117919590, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111416, 'user1', '7bf4e816-08e3-40d3-bc9f-cf242240091b', 'Yes.', 956117903279, 7);
