INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111419, 'user1', '7bf4e816-08e3-40d3-bc9f-cf242240091b', 'Mostly in the mornings.', 956117896106, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111420, 'user3', '7bf4e816-08e3-40d3-bc9f-cf242240091b', 'I have your recent E E G report. It did show multiple spikes and some complexes on both the sides, but it is more prominent on left.', 956117894757, 4);
