INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111494, 'user1', '5f906a35-ac24-4b38-b126-d1c97255e1b7', 'Oh yes. I am allergic to horse serum. I think it is added in vaccinations?', 1039985861404, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111495, 'user1', '5f906a35-ac24-4b38-b126-d1c97255e1b7', 'Actually, there is a wooden splinter stuck beneath my left fifth fingernail. I am an American farmer by blood, so this has happened before.', 1039985792964, 3);
