INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111504, 'user3', 'a646b1a9-d877-4bee-a7f9-fc24e34df5d9', 'Are you right handed or left handed?', 1331176069039, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111505, 'user3', 'a646b1a9-d877-4bee-a7f9-fc24e34df5d9', 'When did you see changes in your eyelid?', 1331176090649, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111506, 'user1', 'a646b1a9-d877-4bee-a7f9-fc24e34df5d9', 'Yeah, on the following day, it seemed like swelling and then my eyelid, it began like pulling down and getting down. Kind of drooping. We went to a local doctor, and he did some x rays.', 1331176100346, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111507, 'user3', 'a646b1a9-d877-4bee-a7f9-fc24e34df5d9', 'Yeah, I have your brain C T report from there. There is no sign of any kind of bleeding, but I do see a torturous blood vessel there.', 1331176083150, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111508, 'user1', 'a646b1a9-d877-4bee-a7f9-fc24e34df5d9', 'Yeah, after looking at this report they transferred us here to the U I H C on the twelfth.', 1331176083187, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111509, 'user1', 'a646b1a9-d877-4bee-a7f9-fc24e34df5d9', 'Right handed.', 1331176069501, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111510, 'user1', 'a646b1a9-d877-4bee-a7f9-fc24e34df5d9', 'Seventy one.', 1331176067555, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111511, 'user1', 'a646b1a9-d877-4bee-a7f9-fc24e34df5d9', 'I, I had this bad headache on fifth of November and then I had a big sneeze, like it was too loud. I had-- it was going on for like three to four days. Then, on the seventh, I had this severe pain over my left eye and I kind of lost my vision there.', 1331176093443, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111512, 'user3', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'I see here that you''re in for a med refill. Is that correct?', 1496176917960, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111513, 'user1', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'Yep. I ran out of Klonopin one or two days ago.', 1496176919452, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111514, 'user1', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'My doctor back in Georgia.', 1496176933468, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111515, 'user3', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'Do you happen to have their name or contact info on hand?', 1496176951830, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111516, 'user1', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'No, unfortunately.', 1496176948001, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111517, 'user3', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'How much Klonopin do you take for your panic attacks?', 1496176948128, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111518, 'user1', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'I take a pretty low dose. I think I''m on zero point five milligrams a day. Is there any way you could verify the dosage?', 1496176928913, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111519, 'user3', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'I can try to look it up online. When were you last prescribed Klonopin?', 1496176977661, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111520, 'user1', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'Over two months ago I think.', 1496176964335, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111521, 'user3', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'Let me pull up the page and see if we can figure out your dosage and when you''re due for a refill based on your doctor''s orders.', 1496176940622, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111522, 'user1', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'Okay, thank you.', 1496176945669, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111523, 'user3', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'Are you experiencing any symptoms currently, such as headache, nausea, vomiting, shortness of breath or chest pain?', 1496176944089, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111524, 'user1', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'Not right now, no. I did have some nausea yesterday. Oh and I guess I had a slight headache when I woke up this morning, but that''s about it.', 1496177000555, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111525, 'user3', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'What are you taking it for? And how long have you been on it?', 1496176923949, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111526, 'user1', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'Panic attacks. I have really bad episodes without it. Um I think I started it about four months ago. I could be wrong though. I''ve lost track of time.', 1496176928408, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111527, 'user3', '94358b53-9d59-4b9a-bfdd-aa0f4bd0a00e', 'Who usually prescribes it to you?', 1496176927586, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111528, 'user2', '818094b1-dca9-4adc-8122-b8782bdd54cf', 'How are you? I haven''t seen you in a long time.', 1570771520094, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111529, 'user1', '818094b1-dca9-4adc-8122-b8782bdd54cf', 'I''m doing fine. I hurt my hand the other day.', 1570771522754, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111530, 'user1', '818094b1-dca9-4adc-8122-b8782bdd54cf', 'Yeah. We do. We just got married.', 1570771529119, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111531, 'user1', '818094b1-dca9-4adc-8122-b8782bdd54cf', 'My husband and I moved into our new home, and we were building a desk. I tried to nail something in, and I hammered my hand.', 1570771536220, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111532, 'user2', '818094b1-dca9-4adc-8122-b8782bdd54cf', 'Oh, no. So, you and your husband live together now?', 1570771542381, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111533, 'user2', '818094b1-dca9-4adc-8122-b8782bdd54cf', 'How did that happen?', 1570771530176, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111534, 'user1', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'Man, what a night.', 1310824070204, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111535, 'user2', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'What kind of car were you driving that night?', 1310824074007, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111536, 'user2', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'Good.', 1310824076620, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111537, 'user1', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'Unfortunately, the driver was drunk and ran a traffic signal.', 1310824093165, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111538, 'user2', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'That''s such a shame. Do you remember how fast the car was going when it collided into you?', 1310824092830, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111539, 'user1', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'If I had to guess maybe eighty miles per hour. It looks like the driver who hit me was already cited by police.', 1310824113232, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111540, 'user2', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'Did you lose consciousness at all?', 1310824079909, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111541, 'user1', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'Yeah, I briefly lost consciousness when help arrived at the scene. I felt an immediate headache when I regained consciousness. I also had lower back and neck pain.', 1310824113405, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111542, 'user2', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'Did you get out of the car by yourself?', 1310824121590, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111543, 'user1', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'Yeah, I got out by myself. Once I made it out, the Rescue Squad drove me to Saint Thomas Memorial Hospital. I was seen in the emergency room and later discharged.', 1310824133702, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111544, 'user2', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'This was on January fifteenth, correct?', 1310824123323, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111545, 'user1', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'Yessir.', 1310824128433, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111546, 'user1', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'Yeah, I had my belt on and everything.', 1310824082978, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111547, 'user1', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'I was driving my small sports car through an intersection when another car hit me from the left side. The impact forced my car off the road and into a utility pole.', 1310824077077, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111548, 'user2', '38a0e855-9590-4896-8d55-2d4fb05ffced', 'I''m so sorry to hear that. I''m glad that you are here in one piece. Were you wearing your seatbelt?', 1310824074817, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111549, 'user2', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'How''re you doing?', 1650408469285, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111550, 'user1', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'Good for the most part. I''m still pretty tired most days, but I''m trying to stay more active. I''m wondering if it has to do with my sugar levels?', 1650408475055, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111551, 'user1', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'Maybe a week or so?', 1650408483682, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111552, 'user2', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'Are you having any other symptoms? Black or tarry stool? Nausea, vomiting, diarrhea? Lightheadedness?', 1650408493991, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111553, 'user1', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'No, none of that.', 1650408486782, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111554, 'user2', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'I''d like to order a hemoccult then. It''s going to check to see if you''re still having blood in your stool.', 1650408496629, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111555, 'user1', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'Can I do this at the blood work place?', 1650408483385, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111556, 'user2', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'Yes, they''ll be able to help you and answer any additional questions you may have.', 1650408484111, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111557, 'user1', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'Okay. I''ll try to go in tomorrow.', 1650408499606, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111558, 'user2', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'Remember you need to fast for the lipid panel, so I''d recommend going in early tomorrow morning before eating breakfast.', 1650408508725, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111559, 'user1', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'Okay, got it.', 1650408491557, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111560, 'user2', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'And before I send you on your way, have you been able to schedule your yearly mammogram?', 1650408507074, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111561, 'user1', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'Oh shoot. I still need to do that. I''ll call them tomorrow.', 1650408489139, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111562, 'user2', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'Hm let''s see. I''d like to check your glucose and lipid panels and get you back in here again.', 1650408472115, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111563, 'user1', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'And oh I''ve noticed some blood in my stool. I''m not sure if it''s related.', 1650408484457, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111564, 'user2', 'f39027a9-dd84-4294-af26-e8ea6286ddb3', 'How long has that been going on?', 1650408492511, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111565, 'user3', 'c55e7a9a-9255-4e44-bbd8-bed0a8353326', 'Hello, ma''am. How are you doing?', 995517749267, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111566, 'user1', 'c55e7a9a-9255-4e44-bbd8-bed0a8353326', 'My knees hurt. They''ve been slowly getting worse each year. Life''s getting hard at seventy two.', 995517750511, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111567, 'user1', 'c55e7a9a-9255-4e44-bbd8-bed0a8353326', 'Nope. I just sit all day.', 995517759111, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111568, 'user3', 'c55e7a9a-9255-4e44-bbd8-bed0a8353326', 'I see. We can offer to do arthroplasty to fix your knees.', 995517766974, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111569, 'user1', 'c55e7a9a-9255-4e44-bbd8-bed0a8353326', 'What''s that?', 995517757512, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111570, 'user3', 'c55e7a9a-9255-4e44-bbd8-bed0a8353326', 'It''s like a reconstruction of your joints. It''ll help increase your ability to do daily activities.', 995517781651, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111571, 'user1', 'c55e7a9a-9255-4e44-bbd8-bed0a8353326', 'I''m up for it. I need to get my life going.', 995517773861, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111572, 'user3', 'c55e7a9a-9255-4e44-bbd8-bed0a8353326', 'Sounds great. I just want to confirm some information. Would you say your quality of life and daily activities is decreasing?', 995517802434, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111573, 'user1', 'c55e7a9a-9255-4e44-bbd8-bed0a8353326', 'Oh, yeah. These knees are making my life terrible.', 995517814988, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111574, 'user3', 'c55e7a9a-9255-4e44-bbd8-bed0a8353326', 'I''m sorry to hear that. Have you always had knee pain?', 995517757822, 2);
