INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111577, 'user3', '85d2a6bc-6bb3-4fd7-87ce-7e488b44127f', 'How''s he doing?', 1598679078031, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111578, 'user3', '85d2a6bc-6bb3-4fd7-87ce-7e488b44127f', 'Is he complaining of any pain?', 1598679098827, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111579, 'user3', '85d2a6bc-6bb3-4fd7-87ce-7e488b44127f', 'How long has it been since you noticed any behavioral changes?', 1598679081285, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111580, 'user1', '85d2a6bc-6bb3-4fd7-87ce-7e488b44127f', 'A few days now.', 1598679092178, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111581, 'user1', '85d2a6bc-6bb3-4fd7-87ce-7e488b44127f', 'Sorry, my phone was on vibrate and I had to turn it off.', 1598679086968, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111582, 'user3', '85d2a6bc-6bb3-4fd7-87ce-7e488b44127f', 'No problem.', 1598679112622, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111583, 'user1', '85d2a6bc-6bb3-4fd7-87ce-7e488b44127f', 'He''s been pointing to his stomach and saying it hurts.', 1598679093067, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111584, 'user3', '85d2a6bc-6bb3-4fd7-87ce-7e488b44127f', 'Is he having any other symptoms?', 1598679125003, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111585, 'user1', '85d2a6bc-6bb3-4fd7-87ce-7e488b44127f', 'He''s told me he feels queasy. I took his temperature the other night and he was running a fever of one O two.', 1598679089411, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111586, 'user3', '85d2a6bc-6bb3-4fd7-87ce-7e488b44127f', 'Any vomiting with the nausea?', 1598679108425, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111587, 'user1', '85d2a6bc-6bb3-4fd7-87ce-7e488b44127f', 'Yeah, he''s thrown up a handful of times.', 1598679107907, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111588, 'user3', '85d2a6bc-6bb3-4fd7-87ce-7e488b44127f', 'He''s been?', 1598679102566, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111589, 'user1', '85d2a6bc-6bb3-4fd7-87ce-7e488b44127f', 'Not so great. He''s been out of it. He hasn''t been acting like himself.', 1598679080246, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111590, 'user1', '85d2a6bc-6bb3-4fd7-87ce-7e488b44127f', 'Yeah he''s been-', 1598679097199, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111591, 'user2', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'Good morning, sir. Remind me please, when was your surgery?', 1133673397101, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111592, 'user1', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'Hello, doctor. It was about a week ago now.', 1133673401451, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111593, 'user1', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'Oh, wow.', 1133673413879, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111594, 'user2', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'Yeah, it''s great, eliminates some need for P T in fact. How are you doing today?', 1133673416605, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111595, 'user1', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'Overall, my pain is under control.', 1133673410946, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111596, 'user2', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'Are you having any flu like, or infection symptoms?', 1133673434860, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111597, 'user1', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'No, nothing like that at all.', 1133673437450, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111598, 'user2', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'So, no fever, or chills, or sweating at night.', 1133673454929, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111599, 'user1', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'Yeah, nothing like that.', 1133673442106, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111600, 'user2', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'Great. I see you''re having some drainage from the pin sites, but that doesn''t bother me too much.', 1133673445006, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111601, 'user1', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'Okay, good. I was getting worried.', 1133673424785, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111602, 'user2', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'No need to worry. Are you doing your range of motion exercises? Those are imperative.', 1133673446430, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111603, 'user1', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'Yes, doctor. I am.', 1133673441949, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111604, 'user2', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'Good, and do you have any numbness or tingling?', 1133673478363, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111605, 'user1', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'No, doctor. I don''t have any of that.', 1133673445441, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111606, 'user1', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'Yes, that all sounds familiar. What''s M U A?', 1133673414791, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111607, 'user2', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'It stands for manipulation under anesthesia. We bent the knee in order to forcibly break up some scar tissue.', 1133673419186, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111608, 'user2', 'e31dbb1b-73c5-402d-b128-61c4994dd2a0', 'Great, and just to remind you, you had a removal of Ex Fix from the right knee with an M U A following O R I F of a right tibial plateau fracture.', 1133673405509, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111609, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'How old are you, young lady?', 1238375689823, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111610, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'What brings you here?', 1238375698114, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111611, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'I had a fall. And I was told to consult you for my heart conditions.', 1238375696836, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111612, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'Okay. Um? Can you tell me a little detail about anything you experienced before or diagnosed before?', 1238375702955, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111613, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'Yeah, I have high blood pressure. And they also diagnosed me with other heart diseases. I cannot pronounce all the names I don''t remember.', 1238375705723, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111614, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'That''s fine. Let me go through your medical record first.', 1238375700921, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111615, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'Let''s see what we have here. Looks like you have your plate full. Your record says you had hypertension I mean, high blood pressure. Also, you have a history of severe tricuspid regurgitation with mild pulmonary hypertension, mild aortic stenosis, and previously moderate mitral regurgitation.', 1238375696419, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111616, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'Wow! Those are a lot of fancy words that I can never remember.', 1238375696738, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111617, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'Ha ha. So, it says here they they want me to check you for atrial fibrillation. Yet another fancy word to add to your list.', 1238375743328, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111618, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'What does it mean?', 1238375707033, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111619, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'It means I must check if you have faster than normal heartbeat after your fall. In simple words, just to check if there are any irregularities in your heart beating, okay?', 1238375700489, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111620, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'Hm, okay.', 1238375717146, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111621, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'So tell me what happened? How did you fall?', 1238375738650, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111622, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'I''m not sure about how it happened, but yeah, I fell yesterday on my driveway and kind of hit a rock.', 1238375712745, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111623, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'Which side did you hit the rock?', 1238375714398, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111624, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'Um I think it was left side.', 1238375723072, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111625, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'They gave me some medicine. And they put something on my finger. They said that my heart rate was very high.', 1238375717774, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111626, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'Let me review your electrocardiogram from emergency. It says that there was rapid heart rate. Your heart was really beating very fast and then there was one more electrocardiogram which showed that your pacemaker is acting weird.', 1238375765362, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111627, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'Yeah, in the record it says that they found rapid atrial tachyarrhythmia. So, according to this, they have given you Cardizem and they stopped it when your heart rate came to fifties.', 1238375772435, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111628, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'They also did the same test this morning.', 1238375815514, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111629, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'One they did this morning shows normal rate with frequent early heartbeats. Looks like they also tested your blood. Your potassium level is three point one.', 1238375770801, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111630, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'How was your heart feeling when you fell yesterday?', 1238375725699, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111631, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'I felt that I just ran in a race. I could feel all the pain after that fall. It was ugly. My heart was pounding so fast it was ready to come out, I never felt like that before in my life.', 1238375830345, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111632, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'Did you feel the same way afterwards as well?', 1238375715913, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111633, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'What happened in the emergency room?', 1238375721237, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111634, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'No, it was just after fall. It did not stay like that for long, I was normal later. I never felt it again after that incident.', 1238375749871, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111635, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'That is good. Do you have any pain or discomfort in your chest?', 1238375776285, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111636, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'I don''t think so.', 1238375729319, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111637, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'How about before the fall? Did you have any pain or discomfort in your chest before the fall?', 1238375780756, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111638, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'Nope.', 1238375715784, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111639, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'how about shortness of breath?', 1238375721917, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111640, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'No, not even before the fall. I''m able to walk and I''m sure I can climb stairs. Maybe two floors without any problems.', 1238375870787, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111641, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'I''m good. Thank you.', 1238375685226, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111642, 'user1', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'Eighty four.', 1238375691272, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111643, 'user3', '5d1cd856-9770-43f3-8b81-ac9894d93713', 'Hi, how are you doing?', 1238375682938, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111644, 'user2', '5e50814d-d495-4a11-9a51-92880ea499b9', 'So just a few quick questions before we wrap up. Do you smoke or drink?', 1428020389141, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111645, 'user2', '5e50814d-d495-4a11-9a51-92880ea499b9', 'Are you sexually active?', 1428020404325, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111646, 'user1', '5e50814d-d495-4a11-9a51-92880ea499b9', 'Uh I was back in Haiti, but that was back in eighty two. I had several male partners, but no sex since moving here.', 1428020394716, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111647, 'user2', '5e50814d-d495-4a11-9a51-92880ea499b9', 'Did you use protection in your previous encounters?', 1428020395422, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111648, 'user1', '5e50814d-d495-4a11-9a51-92880ea499b9', 'Most of the time, yes.', 1428020414583, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111649, 'user2', '5e50814d-d495-4a11-9a51-92880ea499b9', 'Any history of S T Ds?', 1428020435168, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111650, 'user1', '5e50814d-d495-4a11-9a51-92880ea499b9', 'No.', 1428020432096, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111651, 'user2', '5e50814d-d495-4a11-9a51-92880ea499b9', 'Are you currently working?', 1428020420063, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111652, 'user1', '5e50814d-d495-4a11-9a51-92880ea499b9', 'Yep. I work for a car dealership down the street.', 1428020439122, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111653, 'user1', '5e50814d-d495-4a11-9a51-92880ea499b9', 'I drink sometimes. I''ve never smoked.', 1428020393313, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111654, 'user1', '5e50814d-d495-4a11-9a51-92880ea499b9', 'No.', 1428020402048, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111655, 'user2', '5e50814d-d495-4a11-9a51-92880ea499b9', 'Any drug use?', 1428020393846, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111656, 'user3', '3df3dc71-5013-4fca-84fd-846981688a30', 'Are you taking any medications for your pain?', 1572193758835, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111657, 'user1', '3df3dc71-5013-4fca-84fd-846981688a30', 'Yeah, occasionally.', 1572193763050, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111658, 'user3', '3df3dc71-5013-4fca-84fd-846981688a30', 'Which one?', 1572193766258, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111659, 'user1', '3df3dc71-5013-4fca-84fd-846981688a30', 'Just a regular pain medicine.', 1572193763412, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111660, 'user2', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Good morning, sir, I hear you''re a patient of Doctor A.', 1409432675719, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111661, 'user2', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Are you having diarrhea?', 1409432697457, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111662, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Yeah, I am.', 1409432685347, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111663, 'user2', 'ec0810d8-7f72-4738-a777-c994699703a0', 'How would you describe the frequency?', 1409432710027, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111664, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'I''d say it''s chronic at this point.', 1409432692802, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111665, 'user2', 'ec0810d8-7f72-4738-a777-c994699703a0', 'How long have you known you have anemia?', 1409432696057, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111666, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Um, it''s been a few months now.', 1409432697375, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111667, 'user2', 'ec0810d8-7f72-4738-a777-c994699703a0', 'What markers were evaluated in order to diagnose this?', 1409432706657, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111668, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'I had, um, an unusual pruritus, and I had a C B C.', 1409432717330, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111669, 'user2', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Do you have the results of that?', 1409432704360, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111670, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Yes, right here.', 1409432748313, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111671, 'user2', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Thank you, so this shows a hemoglobin of nine, and M C V of sixty five.', 1409432738595, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111672, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Are those high?', 1409432734342, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111673, 'user2', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Well, actually, both of those are low.', 1409432694501, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111674, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Oh, okay.', 1409432772267, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111675, 'user2', 'ec0810d8-7f72-4738-a777-c994699703a0', 'How long have you had blood in your stool?', 1409432767125, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111676, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Um, it''s been about five months now.', 1409432764434, 19);
