INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111678, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Well, it''s been both dark and bright blood, actually?', 1409432730516, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111679, 'user2', 'ec0810d8-7f72-4738-a777-c994699703a0', 'When was your last colonoscopy?', 1409432757808, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111680, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'It was about three years ago, I had it with Doctor X. I did it in Las Cruces.', 1409432813685, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111681, 'user2', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Was there any abnormality found?', 1409432752538, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111682, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Yeah, I had polyps removed.', 1409432707758, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111683, 'user2', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Were those polyps evaluated?', 1409432714925, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111684, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Yeah, the doctors said they were, um, hyperplastic. They diagnosed me with, um, lymphocytic colitis.', 1409432728957, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111685, 'user2', 'ec0810d8-7f72-4738-a777-c994699703a0', 'I see, when was the last time you were treated for diarrhea?', 1409432795744, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111686, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'At this point, it''s been more than three years.', 1409432709602, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111687, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Yeah, I''m fifty five, so I''m not too young anymore, but I have developed iron deficiency anemia with blood in my stool. At least, that''s what she''s told me so far.', 1409432691013, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111688, 'user1', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Yes, that''s correct.', 1409432681710, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111689, 'user2', 'ec0810d8-7f72-4738-a777-c994699703a0', 'Did she refer you to me?', 1409432684933, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111690, 'user2', 'd0ae4409-1c50-47a4-aee5-69589330ed18', 'Good afternoon, before we begin, what are your pronouns?', 1001999517283, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111691, 'user1', 'd0ae4409-1c50-47a4-aee5-69589330ed18', 'I identify as a female, and I use she her pronouns.', 1001999518673, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111692, 'user1', 'd0ae4409-1c50-47a4-aee5-69589330ed18', 'Absolutely, here you go.', 1001999540476, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111693, 'user2', 'd0ae4409-1c50-47a4-aee5-69589330ed18', 'Thank you. So I see you''ve had a multiple bowel surgeries, including, um, a hysterectomy, rectocele repair, and an appendectomy. Do all of those sound familiar.', 1001999537675, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111694, 'user1', 'd0ae4409-1c50-47a4-aee5-69589330ed18', 'Yep, I got this list from all of the surgeons.', 1001999525384, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111695, 'user2', 'd0ae4409-1c50-47a4-aee5-69589330ed18', 'Are there any other major conditions I should be aware of?', 1001999537388, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111696, 'user1', 'd0ae4409-1c50-47a4-aee5-69589330ed18', 'Yes, actually, I have another list, um, I have polymyalgia rheumatica.', 1001999533635, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111697, 'user2', 'd0ae4409-1c50-47a4-aee5-69589330ed18', 'That''s all great information to know, thank you very much.', 1001999549298, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111698, 'user2', 'd0ae4409-1c50-47a4-aee5-69589330ed18', 'That''s really helpful, may I see it?', 1001999535556, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111699, 'user2', 'd0ae4409-1c50-47a4-aee5-69589330ed18', 'Thank you, so, have you ever had surgery?', 1001999525678, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111700, 'user1', 'd0ae4409-1c50-47a4-aee5-69589330ed18', 'Yes, I actually have a list of them written down.', 1001999522904, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111701, 'user2', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'Hello Mister Strange, can you please confirm your age and ethnicity for the records.', 1444976322154, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111702, 'user2', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'They did phlebotomy and then subsequently you got yourself transferred here in our healthcare.', 1444976331624, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111703, 'user2', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'Let''s first talk about your medical condition. There has been a diagnosis of polycythemia vera with secondary myelofibrosis. Also, you are J A K two positive. Do you remember when you were diagnosed?', 1444976327485, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111704, 'user2', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'You have been on hydroxyurea and interferon, right?', 1444976336562, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111705, 'user1', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'Oh, it was a terrible time, I could not deal with anyone of them. I had numbness and tingling with burning pain in my hands.', 1444976343370, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111706, 'user2', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'You do not have any siblings that we can try for transplant match?', 1444976357537, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111707, 'user1', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'That''s right!', 1444976365735, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111708, 'user2', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'You were also considered for the Matched Unrelated Donor Transplant, but you couldn''t be on the list due to social support and also health was in reasonably better state than other candidates normally on that transplant list.', 1444976370698, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111709, 'user1', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'We had some medications here as well when I first started my care here, I forgot the name.', 1444976360883, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111710, 'user2', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'Yes, here we started you on a trial of lenalidomide and prednisone for some time. You were doing great on that for a while, but then you developed intolerance to lenalidomide.', 1444976382819, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111711, 'user1', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'Yes, I had severe diarrhea and I always felt tired like I have no energy left in me. Eventually it all stopped.', 1444976396910, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111712, 'user2', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'Yeah, here it says that you injured your leg? Tell me what happened.', 1444976352449, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111713, 'user1', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'It all happened last week, I injured this left leg and got swelling. I had some prescribed steroids, so I took them for about three days only. The swelling is eventually gone now.', 1444976364200, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111714, 'user2', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'Any other related complaints?', 1444976395277, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111715, 'user1', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'No.', 1444976419835, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111716, 'user2', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'Do you smoke or drink?', 1444976351260, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111717, 'user1', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'I take marijuana. I feel really hungry after smoking it, so I eat a lot. In just the last few weeks I have gained a few pounds.', 1444976369075, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111718, 'user2', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'Okay, your overall performance status in the E C O G scale is one.', 1444976355080, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111719, 'user1', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'Yes.', 1444976336959, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111720, 'user1', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'It was sometimes between two thousand and five and six.', 1444976333423, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111721, 'user1', 'ff5008b0-7568-4aa3-8665-72067ac02c45', 'Hi Doctor, I am fifty five now and would identify myself as a white male.', 1444976323709, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111722, 'user2', '536312a9-7b22-4e7a-82a5-14174bfb1c76', 'Do you have any family history of neurological disorders, such as multiple sclerosis, Parkinson''s or dementia?', 1099727690835, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111723, 'user1', '536312a9-7b22-4e7a-82a5-14174bfb1c76', 'Nope. Fortunately, no one in my family has neurological problems.', 1099727695308, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111724, 'user3', '07c3b639-d75d-4189-99f8-60b08ff74dfe', 'How long have you had this rash?', 1602932402457, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111725, 'user1', '07c3b639-d75d-4189-99f8-60b08ff74dfe', 'Not long. Less than a day if I had to guess.', 1602932407951, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111726, 'user3', '07c3b639-d75d-4189-99f8-60b08ff74dfe', 'Is it causing you any pain?', 1602932413164, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111727, 'user1', '07c3b639-d75d-4189-99f8-60b08ff74dfe', 'No, it''s just really itchy. I tried applying Cortisone to it, but it didn''t help much.', 1602932417278, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111728, 'user3', '07c3b639-d75d-4189-99f8-60b08ff74dfe', 'Is the rash localized to the left arm?', 1602932422435, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111729, 'user1', '07c3b639-d75d-4189-99f8-60b08ff74dfe', 'Yeah. I''ve only noticed it on my left arm.', 1602932411068, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111730, 'user2', '2e76a37f-981a-4740-b856-dd7c992953f9', 'Hello. How are you both doing today?', 1266669890331, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111731, 'user1', '2e76a37f-981a-4740-b856-dd7c992953f9', 'We''re doing great. The E D told us to come here. We''re here to see if we could get the stuff in his leg taken out.', 1266669894968, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111732, 'user2', '2e76a37f-981a-4740-b856-dd7c992953f9', 'I see. Did he have a fracture before?', 1266669899860, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111733, 'user2', '2e76a37f-981a-4740-b856-dd7c992953f9', 'Perfect. So, now we just have to remove the hardware that was used to fix the fracture, right?', 1266669917675, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111734, 'user2', '2e76a37f-981a-4740-b856-dd7c992953f9', 'Great. Let me take a look. It looks like he had a distracted left lateral condyle fracture. He then underwent screw compression to fix the fracture, correct?', 1266669909224, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111735, 'user2', '2e76a37f-981a-4740-b856-dd7c992953f9', 'The risks include the risk of anesthesia, infection, bleeding, changes in sensation and motion of extremity, failure of removal of hardware, failure to relieve pain or improved range of motion.', 1266669926099, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111736, 'user1', '2e76a37f-981a-4740-b856-dd7c992953f9', 'Oh, wow. That''s a lot. Could you go over the benefits?', 1266669905117, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111737, 'user2', '2e76a37f-981a-4740-b856-dd7c992953f9', 'Of course. Before I do, I just need to confirm your son''s age.', 1266669921657, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111738, 'user1', '2e76a37f-981a-4740-b856-dd7c992953f9', 'He can tell you.', 1266669929094, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111739, 'user1', '2e76a37f-981a-4740-b856-dd7c992953f9', 'Hi. I''m five years old. My birthday is in four months.', 1266669957729, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111740, 'user2', '2e76a37f-981a-4740-b856-dd7c992953f9', 'Thank you. Happy almost birthday.', 1266669925830, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111741, 'user1', '2e76a37f-981a-4740-b856-dd7c992953f9', 'He gets excited about birthdays. I just have a few more questions, but it looks like we''re going to go through with the surgery.', 1266669955748, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111742, 'user1', '2e76a37f-981a-4740-b856-dd7c992953f9', 'Yeah, that''s correct. What are the risks of the surgery?', 1266669930112, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111743, 'user1', '2e76a37f-981a-4740-b856-dd7c992953f9', 'That''s correct.', 1266669901817, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111744, 'user1', '2e76a37f-981a-4740-b856-dd7c992953f9', 'Yeah, he did. Here''s the report from the surgery from October two thousand and seven.', 1266669903582, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111745, 'user3', '51db022a-cd83-4941-a63f-83e0dbae0e2e', 'I am looking at her x ray report and she had a sternotomy in the past.', 1561990022915, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111746, 'user3', '51db022a-cd83-4941-a63f-83e0dbae0e2e', 'Yes, and we placed an I C D implant and an aortic valve mechanical implant. Her pleural effusion was really worrisome causing left sided opacification of her diaphragm.', 1561990026726, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111747, 'user3', '51db022a-cd83-4941-a63f-83e0dbae0e2e', 'Oh I see!', 1561990031217, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111748, 'user3', 'ffd5e396-37ce-4071-85b1-d6f95b3bab0e', 'What happened to your right leg?', 1175369222305, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111749, 'user1', 'ffd5e396-37ce-4071-85b1-d6f95b3bab0e', 'I had a little accident with a dog, he bit me. I got really scared.', 1175369226807, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111750, 'user3', 'ffd5e396-37ce-4071-85b1-d6f95b3bab0e', 'Don''t worry we will take care of this.', 1175369230498, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111751, 'user3', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'We''ve been following you for several conditions for a while now. What seems to be the problem today, sir?', 1082926309301, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111752, 'user1', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'Um, I was peeing blood, it''s back again.', 1082926310594, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111753, 'user1', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'Yes, I have been.', 1082926328931, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111754, 'user3', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'What about the Coumadin?', 1082926339583, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111755, 'user1', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'Yes, I''ve been taking that too. It has been held recently, but I ususally take it.', 1082926320953, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111756, 'user3', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'Remind me, I don''t have my chart with me. What conditions have you been taking the Coumadin for?', 1082926344604, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111757, 'user1', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'I have A F I B and stroke.', 1082926357200, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111758, 'user3', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'Thank you. Isn''t this your second occurrence of gross hematuria this month?', 1082926343231, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111759, 'user1', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'Yes, doctor.', 1082926352294, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111760, 'user3', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'Are you sure you haven''t experienced any falls or anything recently?', 1082926378458, 12);
