INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111762, 'user3', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'Where is your pain from that fall?', 1082926359566, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111763, 'user1', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'It''s in my butt and leg.', 1082926342790, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111764, 'user3', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'Have you had your x rays taken yet?', 1082926400972, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111765, 'user1', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'Yeah, the x ray tech just brought me back.', 1082926335984, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111766, 'user3', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'Okay, these x rays of the hips, knees, and ankles show severe degeneration in all areas.', 1082926367261, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111767, 'user1', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'What does that mean, doctor?', 1082926337661, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (111768, 'user3', 'a02a9b8e-04e1-441e-a680-38fb327a1bd8', 'I see some pretty significant arthritis in these areas.', 1082926419466, 20);
