INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112010, 'user2', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'I would like to get a detailed history of your inperforated anus and the curvature of the penis. It is a genetic condition. And do you know if you had surgery soon after birth?', 1518910220176, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112011, 'user1', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'Yeah, my mother said that I had to have surgery after she gave birth to me.', 1518910221315, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112012, 'user1', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'Yeah. I was hospitalized in nineteen seventy for a U T I. That is when the problems started happening. It was a really bad infection.', 1518910233113, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112013, 'user2', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'Okay.', 1518910236176, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112014, 'user1', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'In nineteen eighty eight I the tissue removed from the anus. There was a blockage. They also did an operation in the shaft of the penis too.', 1518910245727, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112015, 'user2', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'I bet things improved after that surgery.', 1518910232465, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112016, 'user1', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'It did. I have here in January of nineteen ninety one I had a cystoscopy to remove a blockage.', 1518910265391, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112017, 'user2', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'Um hum.', 1518910242021, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112018, 'user1', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'In two thousand and one I had a colonoscopy that was normal. Later that year I had a biopsy of my prostate.', 1518910246902, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112019, 'user2', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'What did the biopsy show?', 1518910268889, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112020, 'user1', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'They said I had severe inflammation in the prostate. I was never told that cause of the inflammation.', 1518910254330, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112021, 'user2', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'Okay. Any other surgeries for your condition?', 1518910266837, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112022, 'user1', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'Oh yeah. I had that same procedure done again when I was twenty seven and twenty eight. The same one that I had as a newborn. I had a third surgery when I was seventy with just a correction of the shaft area.', 1518910250125, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112023, 'user2', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'Um hum. Any other surgeries unrelated to your condition?', 1518910255402, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112024, 'user1', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'Yeah. I have it written down here. In two thousand and one there was a left rotator cuff repair with acromioplasty and distal clavicle resection and in two thousand and three I had a left inguinal hernia repair with M E S H. That is what my notes say.', 1518910311980, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112025, 'user2', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'Have you ever had any complications during any of your surgeries?', 1518910249575, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112026, 'user1', '20577e99-b1ae-43a3-98e9-250a3aaf5f52', 'Yeah, I did. I have a blood clot that apparently went into my lungs. I was very scary.', 1518910285357, 19);
