INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112045, 'user2', '3a247608-982f-49f4-8047-54ebe8e36bfd', 'How old are you, young man?', 1137580788504, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112046, 'user1', '3a247608-982f-49f4-8047-54ebe8e36bfd', 'I am twenty one.', 1137580794489, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112047, 'user1', '3a247608-982f-49f4-8047-54ebe8e36bfd', 'Everything started on the fifth of November. Then after I saw the gradual increase in my symptoms. So it was all like numbness. I could not feel my legs. They felt numb all the time and there was no coordination between them, and it also affected my walk. All these symptoms were at their limit in just like a half day or more. It is continuing the same way since then. I also feel like somebody is putting pins and needles on my legs approximately  halfway up the calf on both sides.', 1137580811259, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112048, 'user2', '3a247608-982f-49f4-8047-54ebe8e36bfd', 'You said that you felt decreased coordination or less coordination between your legs, right?', 1137580796568, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112049, 'user1', '3a247608-982f-49f4-8047-54ebe8e36bfd', 'Yeah, that''s right. It totally feels like I''m walking in space and don''t know where to put my next step. I have no up and down spatial awareness.', 1137580811682, 7);
