INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112062, 'user2', '3a247608-982f-49f4-8047-54ebe8e36bfd', 'What about any other major health issues in the past?', 1137580871077, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112063, 'user1', '3a247608-982f-49f4-8047-54ebe8e36bfd', 'No, no medical issues.', 1137580867544, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112064, 'user2', '3a247608-982f-49f4-8047-54ebe8e36bfd', 'Are you taking any kind of medication for anything?', 1137580911224, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112065, 'user1', '3a247608-982f-49f4-8047-54ebe8e36bfd', 'No medications.', 1137580816314, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112066, 'user2', '3a247608-982f-49f4-8047-54ebe8e36bfd', 'Are you right handed or left handed?', 1137580794605, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112067, 'user1', '3a247608-982f-49f4-8047-54ebe8e36bfd', 'I am right handed.', 1137580804746, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112068, 'user2', '3a247608-982f-49f4-8047-54ebe8e36bfd', 'So, tell me what brings you here today?', 1137580794149, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112069, 'user2', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'What brings you in to the clinic today?', 1129930473484, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112070, 'user2', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'Okay. How long has the vision loss been progressing for?', 1129930478290, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112071, 'user1', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'About two months. It seems like it has been progressing really fast. I have always had bad vision in my left eye. That started about two years ago.', 1129930489084, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112072, 'user2', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'Can you still see out of you left eye?', 1129930493570, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112073, 'user1', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'No. I am considered blind in this eye now.', 1129930481022, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112074, 'user1', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'No.', 1129930494818, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112075, 'user2', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'Have you had any other symptoms associated with your vision loss?', 1129930503090, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112076, 'user2', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'Any headaches?', 1129930514608, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112077, 'user2', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'What is you dominate hand?', 1129930488480, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112078, 'user2', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'What hand do you write with or use dominantly?', 1129930493556, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112079, 'user2', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'And how old are you?', 1129930549103, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112080, 'user1', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'Well, I have had a progressive loss of my vision in my right eye. My eye doctor told me that I should come and see a neurologist. So here I am.', 1129930477035, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112081, 'user2', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'Okay. I would like to run some test now.', 1129930490199, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112082, 'user1', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'Okay.', 1129930510081, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112083, 'user1', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'What do you mean?', 1129930494640, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112084, 'user1', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'I am sixty two.', 1129930532697, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112085, 'user1', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'Nope.', 1129930493097, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112086, 'user1', 'ab555a9d-41a8-4f02-9e16-9e8f72b3c230', 'Oh! I am right handed.', 1129930497183, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112087, 'user2', '56d80b89-b18f-4c1e-9e71-909cef68a025', 'Do you have any history of rheumatic fever as a child?', 1627816335430, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112088, 'user1', '56d80b89-b18f-4c1e-9e71-909cef68a025', 'No.', 1627816338566, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112089, 'user2', '56d80b89-b18f-4c1e-9e71-909cef68a025', 'Any history of anything other then usual childhood illnesses?', 1627816346482, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112090, 'user1', '56d80b89-b18f-4c1e-9e71-909cef68a025', 'No.', 1627816347684, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112091, 'user3', 'be693d19-701e-4733-9b00-5f6e4759771f', 'So, tell me a little bit more about your family history, please.', 957442673874, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112092, 'user1', 'be693d19-701e-4733-9b00-5f6e4759771f', 'Sure, I know that my grandmother on my mom''s side had pancreatic cancer, and my dad had prostate cancer.', 957442679531, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112093, 'user3', 'be693d19-701e-4733-9b00-5f6e4759771f', 'Besides cancer, are there any other conditions that you know run in your family?', 957442684710, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112094, 'user1', 'be693d19-701e-4733-9b00-5f6e4759771f', 'Um, I know that my dad had heart disease, as well as diabetes.', 957442684184, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112095, 'user3', 'be693d19-701e-4733-9b00-5f6e4759771f', 'Thank you, this is good information to know.', 957442695335, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112096, 'user2', '26f73c29-78e1-403c-ba9e-c95db0012d2a', 'What do you do?', 1189207741236, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112097, 'user1', '26f73c29-78e1-403c-ba9e-c95db0012d2a', 'I am a registered nurse.', 1189207742984, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112098, 'user2', '26f73c29-78e1-403c-ba9e-c95db0012d2a', 'Any history of drug abuse or anything?', 1189207753218, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112099, 'user1', '26f73c29-78e1-403c-ba9e-c95db0012d2a', 'Absolutely not!', 1189207775137, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112100, 'user2', '26f73c29-78e1-403c-ba9e-c95db0012d2a', 'Okay, good.', 1189207777962, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112101, 'user2', '26f73c29-78e1-403c-ba9e-c95db0012d2a', 'That''s nice.', 1189207746107, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112102, 'user2', '26f73c29-78e1-403c-ba9e-c95db0012d2a', 'And do you smoke or drink?', 1189207747512, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112103, 'user1', '26f73c29-78e1-403c-ba9e-c95db0012d2a', 'No sir.', 1189207764571, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112104, 'user3', 'e3495a2f-0ea7-4684-811e-66112a783a33', 'Hello, sir. How are you doing?', 1313205355364, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112105, 'user3', 'e3495a2f-0ea7-4684-811e-66112a783a33', 'You have a great attitude. I appreciate when patient''s take their health into their own hands. We can only do so much, but it is up to the patient to bring themselves in.', 1313205375053, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112106, 'user3', 'e3495a2f-0ea7-4684-811e-66112a783a33', 'That''s great. The previous notes said that you quit smoking. Are you still off?', 1313205360297, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112107, 'user3', 'e3495a2f-0ea7-4684-811e-66112a783a33', 'Do you drink at all?', 1313205390994, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112108, 'user1', 'e3495a2f-0ea7-4684-811e-66112a783a33', 'I do. Only occasionally.', 1313205383691, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112109, 'user1', 'e3495a2f-0ea7-4684-811e-66112a783a33', 'Yeah. I smoked for a long time and I know it was bad for me. It was just the norm back in the day.', 1313205369636, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112110, 'user1', 'e3495a2f-0ea7-4684-811e-66112a783a33', 'Yes, I quit in nineteen ninety six. I come yearly to the doctor''s office to make sure that the damage I did to my lungs is monitored.', 1313205370116, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112111, 'user1', 'e3495a2f-0ea7-4684-811e-66112a783a33', 'I am doing well, thanks. Just trying to come to you more regularly to make sure my lungs and heart are okay.', 1313205360074, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112112, 'user1', '69ea5043-461b-455b-9d3b-764f56dc771f', 'Hello Doctor. I am from High Hope assisted living center. I am Mister Rath''s assigned assistant.', 1108598927910, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112113, 'user3', '69ea5043-461b-455b-9d3b-764f56dc771f', 'Right. What brings you here?', 1108598929146, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112114, 'user1', '69ea5043-461b-455b-9d3b-764f56dc771f', 'I got some of Mister Rath''s food diary sheets here. He has already lost fifteen pounds in the last three months. We were just wondering if he needed to lose anymore.', 1108598931518, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112115, 'user3', '69ea5043-461b-455b-9d3b-764f56dc771f', 'Let me have a look.', 1108598936531, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112116, 'user2', '7b5f5953-f9dc-4061-8c97-5dc094aca9b9', 'Your condition and all your vital signs look stable to me right now. You must be very careful as your condition can get poor or it might improve as well.', 1239320608949, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112117, 'user2', '7b5f5953-f9dc-4061-8c97-5dc094aca9b9', 'That is good. Do take care of yourself and let me know if your condition worsens.', 1239320618776, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112118, 'user1', '7b5f5953-f9dc-4061-8c97-5dc094aca9b9', 'Yes, my son and his family lives with me. They are very caring.', 1239320626491, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112119, 'user2', '7b5f5953-f9dc-4061-8c97-5dc094aca9b9', 'Do you have any support system? Is there anyone at home to take care of you?', 1239320612750, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112120, 'user1', '7b5f5953-f9dc-4061-8c97-5dc094aca9b9', 'Okay, so what do you recommend?', 1239320612202, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112121, 'user1', '82392591-a3d6-47f4-bc64-7891d87cdf64', 'I''m a truck driver. It''s a big construction company. I work for them.', 1267879869211, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112122, 'user2', '82392591-a3d6-47f4-bc64-7891d87cdf64', 'Cigarette or something else?', 1267879885152, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112123, 'user1', '82392591-a3d6-47f4-bc64-7891d87cdf64', 'I do Cigar.', 1267879890339, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112124, 'user1', '82392591-a3d6-47f4-bc64-7891d87cdf64', 'Yeah.', 1267879876886, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112125, 'user2', '82392591-a3d6-47f4-bc64-7891d87cdf64', 'Where do you work?', 1267879863275, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112126, 'user2', '82392591-a3d6-47f4-bc64-7891d87cdf64', 'Do you smoke?', 1267879868695, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112127, 'user2', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'Good morning, ma''am. I just need a few pieces of information before we get started today.', 1609777945834, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112128, 'user2', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'What about harder drugs, do you use any of those?', 1609777962234, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112129, 'user1', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'No, I don''t.', 1609777964556, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112130, 'user2', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'Are you married?', 1609777952318, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112131, 'user1', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'Yes, to my wonderful husband.', 1609777975902, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112132, 'user2', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'That''s great, what do you two do for a living?', 1609777968855, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112133, 'user1', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'I''m a social worker, and my husband is a high school chemistry teacher.', 1609777988759, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112134, 'user2', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'What great work both of you are doing. What kinds of people do you work with as a social worker?', 1609777989341, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112135, 'user1', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'I love it, I work with adult abuse and neglect issues.', 1609777999786, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112136, 'user2', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'Yes, that''s great. Do you have any children?', 1609777962039, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112137, 'user1', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'Yes, we have two sons.', 1609778005748, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112138, 'user2', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'Do they live at home?', 1609778022626, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112139, 'user1', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'No, they''re both grown and on their own now.', 1609777974276, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112140, 'user2', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'Do you smoke or drink, ma''am?', 1609777952316, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112141, 'user1', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'I don''t smoke, and I drink, um, I''d say on occasionally.', 1609777958403, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112142, 'user1', 'bb2beb71-254c-42a8-87b1-22e1ebca024f', 'Good morning, doctor. Absolutely, that''s not a problem at all.', 1609777948756, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112143, 'user3', '00fea110-b2e7-42e7-8837-1cf876404b2b', 'Did both your parents have heart complications.', 1329016705274, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112144, 'user3', '00fea110-b2e7-42e7-8837-1cf876404b2b', 'I can''t imagine how hard that must''ve been.', 1329016726449, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112145, 'user1', '00fea110-b2e7-42e7-8837-1cf876404b2b', 'It was a dark time in our lives, but we survived it as a family.', 1329016725784, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112146, 'user1', '00fea110-b2e7-42e7-8837-1cf876404b2b', 'I lost my brother as well. He passed away from a brain tumor when he was nine years old.', 1329016716508, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112147, 'user1', '00fea110-b2e7-42e7-8837-1cf876404b2b', 'Unfortunately, yes. My mom passed from a heart attack at seventy three and my father at eighty.', 1329016709298, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112148, 'user3', '00fea110-b2e7-42e7-8837-1cf876404b2b', 'I''m so sorry to hear that.', 1329016709667, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112149, 'user3', 'cf3defbf-bac0-445f-bd8c-3793ec979485', 'I am going write you a prescription for a stimulant. It is called Cylert.', 1203506161797, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112150, 'user2', '23403291-b559-4adf-a4f0-1b2aff2d626d', 'Are you married?', 1441303302565, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112151, 'user1', '23403291-b559-4adf-a4f0-1b2aff2d626d', 'Yes. I have been married for twenty two years.', 1441303305760, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112152, 'user2', '23403291-b559-4adf-a4f0-1b2aff2d626d', 'Are you working?', 1441303307351, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112153, 'user1', '23403291-b559-4adf-a4f0-1b2aff2d626d', 'No. I am unemployed. I have not completed my collage degree yet. I have been in school for the last two years.', 1441303309891, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112154, 'user2', '23403291-b559-4adf-a4f0-1b2aff2d626d', 'Keep at it.', 1441303315706, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112155, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'Nurse, do you have a report on my patient?', 1077655379345, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112156, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'How are her symptoms now?', 1077655396614, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112157, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'Oh, no. Did she get chemotherapy?', 1077655388272, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112158, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'I see. Does she have any imaging done?', 1077655402856, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112159, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'She does. A C T scan was done to check for metastasis.', 1077655407248, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112160, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'Thank you, Nurse. I''ll go see her now.', 1077655404639, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112161, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'No problem.', 1077655432141, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112162, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'Hello, ma''am. What is the reason for your visit today?', 1077655407312, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112163, 'user1', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'I wanted to see if I could get some treatment for my pain.', 1077655418593, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112164, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'What kind of pain are you having?', 1077655449392, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112165, 'user1', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'I feel like it''s a burning feeling? I don''t know. I can feel it one spot and then it spreads down.', 1077655443650, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112166, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'I see. Where do you feel the pain?', 1077655462359, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112167, 'user1', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'I feel it mostly on my lower right side of my back.', 1077655468658, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112168, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'Do you feel it anywhere else?', 1077655408435, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112169, 'user1', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'The back of my right leg and knee.', 1077655430264, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112170, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'Would you said the pain radiates down from your back to your knee?', 1077655478581, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112171, 'user1', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'That''s it. Radiating. I forgot the word.', 1077655424296, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112172, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'No problem. On a scale from zero to ten, with zero being no pain and ten being the worst pain of your life, how would you rate your back and leg?', 1077655427800, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112173, 'user1', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'They''re both a ten.', 1077655486131, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112174, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'Oh, wow. Do you feel pain anywhere else?', 1077655459041, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112175, 'user1', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'Yes. Could you check my feet?', 1077655480445, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112176, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'Let me check them. I''ll feel around your left foot. Let me know what you feel.', 1077655464623, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112177, 'user1', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'I feel like the bottom is numb. Ouch. It also feels sharp at times too.', 1077655428901, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112178, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'I see. The nurse stated here that you had some pain spreading to your mid back too. Let me feel it really quick. Let me know how that feels.', 1077655426640, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112179, 'user1', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'Ouch! It hurts a lot. I feel a sharp and dull pain. Most of the time, it''s just aching.', 1077655445274, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112180, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'I see. When do you feel like the pain in your body gets the worst?', 1077655418030, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112181, 'user1', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'I''d say when I''m sitting in a car for a long time.', 1077655410348, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112182, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'So, just sitting for long periods of time?', 1077655432120, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112183, 'user1', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'Yeah. When I stand and walk, too.', 1077655552722, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112184, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'Have you ever taken anything for the pain?', 1077655440800, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112185, 'user1', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'I am on a load of narcotics for the pain.', 1077655505954, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112186, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'She''s had chemotherapy and radiation treatments multiple times. She can''t remember how many times she had those treatments because she lost track. She also said she finished a series of ten radiation treatments for pain relief.', 1077655395732, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112187, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'I do. She has a two year history of small cell lung cancer, which spread to both femurs, lower lumbar spine, and pelvis.', 1077655383774, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112188, 'user2', 'c06820b1-5f15-4791-81ab-eb70c73544e4', 'She''s currently having severe pain.', 1077655404848, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112189, 'user2', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'Any fever, chills or rigors?', 1093958837038, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112190, 'user1', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'No.', 1093958840383, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112191, 'user1', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'No.', 1093958847887, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112192, 'user2', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'Any stomach discomfort?', 1093958869385, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112193, 'user1', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'No.', 1093958860554, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112194, 'user2', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'Did you observe blood in your stool or in vomit?', 1093958869983, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112195, 'user1', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'No, nothing like that.', 1093958873953, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112196, 'user2', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'Okay, good. Did you notice any increase in your urine frequency or urgency?', 1093958855110, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112197, 'user1', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'No.', 1093958867808, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112198, 'user2', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'Do you feel any muscle weakness or tiredness?', 1093958850942, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112199, 'user1', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'No, nothing of that sort.', 1093958856070, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112200, 'user2', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'Any known history of arthritis?', 1093958877587, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112201, 'user1', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'Nope.', 1093958874412, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112202, 'user2', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'And no fever due to any fungal infection or anything, right? Like valley fever?', 1093958864404, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112203, 'user1', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'No, nothing of that sort.', 1093958932750, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112204, 'user2', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'Any history of pneumonia?', 1093958935696, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112205, 'user1', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'No.', 1093958868078, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112206, 'user2', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'And I am looking at your chart, so no history of stroke, C V A, or any seizure disorder.', 1093958916570, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112207, 'user1', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'That''s correct.', 1093958939726, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112208, 'user2', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'No thyroid or hormone related problem?', 1093958911214, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112209, 'user1', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'No.', 1093958962892, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112210, 'user2', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'And you do not have any blood disorders, right?', 1093958875277, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112211, 'user1', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'That is right.', 1093958942262, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112212, 'user1', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'No.', 1093958852157, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112213, 'user2', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'Did you experience any shortness of breath?', 1093958851198, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112214, 'user2', '1b0733b6-b70d-47f2-8da3-df8e31075f35', 'Any blurring of vision or history of glaucoma or cataract?', 1093958847154, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112215, 'user3', '2cff772f-51d3-4b83-88c2-ae8390e8a118', 'Have you experienced any diarrhea?', 1120620143971, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112216, 'user1', '2cff772f-51d3-4b83-88c2-ae8390e8a118', 'Yes. I have been having diarrhea. When I think about it, it started happening around the same time that the mouth sores started. I didn''t have any diarrhea today though.', 1120620149145, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112217, 'user1', '2cff772f-51d3-4b83-88c2-ae8390e8a118', 'No.', 1120620173831, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112218, 'user3', '2cff772f-51d3-4b83-88c2-ae8390e8a118', 'Even though you have been taking the medications without any issue, for about ten years, the methotrexate may be the cause of the mouth sores and the inflammation in the small intestines. These are both common side effects from the use of methotrexate. I am not as familiar with NSAID''s causing mouth sores. Aspirin use can cause gastrointestinal upset. I think the most likely cause of the sores is the methotrexate not the use of Aspirin.', 1120620166927, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112219, 'user3', '2cff772f-51d3-4b83-88c2-ae8390e8a118', 'Have you noticed any blood in your bowel movements?', 1120620166944, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112220, 'user3', '2cff772f-51d3-4b83-88c2-ae8390e8a118', 'Have you experienced any episodes of nausea or vomiting?', 1120620153902, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112221, 'user1', '2cff772f-51d3-4b83-88c2-ae8390e8a118', 'No.', 1120620157427, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112222, 'user2', '32968d63-e420-452b-a436-5463022be3ea', 'Are you on insulin?', 1255630218070, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112223, 'user1', '32968d63-e420-452b-a436-5463022be3ea', 'Yes.', 1255630223856, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112224, 'user1', '32968d63-e420-452b-a436-5463022be3ea', 'Yes I take that.', 1255630224206, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112225, 'user2', '32968d63-e420-452b-a436-5463022be3ea', 'Are you on lipitor?', 1255630233996, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112226, 'user1', '32968d63-e420-452b-a436-5463022be3ea', 'Yes.', 1255630250198, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112227, 'user2', '32968d63-e420-452b-a436-5463022be3ea', 'Are you on metformin as well?', 1255630227470, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112228, 'user1', '32968d63-e420-452b-a436-5463022be3ea', 'Yes.', 1255630226236, 3);
