INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112230, 'user2', 'dd619907-3842-4806-b07e-65f4bff0a5b2', 'What was he given in the E R?', 1072370776031, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112231, 'user2', 'dd619907-3842-4806-b07e-65f4bff0a5b2', 'Epi one M G, zero point three M L subcutaneously along with fifty M G of Benadryl intramuscularly. In about fifteen to twenty minutes, he reported his itching had improved. The rash itself faded a little bit and he began to feel a lot more comfortable.', 1072370777396, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112232, 'user2', '8e175564-2778-4002-b7b2-59c3468024f6', 'Hello, how are you?', 1201697990361, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112233, 'user1', '8e175564-2778-4002-b7b2-59c3468024f6', 'I am good, Doctor.', 1201697993636, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112234, 'user2', '8e175564-2778-4002-b7b2-59c3468024f6', 'So, what brings you here today?', 1201697999581, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112235, 'user2', '8e175564-2778-4002-b7b2-59c3468024f6', 'So, let me start by getting your medical history.', 1201698004894, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112236, 'user1', '8e175564-2778-4002-b7b2-59c3468024f6', 'Sure, I had skin cancer which was treated by removal of that part.', 1201698004737, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112237, 'user2', '8e175564-2778-4002-b7b2-59c3468024f6', 'Okay.', 1201698023593, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112238, 'user1', '8e175564-2778-4002-b7b2-59c3468024f6', 'Other than that, I have anemia and an acid reflux problem. I also have history of C O P D.', 1201698010668, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112239, 'user2', '8e175564-2778-4002-b7b2-59c3468024f6', 'I see.', 1201698035976, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112240, 'user1', '8e175564-2778-4002-b7b2-59c3468024f6', 'I also suffer from sciatica which was caused mainly due to my arthritis.', 1201698046833, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112241, 'user2', '8e175564-2778-4002-b7b2-59c3468024f6', 'Alright.', 1201698043238, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112242, 'user1', '8e175564-2778-4002-b7b2-59c3468024f6', 'Thank you.', 1201698000205, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112243, 'user1', '8e175564-2778-4002-b7b2-59c3468024f6', 'Well, I have many medical issues and I see Doctor X for them, but I wanted a second opinion, so he referred me here.', 1201698001793, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112244, 'user2', '8e175564-2778-4002-b7b2-59c3468024f6', 'Yeah, he is a good man! Don''t worry we will take care of you.', 1201698009302, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112245, 'user2', 'cecdc1a6-55c5-4d43-8a85-f57ab404287c', 'Welcome back to Sample Clinic, Mister Sample.', 1164672032333, 0);
