INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112248, 'user2', 'cecdc1a6-55c5-4d43-8a85-f57ab404287c', 'When is the pain the worst?', 1164672039403, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112249, 'user1', 'cecdc1a6-55c5-4d43-8a85-f57ab404287c', 'Honestly, it starts with the first step first thing in the morning.', 1164672073749, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112250, 'user2', 'cecdc1a6-55c5-4d43-8a85-f57ab404287c', 'Does it get worse throughout the day?', 1164672044890, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112251, 'user1', 'cecdc1a6-55c5-4d43-8a85-f57ab404287c', 'Yes, it gets worse all day with activities.', 1164672079611, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112252, 'user2', 'cecdc1a6-55c5-4d43-8a85-f57ab404287c', 'What treatments have you had for this?', 1164672058452, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112253, 'user1', 'cecdc1a6-55c5-4d43-8a85-f57ab404287c', 'Well, nothing to date.', 1164672094078, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112254, 'user2', 'cecdc1a6-55c5-4d43-8a85-f57ab404287c', 'Where is your heel pain?', 1164672061536, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112255, 'user1', 'cecdc1a6-55c5-4d43-8a85-f57ab404287c', 'It''s on the right heel, then it''s on the inside bottom part of the heel and into the inside of the heel.', 1164672056740, 13);
