INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112275, 'user3', '679f12d2-55f2-4cef-b020-da5bb4bb0b6e', 'Are you working somewhere?', 1137680703850, 8);
