INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112278, 'user3', '679f12d2-55f2-4cef-b020-da5bb4bb0b6e', 'Okay according to my records we have last seen you here in our office on July thirteenth of two thousand and four.', 1137680719238, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112279, 'user1', '679f12d2-55f2-4cef-b020-da5bb4bb0b6e', 'Yeah, I think so.', 1137680739272, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112280, 'user3', '679f12d2-55f2-4cef-b020-da5bb4bb0b6e', 'I have previously treated you with Aristocort cream and Cetaphil cream. I also ask you to increase your moisturizing cream and lotion and asked you to wash your hands in Cetaphil cleansing lotion.', 1137680730765, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112281, 'user1', '679f12d2-55f2-4cef-b020-da5bb4bb0b6e', 'I''ve been doing all that, but now it looks like my eczema is flaring. I have these cracks in my hands and they feel very dry.', 1137680741918, 14);
