INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112283, 'user1', '679f12d2-55f2-4cef-b020-da5bb4bb0b6e', 'No, I was using soap. The Cetaphil cleansing lotion was not working.  I had a lot of pain and burning sensation whenever I tried to use that.', 1137680753125, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112284, 'user3', '679f12d2-55f2-4cef-b020-da5bb4bb0b6e', 'It may be because of the fissures. I mean those cracks in your hands.', 1137680697702, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112285, 'user1', '679f12d2-55f2-4cef-b020-da5bb4bb0b6e', 'I have been wearing gloves as much as I can.', 1137680728326, 18);
