INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112301, 'user2', '1d2bd2f5-0774-4221-b5a4-fc19782411da', 'So, I am looking at your reports, you don''t have anemia or any other blood disorders.', 1722261034953, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112302, 'user1', '1d2bd2f5-0774-4221-b5a4-fc19782411da', 'Well, that''s a relief!', 1722261040502, 1);
