INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112355, 'user3', '7ddf2785-36a0-44c1-b94a-37d257ecd287', 'I remember you had mentioned that one of your family members had bone cancer. Are there any other medical problems that run in your family?', 1150778362440, 0);
