INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112365, 'user3', '6290ec53-46c7-4048-858c-e5d1ed4ea192', 'What''s bringing her in today?', 1465134905596, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112366, 'user1', '6290ec53-46c7-4048-858c-e5d1ed4ea192', 'Oh, doctor. She hasn''t been doing well at all.', 1465134910580, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112367, 'user1', '6290ec53-46c7-4048-858c-e5d1ed4ea192', 'I think she''s actually gotten worse.', 1465134910576, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112368, 'user1', '6290ec53-46c7-4048-858c-e5d1ed4ea192', 'Um, around eight I believe. She also suffers from apnea.', 1465134913883, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112369, 'user3', '6290ec53-46c7-4048-858c-e5d1ed4ea192', 'It looks like she has an upper respiratory infection.', 1465134933842, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112370, 'user1', '6290ec53-46c7-4048-858c-e5d1ed4ea192', 'Is she going to get better?', 1465134944988, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112371, 'user3', '6290ec53-46c7-4048-858c-e5d1ed4ea192', 'Yes, she should feel better once we start treating the infection. But I''m worried it may be pertussis.', 1465134940246, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112372, 'user3', '6290ec53-46c7-4048-858c-e5d1ed4ea192', 'I understand. I''m sorry to hear that she hasn''t been feeling well. Let me see what we can do for her today.', 1465134909480, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112373, 'user1', '6290ec53-46c7-4048-858c-e5d1ed4ea192', 'I haven''t taken her temperature since this morning. It was one hundred and three degrees when she woke up.', 1465134926022, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112374, 'user3', '6290ec53-46c7-4048-858c-e5d1ed4ea192', 'What time did she wake up today?', 1465134929915, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112375, 'user2', '8f6b9566-f4aa-426e-ade5-44bc3aa3bcb3', 'And you''ve had recurring abscesses for the past two years, correct?', 1564821076119, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112376, 'user1', '8f6b9566-f4aa-426e-ade5-44bc3aa3bcb3', 'Unfortunately, yes.', 1564821080908, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112377, 'user1', '8f6b9566-f4aa-426e-ade5-44bc3aa3bcb3', 'Yeah. I''ve gotten about four I and D''s.', 1564821104903, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112378, 'user1', '8f6b9566-f4aa-426e-ade5-44bc3aa3bcb3', 'Um in the public area and my thighs.', 1564821087655, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112379, 'user2', '8f6b9566-f4aa-426e-ade5-44bc3aa3bcb3', 'Have you ever needed to get an abscess drained?', 1564821091527, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112380, 'user2', '8f6b9566-f4aa-426e-ade5-44bc3aa3bcb3', 'Where have they been located?', 1564821080622, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112381, 'user2', '5f5f4cd9-3680-468f-b9ee-f337a2beaf9c', 'How''s your overall health?', 1059771549250, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112382, 'user1', '5f5f4cd9-3680-468f-b9ee-f337a2beaf9c', 'Fine, I guess. I''m being treated for I B S by my G I. Last time I was in, they told me that my white blood cell levels aren''t where they were supposed to be.', 1059771551396, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112383, 'user3', '0fc1a7e5-4b2a-4ae6-aef9-386336493705', 'Do you have any family history of chronic illnesses that I should know about?', 1158722280603, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112384, 'user1', '0fc1a7e5-4b2a-4ae6-aef9-386336493705', 'What do you mean by that?', 1158722283337, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112385, 'user3', '0fc1a7e5-4b2a-4ae6-aef9-386336493705', 'Well, it could be anything from depression, to arthritis, to cancer.', 1158722285024, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112386, 'user1', '0fc1a7e5-4b2a-4ae6-aef9-386336493705', 'Oh yeah, my mom has arthritis.', 1158722290440, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112387, 'user2', '30df9ca3-ab12-4431-9b44-0abe05e4cf37', 'How are you moving around? Are you able to perform your day to day activities?', 1633500716384, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112388, 'user2', '30df9ca3-ab12-4431-9b44-0abe05e4cf37', 'Do not overstress yourself.', 1633500722641, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112389, 'user1', '30df9ca3-ab12-4431-9b44-0abe05e4cf37', 'Okay I can do that.', 1633500737592, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112390, 'user1', '30df9ca3-ab12-4431-9b44-0abe05e4cf37', 'Okay.', 1633500723783, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112391, 'user1', '30df9ca3-ab12-4431-9b44-0abe05e4cf37', 'Little bit, not so much.', 1633500718802, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112392, 'user2', '30df9ca3-ab12-4431-9b44-0abe05e4cf37', 'So just listen to your body and go around as much as you can.', 1633500720535, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112393, 'user2', 'c646cbe7-3d49-4585-a940-08bd91333659', 'Are you allergic to anything?', 1077749105727, 0);
