INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112396, 'user1', 'c646cbe7-3d49-4585-a940-08bd91333659', 'Yeah.', 1077749115488, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112397, 'user2', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'Remind me, how did he hurt himself?', 1172480788543, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112398, 'user1', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'He was riding quads on October tenth two thousand seven when he got thrown off.', 1172480792643, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112399, 'user1', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'He writes with his right hand.', 1172480801613, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112400, 'user2', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'Okay. That fracture appears to have healed very well; kids generally heal pretty well. How does it feel today?', 1172480819305, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112401, 'user1', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'Yes, he''s only ten. He''s been pretty stiff, so he''s been going to P T, and using his Dynasplint.', 1172480810850, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112402, 'user2', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'That''s good that he is already in P T. His left elbow fracture is healed, so we should do another surgery in order to remove that hardware. That may help decrease some of the irritation with elbow extension. He looks neurologically intact in terms of movement and reflexed in his wrist and hand.', 1172480817901, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112403, 'user1', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'Yes, I agree. What is the risk of infection of this surgery?', 1172480815364, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112404, 'user2', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'Historically, the risk of infection is less than one percent.', 1172480808993, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112405, 'user1', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'Oh, wow, that''s low, how is that possible?', 1172480840702, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112406, 'user2', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'We''ll use prophylactic antibiotics, this controls for infection, and helps keep everything clean. Other Risks include bleeding, changes in sensation and motion of the extremities, failure to remove hardware, failure to relieve pain, and continued postoperative stiffness.', 1172480847313, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112407, 'user2', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'Yes, and we did O R I F on his fracture dislocation of the left elbow.', 1172480792816, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112408, 'user2', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'Yes, we''ll use anesthesia, he won''t feel a thing.', 1172480845741, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112409, 'user1', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'Will this fix his pain, for sure?', 1172480862971, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112410, 'user2', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'I can''t guarantee it, he may still be in some pain.', 1172480856604, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112411, 'user1', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'Okay, what about you, dear? What do you think?', 1172480884070, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112412, 'user1', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'Yeah, I think we should do it, boys should be playing sports with their friends.', 1172480878112, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112413, 'user2', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'Which hand does he write with?', 1172480805109, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112414, 'user1', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'Wow, that''s great, will be he asleep the entire time?', 1172480851216, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112415, 'user1', 'c22e5981-d822-4a73-8a7a-7473ae10e5ee', 'Yes, he also fractured the neck of his right glenoid, um, if I remember correctly.', 1172480798703, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112416, 'user2', 'fd26213d-2c0d-4a4b-8d2c-7ba8b39f87d4', 'Since you have a family history of coronary heart disease, let me check you for its risk factors.', 1572179071757, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112417, 'user2', 'fd26213d-2c0d-4a4b-8d2c-7ba8b39f87d4', 'How about smoking, do you smoke?', 1572179079658, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112418, 'user1', 'fd26213d-2c0d-4a4b-8d2c-7ba8b39f87d4', 'No, I don''t smoke.', 1572179085613, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112419, 'user2', 'fd26213d-2c0d-4a4b-8d2c-7ba8b39f87d4', 'And in the past, did any other Doctor mention that you might have sign or symptom indicating that you may have coronary artery disease?', 1572179080672, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112420, 'user1', 'fd26213d-2c0d-4a4b-8d2c-7ba8b39f87d4', 'No.', 1572179086002, 7);
