INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112422, 'user2', 'fd26213d-2c0d-4a4b-8d2c-7ba8b39f87d4', 'Any history of high blood pressure or diabetes?', 1572179076614, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112423, 'user1', 'fd26213d-2c0d-4a4b-8d2c-7ba8b39f87d4', 'No.', 1572179083504, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112424, 'user1', 'fd26213d-2c0d-4a4b-8d2c-7ba8b39f87d4', 'Yeah, my father had it.', 1572179075738, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112425, 'user2', '60a8ee92-eac2-44ed-a8a6-7db2b3edcc30', 'Who all are there in your family?', 1423280515626, 0);
