INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112454, 'user2', '80344993-c2c5-4d2b-878d-43ece8cf91d1', 'So, let''s see here. You don''t recall anyone in your family having a history of neuromuscular diseases, correct?', 1219199229042, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112455, 'user1', '80344993-c2c5-4d2b-878d-43ece8cf91d1', 'No, no one I can think of.', 1219199232140, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112456, 'user1', '80344993-c2c5-4d2b-878d-43ece8cf91d1', 'No, at least no one that I know of.', 1219199254588, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112457, 'user2', '80344993-c2c5-4d2b-878d-43ece8cf91d1', 'And you said that your aunt or sister has type two diabetes?', 1219199237123, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112458, 'user1', '80344993-c2c5-4d2b-878d-43ece8cf91d1', 'My aunt. She''s had it for some time now.', 1219199270286, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112459, 'user2', '80344993-c2c5-4d2b-878d-43ece8cf91d1', 'Do you know of anyone who has had foot deformities or neuropathy in their arms or legs?', 1219199234690, 2);
