INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112461, 'user2', '80344993-c2c5-4d2b-878d-43ece8cf91d1', 'Great. Does anyone in your immediate family have a high arch?', 1219199238998, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112462, 'user2', 'd637f715-4710-4aa2-8b20-1c9d545f3537', 'So, what I feel is you might have short term memory loss due to high stress, but I also feel it''s probably due to your current situation. The other impression I have is that you have anxiety issues and again it''s stress related.', 1574635757171, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112463, 'user1', 'd637f715-4710-4aa2-8b20-1c9d545f3537', 'Yeah, I do have anxiety issues.', 1574635762593, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112464, 'user3', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Who''s my patient today?', 1230093670075, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112465, 'user3', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Has he changed his diet?', 1230093687351, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112466, 'user1', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Yes, he did when he got a letter saying that his fat levels were high in the blood.', 1230093693785, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112467, 'user3', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'What kinds of foods did he eliminate?', 1230093705223, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112468, 'user1', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Oh, you know, all of the fun ones. Like cappuccino, quiche, crescents, candy, vending machines, all of that stuff.', 1230093686814, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112469, 'user3', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Do you take your lunch to work?', 1230093695056, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112470, 'user1', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Yes, I do about three or four times a week instead of eating out so much.', 1230093714347, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112471, 'user3', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Are you exercising right now?', 1230093689329, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112472, 'user1', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Yes, I do about six or seven days a week.', 1230093688315, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112473, 'user3', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'What kind do you like to do?', 1230093683451, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112474, 'user1', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Well, I do just about everything. I swim, I bike, run and then I lift weights.', 1230093734506, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112475, 'user3', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'How long do you workout per day?', 1230093734588, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112476, 'user1', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Usually, it''s about one and a half to two and a half hours every day.', 1230093721401, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112477, 'user3', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Good, are you training for anything specific?', 1230093764587, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112478, 'user1', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Actually, yes I''m going to do a triathlon.', 1230093744499, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112479, 'user3', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Can I assume you''re losing weight?', 1230093698209, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112480, 'user1', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Yes, I am.', 1230093732624, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112481, 'user3', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'What seems to be the problem today?', 1230093677290, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112482, 'user1', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Well, he''s a vegetarian but he has high cholesterol and he''s on a medication to control it.', 1230093685825, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112483, 'user1', 'e24f78b6-0f66-4596-906c-264f63fdf5db', 'Today, it''s my brother.', 1230093675623, 1);
