INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112489, 'user3', '23d70de0-1a7c-4678-8e92-474c386eba49', 'Out of ten, ten being the worst pain imaginable, how would you rate your pain today?', 1139716827170, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112490, 'user1', '23d70de0-1a7c-4678-8e92-474c386eba49', 'Today it''s about a six or seven, and it''s usually pretty constant there.', 1139716829593, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112491, 'user3', '23d70de0-1a7c-4678-8e92-474c386eba49', 'Does the pain change with the weather?', 1139716830868, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112492, 'user3', '23d70de0-1a7c-4678-8e92-474c386eba49', 'Out of ten, how would you rate your pain at night?', 1139716846987, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112493, 'user1', '23d70de0-1a7c-4678-8e92-474c386eba49', 'Oh, it''s ten out of ten.', 1139716842025, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112494, 'user3', '23d70de0-1a7c-4678-8e92-474c386eba49', 'Does the pain wake you up at night?', 1139716860698, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112495, 'user1', '23d70de0-1a7c-4678-8e92-474c386eba49', 'If I sleep at all. I''m not sleeping well at all, and when I do it''s for less than an hour at a time.', 1139716843356, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112496, 'user3', '23d70de0-1a7c-4678-8e92-474c386eba49', 'Are there any activities that really aggravate the pain?', 1139716841875, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112497, 'user1', '23d70de0-1a7c-4678-8e92-474c386eba49', 'Yes, if I sit for more than about twenty minutes, or if I lay flat on my back.', 1139716858331, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112498, 'user3', '23d70de0-1a7c-4678-8e92-474c386eba49', 'Does anything alleviate the pain?', 1139716896957, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112499, 'user1', '23d70de0-1a7c-4678-8e92-474c386eba49', 'Laying on my side helps a little.', 1139716891968, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112500, 'user1', '23d70de0-1a7c-4678-8e92-474c386eba49', 'Yes, when it''s cold out it turns to ten out of ten. It''s better when it''s warm out.', 1139716833480, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112501, 'user3', '23d70de0-1a7c-4678-8e92-474c386eba49', 'Does the pain change throughout the course of the day?', 1139716848152, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112502, 'user1', '23d70de0-1a7c-4678-8e92-474c386eba49', 'Yes, it progressively gets worse and worse as the day goes on, but I also have a pretty hard time getting out of bed in the morning, too.', 1139716845238, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112503, 'user1', '3f438cd1-5f64-4fad-91e0-976e7f4e8dbf', 'For as long as I have been taking care of her, she has had this tracheal tube and she barely speaks. She mostly signals if she needs anything.', 1300949205325, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112504, 'user2', '3f438cd1-5f64-4fad-91e0-976e7f4e8dbf', 'Okay. It''s mentioned in her report that she has a history of smoking.', 1300949206866, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112505, 'user1', '3f438cd1-5f64-4fad-91e0-976e7f4e8dbf', 'She is nodding yes.', 1300949208473, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112506, 'user2', '3f438cd1-5f64-4fad-91e0-976e7f4e8dbf', 'Well, it''s alright. I think it''s going to be difficult taking any past medical information from her.', 1300949222360, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112507, 'user2', '21183582-8fc5-426d-a7d2-c37ee5fae456', 'Have you been taking anything for high blood pressure?', 1089215679187, 0);
