INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112511, 'user3', '1ddf1b4f-36e1-4e18-a82b-f637ecb59ef3', 'Good afternoon, ma''am. Before we begin, may I ask how old you are?', 1578508286033, 0);
