INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112515, 'user1', '1ddf1b4f-36e1-4e18-a82b-f637ecb59ef3', 'Well, we live by ourselves now that our children are gone, but I''m used to cooking really large portions.', 1578508294787, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112516, 'user3', '1ddf1b4f-36e1-4e18-a82b-f637ecb59ef3', 'Are you struggling to make food for just two people?', 1578508315759, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112517, 'user1', '1ddf1b4f-36e1-4e18-a82b-f637ecb59ef3', 'Yes, that''s a good way to put it. I''d like to just make less food, that way we''re not so tempted to eat so much.', 1578508299833, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112518, 'user3', '1ddf1b4f-36e1-4e18-a82b-f637ecb59ef3', 'I understand, are you busy, do you work?', 1578508327382, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112519, 'user1', '1ddf1b4f-36e1-4e18-a82b-f637ecb59ef3', 'Well, I start a new job this week.', 1578508321112, 11);
