INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112521, 'user1', '1ddf1b4f-36e1-4e18-a82b-f637ecb59ef3', 'Well, I need some support for dietary recommendations for healthy eating for my husband and me.', 1578508295810, 3);
