INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112664, 'user1', '853eed6d-8535-468e-9f64-313b211109ef', 'My head has been hurting a lot.', 1256122801077, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112665, 'user1', '853eed6d-8535-468e-9f64-313b211109ef', 'I''m ready for less pain. Let''s go.', 1256122820473, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112666, 'user2', '853eed6d-8535-468e-9f64-313b211109ef', 'Sorry, Doctor. I was looking for you. I reviewed his history with him, and nothing has changed.', 1256122799997, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112667, 'user2', '853eed6d-8535-468e-9f64-313b211109ef', 'Perfect. Let''s do some tests to see why your head has been hurting.', 1256122804374, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112668, 'user2', '853eed6d-8535-468e-9f64-313b211109ef', 'I see. Did the nurse come in and ask you questions about past medical history?', 1256122800069, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112669, 'user2', '0b7e3e28-7d29-4aac-be9d-daa5e69b3dc8', 'We''re going to check around your knee now.', 1558958970153, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112670, 'user2', '0b7e3e28-7d29-4aac-be9d-daa5e69b3dc8', 'Looks like your deep tendon reflexes are the same on both legs. Sensation seems great and intact.', 1558958972378, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112671, 'user1', '0b7e3e28-7d29-4aac-be9d-daa5e69b3dc8', 'Okay, sounds good.', 1558958973904, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112672, 'user2', 'ee4eebf1-7485-4a32-9e1c-70578126825d', 'Can you tell me something about your family? Any illnesses in family?', 1720138025336, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112673, 'user1', 'ee4eebf1-7485-4a32-9e1c-70578126825d', 'My dad''s mom has diabetes and hypertension and my dad''s dad had emphysema and he was a smoker.', 1720138028611, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112674, 'user2', 'ee4eebf1-7485-4a32-9e1c-70578126825d', 'Okay.', 1720138032376, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112675, 'user2', 'ee4eebf1-7485-4a32-9e1c-70578126825d', 'Okay. That''s great. No illnesses for small children?', 1720138041850, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112676, 'user1', 'ee4eebf1-7485-4a32-9e1c-70578126825d', 'No.', 1720138036413, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112677, 'user1', 'ee4eebf1-7485-4a32-9e1c-70578126825d', 'No, there isn''t.', 1720138037684, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112678, 'user1', 'ee4eebf1-7485-4a32-9e1c-70578126825d', 'Yeah.', 1720138030003, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112679, 'user2', 'ee4eebf1-7485-4a32-9e1c-70578126825d', 'Is there any history of death of child who was less than a year maybe?', 1720138048866, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112680, 'user3', '02970580-333b-4406-bdc4-ba5e5997798c', 'Alright, I am looking at your urine report and it confirms what I was suspecting. You have a urinary tract infection.', 1412873815489, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112681, 'user1', '02970580-333b-4406-bdc4-ba5e5997798c', 'I kind of knew it was a U T I. I have had it before, but nothing this painful and severe. I feel like I am going to die!', 1412873819732, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112682, 'user1', '02970580-333b-4406-bdc4-ba5e5997798c', 'Yes!', 1412873824385, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112683, 'user3', '02970580-333b-4406-bdc4-ba5e5997798c', 'How bout diet?', 1412873841503, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112684, 'user1', '02970580-333b-4406-bdc4-ba5e5997798c', 'Yeah, sometimes I don''t care about my diet.', 1412873843060, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112685, 'user3', '02970580-333b-4406-bdc4-ba5e5997798c', 'Well, you must watch your diet, you can''t just be careless. I am going to change your diabetes medication. And let''s start you on the antibiotic that should give you relief. Also stay hydrated drink plenty of fluids it will help you flush the infection out.', 1412873839271, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112686, 'user1', '02970580-333b-4406-bdc4-ba5e5997798c', 'Alright, thank you!', 1412873867796, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112687, 'user3', '02970580-333b-4406-bdc4-ba5e5997798c', 'Take care.', 1412873859886, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112688, 'user3', '02970580-333b-4406-bdc4-ba5e5997798c', 'I am afraid I don''t have better news for you, but your diabetes is out of control. It''s way too high and you must be really careful. Are you taking your medicines?', 1412873821338, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112689, 'user3', '02970580-333b-4406-bdc4-ba5e5997798c', 'Oh yes, it is because you got something called as acute cystitis and its usually very painful and can cause some serious complications.', 1412873822776, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112690, 'user1', '02970580-333b-4406-bdc4-ba5e5997798c', 'Well, is it because of my diabetes?', 1412873831189, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112691, 'user3', '34329144-abc9-4d7b-b6a5-34c06e2fa330', 'Good morning, ma''am.', 1185225380708, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112692, 'user1', '34329144-abc9-4d7b-b6a5-34c06e2fa330', 'Good morning, doctor.', 1185225386000, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112693, 'user3', '34329144-abc9-4d7b-b6a5-34c06e2fa330', 'Before we begin, I just have a few questions. Do you remember what illnesses you had as a child?', 1185225386710, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112694, 'user1', '34329144-abc9-4d7b-b6a5-34c06e2fa330', 'Yes, I got a few. I had strep throat, mumps, and, um, chickenpox growing up.', 1185225385410, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112695, 'user2', 'f094d392-a3bd-4d0f-8fca-ad989a557011', 'Hi there! I am Doctor Sherman.', 1473872219112, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112696, 'user2', 'f094d392-a3bd-4d0f-8fca-ad989a557011', 'Do not be nervous. We will start with discussing the symptoms you have been experiencing, a physical exam and then we will get a urine sample if you are able.', 1473872223151, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112697, 'user1', 'f094d392-a3bd-4d0f-8fca-ad989a557011', 'Okay.', 1473872228851, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112698, 'user1', 'f094d392-a3bd-4d0f-8fca-ad989a557011', 'Yes. I am nervous.', 1473872226078, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112699, 'user1', 'f094d392-a3bd-4d0f-8fca-ad989a557011', 'Hello! It is nice to meet you.', 1473872222648, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112700, 'user2', 'f094d392-a3bd-4d0f-8fca-ad989a557011', 'It looks like your P C P sent you to us for a possible prostate problem.', 1473872230060, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112701, 'user2', '10e89f44-d5b3-4162-a0a3-47fda087b559', 'What are you taking for allergies?', 1181976149980, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112702, 'user1', '10e89f44-d5b3-4162-a0a3-47fda087b559', 'Claritin.', 1181976154686, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112703, 'user2', '10e89f44-d5b3-4162-a0a3-47fda087b559', 'Okay.', 1181976152374, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112704, 'user1', '10e89f44-d5b3-4162-a0a3-47fda087b559', 'For my allergic rhinitis.', 1181976159553, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112705, 'user3', '9a27ca63-64d2-4720-86a8-b4d91a84069d', 'Do you have any known allergies to medication?', 1039951744443, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112706, 'user1', '9a27ca63-64d2-4720-86a8-b4d91a84069d', 'Nope. None that I know of.', 1039951747797, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112707, 'user3', '989be6c5-ce07-42d1-a884-9537d86887a7', 'What is your family medical history?', 1504708661149, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112708, 'user3', '989be6c5-ce07-42d1-a884-9537d86887a7', 'Do you know of any other major health conditions in your family?', 1504708681954, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112709, 'user1', '989be6c5-ce07-42d1-a884-9537d86887a7', 'No. None that I know of. Everyone is relatively healthy.', 1504708689802, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112710, 'user3', '989be6c5-ce07-42d1-a884-9537d86887a7', 'That''s good.', 1504708694214, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112711, 'user1', '989be6c5-ce07-42d1-a884-9537d86887a7', 'My dad had a heart attack and passed away at sixty one.', 1504708663837, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112712, 'user3', '989be6c5-ce07-42d1-a884-9537d86887a7', 'I am so sorry to hear that.', 1504708664173, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112713, 'user1', '989be6c5-ce07-42d1-a884-9537d86887a7', 'Thank you.', 1504708672283, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112714, 'user3', '27684fec-8fea-47bf-9eed-4f31ce17f168', 'Hello, sir how are you feeling today?', 1568885011801, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112715, 'user1', '27684fec-8fea-47bf-9eed-4f31ce17f168', 'I feel terrible. Very sick and I can barely move. I feel so weak.', 1568885016983, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112716, 'user2', '24e53662-368a-4742-9533-f160fb151893', 'So, we looked at your previous blood work results, now let me see what these reports say from today''s C B C exam.', 1734893841907, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112717, 'user1', '24e53662-368a-4742-9533-f160fb151893', 'Okay.', 1734893864221, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112718, 'user2', '24e53662-368a-4742-9533-f160fb151893', 'Okay so your hemoglobin levels look within range, white counts are thirteen point three, then seven point six lymphocytes and twenty six thousand platelets.', 1734893847548, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112719, 'user2', '24e53662-368a-4742-9533-f160fb151893', 'Okay?', 1734893857201, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112720, 'user1', '24e53662-368a-4742-9533-f160fb151893', 'Sure.', 1734893846724, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112721, 'user3', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'Welcome back.', 1390242633063, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112722, 'user1', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'Thank you.', 1390242635162, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112723, 'user1', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'I still have this dull pain in my upper outer area of my arm.', 1390242654402, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112724, 'user3', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'How long does the pain last?', 1390242647358, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112725, 'user1', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'It was coming and going, but now the pain is more persistent since I last saw you. It is still happening every day.', 1390242667780, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112726, 'user3', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'Remind me again. You are right handed. Right?', 1390242654094, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112727, 'user1', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'Yeah. It makes is hard to do things with the persistent pain.', 1390242684854, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112728, 'user3', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'I bet it does. Are you experiencing any numbness or tingling sensation in your arm or hand?', 1390242646396, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112729, 'user1', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'No, but I have had this achy sensation in my hand radiating down to my fingers.', 1390242686647, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112730, 'user3', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'Do you have a history of any other neck or shoulder injuries?', 1390242655102, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112731, 'user1', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'It is not from a specific injury but I have had this neck pain for thirty years.', 1390242690061, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112732, 'user3', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'Did you see anyone for the neck pain?', 1390242686074, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112733, 'user1', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'Yes. I saw someone for it in two thousand and six, and then I developed this ear pain. They could not figure out what was going on so eventually I was sent to have an M R I of my neck and upper spine, which showed some degenerative changes. Then I was referred to Doctor X who was treating me for neck pain.  He gave me steroid injections.', 1390242648517, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112734, 'user3', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'Are you still seeing Doctor X for the epidural injections?', 1390242727196, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112735, 'user1', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'Yes. I have been seeing him since two thousand and seven.', 1390242689515, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112736, 'user3', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'How old are you?', 1390242676019, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112737, 'user1', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'I am fifty eight.', 1390242657052, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112738, 'user3', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'Are you experiencing any symptoms from receiving the injections?', 1390242695689, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112739, 'user1', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'Those are for neck pain. My arm pain recent. I have been having the injections for a while now, without any trouble.', 1390242748493, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112740, 'user3', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'What medications have you been taking for the pain?', 1390242685561, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112741, 'user1', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'There are a few of them that I take. I gave the list to the nurse.', 1390242709005, 23);
