INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112743, 'user1', 'af7bbe2e-1a61-47c4-9da0-0959901a62a1', 'I also have taken several Medrol packs. They make my blood sugars to increase so I try not to take it.', 1390242777911, 25);
