INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112778, 'user3', '5f7235fd-9132-4bc9-9b42-9d04c1e5e7c3', 'Okay. The results showed clinoid masses. This explains that problems that you have been having with your right side, your balancing problems, and the visual disturbances. With only the M R I I cannot tell if the masses are malignant or not.', 1715017985672, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112779, 'user1', '5f7235fd-9132-4bc9-9b42-9d04c1e5e7c3', 'So, are the masses cancer?', 1715018013270, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112780, 'user3', '5f7235fd-9132-4bc9-9b42-9d04c1e5e7c3', 'I don''t know yet. I will have to run some more tests and potently have to do a biopsy.', 1715018016221, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112781, 'user1', '5f7235fd-9132-4bc9-9b42-9d04c1e5e7c3', 'Okay.', 1715017967572, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112782, 'user3', '5f7235fd-9132-4bc9-9b42-9d04c1e5e7c3', 'What happened?', 1715017937892, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112783, 'user1', '5f7235fd-9132-4bc9-9b42-9d04c1e5e7c3', 'I don''t really know. I have balancing problems. I have been to my P C P for this issue a few days ago. I saw her about a week and a half ago because I had another fall. Maybe around late December since today is January seventh.  I have been having trouble with my right hand. It is like I am clumsy on my right side. I ended up falling because my right hand missed the railing when I grabbed it to head up the stairs.', 1715017949356, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112784, 'user1', '5f7235fd-9132-4bc9-9b42-9d04c1e5e7c3', 'Yes. I did fall.', 1715017937517, 1);
