INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112794, 'user2', 'ada7b5ba-6a93-4a92-8f32-f8ed648a6a78', 'What activities make your surgery worse?', 1463653652854, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112795, 'user1', 'ada7b5ba-6a93-4a92-8f32-f8ed648a6a78', 'I can''t go up and down stairs without a lot of pain, and it hurts when I sit for a long time, like when I drive.', 1463653678585, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112796, 'user2', 'ada7b5ba-6a93-4a92-8f32-f8ed648a6a78', 'Before this pain, how would you describe your activity level?', 1463653665868, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112797, 'user1', 'ada7b5ba-6a93-4a92-8f32-f8ed648a6a78', 'I was very active before all this started.', 1463653665006, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112798, 'user2', 'ada7b5ba-6a93-4a92-8f32-f8ed648a6a78', 'Are you able to do any of your prior activities?', 1463653680697, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112799, 'user1', 'ada7b5ba-6a93-4a92-8f32-f8ed648a6a78', 'Not really, I''m having a lot of problems with stuff around the house, like all the chores and projects I used to be able to do.', 1463653682698, 11);
