INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112818, 'user2', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'How old are you?', 1359369120227, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112819, 'user1', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'I am seventy three.', 1359369122968, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112820, 'user1', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'We noticed it the week prior to Thanksgiving last year in nineteen ninety four. We have a family tradition where we play a game and this time, we were taking her to Vail, Colorado to play "Murder She Wrote" at one of our family gatherings. She was chosen to be the assassin.', 1359369143638, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112821, 'user2', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'Okay.', 1359369150257, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112822, 'user1', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'Kids played a trick with her and they hid a plastic gun, a toy gun in her luggage. As she walked through the security, the alarm went off and like within seconds she was all surrounded, and everyone was like panicked. There was so much panic, they searched her and interrogated her and what not. Eventually she and her family made it to the flight, and she seemed unusually frustrated and disoriented by all that. Previously, if any such incident would have happened in the past, she would just have like chuckled and brushed it off. And we all would have sat together and laughed about it. This time it was different.', 1359369131915, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112823, 'user2', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'I can see why she was frustrated. Anyone can be in such situations.', 1359369136035, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112824, 'user1', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'When we were in Colorado, she seemed slow. She had difficulty reading her lines to her part when we were playing that game. She needed assistance to complete the whole game.', 1359369162259, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112825, 'user1', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'Right.', 1359369136014, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112826, 'user1', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'Nope.', 1359369135123, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112827, 'user2', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'Was there any difficulty with vision? Or any weakness?', 1359369172243, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112828, 'user1', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'Nope. Nothing that we noticed.', 1359369166650, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112829, 'user2', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'How was it after returning from there?', 1359369141528, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112830, 'user1', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'She returned to work. She used to work in a local florist shop. She returned on the Monday following Thanksgiving. And she had difficulty.', 1359369190163, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112831, 'user1', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'I was not able to take on with my usual task of flower arrangements or dealing with the cash at the cash register.', 1359369194619, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112832, 'user1', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'She quit the next day, and she never went back.', 1359369203141, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112833, 'user2', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'How was it after that?', 1359369192119, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112834, 'user2', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'Yeah, I see the working diagnosis of dementia of the Alzheimer''s Type. When did these symptoms increase? Like when did you started noticing them more?', 1359369166646, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112835, 'user1', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'One or two weeks ago, so end of December nineteen ninety four, she got lost in her own home. She was getting more sensitive and started saying that she is becoming a liability for everyone, which is not at all like her. Her walking was affected. She started walking like a bended form and also started veering to the right. She also did not recognize the location of where people were talking to her.', 1359369190166, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112836, 'user1', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'She seemed to be doing fine and stable throughout November and December, and we were visiting a local neurologist as well, who was evaluating her. He did a few blood tests and did uh, M R I of the brain. He gave us all clear. He said there''s nothing there.', 1359369225806, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112837, 'user2', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'Was she slurring?', 1359369134910, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112838, 'user2', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'So, I see the chief complaint is memory loss and cognitive decline. Tell me what exactly happened, and how did you notice the symptoms? Let me document that today is January twelfth of nineteen ninety five.', 1359369127675, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112839, 'user2', '2dc758ea-fa8c-4f86-b0b8-0c86d9f8ff70', 'Are you right handed or left handed?', 1359369127054, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112840, 'user3', '2eb2e1a1-e15d-438d-9ff8-51a1fdbc023f', 'You are not allergic to anything?', 1540595209909, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112841, 'user1', '2eb2e1a1-e15d-438d-9ff8-51a1fdbc023f', 'No, I am not.', 1540595214169, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112842, 'user3', '2eb2e1a1-e15d-438d-9ff8-51a1fdbc023f', 'Any food or other pollen?', 1540595214079, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112843, 'user1', '2eb2e1a1-e15d-438d-9ff8-51a1fdbc023f', 'No, I am not allergic to anything.', 1540595216486, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112844, 'user3', '2eb2e1a1-e15d-438d-9ff8-51a1fdbc023f', 'Great!', 1540595230887, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112845, 'user3', '615218ce-074d-4f62-82d3-d5a9c651e03e', 'April twenty two three we checked your list of medications.', 1092625416192, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112846, 'user3', '615218ce-074d-4f62-82d3-d5a9c651e03e', 'We saw that it lifts up in the morning and evening.', 1092625420445, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112847, 'user1', '615218ce-074d-4f62-82d3-d5a9c651e03e', 'Yeah.', 1092625423385, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112848, 'user3', '615218ce-074d-4f62-82d3-d5a9c651e03e', 'Yeah.', 1092625427171, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112849, 'user2', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'What brings you here today?', 1404584363716, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112850, 'user1', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'I have concerns about his motor development. Many times he seems to have lazy eyes and sometimes I can notice his jaw quivering.', 1404584357306, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112851, 'user2', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'How was your pregnancy?', 1404584375221, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112852, 'user1', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'I had no complications in my pregnancy with him. My labor was very spontaneous, and it was a normal delivery.', 1404584379296, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112853, 'user2', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'Is this the only child?', 1404584364969, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112854, 'user1', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'No, I have two more kids.', 1404584360973, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112855, 'user2', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'How much did he weigh at birth?', 1404584379027, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112856, 'user1', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'He was around eight pounds and ten ounces.', 1404584390882, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112857, 'user2', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'Did you remember his milestones?', 1404584386909, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112858, 'user1', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'Yes, I have all of it written down for all of my three kids and I brought this with me. He sat on his own by seven months. He was able to stand by eleven months and crawled around sixteen months but he was not walking until eighteen months.', 1404584401597, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112859, 'user2', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'What issues are he facing right now?', 1404584405547, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112860, 'user1', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'He falls a lot. He cannot walk properly. He is kind of in toeing on his left. He''s able to feed himself properly. He also throws, um, he picks up the things and throws them. His upper body looks strong.', 1404584411639, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112861, 'user2', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'How about his speech? How many words do you think he knows?', 1404584373556, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112862, 'user1', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'He knows more than twenty words for sure.', 1404584405963, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112863, 'user2', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'Is he able to speak two word phrases?', 1404584407019, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112864, 'user1', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'Yes. He says things like ,”give me,” and, “come here.”', 1404584437877, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112865, 'user2', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'Any other unusual behavior that you noticed? Any seizures or just the quivering movement of the jaw?', 1404584435495, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112866, 'user1', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'He is twenty one months old.', 1404584354358, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112867, 'user2', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'How old is the baby?', 1404584352835, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112868, 'user1', 'e8a28b56-c534-4ef1-8789-b9390456b3a6', 'No, it was only this and we have noticed this since birth. I don''t know if it is related but I did notice that his left eye deviates outside.', 1404584382141, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112869, 'user2', '1cb6c5a1-4fcd-4bfd-b8bf-29d60fb2f47a', 'What brings you back into the clinic today?', 1701593231747, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112870, 'user1', '1cb6c5a1-4fcd-4bfd-b8bf-29d60fb2f47a', 'I have been having some severe bruising. I have been taking Coumadin for three months now. Am I taking to much Coumadin?', 1701593235338, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112871, 'user2', '1cb6c5a1-4fcd-4bfd-b8bf-29d60fb2f47a', 'You are taking a normal start dose. Some people do not metabolize the medication as well as others. I would like to get you tested for hypersensitivity. After we get the test results back, we will be able to adjust your dosage accordingly.', 1701593238667, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112872, 'user1', '1cb6c5a1-4fcd-4bfd-b8bf-29d60fb2f47a', 'Okay.', 1701593243818, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112873, 'user2', '70f9dfdf-0bf7-4115-bda1-9ad20bc561b2', 'Let me examine you. Tell me, did you have any fever or chills, any sweating or that sort of thing?', 1365052618631, 0);
