INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (112876, 'user2', '70f9dfdf-0bf7-4115-bda1-9ad20bc561b2', 'Let me see your legs. They look good I don''t see any pedal edema. Usually that happens due to excess water retention. Any palpitations?', 1365052644682, 6);
