INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113090, 'user1', '2c696db8-b0f9-4feb-b8b5-d35399f4c6e5', 'We just want what is best for him. We want to support him in every possible way. He has only one elder sister. She lives in Texas and she also wants the same for him. Before he started living with us, he has been living in the A B C D places and some were in very bad condition. He was not striving there. That''s why we asked him to move in with us.', 1426462318617, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113091, 'user1', '2c696db8-b0f9-4feb-b8b5-d35399f4c6e5', 'Yes, I''m the mother.', 1426462310256, 3);
