INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113126, 'user1', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'Sounds about right.', 1735223668309, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113127, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'I see she underwent a procedure. What was it, Doctor X?', 1735223666267, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113128, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'She underwent a decompression for L three and L four. Did Doctor Stanley Gertzbein perform this procedure for your back?', 1735223677846, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113129, 'user1', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'He did. He also did surgery on my lower legs.', 1735223667921, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113130, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'Thank you for confirming.', 1735223692364, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113131, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'I see after the surgery, you had some pain in your right L four distribution, correct?', 1735223677789, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113132, 'user1', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'That''s correct.', 1735223659038, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113133, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'Doctor X, did the M R I report of the outside lumbar come in?', 1735223688733, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113134, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'It did. We also have a report of a lumbar C T myelogram, but no films came.', 1735223693641, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113135, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'What does the C T myelogram say?', 1735223722452, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113136, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'It says she has spondylolisthesis and L four and L 5 stenosis with right posterior surgical fusion changes at both levels.', 1735223740041, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113137, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'I see. There are some notes from Doctor Reitman. What does it say?', 1735223695478, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113138, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'It looks like she is being sent for an L four selective nerve root block to rule out if she would be a candidate for a T L I F at L four and L 5.', 1735223730386, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113139, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'I see. Could you review the M R I film as well?', 1735223711993, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113140, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'The M R I reveal a grade two L four anterior spondylolisthesis without major canal stenosis. She does, however, have facet joint disease at this level and dorsal postoperative changes. She also has a foraminal disc protrusion on the right and a severely degenerated disc at L three and L four.', 1735223692507, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113141, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'Thank you for that. So, miss. Where are you feeling pain today?', 1735223784799, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113142, 'user1', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'I feel it in the font of my lower leg and right hip.', 1735223764066, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113143, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'What kind of pain are you feeling?', 1735223698031, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113144, 'user1', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'I told Doctor X about it. He could let you know.', 1735223805215, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113145, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'She claimed she had a burning, shooting, aching, and constant pain in nature.', 1735223773610, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113146, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'I see. Is it worse when you do certain activities?', 1735223778050, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113148, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'Are you able to walk at all?', 1735223704873, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113149, 'user1', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'I can walk around a block before it gets to the point where I get weak.', 1735223796541, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113150, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'When does it feel better?', 1735223712683, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113151, 'user1', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'I feel more comfortable when I''m resting, sitting, sleeping, or getting a massage.', 1735223730127, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113152, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'From a scale of zero to ten, with ten being the worst pain, how would you rate the pain on average?', 1735223723228, 35);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113153, 'user1', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'I''d say like a nine.', 1735223797538, 36);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113156, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'What''s the lowest pain you''ve ever felt?', 1735223699076, 39);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113157, 'user1', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'I think it was a five.', 1735223695511, 40);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113159, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'I did. She denied any bowel or bladder dysfunction, saddle area hypoesthesia, numbness, tingling, weakness or Valsalva related exacerbation.', 1735223792391, 42);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113162, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'It states here you took Tylenol, correct?', 1735223740075, 45);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113164, 'user2', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'Thank you, ma''am.', 1735223653314, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113165, 'user1', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'Sounds good to me.', 1735223648999, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113166, 'user1', '6a7ab18b-8ce7-443d-bfc5-723612d5b2e0', 'I''m seventy six years old. I''m also a resident of A S D F if that matters.', 1735223660504, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113167, 'user1', '5d4030fe-6aad-4dd9-a9bd-6dea1dc77a4f', 'Um, do I have to follow some special or soft diet?', 1679087412453, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113168, 'user1', '5d4030fe-6aad-4dd9-a9bd-6dea1dc77a4f', 'Alright, thank you.', 1679087418917, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113169, 'user1', '5d4030fe-6aad-4dd9-a9bd-6dea1dc77a4f', 'At this age, my diet is very limited. I am going to be eighty-two next month.', 1679087422617, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113170, 'user2', '5d4030fe-6aad-4dd9-a9bd-6dea1dc77a4f', 'Well, I don''t think you need to restrict your diet. You can follow your regular diet.', 1679087425962, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113171, 'user2', '5d4030fe-6aad-4dd9-a9bd-6dea1dc77a4f', 'No, nothing like that. You can have a normal diet. Whatever you like to eat.', 1679087416450, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113172, 'user2', '4ac3732d-9f3f-439a-baf3-af1c228256cc', 'Do migraine headaches run in the family?', 1268102769574, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113173, 'user1', '4ac3732d-9f3f-439a-baf3-af1c228256cc', 'My mother gets migraines and she told me that it runs on her side of the family.', 1268102773414, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113174, 'user2', '4ac3732d-9f3f-439a-baf3-af1c228256cc', 'Any family history of blood clots?', 1268102776781, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113175, 'user1', '4ac3732d-9f3f-439a-baf3-af1c228256cc', 'No.', 1268102778343, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113176, 'user2', 'cc5ba8c5-877b-482c-ac8e-3f40070a077c', 'Are you married?', 1594669278003, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113177, 'user1', 'cc5ba8c5-877b-482c-ac8e-3f40070a077c', 'I was, but my husband died thirty years ago.', 1594669283748, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113178, 'user2', 'cc5ba8c5-877b-482c-ac8e-3f40070a077c', 'Are you working?', 1594669287106, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113179, 'user2', 'cc5ba8c5-877b-482c-ac8e-3f40070a077c', 'How is your living situation now? Who is taking care of you?', 1594669288941, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113180, 'user1', 'cc5ba8c5-877b-482c-ac8e-3f40070a077c', 'My daughters have started taking care of me on a shareable basis.', 1594669304194, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113181, 'user2', 'cc5ba8c5-877b-482c-ac8e-3f40070a077c', 'Do you smoke? Or drink or have ever used any drugs.', 1594669297869, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113182, 'user1', 'cc5ba8c5-877b-482c-ac8e-3f40070a077c', 'Nope.', 1594669310194, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113183, 'user1', 'cc5ba8c5-877b-482c-ac8e-3f40070a077c', 'Nope.', 1594669281529, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113184, 'user2', 'cc5ba8c5-877b-482c-ac8e-3f40070a077c', 'What is your highest degree?', 1594669291715, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113185, 'user1', 'cc5ba8c5-877b-482c-ac8e-3f40070a077c', 'I did high school. I was living alone for fifteen years until December of ninety four.', 1594669299534, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113186, 'user2', '8c3abc68-5ffc-49ca-b53b-69e46c83d545', 'Do you smoke, or have you smoked in the past?', 1539592008479, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113187, 'user2', '8c3abc68-5ffc-49ca-b53b-69e46c83d545', 'Any illicit drug use, such as cocaine, marijuana or heroin?', 1539592028504, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113188, 'user1', '8c3abc68-5ffc-49ca-b53b-69e46c83d545', 'Yeah, I quit two years ago. But before that I used to smoke two packs per day. I first started smoking as a teenager.', 1539592010196, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113189, 'user1', '8c3abc68-5ffc-49ca-b53b-69e46c83d545', 'I used to drink six packs of beer plus two additional drinks a day for many years. Good news is that I''ve been dry for two years now.', 1539592015759, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113190, 'user2', '8c3abc68-5ffc-49ca-b53b-69e46c83d545', 'Do you drink at all?', 1539592012029, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113191, 'user1', '8c3abc68-5ffc-49ca-b53b-69e46c83d545', 'No none of that.', 1539592029409, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113192, 'user2', '9677624f-c6ed-40f7-9f88-48670e71f36c', 'Hello, miss. How are you doing today? It looks like we are evaluating C O P D and emphysema.', 1625266251206, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113193, 'user1', '9677624f-c6ed-40f7-9f88-48670e71f36c', 'Yes, the last time I was seen in Pulmonary Medicine Clinic was March two thousand and four.', 1625266255247, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113194, 'user2', '9677624f-c6ed-40f7-9f88-48670e71f36c', 'It has been quite some time. How are you feeling?', 1625266258042, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113195, 'user2', '9677624f-c6ed-40f7-9f88-48670e71f36c', 'In spite of all of that how are your respiratory issues?', 1625266278041, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113196, 'user1', '9677624f-c6ed-40f7-9f88-48670e71f36c', 'I feel pretty stable. I still have shortness of breath when I do activities, but with my condition I feel like that is something I will have to live with.', 1625266269151, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113197, 'user2', '9677624f-c6ed-40f7-9f88-48670e71f36c', 'Unfortunately, that is the nature of the disease. I am happy to see that the pulmonary disease has not changed significantly since your last visit.', 1625266267528, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113198, 'user1', '9677624f-c6ed-40f7-9f88-48670e71f36c', 'The only thing that seems to have changed is that I have a small cough and produce some mucus.', 1625266291303, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113199, 'user2', '9677624f-c6ed-40f7-9f88-48670e71f36c', 'Okay. Do you have any fever or chills?', 1625266280486, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113200, 'user1', '9677624f-c6ed-40f7-9f88-48670e71f36c', 'No, none of that.', 1625266298362, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113201, 'user2', '9677624f-c6ed-40f7-9f88-48670e71f36c', 'Do you experience any chest pains? I want to check especially since you have been coughing up some mucus.', 1625266285925, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113202, 'user1', '9677624f-c6ed-40f7-9f88-48670e71f36c', 'No, I luckily do not have any chest pains.', 1625266312614, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113203, 'user1', '9677624f-c6ed-40f7-9f88-48670e71f36c', 'I have actually been hospitalized for psychiatric problems and now live in a nursing facility. Things have not been too great. I don''t like living there.', 1625266255339, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113204, 'user2', '9677624f-c6ed-40f7-9f88-48670e71f36c', 'I understand the frustration. When you live in a nursing facility you lose a lot of your freedom.', 1625266266778, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113205, 'user1', '9677624f-c6ed-40f7-9f88-48670e71f36c', 'I want to live back in my apartment, but I know I am too ill to care for myself.', 1625266261455, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113206, 'user3', 'f8bbe774-b33b-4416-b6d1-296f3ed3d27b', 'You can continue working, I just want you to be careful.', 1510234501821, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113207, 'user1', 'f8bbe774-b33b-4416-b6d1-296f3ed3d27b', 'Thanks Doctor. I will be.', 1510234504517, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113208, 'user3', 'f8bbe774-b33b-4416-b6d1-296f3ed3d27b', 'Great.', 1510234510354, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113209, 'user2', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'Can you confirm your age for me, ma''am?', 1432417725578, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113210, 'user2', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'Have you ever had a cystoscopy?', 1432417738199, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113211, 'user1', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'Yes, it was unremarkable, that''s what they told me.', 1432417743520, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113212, 'user2', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'When are your episodes for the most part?', 1432417758661, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113213, 'user1', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'Um, usually during the day. I don''t usually have them at night.', 1432417735431, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113214, 'user2', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'Are you having any pain with urination?', 1432417752909, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113215, 'user1', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'No, no pain.', 1432417757769, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113216, 'user2', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'Aside from the little bit of blood, can you tell if there''s any pus in your urine?', 1432417743735, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113217, 'user1', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'No, I don''t have any of that, it''s just the little bit of blood.', 1432417752356, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113218, 'user2', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'Have you taken any medications for this?', 1432417738156, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113219, 'user1', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'Um, I had Ditropan, and it didn''t do very well.', 1432417764777, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113220, 'user2', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'Well, this ultrasound of the kidney is also unremarkable, so at this time I think we should try a different medication.', 1432417766406, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113221, 'user1', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'Sure, I''m fifty six years old.', 1432417731394, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113222, 'user2', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'Great, so what brings you in to see me today?', 1432417730341, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113223, 'user1', '16b4b176-1aee-4f70-8894-766e2604cf4c', 'Um, I''m peeing a lot, and I''m having  a little bit blood in that urine as well.', 1432417735220, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113224, 'user3', '80ae6084-21c8-4320-b17d-b2aa1f79f270', 'Any health issues on your mom or dad''s side?', 1101607400759, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113225, 'user1', '80ae6084-21c8-4320-b17d-b2aa1f79f270', 'No, we''re a pretty healthy family.', 1101607402821, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113226, 'user2', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'Hello sir, how are you?', 1317218033752, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113227, 'user2', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'Hm, don''t worry! We will take care of you, let me start by taking some details.', 1317218045558, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113228, 'user1', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'Sure!', 1317218049505, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113229, 'user2', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'So were you referred by someone or-', 1317218052743, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113230, 'user1', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'Oh, no I referred myself to your clinic.', 1317218056456, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113231, 'user2', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'Okay. And what is your age?', 1317218055551, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113232, 'user1', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'I am sixty four years young!', 1317218068775, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113233, 'user2', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'Ah, that''s clever, you certainly look very young. And which is your dominant hand? Are you left handed, or right?', 1317218072849, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113234, 'user1', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'I am right handed.', 1317218075424, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113235, 'user2', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'So, tell me what is going on with you?', 1317218091800, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113236, 'user1', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'Well, lately I am having difficulty remembering names and phone numbers or even events.', 1317218067525, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113237, 'user2', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'Well, it''s not uncommon.', 1317218103191, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113238, 'user1', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'I know, but I am usually very good at remembering things. I would have not worried that much, but it was brought to my attention by my clerical staff.', 1317218068198, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113239, 'user2', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'Oh, okay. What do you do?', 1317218073510, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113240, 'user1', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'Well, I was the catholic priest at my parish, like we have our own small administrative district and church.', 1317218114512, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113241, 'user2', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'Okay, and when did you notice first that you are forgetting things?', 1317218055560, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113242, 'user1', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'Around twelve months back.', 1317218105878, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113243, 'user2', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'And did it cause any problem at work or any mishaps?', 1317218111879, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113244, 'user2', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'Okay, I have my notes let me put the date, oh what is the date-', 1317218064803, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113245, 'user1', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'I don''t know, I don''t know whether I am good, or my problem is getting worse and that is the reason I got myself to your clinic for a neurological consult.', 1317218036856, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113246, 'user1', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'It''s twenty eighth of February.', 1317218132268, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113247, 'user2', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'Thank you!', 1317218120916, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113248, 'user1', '968c7169-f7d3-4750-96c5-0bb6822689d8', 'No, not at all! No social or professional faux pas whatsoever.', 1317218068770, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113249, 'user2', '5b0f759e-abff-4a22-9819-f12bf7eeef8a', 'All right, you can go home now.', 1259056634603, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113250, 'user1', '5b0f759e-abff-4a22-9819-f12bf7eeef8a', 'Thank you doctor.', 1259056640116, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113251, 'user2', '5b0f759e-abff-4a22-9819-f12bf7eeef8a', 'You can stay at your friend''s place and make sure to take good care of yourself.', 1259056643983, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113252, 'user1', '5b0f759e-abff-4a22-9819-f12bf7eeef8a', 'Yes.', 1259056646799, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113253, 'user2', '5b0f759e-abff-4a22-9819-f12bf7eeef8a', 'Make sure you follow up with Doctor X on Monday or Tuesday. I know that Doctor Y already discussed his plans. Continue taking your medicines except Prozac. Okay?', 1259056645075, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113254, 'user3', '76358672-1a0c-4cd5-906e-596367e2f75b', 'Do you smoke or drink?', 1429411005633, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113255, 'user1', '76358672-1a0c-4cd5-906e-596367e2f75b', 'Nope, I''ve never touched a cigarette nor do I plan on ever doing so. Same goes for alcohol.', 1429411008581, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113256, 'user3', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'Hi there! Welcome to the Neurology clinic, sir.', 1636719945635, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113257, 'user1', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'Hi! Thank you.', 1636719949919, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113258, 'user1', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'Suddenly, I started having double vision.', 1636719961211, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113259, 'user3', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'Did the double vision happen more than one time?', 1636719960451, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113260, 'user1', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'It has been happening almost every day off and on through out the day.', 1636719982003, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113261, 'user3', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'How long do the episodes last?', 1636719971807, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113262, 'user1', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'They last for only a few minutes at a time. When I was first diagnosed years ago it happened for a year and then it stopped happening. It was not happening as often as it is now.', 1636719973272, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113263, 'user3', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'Did you ever receive any treatment for your binocular diplopia?', 1636719994905, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113264, 'user1', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'No. It spontaneously resolved and so I didn''t need to seek any treatment. Back when all this was happening it had two episodes of a drooping eyelid. I thought I had myasthenia gravis but I was told that that was probably not the case.', 1636719983932, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113265, 'user3', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'What eyelid was drooping?', 1636719999154, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113266, 'user3', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'What brings you in to the clinic today?', 1636719950710, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113267, 'user3', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'What is your dominate hand?', 1636720010711, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113268, 'user1', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'I am right handed.', 1636720024199, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113269, 'user3', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'And how old are you?', 1636720023121, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113270, 'user1', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'I am sixty seven.', 1636719971767, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113271, 'user3', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'Involving the double vision, does it become worse when looking at distant objects?', 1636719986168, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113272, 'user1', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'Yes.', 1636720003882, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113273, 'user1', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'I don''t remember?', 1636719992903, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113274, 'user1', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'Yes. That makes it worse too. When I put my hand over one eye is goes away.', 1636720054523, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113275, 'user3', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'Do you have any other symptoms related to the vision issues?', 1636720055353, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113276, 'user1', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'No.', 1636720078263, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113277, 'user1', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'I was diagnosed with binocular diplopia twenty five years ago but I haven''t had much of an issue with it until about a year ago.', 1636719959650, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113278, 'user3', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'What did you notice as far as symptoms?', 1636719963687, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113279, 'user3', '1df05819-ac24-4fa8-acb5-99410dcd621b', 'When you look at objects off to either side of midline does it become worse?', 1636720032127, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113280, 'user2', '3254863d-b549-48e8-995d-356083813f22', 'How old is your son?', 1572365023808, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113281, 'user1', '3254863d-b549-48e8-995d-356083813f22', 'He is almost five and a half years old now.', 1572365026822, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113282, 'user1', '3254863d-b549-48e8-995d-356083813f22', 'Okay.', 1572365051281, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113283, 'user2', '3254863d-b549-48e8-995d-356083813f22', 'I believe he would benefit from a subtalar arthrodesis, possible autograft, and lengthening of the Achilles. I''ll go over the details of that procedure right now.', 1572365045836, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113284, 'user1', '3254863d-b549-48e8-995d-356083813f22', 'Can we do the surgery soon?', 1572365054174, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113285, 'user2', '3254863d-b549-48e8-995d-356083813f22', 'Yes we can. But we''ll probably need to do another procedure until his foot matures some more.   This is a stabilizing measure.', 1572365032843, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113286, 'user1', '3254863d-b549-48e8-995d-356083813f22', 'What are the risks of infection if we do the surgery?', 1572365057206, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113287, 'user2', '3254863d-b549-48e8-995d-356083813f22', 'Historically, the risk of infection is very low, usually less than one percent.', 1572365065184, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113288, 'user1', '3254863d-b549-48e8-995d-356083813f22', 'How do you get the risk so low?', 1572365034892, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113289, 'user2', '3254863d-b549-48e8-995d-356083813f22', 'We use prophylactic antibiotics to minimize the infection risk.', 1572365041042, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113290, 'user1', '3254863d-b549-48e8-995d-356083813f22', 'Will he be able to walk again right after the surgery?', 1572365101636, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113291, 'user2', '3254863d-b549-48e8-995d-356083813f22', 'No, he''ll need to stay off it for a while, we call this nonweightbearing. It will only be for some time after the procedure, it''s not permanent.', 1572365048779, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113292, 'user1', '3254863d-b549-48e8-995d-356083813f22', 'What are the rest of the risks?', 1572365054953, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113293, 'user2', '3254863d-b549-48e8-995d-356083813f22', 'The total risks of surgery include risks of anesthesia, infection, bleeding, changes in sensation and motion of the extremity, hardware failure, need for other surgical procedures, need to be nonweightbearing for some time. I would not worry about these risks, though. The risk is low.', 1572365100456, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113294, 'user1', '3254863d-b549-48e8-995d-356083813f22', 'Okay. Let''s do the surgery.', 1572365081759, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113295, 'user1', '3254863d-b549-48e8-995d-356083813f22', 'He has a lot of pain about both feet, and if you look at it, it looks like his feet rotate inwards.', 1572365029909, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113296, 'user2', '3254863d-b549-48e8-995d-356083813f22', 'Okay, let me see, okay, um, he has rocker bottom feet.', 1572365036705, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113297, 'user2', '3254863d-b549-48e8-995d-356083813f22', 'What seems to be the problem?', 1572365035528, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113298, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Welcome back to the clinic.', 1405392014317, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113299, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Thank you.', 1405392017828, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113300, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Yes.', 1405392034346, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113301, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Was this a workrelated injury?', 1405392032216, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113302, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Yes. I was working as a C N A at the Veteran''s House.', 1405392025694, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113303, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'How did the work injury happen?', 1405392059848, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113304, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'I was transferring a patient from a wheal chair to a bed, and I hurt my shoulder.', 1405392044675, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113305, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'What is the date of the incident?', 1405392051130, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113306, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'January first, two thousand and two.', 1405392034711, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113307, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'I understand that we are doing an impairment rating exam today.', 1405392023648, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113308, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Yes, that''s correct.', 1405392023180, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113309, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'I am required to ask some specific questions for the L and I paperwork. What is your ago, ethnicity and gender?', 1405392098281, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113310, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'I am a thirty one year old, white, female.', 1405392102550, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113311, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Have you ever had a prior injury to your right shoulder?', 1405392052064, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113312, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'No.', 1405392072930, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113313, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Are right or left hand dominant?', 1405392094746, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113314, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Right.', 1405392073662, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113315, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Other then your shoulder injury, do you have any other chronic health problems?', 1405392088309, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113316, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'No.', 1405392111634, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113317, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Are you experiencing any fever, chills or illnesses?', 1405392039170, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113318, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'No.', 1405392046463, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113319, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Let discuss some of the previous treatments and test that you have been done for your shoulder.', 1405392086606, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113320, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Okey. I have done a lot of different treatments.', 1405392162878, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113321, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'What treatments have you done?', 1405392124129, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113322, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'I tried physical therapy. They did a subacromion decompression treatment in November, two thousand and two.', 1405392101164, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113323, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Did either of those treatments help?', 1405392043383, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113324, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Not much. I went and saw Doctor Lin and he said that I might have a nerve fiber injury. I forget what he called it.', 1405392173053, 29);
