INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113326, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Yes. That sounds right.', 1405392067763, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113327, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Oh, I see his notes in your chart. It says that he felt like you had a right superficial radial neuritis and blocked this with resolution of your symptoms. Then it looks like he sent you to get E M G testing at Valley Medical. Let me look for those results.', 1405392196081, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113328, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Okey. They should be in my chart. I had Doctor Lin send over all my records.', 1405392145156, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113329, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Here it is. It says that the right suprascapular neuropathy although a C5 radiculopathy could not be ruled out.  MRI testing on the cervical spine was then done which was negative for disk herniation and underwent suprascapular nerve decompression of the scapular notch on December eighteenth, two thousand and three.', 1405392075979, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113330, 'user1', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'Whatever that means? I ended up getting a nerve block because I was still in pain. Doctor Lin did one in the frount of my shoulder and then another in the back.', 1405392095851, 35);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113331, 'user2', 'fdc46953-b258-4c54-9b26-1fd5d4144de7', 'This has been a long drawn out course of treatments for you.', 1405392062049, 36);
