INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113519, 'user3', '5b2dffab-76a0-4cf4-a57e-6fecaf4d944e', 'That is decently normal. I get out of breath when walking from floor to floor in this hospital too.', 1221706135832, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113520, 'user1', '5b2dffab-76a0-4cf4-a57e-6fecaf4d944e', 'I thought so. I remember being young and still struggling with stairs.', 1221706168859, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113521, 'user3', '5b2dffab-76a0-4cf4-a57e-6fecaf4d944e', 'Unfortunately, some things are just with us for life. Do you have any coughing fits or irregular heart beating?', 1221706176970, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113522, 'user1', '5b2dffab-76a0-4cf4-a57e-6fecaf4d944e', 'No.', 1221706143115, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113523, 'user3', '5b2dffab-76a0-4cf4-a57e-6fecaf4d944e', 'Great! You are getting a clean bill of health from me today. On the notes it says you have Crohn''s disease. Are you getting regularly checked for that?', 1221706186233, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113524, 'user1', '5b2dffab-76a0-4cf4-a57e-6fecaf4d944e', 'Yes. Doctor Ferguson takes care of me for that.', 1221706129272, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113525, 'user3', '5b2dffab-76a0-4cf4-a57e-6fecaf4d944e', 'Excellent. Are you scheduled for a prostate check?', 1221706163790, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113526, 'user1', '5b2dffab-76a0-4cf4-a57e-6fecaf4d944e', 'Yes, I go to Doctor Roszhart.', 1221706158605, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113527, 'user3', '5b2dffab-76a0-4cf4-a57e-6fecaf4d944e', 'You are wonderfully on top of it. What a breath of fresh air. From all of your travelling, how are your ankles? Have you noticed any swelling?', 1221706172578, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113528, 'user1', '5b2dffab-76a0-4cf4-a57e-6fecaf4d944e', 'Surprisingly, from all the walking I do, I do not have any swelling. After quitting smoking ten years ago I had to get addicted to something else and that was walking and travelling.', 1221706169035, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113529, 'user3', '5b2dffab-76a0-4cf4-a57e-6fecaf4d944e', 'I could not agree more. From your last checkup notes, it looks like you had right knee surgery and back surgery about eighteen months ago. How is that going? Any pain?', 1221706115076, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113530, 'user1', '5b2dffab-76a0-4cf4-a57e-6fecaf4d944e', 'Yes, I had a right knee replacement. I am doing great so far. Nothing to complain about. I can do almost anything I desire now. It is such a good lifestyle change from before surgery.', 1221706118699, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113531, 'user3', '5b2dffab-76a0-4cf4-a57e-6fecaf4d944e', 'What do you do with your new body?', 1221706119738, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113532, 'user1', '0cdb1f2c-cd34-43b7-9553-c197630f0c0d', 'Um, I don''t remember correctly, but it should be in my reports. I did have one sometime back, just don''t remember when exactly.', 1390097952318, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113533, 'user2', '0cdb1f2c-cd34-43b7-9553-c197630f0c0d', 'Ah, no problem. I see it here in your reports and it''s up to date. So that''s good.', 1390097953378, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113534, 'user2', '0cdb1f2c-cd34-43b7-9553-c197630f0c0d', 'And when did you had your last tetanus shot?', 1390097949596, 0);
