INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113539, 'user2', 'e4793b05-ccc3-4990-92bb-278e335ec004', 'And how much would say you smoke per day?', 1428691272626, 6);
