INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113542, 'user1', 'e4793b05-ccc3-4990-92bb-278e335ec004', 'I don''t remember exactly but for many, many years, I have a long history of chain smoking.', 1428691298392, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113543, 'user2', 'e4793b05-ccc3-4990-92bb-278e335ec004', 'Hm. And alcohol?', 1428691289469, 10);
