INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113545, 'user2', 'e4793b05-ccc3-4990-92bb-278e335ec004', 'Hm.', 1428691266420, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113546, 'user2', 'e4793b05-ccc3-4990-92bb-278e335ec004', 'Alone?', 1428691257300, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113547, 'user1', 'e4793b05-ccc3-4990-92bb-278e335ec004', 'No, I stay with my boyfriend.', 1428691262298, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113548, 'user1', 'e4793b05-ccc3-4990-92bb-278e335ec004', 'I stay nearby in my apartment.', 1428691254437, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113549, 'user2', '48c11245-23a4-42fd-acd4-6550ad782e88', 'How are you, sir?', 1353088985699, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113550, 'user1', '48c11245-23a4-42fd-acd4-6550ad782e88', 'We thought he was having a long shower that day. Then about one and a half hours later my son suspected something is not right and we went up to check. There we found him unconscious on the shower floor. Our son, he then drove us back to Iowa and since then he is complaining of these headaches and that he''s not feeling well. He gets unconscious or falls asleep I don''t know but it is happening a lot of the time. We got him to local hospital today in the morning. It is three days after that shower incident.', 1353088992434, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113551, 'user2', '48c11245-23a4-42fd-acd4-6550ad782e88', 'Yeah, his report says he got a hemorrhage, I mean, blood clot in his brain.', 1353089005960, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113552, 'user1', '48c11245-23a4-42fd-acd4-6550ad782e88', 'Yeah, after that report they transferred us to this hospital.', 1353089007796, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113553, 'user1', '48c11245-23a4-42fd-acd4-6550ad782e88', 'One less than sixty.', 1353088990378, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113554, 'user2', '48c11245-23a4-42fd-acd4-6550ad782e88', 'So, what happened?', 1353088991880, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113555, 'user1', '48c11245-23a4-42fd-acd4-6550ad782e88', 'I was visiting my son in Cheyenne, Wyoming, then I on October tenth when I was taking a shower, I felt a pop in my head. I don''t know what happened after that.', 1353089002388, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113556, 'user3', '3faaa35b-0614-4b08-abf5-b8e47d8d1cd8', 'Is this your first surgery or have you had other surgeries in the past?', 954310643791, 0);
