INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113563, 'user3', '1b25b161-bf66-4b5c-939f-5064b9cdfad8', 'Do you smoke or consume any form of tobacco?', 1200633717186, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113564, 'user3', '037956fe-c478-4aff-baf3-2dc293f2086c', 'Where do you feel the most pain?', 1714413028648, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113565, 'user1', '037956fe-c478-4aff-baf3-2dc293f2086c', 'I''d have to say at the heels of my feet. I spend a lot of time on my feet at work.', 1714413029867, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113566, 'user3', '037956fe-c478-4aff-baf3-2dc293f2086c', 'I see. What kind of shoes do you normally wear to work?', 1714413031917, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113567, 'user3', '037956fe-c478-4aff-baf3-2dc293f2086c', 'I''d advise getting an orthotic for your shoes to help with the heel pain and resting your feet when you''re home. In the meantime, I''d like for you to see a specialist to make sure nothing else is going on.', 1714413049787, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113568, 'user1', '037956fe-c478-4aff-baf3-2dc293f2086c', 'Alright, I''m good with that plan.', 1714413054367, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113569, 'user3', '037956fe-c478-4aff-baf3-2dc293f2086c', 'Are you having any other problems? Joint pain, difficulty walking, nausea, vomiting, or other symptoms?', 1714413057679, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113570, 'user1', '037956fe-c478-4aff-baf3-2dc293f2086c', 'No, just heel pain for now.', 1714413078612, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113571, 'user1', '037956fe-c478-4aff-baf3-2dc293f2086c', 'Regular tennis shoes.', 1714413041368, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113572, 'user3', '037956fe-c478-4aff-baf3-2dc293f2086c', 'Are they cushioned?', 1714413045885, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113573, 'user1', '037956fe-c478-4aff-baf3-2dc293f2086c', 'Eh not really, but they''re pretty durable.', 1714413058153, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113574, 'user3', 'a4b82719-f2a3-4099-b6a0-3734dee49427', 'I''m here to take your social history. So, tell me about yourself.', 1680347154641, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113575, 'user3', 'a4b82719-f2a3-4099-b6a0-3734dee49427', 'What is your living status?', 1680347175882, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113576, 'user1', 'a4b82719-f2a3-4099-b6a0-3734dee49427', 'I live with my roommate.', 1680347179228, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113577, 'user1', 'a4b82719-f2a3-4099-b6a0-3734dee49427', 'Yes. I''m also going to the psychiatry department for my depression and these drug issues.', 1680347172068, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113578, 'user1', 'a4b82719-f2a3-4099-b6a0-3734dee49427', 'I was taking drugs. I tried all the methods, mainly I was using inhalation and I V drugs.', 1680347160062, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113579, 'user3', 'a4b82719-f2a3-4099-b6a0-3734dee49427', 'Right now, you are on methadone, right?', 1680347160167, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113580, 'user2', '0b44a17a-2866-4e44-bb0c-5796edaa2b92', 'I will ask you a few questions about your family history, sir.', 1471797509701, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113581, 'user1', '0b44a17a-2866-4e44-bb0c-5796edaa2b92', 'That''s okay.', 1471797511131, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113582, 'user2', '0b44a17a-2866-4e44-bb0c-5796edaa2b92', 'Does anyone in your family ever have any medical problems?', 1471797521347, 2);
