INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113586, 'user1', '5732a6fa-2476-4ab9-8d06-b8c1e01d627b', 'I have no idea. I''m not in contact with her.', 1497327296409, 5);
