INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113590, 'user3', 'ead71027-cc41-483d-99dd-90e83a665880', 'Good morning, sir. Before we begin, how old are you?', 962167517131, 0);
