INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113598, 'user1', 'ead71027-cc41-483d-99dd-90e83a665880', 'Good morning, doctor. I''m forty one.', 962167518420, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113599, 'user3', 'ead71027-cc41-483d-99dd-90e83a665880', 'Thank you, and how long have you had this left knee pain?', 962167525704, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113600, 'user3', 'f57175c2-460b-47cb-9b51-11895fa03bd9', 'I see here that you''ve been feeling more short of breath.', 1287120642739, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113601, 'user1', 'f57175c2-460b-47cb-9b51-11895fa03bd9', 'Yes, for three days now.', 1287120648138, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113602, 'user3', 'f57175c2-460b-47cb-9b51-11895fa03bd9', 'Is it worse when you exert yourself?', 1287120648661, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113603, 'user3', 'f57175c2-460b-47cb-9b51-11895fa03bd9', 'Where does your chest feel most congested? And how would you rate the pain right now? Ten being the worst.', 1287120674536, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113604, 'user1', 'f57175c2-460b-47cb-9b51-11895fa03bd9', 'Both sides. I''d say it''s at a three currently.', 1287120667597, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113605, 'user3', 'f57175c2-460b-47cb-9b51-11895fa03bd9', 'Does it send pain or numbness or tingling down your arms? How about any jaw pain as a result?', 1287120655213, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113606, 'user1', 'f57175c2-460b-47cb-9b51-11895fa03bd9', 'No, but it does get worse whenever I cough.', 1287120667551, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113607, 'user3', 'f57175c2-460b-47cb-9b51-11895fa03bd9', 'Is this your first time experiencing this type of congestion?', 1287120681176, 10);
