INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113609, 'user3', 'f57175c2-460b-47cb-9b51-11895fa03bd9', 'Did that improve on its own?', 1287120677006, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113610, 'user1', 'f57175c2-460b-47cb-9b51-11895fa03bd9', 'It would come and go, but over the past few days it''s gotten worse. I am a strong German man so I held out coming to the doctor as long as I could.', 1287120718200, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113611, 'user3', 'f57175c2-460b-47cb-9b51-11895fa03bd9', 'You are very strong! You are sixty nine though, so I don''t think anyone would see it as weak if you came to the doctor more often.', 1287120726043, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113612, 'user3', 'f57175c2-460b-47cb-9b51-11895fa03bd9', 'Did these symptoms start around the same time?', 1287120664930, 4);
