INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113623, 'user2', 'adfb2a45-054a-4ed5-9066-42949e74f12f', 'Hello, sir how can I help you? Looks like we are talking about snoring today.', 1133553217437, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113624, 'user1', 'adfb2a45-054a-4ed5-9066-42949e74f12f', 'Yeah, I need to get this loud and obnoxious snoring under control. I keep waking up my partner. I have a C P A P right now because I was told I have almost severe sleep apnea.', 1133553221326, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113625, 'user1', 'adfb2a45-054a-4ed5-9066-42949e74f12f', 'Usually I sleep around eleven or eleven thirty and wake up at six or seven on the weekends. I''ll sleep in until eight or nine on the weekdays. On Saturday''s I might go to sleep around midnight because I usually watch a show with my family. I feel good when I wake up though. Much less tossing and turning. The sheets are always on the bed still.', 1133553229180, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113626, 'user2', 'adfb2a45-054a-4ed5-9066-42949e74f12f', 'That''s some good news. I see you have lost a bit of weight too. Around fifteen to eighteen pounds is something to be proud of.', 1133553246670, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113627, 'user1', 'adfb2a45-054a-4ed5-9066-42949e74f12f', 'Thanks. It has been a lot of exercising and dieting. I am motivated because I want to stop snoring.', 1133553254507, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113628, 'user2', 'adfb2a45-054a-4ed5-9066-42949e74f12f', 'How has work been? Do you think it has been stressful at all?', 1133553236168, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113629, 'user1', 'adfb2a45-054a-4ed5-9066-42949e74f12f', 'I still work at Smith Barney in downtown Baltimore. I work from around eight or eight thirty to five or five thirty. I deal with training on how to sell managed funds and accounts. I do not think I have been stressed because I am able to stay awake through my shift and even when I come home at night. I may get a little tired during hay fever season, but that is rare.', 1133553256122, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113630, 'user2', 'adfb2a45-054a-4ed5-9066-42949e74f12f', 'Yes, I see that you have hay fever. Fatigue is a common symptom from the allergy.', 1133553228474, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113631, 'user2', 'adfb2a45-054a-4ed5-9066-42949e74f12f', 'So what is your sleep pattern now? When do you usually go to bed and wake up?', 1133553232529, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113632, 'user2', 'adfb2a45-054a-4ed5-9066-42949e74f12f', 'Yes, I see on your chart that you were given ten centimeters of H two O nasal pressure and that you predominately suffer from hypopnea. Hypopnea is shallow breathing. How has the device been working?', 1133553227081, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113633, 'user1', 'adfb2a45-054a-4ed5-9066-42949e74f12f', 'It definitely has reduced my snoring, but my partner keeps waking me up in the middle of the night because the mask pops off. I wear it around five to seven nights a week, but for some reason it falls off or I take it off randomly in the night. My wife usually must remind me to put it back on.', 1133553229048, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113634, 'user3', 'd1bcdad9-05dd-41a5-8e0a-acd406f1ea8e', 'Anything else?', 1189604848390, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113635, 'user1', 'd1bcdad9-05dd-41a5-8e0a-acd406f1ea8e', 'I have a lot of pain in my chest as well.', 1189604854842, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113636, 'user1', 'd1bcdad9-05dd-41a5-8e0a-acd406f1ea8e', 'Yes, I cannot stop myself. I have tried many times but it''s hard to control.', 1189604872452, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113637, 'user3', 'd1bcdad9-05dd-41a5-8e0a-acd406f1ea8e', 'How are you feeling today?', 1189604844748, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113638, 'user1', 'd1bcdad9-05dd-41a5-8e0a-acd406f1ea8e', 'I have a lot of anxiety.', 1189604848716, 1);
