INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113644, 'user2', '9d277418-5133-42d9-a458-8854939a50b3', 'Okay. So, no history of any drug or alcohol abuse, right?', 1620473103502, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113645, 'user2', '9d277418-5133-42d9-a458-8854939a50b3', 'How about alcohol?', 1620473105390, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113646, 'user1', '9d277418-5133-42d9-a458-8854939a50b3', 'I drink, but just normal. I don''t have any alcohol problem.', 1620473104669, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113647, 'user2', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'Hi, how can I help you?', 1610071301918, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113648, 'user2', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'Okay. Let me see. What symptoms are you experiencing right now?', 1610071314276, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113649, 'user1', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'I am feeling very dizzy. I do have some vertigo and lightheadedness.', 1610071311643, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113650, 'user2', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'You are on blood thinners, right? That is Coumadin therapy? Or am I wrong here?', 1610071326329, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113651, 'user1', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'No, you are right but please stop the Coumadin. I am tired of these regular blood draws.', 1610071318968, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113652, 'user2', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'See, I understand it is hard to control it. It is difficult to regulate that.', 1610071312012, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113653, 'user1', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'Yes exactly. That is why I don''t want it. Give me something simple.', 1610071311403, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113654, 'user2', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'Okay I will investigate it. Are you experiencing any chest pain or shortness of breath?', 1610071330700, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113655, 'user1', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'Oh no, I am not feeling that.', 1610071339015, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113656, 'user2', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'Okay great!', 1610071345506, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113657, 'user1', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'Actually, I am moving around a little bit better now and my arm does not hurt.', 1610071333993, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113658, 'user2', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'How about your back pain?', 1610071343745, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113659, 'user1', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'Um, it is improving as well.', 1610071385420, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113660, 'user2', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'Okay, cool.', 1610071391095, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113661, 'user1', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'Yeah.', 1610071340350, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113662, 'user1', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'That''s right. I misplaced it.', 1610071311104, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113663, 'user1', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'I am here for a follow up on my heart rhythm problem. I think it is atrial fibrillation.', 1610071307782, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113664, 'user2', 'ff62524a-287e-430e-96e5-5976ebdc7f16', 'Oh yes. You are not on Cardizem and your heart rate is up just a little bit today.', 1610071311862, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113665, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Good morning, young man.', 1064873211124, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113666, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Good morning, doctor.', 1064873216749, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113667, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Yes sir.', 1064873237241, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113668, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Good, so what seems to be the problem today?', 1064873245997, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113669, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'I''ve been having pain in this knee for about a month now.', 1064873229419, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113670, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Can you remember a specific injury to this knee?', 1064873242566, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113671, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Um, yeah, I was playing basketball when I jumped, and then when I landed I felt this knee pop.', 1064873222930, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113672, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Do you remember the date of your injury, young man?', 1064873249643, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113673, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Um, it was on December twenty second two thousand seven.', 1064873254268, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113674, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Good, so how have you been treated for this so far?', 1064873248543, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113675, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'We went to another clinic first, and they put me in a splint.', 1064873241981, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113676, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Yeah, and then they referred us over to Children''s.', 1064873267700, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113677, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Have they taken x rays yet?', 1064873236101, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113678, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Yes, I got back a few minutes ago.', 1064873277593, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113679, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Let''s have a look. Well, you broke your leg.', 1064873230294, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113680, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'What, where? Can you show me?', 1064873252702, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113681, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Right here, this is a tibial tubercule avulsion fracture with patella alta.', 1064873254550, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113682, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'What does that mean, doctor?', 1064873324384, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113683, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Well, he''s broken his leg, and pulled some bone off by doing so. We''ll need to do surgery on this.', 1064873290590, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113684, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Oh no, what''s the name of the procedure?', 1064873317666, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113685, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'It''s called an O R I F. We''ll go in there with some hardware to put everything back together, and he can get on the road to healing.', 1064873337516, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113686, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Let me call his father while we discuss this. What''s the risk of infection from this surgery?', 1064873307343, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113687, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Historically, it''s less than one percent. We use antibiotics to control for infection.', 1064873262551, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113688, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Okay, will he be asleep for this?', 1064873351414, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113689, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Yes, he won''t feel a thing.', 1064873344865, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113690, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'That''s good too. Will he need this hardware out in the future?', 1064873357398, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113691, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'We can remove everything once he has healed up nicely. Other risks include bleeding, changes in the sensation of the leg, hardware failure, need for post op rehab, need for hardware removal, and failure to restore extensor mechanism tension. But I would not worry about these things. I have been doing these surgeries for years and things like this rarely happen.', 1064873272024, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113692, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Yes, his father agrees. We''re going to do the surgery.', 1064873331730, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113693, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Good, my chart says that you''re fourteen years old. Is that correct?', 1064873225549, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113694, 'user3', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Who is this young lady, is this your grandmother, or sister?', 1064873218559, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113695, 'user1', '01081213-fb9d-477f-ab0b-fd7cd4904137', 'Oh doctor, yes, I am his grandmother.', 1064873214759, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113696, 'user2', 'ef938d86-f788-4ec4-9aaa-98748a0edd11', 'Good afternoon, ma''am. Can you confirm your age for me, please?', 1057099138205, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113697, 'user1', 'ef938d86-f788-4ec4-9aaa-98748a0edd11', 'Sure, good afternoon, doctor. I''m sixty one years old.', 1057099143291, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113698, 'user1', 'ef938d86-f788-4ec4-9aaa-98748a0edd11', 'Um, it''s in my legs.', 1057099143808, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113699, 'user2', 'ef938d86-f788-4ec4-9aaa-98748a0edd11', 'I see here that you have sleep apnea too.', 1057099144725, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113700, 'user1', 'ef938d86-f788-4ec4-9aaa-98748a0edd11', 'Yeah, I was involved in an overnight sleep study on C P A P and oxygen.', 1057099164268, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113701, 'user2', 'ef938d86-f788-4ec4-9aaa-98748a0edd11', 'Why did they do this?', 1057099180371, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113702, 'user1', 'ef938d86-f788-4ec4-9aaa-98748a0edd11', 'It was in order to determine why I had difficulty falling asleep and staying asleep.', 1057099171621, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113703, 'user2', 'ef938d86-f788-4ec4-9aaa-98748a0edd11', 'Have You had any other treatments?', 1057099168853, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113704, 'user1', 'ef938d86-f788-4ec4-9aaa-98748a0edd11', 'Yeah, I had a review done while I was in the hospital about two weeks ago, I have the results right here.', 1057099190496, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113705, 'user2', 'ef938d86-f788-4ec4-9aaa-98748a0edd11', 'Thank you, so, how is your leg pain been managed?', 1057099196690, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113706, 'user1', 'ef938d86-f788-4ec4-9aaa-98748a0edd11', 'Um, I take pretty substantial doses of opioids in order to control it.', 1057099200021, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113707, 'user2', 'ef938d86-f788-4ec4-9aaa-98748a0edd11', 'Do you have any swelling?', 1057099197256, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113708, 'user1', 'ef938d86-f788-4ec4-9aaa-98748a0edd11', 'Yes, I take Lasix for my leg swelling.', 1057099187665, 15);
