INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113713, 'user2', 'ef938d86-f788-4ec4-9aaa-98748a0edd11', 'Great, what brings you in for a visit today?', 1057099140710, 2);
