INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113716, 'user2', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'Hi there, what''s going on?', 1493651066677, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113717, 'user1', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'I am her daughter. I brought her to the emergency. She lives in a skilled nursing home. Today, when I went to meet her, I found her with the right side of her face drooping. I immediately rushed her here.', 1493651068568, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113718, 'user1', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'She is eighty three. She also has a history of stroke after which she developed this condition where she knows what she wants to speak but is unable to make the word or sentence.', 1493651088400, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113719, 'user2', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'Oh, I see. She has expressive aphasia, correct?', 1493651099538, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113720, 'user1', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'She says yes.', 1493651111702, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113721, 'user1', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'Yes, that.', 1493651100821, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113722, 'user2', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'Okay, let me check her. She does have a droop to her right side of the face. Ma''am, do you feel any weakness on the right side of your body?', 1493651108310, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113723, 'user2', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'She had her C T scan earlier today and I have the report. It does not show any acute attack or anything.', 1493651077030, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113724, 'user1', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'Okay!', 1493651085001, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113725, 'user2', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'But it does show that she has a new onset of a stroke.', 1493651098249, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113726, 'user1', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'Is there anything to worry?', 1493651107829, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113727, 'user2', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'I think we need to admit her for observation. We need to monitor her. We will also get her a proper treatment for her urinary infection which is not getting better due to resistance to the oral medicines.', 1493651100371, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113728, 'user1', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'Yeah, sounds good!', 1493651099021, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113729, 'user2', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'Yeah, let me talk to the nurse.', 1493651107806, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113730, 'user1', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'Thank you.', 1493651168625, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113731, 'user1', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'She has dementia, most of the time she doesn''t even remember me.', 1493651076226, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113732, 'user2', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'Oh, okay.How old is she?', 1493651070960, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113733, 'user2', '6c8388a5-ac52-4d7c-a141-4c4604e254c5', 'Oh, you did the right thing. Ma''am, how are you feeling?', 1493651077149, 2);
