INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113768, 'user2', 'c617935e-e87d-438d-8df8-b1b7c3749af7', 'She had her stunt adjusted which was after the M R I on April eighteenth.', 1704512387975, 7);
