INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113770, 'user2', 'c617935e-e87d-438d-8df8-b1b7c3749af7', 'Are you able to sleep in the night properly?', 1704512403315, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113771, 'user1', 'c617935e-e87d-438d-8df8-b1b7c3749af7', 'No, these headaches wake me up in the night. I haven''t had a proper sleep in like ages.', 1704512390511, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113772, 'user2', 'c617935e-e87d-438d-8df8-b1b7c3749af7', 'Is there anything that elevates this pain? Or decreases it?', 1704512405528, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113773, 'user1', 'c617935e-e87d-438d-8df8-b1b7c3749af7', 'Everything seems like increasing it. It just gets worse with coughing, straining, sneezing, even when I''m trying to stand. I tried all the medications, but nothing is helpful. There was Imitrex and I also tried Motrin eight hundred M G twice a day, but nothing seems to be like effective. Actually, it helps a bit when I lie down.', 1704512403218, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113774, 'user2', 'c617935e-e87d-438d-8df8-b1b7c3749af7', 'Is it like specific to any particular area of your head?', 1704512427480, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113775, 'user1', 'c617935e-e87d-438d-8df8-b1b7c3749af7', 'It is like all over but, uh, very much intense in the forehead.', 1704512409322, 14);
