INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113779, 'user1', 'c617935e-e87d-438d-8df8-b1b7c3749af7', 'Yeah, I get that ringing sound in my ears, and I just don''t feel well.', 1704512418194, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113780, 'user2', 'c617935e-e87d-438d-8df8-b1b7c3749af7', 'Any changes in your vision?', 1704512467044, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113781, 'user1', 'c617935e-e87d-438d-8df8-b1b7c3749af7', 'Yeah, it gets blurry, and I feel like lights are dimming. I will be meeting Doctor Y tomorrow.', 1704512462606, 20);
