INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113784, 'user2', 'c617935e-e87d-438d-8df8-b1b7c3749af7', 'Patient has been cared by Doctor X since two thousand and two. She had a Codman Hakim shunt set at ninety M M H two O. She last came to our clinic in January two thousand and eight. At that time, she was recommended to follow up with Doctor Y for the medical management of her chronic headaches. She was also recommended to see a psychiatrist for her depression.', 1704512375231, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (113785, 'user2', 'c617935e-e87d-438d-8df8-b1b7c3749af7', 'Did you go and see a psychiatrist?', 1704512383668, 2);
