INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114000, 'user2', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Is it getting worse?', 1371714121273, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114001, 'user1', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Yes, it is.', 1371714094434, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114002, 'user2', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'When did you start using the cane?', 1371714072826, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114003, 'user1', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Um, about five days ago, now.', 1371714073995, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114004, 'user2', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Why did you begin using it?', 1371714137007, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114005, 'user1', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'I''m having trouble walking and going up and down stairs.', 1371714127412, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114006, 'user2', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Are you able to stand without it?', 1371714175038, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114007, 'user1', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'No, I''m not.', 1371714191004, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114008, 'user2', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Have you had any loss of bowel or bladder control?', 1371714192544, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114009, 'user1', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'No, thankfully not, but at the same time I haven''t had a bowel movement in about three days.', 1371714165686, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114010, 'user2', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'When was the last time you urinated?', 1371714147528, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114011, 'user1', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'It was about twenty four hours ago.', 1371714196743, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114012, 'user2', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'In addition to the numbness, how else would you describe your leg symptoms?', 1371714113114, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114013, 'user1', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Um, I''d say it feels cold, at least I''ve felt that for the last day or so.', 1371714138788, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114014, 'user2', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Do you have any back or neck pain?', 1371714208259, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114015, 'user1', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'No, nothing there.', 1371714121952, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114016, 'user2', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Do you have any shortness of breath?', 1371714220305, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114017, 'user1', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Well, I''ve had it chronically for a while now, but I think it''s getting worse.', 1371714156782, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114018, 'user2', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Have you had any lightheadedness or feelings of faint?', 1371714124748, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114019, 'user1', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Um, yeah, when I try to stand up.', 1371714114143, 35);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114020, 'user2', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'How long have you had that feeling?', 1371714124736, 36);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114021, 'user1', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'I''ve had it for about two days now.', 1371714231529, 37);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114022, 'user1', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Um, I use my right hand for everything.', 1371714069907, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114023, 'user1', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Um, I have numbness, like here starting at my trunk, and then over the last month or so, it moved into my legs.', 1371714101229, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114024, 'user2', 'de88097f-4029-4f72-8b7f-e153bca1d9e1', 'Great, and which hand is your dominant hand?', 1371714057897, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114025, 'user2', '29f3cb51-b333-4899-aab5-298c55966f26', 'Do you have any known allergies to medications?', 1509128288752, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114026, 'user1', '29f3cb51-b333-4899-aab5-298c55966f26', 'No.', 1509128292656, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114027, 'user3', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Good evening, and welcome to A B C D General Hospital E D.', 1305323279878, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114028, 'user1', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Thank you, Doctor, I''ve really messed up this ankle.', 1305323284536, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114029, 'user1', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'I fell off my liner, and I landed right onto my left foot.', 1305323289195, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114030, 'user1', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Thank you for asking, Doctor, I''m a fifty year old man.', 1305323294484, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114031, 'user1', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Um, it was really about ten feet.', 1305323301202, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114032, 'user3', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Oh, yes, I see. I have some good news for you, there''s no gross deformity in this ankle.', 1305323320658, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114033, 'user1', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'What does that mean, exactly?', 1305323292462, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114034, 'user3', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'I don''t see any ankle dislocation, which is good.', 1305323329950, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114035, 'user1', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Oh, that''s good news.', 1305323291299, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114036, 'user3', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Have you had your x rays taken yet?', 1305323300132, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114037, 'user1', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Yeah, the tech just brought me back.', 1305323333706, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114038, 'user3', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Great, let me pull them up here. Okay, um, if you look here, you''ll see a fracture of your talus.', 1305323346672, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114039, 'user1', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Which bone is that?', 1305323295979, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114040, 'user3', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'That''s your heel, to be specific, it''s a grade I V Hawkins fracture of the left talus. You are still neurovascularly intact in the distal region.', 1305323307537, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114041, 'user1', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'What are we going to do about this?', 1305323367736, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114042, 'user3', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Do you have any other pain from the fall, aside from the ankle?', 1305323345478, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114043, 'user1', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'No, the ankle really took all of the weight of the fall.', 1305323374466, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114044, 'user3', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Okay, I think we should do surgery in order to repair this ankle.', 1305323344305, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114045, 'user1', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Why is that?', 1305323387228, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114046, 'user3', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'There is very weak blood flow to the body of this bone, there''s a risk for avascular necrosis, which is bone death.', 1305323343465, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114047, 'user1', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Okay, you''re right. What are the risks of this infection with this surgery?', 1305323395589, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114048, 'user3', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Overall, the risks of infection are less than one percent. We''ll use antibiotics to keep everything clean.', 1305323402998, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114049, 'user1', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Will I be asleep for this?', 1305323350346, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114050, 'user3', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Yes, you''ll be under anesthesia.', 1305323384889, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114051, 'user1', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Okay, yes, um, I''d like to go forward with the surgery.', 1305323441652, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114052, 'user3', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Before we begin, how old are you? And which gender do you identify?', 1305323289839, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114053, 'user3', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'How far did you fall?', 1305323301885, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114054, 'user3', 'bb2d8392-618e-42fe-8f0e-c1e0af48fdaa', 'Thank you, what happened?', 1305323299629, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114055, 'user3', '94f369a1-0477-40dc-ae8c-f1d6651447cb', 'What medications are you currently taking?', 1289085340709, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114056, 'user1', '94f369a1-0477-40dc-ae8c-f1d6651447cb', 'Augmentin, Detroal LA and lisinopril.', 1289085342880, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114057, 'user2', '15b7005c-dbf5-4870-b1d2-21fbecfa8d24', 'Did you ever have any surgery?', 1116434416923, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114058, 'user1', '15b7005c-dbf5-4870-b1d2-21fbecfa8d24', 'No.', 1116434422591, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114059, 'user2', 'f8b72531-3ff6-470a-99d9-03c4dbfc22d8', 'Hello, miss. How are you doing today?', 1267429472569, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114060, 'user1', 'f8b72531-3ff6-470a-99d9-03c4dbfc22d8', 'I have this massive headache.', 1267429474407, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114061, 'user2', 'f8b72531-3ff6-470a-99d9-03c4dbfc22d8', 'I see. Do migraines usually run in your family?', 1267429481766, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114062, 'user1', 'f8b72531-3ff6-470a-99d9-03c4dbfc22d8', 'They do. Everyone has it. We''ve been having it for many years.', 1267429487444, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114063, 'user2', 'f8b72531-3ff6-470a-99d9-03c4dbfc22d8', 'Oh, wow. I''m looking at your blood reports, and it shows you have high blood sugar. Does diabetes run in your family too?', 1267429481044, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114064, 'user1', 'f8b72531-3ff6-470a-99d9-03c4dbfc22d8', 'Yup. We all eat too much rice for dinner.', 1267429485439, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114065, 'user2', 'a8c623d3-62de-485c-8447-4affc208c270', 'What''s bringing you in today?', 1527338188766, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114066, 'user1', 'a8c623d3-62de-485c-8447-4affc208c270', 'I''ve had a terrible toothache. I can''t stand the pain anymore. I have never experienced this pain in fifty eight years.', 1527338192310, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114067, 'user2', 'a8c623d3-62de-485c-8447-4affc208c270', 'Where are you experiencing the most pain? And when did this pain start?', 1527338197875, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114068, 'user2', 'a8c623d3-62de-485c-8447-4affc208c270', 'I see. When was the last time you visited the dentist?', 1527338208428, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114069, 'user2', 'a8c623d3-62de-485c-8447-4affc208c270', 'That doesn''t sound the least bit comfortable. Let''s get you feeling better. Do you think it''s related to your tooth?', 1527338196113, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114070, 'user2', 'a8c623d3-62de-485c-8447-4affc208c270', 'Have you noticed any facial swelling since all of this started?', 1527338215525, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114071, 'user1', 'a8c623d3-62de-485c-8447-4affc208c270', 'No, no swelling.', 1527338212459, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114072, 'user2', 'a8c623d3-62de-485c-8447-4affc208c270', 'Any headaches, throat swelling, sore throat, difficulty swallowing or chewing?', 1527338200555, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114073, 'user1', 'a8c623d3-62de-485c-8447-4affc208c270', 'No.', 1527338248340, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114074, 'user2', 'a8c623d3-62de-485c-8447-4affc208c270', 'How about any neck pain, swollen lymph nodes, chills, fever, or other symptoms?', 1527338224379, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114075, 'user1', 'a8c623d3-62de-485c-8447-4affc208c270', 'No, thank goodness.', 1527338254060, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114076, 'user1', 'a8c623d3-62de-485c-8447-4affc208c270', 'It started about three weeks ago. It''s mostly on the left side of my mouth. Kind of on the lower end. It goes from my jaw all the way up to my left ear.', 1527338192057, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114077, 'user1', 'a8c623d3-62de-485c-8447-4affc208c270', 'About two months ago for a routine clean.', 1527338209925, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114078, 'user1', 'a8c623d3-62de-485c-8447-4affc208c270', 'No, I don''t think so. I''m pretty good at making my dentist appointments, although I haven''t been in since this new pain started.', 1527338197910, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114079, 'user2', '0be09e03-24f9-4603-bd18-8f53a17adeaf', 'How long has your finger been in pain, sir?', 1363474422806, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114080, 'user1', '0be09e03-24f9-4603-bd18-8f53a17adeaf', 'Well, at this point, it''s been more than a few months.', 1363474426252, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114081, 'user1', '0be09e03-24f9-4603-bd18-8f53a17adeaf', 'Yeah, actually, they''re right here.', 1363474429439, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114082, 'user2', '0be09e03-24f9-4603-bd18-8f53a17adeaf', 'Okay, so I see you have a trigger finger, and a mucous cyst, and this other doctor gave you injections. Is that correct?', 1363474443891, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114083, 'user1', '0be09e03-24f9-4603-bd18-8f53a17adeaf', 'Yes sir.', 1363474450533, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114084, 'user2', '0be09e03-24f9-4603-bd18-8f53a17adeaf', 'Did the injections help at all?', 1363474435632, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114085, 'user1', '0be09e03-24f9-4603-bd18-8f53a17adeaf', 'No sir, honestly, they did nothing.', 1363474474605, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114086, 'user2', '0be09e03-24f9-4603-bd18-8f53a17adeaf', 'So, your finger is still locking today?', 1363474467665, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114087, 'user1', '0be09e03-24f9-4603-bd18-8f53a17adeaf', 'Yes sir, the other doctor referred me over here to see if there was anything more we could do. I''d like to try surgery.', 1363474460303, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114088, 'user2', '0be09e03-24f9-4603-bd18-8f53a17adeaf', 'Have you seen another doctor for this pain?', 1363474433581, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114089, 'user1', '0be09e03-24f9-4603-bd18-8f53a17adeaf', 'Yeah, I saw another guy a little while ago.', 1363474431940, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114090, 'user2', '0be09e03-24f9-4603-bd18-8f53a17adeaf', 'Do you have the records from the visit?', 1363474445015, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114091, 'user2', 'cb7b8129-4ca9-423d-92c6-3e65d776c082', 'Hello, I am Doctor James.', 1102216207702, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114092, 'user1', 'cb7b8129-4ca9-423d-92c6-3e65d776c082', 'Hi Doctor, this is my daughter Miya, and I am Jena.', 1102216211412, 1);
