INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114094, 'user1', 'cb7b8129-4ca9-423d-92c6-3e65d776c082', 'She has been complaining about it for almost six hours now.', 1102216243489, 6);
