INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114111, 'user2', 'cb7b8129-4ca9-423d-92c6-3e65d776c082', 'Okay, so tell me what is going on with you?', 1102216215044, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114112, 'user2', 'c0e76f5c-d59f-4359-a058-d9f89bd58669', 'And you said you''re right handed, correct?', 997108020185, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114113, 'user1', 'c0e76f5c-d59f-4359-a058-d9f89bd58669', 'Yep. Right handed.', 997108021975, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114114, 'user2', 'c0e76f5c-d59f-4359-a058-d9f89bd58669', 'Okay, great. I''ve made note of it in your chart. I have one more question to ask regarding tobacco and alcohol. Do you smoke or drink?', 997108025556, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114115, 'user1', 'c0e76f5c-d59f-4359-a058-d9f89bd58669', 'I don''t do either. I can''t even think of the last time I took a sip of alcohol.', 997108024533, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114116, 'user2', 'd4127a2e-193c-41fd-b578-c488d051d7ae', 'What brings him in today?', 1485120189479, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114117, 'user2', 'd4127a2e-193c-41fd-b578-c488d051d7ae', 'He''s here for sepsis and I suspect he may have spontaneous bacterial peritonitis.', 1485120193602, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114118, 'user2', 'd4127a2e-193c-41fd-b578-c488d051d7ae', 'Let me pull up his chart.', 1485120200995, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114119, 'user2', '49f47249-3f1e-4fad-8f54-5ab573f6c5e5', 'Let''s check your throat. Okay, I don''t see any swelling or any mass. Is there any pain when I touch you?', 1197463409224, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114120, 'user1', '49f47249-3f1e-4fad-8f54-5ab573f6c5e5', 'No pain.', 1197463414271, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114121, 'user2', '49f47249-3f1e-4fad-8f54-5ab573f6c5e5', 'I don''t feel any kind of lump in your throat. That is a good sign. It looks very flexible and symmetric.', 1197463419679, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114122, 'user1', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'Good afternoon, doctor.', 1072189007146, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114123, 'user2', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'Remind me, please, how old are you?', 1072189011974, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114124, 'user2', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'Is the pain messing with your ability to do activities?', 1072189022640, 5);
