INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114126, 'user2', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'What kind of treatments have you had so far?', 1072189014690, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114127, 'user1', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'Another doctor called it conservative treatment, um, I''ve taken antiinflammatories and had some injections.', 1072189054222, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114128, 'user2', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'Do you remember what kind of injections you''ve had?', 1072189022684, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114129, 'user1', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'It was, um, cortisone, and Synvisc.', 1072189046553, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114130, 'user2', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'Did these relieve the pain at all?', 1072189042179, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114131, 'user1', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'Well, it was only a temporary relief. Is there anything else we can do?', 1072189063218, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114132, 'user2', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'Well, there is surgery for this.', 1072189036671, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114133, 'user1', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'What are the risks of infection from the surgery?', 1072189066001, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114134, 'user2', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'Historically, it''s less than one percent.', 1072189093035, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114135, 'user1', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'How is this possible?', 1072189036755, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114136, 'user2', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'We use prophylactic antibiotics in order to eliminate the risk.', 1072189063698, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114137, 'user1', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'That''s great, I''ve heard of D V T from the commercials, is there a risk for that?', 1072189096143, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114138, 'user2', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'There''s a risk, but it''s low. Other risks are pulmonary embolism, need for further surgery, and further pain.', 1072189120152, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114139, 'user1', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'Okay, yes, I''d like to do the surgery.', 1072189059008, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114140, 'user1', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'I''m sixty nine years old, doctor.', 1072189015703, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114141, 'user2', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'Thank you, what seems to be the problem today?', 1072189024680, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114142, 'user1', 'c1b0922d-9cd8-4cc3-ba06-b5341bb03810', 'Oh, I''ve had pain in these knees for years, but it''s been getting a lot worse over the last few months.', 1072189011390, 4);
