INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114175, 'user3', '97729ebc-5555-4005-8b95-65ecd16b6fe5', 'Okay. Hm, are you experiencing any eye pain, blurred vision, or sensitivity to light?', 1293843844318, 4);
