INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114292, 'user3', '16775652-1863-494c-b98f-1bcbb21c5786', 'Of course. So, their son severely injured his left distal humerus. No problems were claimed before the injury. The E R saw him for his deformed elbow.', 955448092617, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114293, 'user3', '16775652-1863-494c-b98f-1bcbb21c5786', 'Are there any exams on the report?', 955448120253, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114294, 'user3', '16775652-1863-494c-b98f-1bcbb21c5786', 'There is an x ray and physical exam. They both confirmed a closed type three supracondylar fracture of his left distal humerus with severe puckering of the skin anteriorly with major ecchymosis in the same region. He did have a radial pulse palpable', 955448108124, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114295, 'user3', '16775652-1863-494c-b98f-1bcbb21c5786', 'Thank you, nurse. Mom, were you there before his surgery?', 955448124229, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114296, 'user1', '16775652-1863-494c-b98f-1bcbb21c5786', 'My husband and I were. My husband rushed from this cultural event he had planned.', 955448115126, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114297, 'user3', '16775652-1863-494c-b98f-1bcbb21c5786', 'I see. What do you all identify as?', 955448110789, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114298, 'user1', '16775652-1863-494c-b98f-1bcbb21c5786', 'We identify as white.', 955448141564, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114299, 'user3', '16775652-1863-494c-b98f-1bcbb21c5786', 'I see. I''m going to perform a neurological exam on your son now. Hi buddy. Is it fine if I do a quick exam?', 955448159607, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114300, 'user1', '16775652-1863-494c-b98f-1bcbb21c5786', 'Sure.', 955448144426, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114301, 'user3', '16775652-1863-494c-b98f-1bcbb21c5786', 'Thanks. It''ll be quick.', 955448119576, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114302, 'user1', '16775652-1863-494c-b98f-1bcbb21c5786', 'Okay.', 955448135388, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114303, 'user3', '16775652-1863-494c-b98f-1bcbb21c5786', 'After doing the exam I see his ulnar, median, and radial nerves are intact. I couldn''t do the entire exam because the pain might be too much for him.', 955448103034, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114304, 'user1', '16775652-1863-494c-b98f-1bcbb21c5786', 'Thank you so much for your help.', 955448153120, 22);
