INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114306, 'user1', '16775652-1863-494c-b98f-1bcbb21c5786', 'He was playing at the park and thought it was a good idea to jump off the swing. Crazy kid, right?', 955448094590, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114307, 'user1', '16775652-1863-494c-b98f-1bcbb21c5786', 'We just wanted to follow up after my son''s E R visit.', 955448088777, 3);
