INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114327, 'user1', 'bd393e06-7819-4d69-bf9e-de8e29f819b4', 'My uncle on my dad''s side of the family had kidney failure.  I lot of my family members have diabetes and asthma.', 1404950692730, 1);
