INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114336, 'user1', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'I don''t think so. Sometimes he even forgets his name.', 1350186012801, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114337, 'user1', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'He''s kidding. I know my name. I also know his kids'' names. I do agree that sometimes I forget my things or feel lost.', 1350186029383, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114338, 'user3', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'I don''t blame you. I forget my things at my age.', 1350186007375, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114339, 'user1', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'Yeah, it is something like episodic that he forgets everything and sometimes he''s absolutely normal. On good days, he''s very nice to talk to.', 1350186005537, 10);
