INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114342, 'user3', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'That''s good. So what brings you here in the emergency today?', 1350186012911, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114343, 'user1', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'He started complaining of stomach aches. Luckily, I was there. It was very sudden at one moment he was talking to me nicely and then all of a sudden he started complaining of severe pain in his stomach area. That''s when I decided to bring him here in the emergency room.', 1350186067080, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114344, 'user3', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'Do you have any previous reports?', 1350186028355, 15);
