INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114349, 'user1', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'Huh uh.', 1350186024006, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114350, 'user3', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'Okay, let me see what your scan says. I am reading the C T Scan report provided by the patient. It states that patient has dilated bladder with thick wall suggesting an outlet obstruction as well as bilateral hydronephrosis and hydroureter.', 1350186052242, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114351, 'user1', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'Hm.', 1350186023301, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114352, 'user3', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'I see that you have already been given some I V fluid along with antibiotics by the emergency room doctor.', 1350186019328, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114353, 'user1', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'Yeah.', 1350186126056, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114354, 'user3', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'Did he ever complain of pain during urination or nausea and vomiting?', 1350186026493, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114355, 'user1', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'Yes, he had fever a few days back. When we asked him about other symptoms, he said, it''s hard to urinate and it is painful. Nausea and vomiting are something that I am not sure about. He was normally rushing to the restroom and every time used to say he didn''t want to pee as it hurt him. He also had a few accidents in the last few days where he wet himself.', 1350186033534, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114356, 'user3', '820ac5f7-99c9-4541-8ac0-b493736b7fed', 'Thank you for providing me with all his history. It will be very helpful for me to treat him now.', 1350186115020, 27);
