INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114394, 'user3', 'a982abcf-c637-4f4a-8293-d47a97fed994', 'What happens when you take Clonidine?', 1652231952338, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114395, 'user3', '849645d5-481f-46b6-92e0-dce0201baffa', 'Good morning, ma''am. My nurses tell me that you''re thirty nine years old, is that correct?', 1410887084336, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114396, 'user1', '849645d5-481f-46b6-92e0-dce0201baffa', 'Good morning, Doctor. Yes, that''s correct.', 1410887086280, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114397, 'user3', '849645d5-481f-46b6-92e0-dce0201baffa', 'So, what seems to be the problem today, ma''am?', 1410887089223, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114398, 'user3', '849645d5-481f-46b6-92e0-dce0201baffa', 'Well, was it a twisting, pulling, snapping kind of injury?', 1410887095281, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114399, 'user1', '849645d5-481f-46b6-92e0-dce0201baffa', 'Oh, I twisted my knee.', 1410887106501, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114400, 'user3', '849645d5-481f-46b6-92e0-dce0201baffa', 'Okay, have you seen another doctor for this?', 1410887094735, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114401, 'user1', '849645d5-481f-46b6-92e0-dce0201baffa', 'Yeah, and I got an M R I.', 1410887106417, 9);
