INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114403, 'user1', '849645d5-481f-46b6-92e0-dce0201baffa', 'Yes, here you go.', 1410887103341, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114404, 'user3', '849645d5-481f-46b6-92e0-dce0201baffa', 'This M R I shows an A C L tear. Do you have any instability in this knee?', 1410887111118, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114405, 'user1', '849645d5-481f-46b6-92e0-dce0201baffa', 'Yeah, I feel like my knee joint has been unstable for years.', 1410887101101, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114406, 'user3', '849645d5-481f-46b6-92e0-dce0201baffa', 'Have there been any dislocations?', 1410887100334, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114407, 'user1', '849645d5-481f-46b6-92e0-dce0201baffa', 'Yeah, there have been. What can be done about this?', 1410887126585, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114408, 'user3', '849645d5-481f-46b6-92e0-dce0201baffa', 'Well, there''s surgery to fix this. I can repair that A C L.', 1410887158456, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114409, 'user1', '849645d5-481f-46b6-92e0-dce0201baffa', 'What are the risks of infection with the procedure?', 1410887132566, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114410, 'user3', '849645d5-481f-46b6-92e0-dce0201baffa', 'Historically, it''s less than one percent. We use antibiotics to control for infection.', 1410887144468, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114411, 'user1', '849645d5-481f-46b6-92e0-dce0201baffa', 'Will I go under for this?', 1410887191404, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114412, 'user3', '849645d5-481f-46b6-92e0-dce0201baffa', 'Yes, you won''t feel a thing.', 1410887104554, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114413, 'user1', '849645d5-481f-46b6-92e0-dce0201baffa', 'Okay, yes, I''d like the surgery done.', 1410887209166, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114414, 'user1', '849645d5-481f-46b6-92e0-dce0201baffa', 'I hurt my knee while on the trampoline back in late August.', 1410887096858, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114415, 'user3', '849645d5-481f-46b6-92e0-dce0201baffa', 'Do you remember the mechanism of injury to this knee?', 1410887096381, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114416, 'user1', '849645d5-481f-46b6-92e0-dce0201baffa', 'What do you mean?', 1410887098935, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114417, 'user3', '04a47bd3-8d7d-4afa-ba93-74aea4638ee5', 'Can you tell me more about your family history, ma''am? How is your father doing?', 1203134129443, 0);
