INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114419, 'user1', '04a47bd3-8d7d-4afa-ba93-74aea4638ee5', 'Oh, it''s okay doctor, thank you.', 1203134139180, 5);
