INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114421, 'user1', '04a47bd3-8d7d-4afa-ba93-74aea4638ee5', 'Yes, I have two brothers and five sisters.', 1203134162169, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114422, 'user3', '04a47bd3-8d7d-4afa-ba93-74aea4638ee5', 'That''s a big family, do they have any conditions that you know about?', 1203134166075, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114423, 'user1', '04a47bd3-8d7d-4afa-ba93-74aea4638ee5', 'One of my sisters has breast cancer.', 1203134145146, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114424, 'user3', '04a47bd3-8d7d-4afa-ba93-74aea4638ee5', 'Okay, thank you. Do you have any children?', 1203134151241, 10);
