INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114429, 'user1', '04a47bd3-8d7d-4afa-ba93-74aea4638ee5', 'Well, doctor, my father passed away from leukemia a while back.', 1203134134345, 1);
