INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114451, 'user1', 'cb7f2721-db61-4b66-99f4-26a6fdcd41f4', 'Right now, I work at Taco Bell. I have a workers comp claim open.', 1090094692790, 13);
