INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114533, 'user1', 'e8f6783f-fff2-46de-8cc8-753ed7dc0277', 'Yes, unfortunately. My dad died from myocardial infarction at fifty six years old. Not sure how old my mom was.', 1394555594995, 5);
