INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114582, 'user2', 'f4723dda-b9d2-4c1b-850b-776bdaae8b1a', 'It''s okay, I know. It is Lap Band.', 1219939636848, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114583, 'user2', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'Please, tell me a little more about your son.', 1560536473223, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114584, 'user2', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'Okay. I see he has previously had an operation on the right knee, can you tell me more about that?', 1560536483475, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114585, 'user2', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'Were there any other complications with the pregnancy?', 1560536478951, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114586, 'user2', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'When was this operation?', 1560536507951, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114587, 'user1', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'It was in February of two thousand seven.', 1560536496803, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114588, 'user2', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'How did he respond to the operation?', 1560536495119, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114589, 'user1', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'He responded really well, he was walking much better, and even got back to playing sports with the other kids in the neighborhood.', 1560536509444, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114590, 'user2', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'What seems to be the problem today?', 1560536489307, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114591, 'user1', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'Now, his left knee is getting really bad, it''s like how the right knee was. He can''t straighten this leg. I think we should do the same operation again on the left knee.', 1560536510444, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114592, 'user2', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'Yes, I think we''ll have to do surgery.', 1560536486124, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114593, 'user1', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'What is the risk of infection with the surgery?', 1560536535214, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114594, 'user2', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'Historically, it''s been less than one percent, we use prophylactic antibiotics in order to minimize infection risk.', 1560536509498, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114595, 'user1', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'Will he be under anesthesia for the procedure?', 1560536503700, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114596, 'user2', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'Yes, he will be. He won''t feel anything.', 1560536521976, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114597, 'user1', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'Will this completely solve his problem?', 1560536529836, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114598, 'user2', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'I can''t guarantee that he won''t need additional procedures in the future. The other risks include, bleeding, changes in sensation and motion to the leg, failure to restore normal anatomy, and risk it won''t work in general.', 1560536559815, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114599, 'user1', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'What''s the name of this procedure?', 1560536545711, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114600, 'user2', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'It''s called a distal medial hamstring release.', 1560536586137, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114601, 'user1', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'This is the same procedure he had in two thousand seven, right?', 1560536586987, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114602, 'user2', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'Yes ma''am, the exact same one.', 1560536539421, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114603, 'user1', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'Okay, that sounds good, we want to go through with the procedure.', 1560536597138, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114604, 'user2', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'Okay, here is my surgical scheduler''s business card, give them a call, and they can walk you through everything.', 1560536511132, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114605, 'user1', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'He previously had a lot of trouble straightening out both of his legs, and since the right was worse than the left he had an operation on the inside part of the back of that leg.', 1560536495590, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114606, 'user1', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'He was exposed to drugs in the womb while I was pregnant, and he has been diagnosed with autism.', 1560536480404, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114607, 'user1', '5c309462-d462-4a62-8f6b-a49d56ec1771', 'Well, he''s twelve years old now, but he was born at about a month and a half early.', 1560536476737, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114608, 'user1', '70a8920f-c25d-4f97-97e0-b84358bf2384', 'Oh doc, I''ve had a lot of trouble breathing lately.', 993756129708, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114609, 'user2', '70a8920f-c25d-4f97-97e0-b84358bf2384', 'I''m sorry to hear that. We''ll get to the bottom of it.', 993756134518, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114610, 'user2', '70a8920f-c25d-4f97-97e0-b84358bf2384', 'Any chest pain or tightness with the shortness of breath?', 993756145493, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114611, 'user1', '70a8920f-c25d-4f97-97e0-b84358bf2384', 'No, thankfully.', 993756141991, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114612, 'user2', '70a8920f-c25d-4f97-97e0-b84358bf2384', 'Any fever, chills, or sweats?', 993756148471, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114613, 'user1', '70a8920f-c25d-4f97-97e0-b84358bf2384', 'No.', 993756154226, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114614, 'user2', '70a8920f-c25d-4f97-97e0-b84358bf2384', 'Any cough or coughing up blood?', 993756140497, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114615, 'user1', '70a8920f-c25d-4f97-97e0-b84358bf2384', 'No.', 993756167201, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114616, 'user2', '70a8920f-c25d-4f97-97e0-b84358bf2384', 'How about wheezing or swelling in your legs?', 993756188694, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114617, 'user1', '70a8920f-c25d-4f97-97e0-b84358bf2384', 'No.', 993756172669, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114618, 'user1', '70a8920f-c25d-4f97-97e0-b84358bf2384', 'Yeah, I lose my breath so quickly with just one to two flights of stairs.', 993756141015, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114619, 'user2', '70a8920f-c25d-4f97-97e0-b84358bf2384', 'When did you first start noticing this?', 993756133230, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114620, 'user1', '70a8920f-c25d-4f97-97e0-b84358bf2384', 'I believe two weeks ago.', 993756138741, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114621, 'user3', '1d26beb4-2f1d-4167-b51d-bf20b8642460', 'Can you tell me more about your family medical history, sir? How''s your dad doing?', 1525084312130, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114622, 'user3', '1d26beb4-2f1d-4167-b51d-bf20b8642460', 'I''m sorry, that must be so hard.', 1525084323256, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114623, 'user1', '1d26beb4-2f1d-4167-b51d-bf20b8642460', 'Yes, it is, but I manage.', 1525084328777, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114624, 'user1', '1d26beb4-2f1d-4167-b51d-bf20b8642460', 'It''s okay, thank you. I lost her too. She had A L S.', 1525084325747, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114625, 'user1', '1d26beb4-2f1d-4167-b51d-bf20b8642460', 'Well, doctor, he passed away. He had mesothelioma.', 1525084316197, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114626, 'user3', '1d26beb4-2f1d-4167-b51d-bf20b8642460', 'I''m so sorry to hear that, sir. How is your mother?', 1525084321084, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114627, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'Good afternoon, who''s the victim today, sir? Is it you, or your daughter?', 1649755708718, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114628, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'Good afternoon, doctor. It''s my daughter today.', 1649755711465, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114629, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'Yeah, I fell off the swing at school earlier this afternoon at about one thirty.', 1649755736121, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114630, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'Where does it hurt, young lady?', 1649755716912, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114631, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'It''s really bad here on my left elbow.', 1649755731095, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114632, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'Which hand do you write with?', 1649755721678, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114633, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'I use my right hand for everything, thank goodness for that.', 1649755757140, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114634, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'I''m thirteen, sir.', 1649755720679, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114635, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'Yeah, we went to an Urgent Care and she had an x ray there.', 1649755741429, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114636, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'What else did they do?', 1649755752784, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114637, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'They said her arm was broken, and they tried to do a reduction.', 1649755760257, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114638, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'Do you have those x rays with you right now?', 1649755792701, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114639, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'Yeah, I have them right here, take a look, please.', 1649755730806, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114640, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'Well, these x rays show an incarcerated medial epicondyle fracture, as well as a mildly angulated radial shaft break.', 1649755728306, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114641, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'What does that mean?', 1649755754569, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114642, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'Well, in short, you broke the inside part of your elbow. In addition to the pain, do you have any burning or tingling feelings in that arm?', 1649755772098, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114643, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'Yes, I do.', 1649755782509, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114644, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'Did you have this before they tried to do a reduction?', 1649755809643, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114645, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'No, I didn''t, this is new.', 1649755746664, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114646, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'Is this feeling getting worse?', 1649755750527, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114647, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'Yes, it is.', 1649755755017, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114648, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'Okay, guys, there is a lot of pressure on that ulnar nerve because of the break and the attempted reduction.', 1649755752467, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114649, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'What should we do?', 1649755847776, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114650, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'We need to do an O R I F procedure A S A P. I''ll reduce that radial shaft fracture at the same time.', 1649755808958, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114651, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'O R I F? What''s that', 1649755761456, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114652, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'I''ll put some pins in the elbow, in order to stabilize the break, and we can start the healing process.', 1649755813641, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114653, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'Will this not heal on its own?', 1649755788459, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114654, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'No, we need to do the surgery.', 1649755781661, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114655, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'Okay, what are the risks of infection with the surgery?', 1649755764159, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114656, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'Historically, its less than one percent.', 1649755793508, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114657, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'How is this possible?', 1649755852987, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114658, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'We use prophylactic antibiotics, this helps us control for infection the entire time.', 1649755907204, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114659, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'Will she be asleep for this?', 1649755809778, 35);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114660, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'Yes, she won''t feel a thing.', 1649755852211, 36);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114661, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'Will she need this hardware taken out in the future?', 1649755850441, 37);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114662, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'Yes, in about a year or two, after everything is healed up nicely. The other risks include bleeding, changes in sensation and motion of the extremity, and hardware failure. I see good results from my surgeries so I would not worry about these things, but I must disclose.', 1649755924635, 38);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114663, 'user1', '9da1e45d-f833-4228-af9e-584234c925bc', 'Okay, yes, we''d like to do the surgery.', 1649755907823, 39);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114664, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'Remind me, how old is she?', 1649755715346, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114665, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'Before seeing me, have you seen anyone else?', 1649755740164, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114666, 'user3', '9da1e45d-f833-4228-af9e-584234c925bc', 'So, what happened? My nurses tell me she fell today.', 1649755716390, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114667, 'user1', '8b7fc357-b037-4c7c-b1c1-5516899704c2', 'Actually, my father passed away due to this disease.', 1184502416617, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114668, 'user1', '8b7fc357-b037-4c7c-b1c1-5516899704c2', 'Yeah.', 1184502429052, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114669, 'user1', '8b7fc357-b037-4c7c-b1c1-5516899704c2', 'Oh, he also had this spastic colon problem and irritable bowel syndrome.', 1184502443316, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114670, 'user2', '8b7fc357-b037-4c7c-b1c1-5516899704c2', 'Anything else that he or any other family member might have.', 1184502427360, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114671, 'user2', '8b7fc357-b037-4c7c-b1c1-5516899704c2', 'Hm, I see.', 1184502433894, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114672, 'user1', '8b7fc357-b037-4c7c-b1c1-5516899704c2', 'No.', 1184502423876, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114673, 'user2', '8b7fc357-b037-4c7c-b1c1-5516899704c2', 'Oh, sorry to hear that.', 1184502417828, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114674, 'user2', '8b7fc357-b037-4c7c-b1c1-5516899704c2', 'So, tell me did anyone in your family have Idiopathic pulmonary fibrosis?', 1184502414637, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114675, 'user2', '8b7fc357-b037-4c7c-b1c1-5516899704c2', 'Anything else?', 1184502440450, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114676, 'user1', 'f4ade237-392a-4898-9f39-2b6acdf51bbc', 'I am doing okay.', 1065269486626, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114677, 'user2', 'f4ade237-392a-4898-9f39-2b6acdf51bbc', 'Do you have any medical conditions?', 1065269492568, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114678, 'user1', 'f4ade237-392a-4898-9f39-2b6acdf51bbc', 'It was two thousand and three, I think. I also have high blood pressure, asthma and high cholesterol.', 1065269494099, 5);
