INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114680, 'user2', 'f4ade237-392a-4898-9f39-2b6acdf51bbc', 'When were you diagnosed with diabetes?', 1065269494973, 4);
