INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114973, 'user1', 'cdd46b09-0577-4d85-9c1e-08f80e4d93f3', 'They all are good.', 1729846783604, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114974, 'user2', 'cdd46b09-0577-4d85-9c1e-08f80e4d93f3', 'Are you aware of any medical issues in your family?', 1729846787532, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114975, 'user1', 'cdd46b09-0577-4d85-9c1e-08f80e4d93f3', 'No, not to my knowledge.', 1729846791736, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114976, 'user2', '98c925dc-c667-4e4c-9720-3e1547eeee33', 'Have you ever had spine problems before?', 1252662659163, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114977, 'user1', '98c925dc-c667-4e4c-9720-3e1547eeee33', 'What, like an injury?', 1252662661210, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114978, 'user2', '98c925dc-c667-4e4c-9720-3e1547eeee33', 'Well, it''s broad. It could be an injury, or just any kind of pain.', 1252662668984, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114979, 'user1', '98c925dc-c667-4e4c-9720-3e1547eeee33', 'Oh, no. I''ve never had any problems.', 1252662674573, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114980, 'user2', '762039dd-aff7-4718-ae09-1bb7d206b2b7', 'Any past medical history?', 1393526419523, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114981, 'user1', '762039dd-aff7-4718-ae09-1bb7d206b2b7', 'No.', 1393526420861, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114982, 'user2', 'e9c313f7-228c-4e19-a6af-d0117f679ff0', 'With ten being the worse pain ever, how would you rate your pain out of ten today, ma''am?', 1667840681422, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114983, 'user1', 'e9c313f7-228c-4e19-a6af-d0117f679ff0', 'Um, out of ten, I''d say it''s about a two.', 1667840684815, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114984, 'user2', 'e9c313f7-228c-4e19-a6af-d0117f679ff0', 'That''s good. What helps the pain feel better?', 1667840689914, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114985, 'user1', 'e9c313f7-228c-4e19-a6af-d0117f679ff0', 'Um, it gets better with elevation, and when I just rest.', 1667840687933, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114986, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Nurse, did you get the documents from the patient?', 1049743173550, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114987, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'I did. Here is her full history and notes from her physical examination. She also completed the patient questionnaire before arriving. You can review that.', 1049743176746, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114988, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Oh, yeah. These are the results from her tests. She brought them so you could refer to them.', 1049743178685, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114989, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Thank you, Nurse. I''ll go see her now.', 1049743203411, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114990, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Hello Doctor. I''ve been waiting a long time. I''m getting impatient as I get older.', 1049743183648, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114991, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'What? You don''t look old at all, ma''am.', 1049743218076, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114992, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Oh, wow. That''s a nice compliment for a sixty year old lady.', 1049743222961, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114993, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'I have these super bad headaches. Help me, please.', 1049743212106, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114994, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'When did they start?', 1049743193131, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114995, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'How can I help you today?', 1049743213996, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114996, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'I had them since I was twenty five years old.', 1049743193531, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114997, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Not every day. That''s crazy. I did get them more when my husband died in nineteen ninety six. I was heartbroken.', 1049743196548, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114998, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Oh, wow. That long? Did you get them every day since then?', 1049743219142, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (114999, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'I''m sorry to hear that. How did the headaches feel?', 1049743193602, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115000, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'It felt like a drum in my head.', 1049743249075, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115001, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'I haven''t heard that description before. Would you say it was pulsating?', 1049743241087, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115002, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Something like that. Yes.', 1049743234963, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115003, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Did you take any medication?', 1049743289530, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115004, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Lots of it. My son wrote it on a paper so that I could give you the names. Here you go.', 1049743277607, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115005, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'I see you were given papaverine. Did that help?', 1049743265925, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115006, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'They did. My headaches would vanish.', 1049743220648, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115007, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'How long did you take it for?', 1049743310211, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115008, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'I think six months. My headaches stopped for a while, but they came back in two thousand and four.', 1049743231197, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115009, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'How often would you say you get headaches now?', 1049743258752, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115010, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'I think more than before. Like one to two per week. I also get some dizziness too. It says for two hours.', 1049743229589, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115011, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Do you take the papaverine when you feel it?', 1049743252152, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115012, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'I do. My headaches vanish after thirty minutes of taking it.', 1049743275125, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115013, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'I see. Did you ever experience any problems with your vision too?', 1049743322269, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115014, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Yes. A lot. There were zig zag lines coming out of nowhere. I thought I was going to die.', 1049743217919, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115015, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Oh, wow. I will do a test right now to check your vision.', 1049743277550, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115016, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Will you use a bright pen?', 1049743303758, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115017, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'I will. Does it give you any discomfort?', 1049743365222, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115018, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'The bright light hurts my eyes.', 1049743357641, 35);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115019, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'I see. I''ll only do it to the side then. Just look forward for me, please.', 1049743264401, 36);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115020, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Thank you.', 1049743308888, 37);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115021, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Are you able to see the light?', 1049743377553, 38);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115022, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'What light?', 1049743363823, 39);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115023, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'It looks like you have trouble seeing things in your peripheral vision. The discomfort you experience with bright lights is also called photophobia.', 1049743383376, 40);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115024, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'That sounds scary. Will I be fine?', 1049743309945, 41);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115025, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Yeah. You don''t have to worry. Are you experiencing any dizziness or lightheadedness right now?', 1049743305668, 42);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115026, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Now that you mentioned it, I am.', 1049743427749, 43);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115027, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Have you ever fainted before?', 1049743337134, 44);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115028, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'I think one time. My son was there to help.', 1049743397669, 45);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115029, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'That''s good to hear. I''ll write down that you experienced a syncope. Did you take any medication for this?', 1049743296084, 46);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115030, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'I took some Russian medicine.', 1049743386471, 47);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115031, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Oh, wow. Are you from Russia?', 1049743231485, 48);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115032, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'No. I''m from Ukraine.', 1049743415213, 49);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115033, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'That''s wonderful. How did the medicine help?', 1049743249615, 50);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115034, 'user1', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'It helped me a lot.', 1049743373955, 51);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115035, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Thank you, Nurse. What is she here for today?', 1049743184140, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115036, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'She came in for a consultation because she''s been experiencing difficult headaches, tunnel vision, and dizziness.', 1049743183848, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115037, 'user2', 'ae43eb6e-0199-4b13-b054-a77400c3f530', 'Sounds good. Was there anything else?', 1049743190591, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115038, 'user2', '73428508-347e-4b5b-8e35-6b976802695c', 'Do you drink?', 951824298796, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115039, 'user1', '73428508-347e-4b5b-8e35-6b976802695c', 'I used to drink before, but now I have stopped it completely.', 951824303948, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115040, 'user1', '73428508-347e-4b5b-8e35-6b976802695c', 'Sometimes it gets hard, I really need some more pain medications.', 951824310393, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115041, 'user2', '73428508-347e-4b5b-8e35-6b976802695c', 'Do you have morphine? Do you need more?', 951824307239, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115042, 'user1', '73428508-347e-4b5b-8e35-6b976802695c', 'I don''t like morphine. Can you change it to Dilaudid? I like that medicine. That one works for me great.', 951824316829, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115043, 'user2', '73428508-347e-4b5b-8e35-6b976802695c', 'How would you rate your pain?', 951824300846, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115044, 'user2', '73428508-347e-4b5b-8e35-6b976802695c', 'Then why do you need more pain medications?', 951824321071, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115045, 'user1', '73428508-347e-4b5b-8e35-6b976802695c', 'It is tolerable, like five out of ten but I do need some pain medications.', 951824312548, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115046, 'user3', '9bf9f388-7cd2-40f3-8700-861db08a270d', 'She has a vast history of surgeries.', 1531858755182, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115047, 'user3', '9bf9f388-7cd2-40f3-8700-861db08a270d', 'Yeah, I am looking at her reports. She had surgery for spina bifida when she was a baby and they had to put a shunt.', 1531858757166, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115048, 'user3', '9bf9f388-7cd2-40f3-8700-861db08a270d', 'Yeah, later she had her uterus removed and also had to undergo a breast reduction surgery.', 1531858763819, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115049, 'user3', '9bf9f388-7cd2-40f3-8700-861db08a270d', 'Hm.', 1531858759729, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115050, 'user2', '6011205c-55f5-4e8c-968a-87e03a991f1e', 'Are you married or divorced?', 1289039988291, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115051, 'user1', '6011205c-55f5-4e8c-968a-87e03a991f1e', 'I am married.', 1289039990851, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115052, 'user1', '6011205c-55f5-4e8c-968a-87e03a991f1e', 'No, I have never.', 1289040005471, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115053, 'user1', '6011205c-55f5-4e8c-968a-87e03a991f1e', 'Hm.', 1289039996721, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115054, 'user2', '6011205c-55f5-4e8c-968a-87e03a991f1e', 'Do you smoke cigarettes or drink alcohol?', 1289040011561, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115055, 'user2', '6011205c-55f5-4e8c-968a-87e03a991f1e', 'Okay.', 1289039991418, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115056, 'user2', 'b5f19a35-2ce4-46ae-b0d6-05866193c3bf', 'What is your family medical history?', 1685701510296, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115057, 'user1', 'b5f19a35-2ce4-46ae-b0d6-05866193c3bf', 'I am not sure. Everyone is healthy as far as I know.', 1685701512135, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115058, 'user3', 'c823844a-95eb-4d68-bacd-74e1ed6728f1', 'Good morning, ma''am. My chart says that you''re forty nine years old, and White, is that correct?', 1338508007550, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115059, 'user1', 'c823844a-95eb-4d68-bacd-74e1ed6728f1', 'Yes, that''s all correct.', 1338508013230, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115060, 'user1', 'c823844a-95eb-4d68-bacd-74e1ed6728f1', 'Um, I think it was on August tenth two thousand four.', 1338508035557, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115061, 'user3', 'c823844a-95eb-4d68-bacd-74e1ed6728f1', 'Good, that''s what I have here as well, so has your acne improved since your last visit?', 1338508034350, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115062, 'user1', 'c823844a-95eb-4d68-bacd-74e1ed6728f1', 'Well, not really, and I think I have a rash too.', 1338508043315, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115063, 'user3', 'c823844a-95eb-4d68-bacd-74e1ed6728f1', 'How long have you been dealing with this?', 1338508045546, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115064, 'user1', 'c823844a-95eb-4d68-bacd-74e1ed6728f1', 'Um, at this point it''s been about two months.', 1338508048972, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115065, 'user3', 'c823844a-95eb-4d68-bacd-74e1ed6728f1', 'Where do you see this rash?', 1338508019583, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115066, 'user1', 'c823844a-95eb-4d68-bacd-74e1ed6728f1', 'Um, it''s right here, on my chest, stomach, neck, and back, it''s all over my upper body.', 1338508059557, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115067, 'user3', 'c823844a-95eb-4d68-bacd-74e1ed6728f1', 'I see, it appears that your acne is flaring, and there are small lesions on the follicles as well. Have you been taking your Amoxicillin and using your Tazorac?', 1338508054894, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115068, 'user1', 'c823844a-95eb-4d68-bacd-74e1ed6728f1', 'Yeah, I taken five hundred M G of amoxicillin twice a day, and I use the cream as well.', 1338508080165, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115069, 'user3', 'c823844a-95eb-4d68-bacd-74e1ed6728f1', 'Good, the acne on your face appears to be clearing.', 1338508070075, 14);
