INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115074, 'user3', 'c823844a-95eb-4d68-bacd-74e1ed6728f1', 'Great, welcome back to the Dermatology office, do you remember when your last appointment was?', 1338508029295, 4);
