INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115464, 'user3', '82ee4e73-b78b-46a1-8f48-ee985d559114', 'Great. That should be easy. How has the stress management been going to control the acne?', 1357356965172, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115465, 'user3', '79007049-f18b-4885-a000-5be04658df12', 'So I have here that you''re taking three different medications.', 1377576018107, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115466, 'user3', '79007049-f18b-4885-a000-5be04658df12', 'I see. That''s good. Did you refill your prescriptions with the newly revised doses? It looks like they changed the dosing of your medications at the hospital.', 1377576021466, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115467, 'user1', '79007049-f18b-4885-a000-5be04658df12', 'Um I''ve just been taking what I have at home.', 1377576036033, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115468, 'user1', '79007049-f18b-4885-a000-5be04658df12', 'Yeah. I''ve been taking them every day just like they told me to.', 1377576020208, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115469, 'user3', '79007049-f18b-4885-a000-5be04658df12', 'I advise that you take the doses that they prescribed. If you''d like me to put in a new order, please let me know.', 1377576034984, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115470, 'user1', '79007049-f18b-4885-a000-5be04658df12', 'Okay, yeah that''s fine. I can pick it up on my way home. I didn''t think the dosing mattered much as long as I took the meds every day.', 1377576031500, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115471, 'user3', '24573e5f-ee3e-4d66-885d-fbe58041226c', 'Any major surgeries in the past?', 1564977554205, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115472, 'user1', '24573e5f-ee3e-4d66-885d-fbe58041226c', 'Not too many, but a catheter was put in my heart.', 1564977560180, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115473, 'user3', '24573e5f-ee3e-4d66-885d-fbe58041226c', 'Oh, so cardiac catherization, correct?', 1564977564414, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115474, 'user1', '24573e5f-ee3e-4d66-885d-fbe58041226c', 'Yep.', 1564977562860, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115475, 'user2', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Hello, sir. I see you''re being seen for an evaluation for your allergy. Can you please confirm your age?', 1421096190675, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115476, 'user2', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Who told you to have a follow up?', 1421096208257, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115477, 'user1', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'One of the E R doctors and the kidney doctor.', 1421096207994, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115478, 'user2', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'I see. Your records indicate you had some swelling around the eye on May third of two thousand and eight. The cause was unknown. I see you were transferred from A B C Medical Center to X Y Z Medical center that day.', 1421096209870, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115479, 'user1', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Yeah, that sounds about right. Were there more details about that?', 1421096200575, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115480, 'user2', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Yeah, there is. It says here you have a history of renal failure, so you needed dialysis. They believe the allergic reaction was due to this medicine called, Keflex, which was used during your dialysis treatment. Does that name ring a bell?', 1421096225534, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115481, 'user1', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Yeah, it does. I forgot why they gave it to me.', 1421096217707, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115482, 'user2', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Usually, Keflex is used to treat a skin cellulitis dialysis shunt infection.', 1421096223583, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115483, 'user1', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Oh, I see.', 1421096232423, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115484, 'user2', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'I would like to ask you more about your allergies. What would you say you''re allergic to?', 1421096224936, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115485, 'user1', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'I''ve had a lot of problems with grass and sometimes pollen.', 1421096242123, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115486, 'user2', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'I see. I''ll put that down as grass allergies, and environmental and inhalant allergies. Do you have any life-threatening allergic reactions?', 1421096223200, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115487, 'user1', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Nope. Never had that.', 1421096224866, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115488, 'user2', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Have you ever had any swelling under the skin due to something you ate or touched?', 1421096267607, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115489, 'user1', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Nope. Never had that either.', 1421096217639, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115490, 'user2', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'That''s great. I''m taking a look at your medications. I see you aren''t taking anything for your allergies, but you are taking Atenolol. Do you have high blood pressure?', 1421096281832, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115491, 'user1', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Yeah, I do.', 1421096228796, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115492, 'user2', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'I see. All that''s left from your report are the treatments they gave you before you were discharged from the hospital.', 1421096236134, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115493, 'user1', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'What were the treatments they gave me?', 1421096213306, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115494, 'user2', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Looks like they monitored you the whole time and gave you some corticosteroid therapy and antihistamine therapy. You didn''t have any additional problems as well.', 1421096254384, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115495, 'user1', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Yeah, that''s right. Thirty four.', 1421096193534, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115496, 'user2', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Let me take a look at your medical records. I see you were treated at the A B C Medical Center for an allergic reaction, correct?', 1421096194765, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115497, 'user1', 'befe7688-e3cc-4b1e-8904-e24f7d25007a', 'Yeah. I was rushed to the hospital that day. After, they told me to get checked for a follow up.', 1421096198022, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115498, 'user1', 'ab0a6c01-e040-4632-9860-d49b68d9256b', 'I don''t want to take anymore medications. I want to try some natural remedies to treat my high blood pressure. I am not going to take any prescription meds that''s it.', 1228196731423, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115499, 'user1', 'ab0a6c01-e040-4632-9860-d49b68d9256b', 'That is not true!', 1228196722135, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115500, 'user3', 'ab0a6c01-e040-4632-9860-d49b68d9256b', 'Miss Tara, you need to take your medications on time. You are hypertensive and your readings don''t look good.', 1228196728323, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115501, 'user1', 'ab0a6c01-e040-4632-9860-d49b68d9256b', 'Doctor, you must tell her. She has stopped taking her medications. And her blood pressure is out of control, she is angry all the time and not looking after herself at all.', 1228196717395, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115502, 'user3', 'ab0a6c01-e040-4632-9860-d49b68d9256b', 'If that''s the case then I will make note in your file that you are not complying.', 1228196731229, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115503, 'user1', 'ca30abd8-1a0b-4432-a5a4-c5ded0e18759', 'I think I got some allergy, my lips are swollen and its causing me difficulty in swallowing.', 1521481715143, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115504, 'user2', 'ca30abd8-1a0b-4432-a5a4-c5ded0e18759', 'Oh, let me take a look.', 1521481718593, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115505, 'user2', 'dc2f08ce-2614-4435-a534-b2a421d86541', 'Any medical history?', 1629324893545, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115506, 'user2', 'dc2f08ce-2614-4435-a534-b2a421d86541', 'Have you had surgeries in the past?', 1629324909410, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115507, 'user1', 'dc2f08ce-2614-4435-a534-b2a421d86541', 'I had surgery to get a few hemorrhoids removed back in two thousand and ten.', 1629324900463, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115508, 'user1', 'dc2f08ce-2614-4435-a534-b2a421d86541', 'Only for high blood pressure.', 1629324907939, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115509, 'user1', 'dc2f08ce-2614-4435-a534-b2a421d86541', 'Um I suffer from depression and high blood pressure.', 1629324898579, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115510, 'user2', 'dc2f08ce-2614-4435-a534-b2a421d86541', 'Are you taking anything for either?', 1629324898939, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115511, 'user3', 'd9ed43a6-b020-45f3-b38c-b8fbdda28fe9', 'Do you have a family history of any medical conditions, such as diabetes or heart disease?', 1696168804913, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115512, 'user1', 'd9ed43a6-b020-45f3-b38c-b8fbdda28fe9', 'No, nothing.', 1696168806815, 1);
