INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115515, 'user1', 'a33095c9-761f-429e-bdd7-c6ebb4f1a1c1', 'Go for it.', 1053505430711, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115516, 'user2', 'a33095c9-761f-429e-bdd7-c6ebb4f1a1c1', 'Do you drink or smoke?', 1053505445110, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115517, 'user1', 'a33095c9-761f-429e-bdd7-c6ebb4f1a1c1', 'I smoke about a third of a pack a day and I drink every now and again, but nothing crazy.', 1053505442682, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115518, 'user2', 'a33095c9-761f-429e-bdd7-c6ebb4f1a1c1', 'You must be so proud of your boys.', 1053505422955, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115519, 'user1', 'a33095c9-761f-429e-bdd7-c6ebb4f1a1c1', 'My wife and I always say how lucky we are.', 1053505436676, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115520, 'user1', 'a33095c9-761f-429e-bdd7-c6ebb4f1a1c1', 'They''re doing well, thank you. My three boys are all grown up. Hard to believe they''re living their own as young professionals. One of them is actually a G I doctor in San Diego, California.', 1053505421965, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115521, 'user2', 'f0c40316-d51a-42d8-bc1a-4debc2507e98', 'How''s it going, buddy? I haven''t seen you in a long time', 1030864399833, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115522, 'user1', 'f0c40316-d51a-42d8-bc1a-4debc2507e98', 'Hey, Doctor. It''s been a while. I''ve been doing well. Just here for my check up.', 1030864404357, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115523, 'user1', 'f0c40316-d51a-42d8-bc1a-4debc2507e98', 'Not that I know of. They''re all doing good.', 1030864409755, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115524, 'user1', 'f0c40316-d51a-42d8-bc1a-4debc2507e98', 'Yeah, they''re doing great. Nobody has been sick for a while.', 1030864414220, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115525, 'user2', 'f0c40316-d51a-42d8-bc1a-4debc2507e98', 'That''s great to hear. Nobody has new medical conditions either, right?', 1030864420329, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115526, 'user2', 'f0c40316-d51a-42d8-bc1a-4debc2507e98', 'Nice. How''s the family doing? Are they all well?', 1030864404788, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115527, 'user3', 'f628190e-b4dd-42c8-a167-21f4f693da6e', 'So, you and your husband live together, correct?', 1201677287151, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115528, 'user1', 'f628190e-b4dd-42c8-a167-21f4f693da6e', 'She''s most comfortable in her wheelchair, but she usually walks with a walker if she''s at home.', 1201677306425, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115529, 'user1', 'f628190e-b4dd-42c8-a167-21f4f693da6e', 'Yeah, he''s right.', 1201677316181, 5);
