INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115531, 'user1', 'f628190e-b4dd-42c8-a167-21f4f693da6e', 'If I were to guess, I''d say half the time.', 1201677300784, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115532, 'user3', 'f628190e-b4dd-42c8-a167-21f4f693da6e', 'Great.', 1201677308579, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115533, 'user1', 'f628190e-b4dd-42c8-a167-21f4f693da6e', 'If I''m nearby, I like to keep any eye on her incase she feels unstable and needs help sitting back down.', 1201677313169, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115534, 'user3', 'f628190e-b4dd-42c8-a167-21f4f693da6e', 'It''s good that you''re both looking out for each other. Now moving onto the last few questions. Do you smoke or drink?', 1201677299741, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115535, 'user1', 'f628190e-b4dd-42c8-a167-21f4f693da6e', 'No and no.', 1201677308194, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115536, 'user3', 'f628190e-b4dd-42c8-a167-21f4f693da6e', 'Did you smoke or drink in the past?', 1201677333464, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115537, 'user1', 'f628190e-b4dd-42c8-a167-21f4f693da6e', 'No.', 1201677334814, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115538, 'user3', 'f628190e-b4dd-42c8-a167-21f4f693da6e', 'Are you able to walk any distance without assistance?', 1201677304914, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115539, 'user1', 'f628190e-b4dd-42c8-a167-21f4f693da6e', 'Yes. It''s a miracle we''ve lasted this long.', 1201677292671, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115540, 'user1', 'f628190e-b4dd-42c8-a167-21f4f693da6e', 'Can''t argue that.', 1201677292104, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115541, 'user3', '0bf423bf-6cef-40d9-92f3-d80250a54cbe', 'You do not look so well today. What seems to be the problem?', 1568424506594, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115542, 'user1', '0bf423bf-6cef-40d9-92f3-d80250a54cbe', 'Well‚ I am having a hard time. My whole body aches and I am in pain.', 1568424511008, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115543, 'user3', '0bf423bf-6cef-40d9-92f3-d80250a54cbe', 'Do you have a history of drug use?', 1568424518064, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115544, 'user3', '0bf423bf-6cef-40d9-92f3-d80250a54cbe', 'Okay. How long have you been using?', 1568424516131, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115545, 'user1', '0bf423bf-6cef-40d9-92f3-d80250a54cbe', 'I don''t feel well. Maybe a year. I can''t sleep or eat.', 1568424515242, 7);
