INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115548, 'user1', '0bf423bf-6cef-40d9-92f3-d80250a54cbe', 'Well yes. I am detoxing.', 1568424512212, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115549, 'user3', '0bf423bf-6cef-40d9-92f3-d80250a54cbe', 'What kind of drugs have you been using?', 1568424530575, 4);
