INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115551, 'user3', 'f5d5d511-152c-48d0-b9bd-8b33526d2015', 'How would you rate your general health?', 1674401743189, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115552, 'user3', 'f5d5d511-152c-48d0-b9bd-8b33526d2015', 'Social support is very important, especially when you are processing the loss of a loved one.', 1674401757377, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115553, 'user1', 'f5d5d511-152c-48d0-b9bd-8b33526d2015', 'Absolutely.', 1674401762941, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115554, 'user3', 'f5d5d511-152c-48d0-b9bd-8b33526d2015', 'I have a few more questions before we move on. Any past medical problems?', 1674401765283, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115555, 'user1', 'f5d5d511-152c-48d0-b9bd-8b33526d2015', 'I used to have high blood pressure.', 1674401773714, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115556, 'user3', 'f5d5d511-152c-48d0-b9bd-8b33526d2015', 'When you say used to, do you mean it''s been resolved now?', 1674401752407, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115557, 'user1', 'f5d5d511-152c-48d0-b9bd-8b33526d2015', 'Yes.', 1674401795322, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115558, 'user3', 'f5d5d511-152c-48d0-b9bd-8b33526d2015', 'Great news. How about surgeries? Have you had any in the past?', 1674401802733, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115559, 'user1', 'f5d5d511-152c-48d0-b9bd-8b33526d2015', 'None whatsoever.', 1674401774399, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115560, 'user3', 'f5d5d511-152c-48d0-b9bd-8b33526d2015', 'I''m so sorry to hear about the loss of your husband. I can''t imagine how difficult that must''ve been. I''m glad that you sought the care that you needed to feel better at that time. Did this happen when you were living in the United States or Korea?', 1674401745950, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115561, 'user1', 'f5d5d511-152c-48d0-b9bd-8b33526d2015', 'No, I stay away from things like that.', 1674401802888, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115562, 'user1', 'f5d5d511-152c-48d0-b9bd-8b33526d2015', 'I''ve been in reasonably good health at least physically. I try to go on frequent walks and eat a clean diet. However, there was one instance where I was not well mentally. After my husband died in nineteen seventy five, I had what I believe was a nervous breakdown. As a result of this, I was hospitalized for several weeks and treated with E C T.', 1674401748538, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115563, 'user3', 'f5d5d511-152c-48d0-b9bd-8b33526d2015', 'Any alcohol or tobacco?', 1674401785691, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115564, 'user1', 'f5d5d511-152c-48d0-b9bd-8b33526d2015', 'This all happened when I was living in Korea. I''m grateful that I had my family and friends to support me.', 1674401757469, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115565, 'user2', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'Are you experiencing any headaches, or do you have any history of migraine?', 1613810072769, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115566, 'user1', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'No.', 1613810075401, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115567, 'user2', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'Any temporary loss of consciousness?', 1613810083959, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115568, 'user2', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'Any continuous sound you may hear?', 1613810097801, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115569, 'user1', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'No.', 1613810084082, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115570, 'user2', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'Okay so no tinnitus. Any mouth sores or ulcers?', 1613810083674, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115571, 'user1', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'Um, no.', 1613810085412, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115572, 'user2', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'Do you notice any change in your voice, any hoarseness?', 1613810103815, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115573, 'user1', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'No, nothing like that.', 1613810091067, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115574, 'user2', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'Did you notice any swelling in and around your mouth?', 1613810133867, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115575, 'user1', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'No, I did not.', 1613810133708, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115576, 'user2', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'Any history of goiter or swelling of your thyroid gland?', 1613810112432, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115577, 'user1', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'Nope.', 1613810116548, 15);
