INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115579, 'user1', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'No.', 1613810092074, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115580, 'user1', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'No.', 1613810089795, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115581, 'user2', 'ac495d2f-4826-4d05-8fe2-8f326f56ea3a', 'Any feeling of being off balance or fainting?', 1613810090331, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115582, 'user3', '33e0b73d-f528-4f6b-ba62-274fa1a1cbec', 'Hello, miss. How can I help?', 1043302341043, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115583, 'user3', '33e0b73d-f528-4f6b-ba62-274fa1a1cbec', 'You look beautiful and actually have a lot of fullness in the face.  It is great that you do not smoke and do not have history of skin disease. We can definitely help you with these minor issues.', 1043302343058, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115584, 'user1', '33e0b73d-f528-4f6b-ba62-274fa1a1cbec', 'Well, I just turned fifty seven this year and I would like to get rid of these wrinkles on my face. I don''t like them one bit.', 1043302346010, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115585, 'user1', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Good afternoon, doctor.', 1289297968620, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115586, 'user2', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Great, and you''ve had a rotator cuff repair before, correct?', 1289297974945, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115587, 'user1', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Yes, that''s correct.', 1289297986983, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115588, 'user2', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Good, well, what seems to be the problem today?', 1289297976282, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115589, 'user1', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'I''m still having a lot of pain in this shoulder.', 1289297993893, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115590, 'user2', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Oh no, have you had any recent imaging done on this shoulder?', 1289297990892, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115591, 'user1', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Yes, I had an M R I not too long ago, can you take a look? I have it right here.', 1289298018937, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115592, 'user2', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Thank you, yes, um, this M R I shows that you''ve torn that rotator cuff again.', 1289297995389, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115593, 'user1', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Oh no, can we do another surgery to repair it again?', 1289298030558, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115594, 'user2', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Yes, we''ll have to.', 1289298026946, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115595, 'user1', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'What''s the risk of infection of the surgery?', 1289298008915, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115596, 'user2', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Its less than one percent. We''ll use antibiotics to control for infection the entire time.', 1289298041293, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115597, 'user1', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Will I be asleep again?', 1289298018787, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115598, 'user2', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Yes, you won''t feel a thing.', 1289298051459, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115599, 'user1', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Great, yes, I''d like to go forward with the surgery. I need to get back to playing tennis.', 1289298041911, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115600, 'user2', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Good afternoon, ma''am.', 1289297965146, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115601, 'user2', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Remind me, how young are you?', 1289297976746, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115602, 'user1', '75e48246-e1d0-41e7-98e6-3390dfb50709', 'Oh doctor, you flatter me. I''m sixty two years old.', 1289297978722, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115603, 'user2', 'e418294e-91a2-48ee-a90d-5a546dab3a27', 'What brings you in today?', 1611685293481, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115604, 'user1', 'e418294e-91a2-48ee-a90d-5a546dab3a27', 'I dropped a glass and one of the broken pieces cut my foot pretty badly. There was a lot of blood.', 1611685299323, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115605, 'user1', 'e418294e-91a2-48ee-a90d-5a546dab3a27', 'No, it doesn''t hurt.', 1611685315175, 5);
