INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115615, 'user1', 'e418294e-91a2-48ee-a90d-5a546dab3a27', 'No.', 1611685332805, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115616, 'user2', 'e418294e-91a2-48ee-a90d-5a546dab3a27', 'Is the area still bleeding?', 1611685300359, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115617, 'user1', 'e418294e-91a2-48ee-a90d-5a546dab3a27', 'I got it to stop bleeding while I was waiting for my ride.', 1611685309225, 3);
