INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115621, 'user2', 'ecf9d377-3865-4389-970c-7135afb964d4', 'That''s great, congratulations on your retirement!', 1525826103948, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115622, 'user2', 'ecf9d377-3865-4389-970c-7135afb964d4', 'Do you drink, sir?', 1525826123593, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115623, 'user1', 'ecf9d377-3865-4389-970c-7135afb964d4', 'Well, not anymore, but I used to be an alcoholic.', 1525826114580, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115624, 'user1', 'ecf9d377-3865-4389-970c-7135afb964d4', 'Sure, I smoke about a half a pack of cigarettes a day.', 1525826105673, 5);
