INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115627, 'user2', '4769f3d9-7d32-4aa7-99eb-66da594b326b', 'Any surgical history?', 1440754143879, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115628, 'user1', '4769f3d9-7d32-4aa7-99eb-66da594b326b', 'I had my thyroids taken out.', 1440754148271, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115629, 'user1', '4769f3d9-7d32-4aa7-99eb-66da594b326b', 'Nothing out of the ordinary.', 1440754170937, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115630, 'user2', '4769f3d9-7d32-4aa7-99eb-66da594b326b', 'Who was the surgeon who did your thyroidectomy?', 1440754174065, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115631, 'user1', '4769f3d9-7d32-4aa7-99eb-66da594b326b', 'Doctor X.', 1440754168641, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115632, 'user2', '4769f3d9-7d32-4aa7-99eb-66da594b326b', 'What was the final diagnosis?', 1440754177504, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115633, 'user1', '4769f3d9-7d32-4aa7-99eb-66da594b326b', 'I had a growth on my thyroids.', 1440754164011, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115634, 'user2', '4769f3d9-7d32-4aa7-99eb-66da594b326b', 'Was the growth cancerous?', 1440754176506, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115635, 'user1', '4769f3d9-7d32-4aa7-99eb-66da594b326b', 'It was. I was initially reluctant to get them out, but I realized it was necessary. I didn''t have much of a choice if I wanted to live ya know.', 1440754164462, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115636, 'user2', '4769f3d9-7d32-4aa7-99eb-66da594b326b', 'That''s understandable. I''m sorry you had to go through that. Surgery is daunting, let alone surgery to remove cancer.', 1440754192316, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115637, 'user2', '4769f3d9-7d32-4aa7-99eb-66da594b326b', 'When did you have them taken out?', 1440754148919, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115638, 'user1', '4769f3d9-7d32-4aa7-99eb-66da594b326b', 'Hm three years ago. Man, time flies.', 1440754159449, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115639, 'user2', '4769f3d9-7d32-4aa7-99eb-66da594b326b', 'Did you experience any complications post surgery?', 1440754153460, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115640, 'user3', '46ef0d36-307f-4bfa-a230-40f13cc25797', 'Welcome in. I am Doctor Welch.', 950237859064, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115641, 'user1', '46ef0d36-307f-4bfa-a230-40f13cc25797', 'Thank you! It is nice to meet you.', 950237861559, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115642, 'user3', '46ef0d36-307f-4bfa-a230-40f13cc25797', 'How old is your daughter?', 950237864030, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115643, 'user3', '46ef0d36-307f-4bfa-a230-40f13cc25797', 'Mom I would like to start off with some questions regarding pregnancy, childbirth, and prior children.', 950237871979, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115644, 'user1', '46ef0d36-307f-4bfa-a230-40f13cc25797', 'Okay.', 950237897225, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115645, 'user3', '46ef0d36-307f-4bfa-a230-40f13cc25797', 'Do you have any other children?', 950237892170, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115646, 'user1', '46ef0d36-307f-4bfa-a230-40f13cc25797', 'No. She is my only child.', 950237891523, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115647, 'user1', '46ef0d36-307f-4bfa-a230-40f13cc25797', 'I had a very early miscarriage before getting pregnant again with her.', 950237911320, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115648, 'user3', '46ef0d36-307f-4bfa-a230-40f13cc25797', 'I am so sorry to hear that.', 950237928947, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115649, 'user3', '46ef0d36-307f-4bfa-a230-40f13cc25797', 'Have you ever had any miscarriages or abortions prior to having your daughter?', 950237893927, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115650, 'user1', '46ef0d36-307f-4bfa-a230-40f13cc25797', 'Thank you. I was difficult but when I got pregnant again with her, we were so overjoyed.', 950237903372, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115651, 'user3', '46ef0d36-307f-4bfa-a230-40f13cc25797', 'Did you have any difficulties or problems during your pregnancy with her.', 950237934581, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115652, 'user3', '46ef0d36-307f-4bfa-a230-40f13cc25797', 'How far along were you when you gave birth?', 950237944732, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115653, 'user1', '46ef0d36-307f-4bfa-a230-40f13cc25797', 'I had the flu in my seventh or eighth month of pregnancy. Other than that I had no problems.', 950237921781, 15);
