INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115757, 'user1', 'adf68d89-32ca-42a7-b6b1-2a02c7eaaf1f', 'He takes Metoprolol and Hydrochlorothiazide for his blood pressure.', 1326506343626, 16);
