INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115780, 'user1', '895c36bc-bd92-406e-89b7-8466b41a9b75', 'Yes it is.', 957297433519, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115781, 'user3', '895c36bc-bd92-406e-89b7-8466b41a9b75', 'Is that only for pain?', 957297434327, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115782, 'user2', '43c04701-eb97-4c05-b183-0652ac881fe2', 'Hello, doctor. Let me give you a run down as to what we are dealing with today. This patient was last seen in January two thousand and four. She is coming for a follow up on interstitial disease secondary to lupus pneumonitis. I will let her tell you more about what happened yesterday.', 1334850665997, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115783, 'user2', '43c04701-eb97-4c05-b183-0652ac881fe2', 'Thanks, nurse. How are you feeling today, miss? Welcome back to the Pulmonary Medicine Clinic. What happened yesterday?', 1334850667271, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115784, 'user2', '43c04701-eb97-4c05-b183-0652ac881fe2', 'Are you experiencing any coughing?', 1334850685914, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115785, 'user1', '43c04701-eb97-4c05-b183-0652ac881fe2', 'No, coughing at this moment.', 1334850684363, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115786, 'user1', '43c04701-eb97-4c05-b183-0652ac881fe2', 'Yesterday I noticed that I have some back and joint pain.  When I breathe deep my back hurts.', 1334850683851, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115787, 'user1', '43c04701-eb97-4c05-b183-0652ac881fe2', 'No, I already said I didn''t cough.', 1334850685823, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115788, 'user2', '43c04701-eb97-4c05-b183-0652ac881fe2', 'Okay. Any fevers or chills?', 1334850700175, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115789, 'user1', '43c04701-eb97-4c05-b183-0652ac881fe2', 'Nothing so far.', 1334850677137, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115790, 'user2', '43c04701-eb97-4c05-b183-0652ac881fe2', 'Do you have any other symptoms currently?', 1334850678991, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115791, 'user1', '43c04701-eb97-4c05-b183-0652ac881fe2', 'I do notice that I am more tired than usual.', 1334850696604, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115792, 'user1', '43c04701-eb97-4c05-b183-0652ac881fe2', 'Well, I was doing fine since last time. My respiratory issues have been great and I have had no major difficulties breathing.', 1334850675057, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115793, 'user1', '43c04701-eb97-4c05-b183-0652ac881fe2', 'No. I don''t have issues with breathing when I do daily activities.', 1334850684418, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115794, 'user2', '43c04701-eb97-4c05-b183-0652ac881fe2', 'Have you been producing any mucus the times that you do cough?', 1334850698183, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115795, 'user2', '43c04701-eb97-4c05-b183-0652ac881fe2', 'During physical activity do you seem out of breath or more tired than usual? I want to see if your pulmonary system is inhibited.', 1334850721968, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115796, 'user2', '43c04701-eb97-4c05-b183-0652ac881fe2', 'That''s good to hear. What happened yesterday that caused you to want to come in so urgently?', 1334850682906, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115797, 'user2', '4222797a-6b68-4c91-bfd1-32e127497981', 'Hello sir, it''s been a while since your last visit. How have you been?', 1242235119983, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115798, 'user1', '4222797a-6b68-4c91-bfd1-32e127497981', 'Hello doctor, yes, I have come a long way. I guess last time I was here was in two thousand and two if I am not wrong. Was does your system say?', 1242235125914, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115799, 'user1', '4222797a-6b68-4c91-bfd1-32e127497981', 'You got it all right doctor!', 1242235131420, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115800, 'user2', '4222797a-6b68-4c91-bfd1-32e127497981', 'Are you still working in that airplane company?', 1242235127856, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115801, 'user1', '4222797a-6b68-4c91-bfd1-32e127497981', 'Yes sir, still with Alaska Airlines but I have been promoted and work as a plane mechanic.', 1242235134771, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115802, 'user2', '4222797a-6b68-4c91-bfd1-32e127497981', 'That is so nice! Good for you man! So, tell me how can I help you today? What brought you to our dermatology department today?', 1242235159570, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115803, 'user1', '4222797a-6b68-4c91-bfd1-32e127497981', 'I''m having pain in my stomach on the right side and down here.', 1242235140722, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115804, 'user2', '4222797a-6b68-4c91-bfd1-32e127497981', 'Is it only on the right side or anywhere else?', 1242235165093, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115805, 'user1', '4222797a-6b68-4c91-bfd1-32e127497981', 'It is on both sides and now I can feel it on the middle part of my left thigh as well.', 1242235134841, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115806, 'user2', '4222797a-6b68-4c91-bfd1-32e127497981', 'Tell me more about it. How did it start? When did you first notice it?', 1242235159036, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115807, 'user1', '4222797a-6b68-4c91-bfd1-32e127497981', 'It''s been going on and off. It was not there for a while, but now it is like back again mainly on my tummy, down here. It is painful when I touch it. At first, I thought maybe I''m having shingles.', 1242235155009, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115808, 'user2', '4222797a-6b68-4c91-bfd1-32e127497981', 'When did you notice it?', 1242235190290, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115809, 'user1', '4222797a-6b68-4c91-bfd1-32e127497981', 'It all started before the holidays, I think one and a half months before the holidays. It is still going on for the past eight days in my tummy and the hips mainly on the right side.', 1242235177274, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115810, 'user2', '4222797a-6b68-4c91-bfd1-32e127497981', 'Did you get any treatment for this? Any over the counter medicines?', 1242235152783, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115811, 'user2', '4222797a-6b68-4c91-bfd1-32e127497981', 'You are right! It was August second of two thousand and two to be very precise.', 1242235126692, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115812, 'user2', '4222797a-6b68-4c91-bfd1-32e127497981', 'Okay, do you bathe every day?', 1242235179341, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115813, 'user2', '4222797a-6b68-4c91-bfd1-32e127497981', 'Okay, here is what I think, all your symptoms are pointing towards hyperesthesia. I would like to run some tests to find the underlying cause and then we will start the treatment. A nurse will come and take you to the lab. Does this sound good to you?', 1242235173648, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115814, 'user1', '4222797a-6b68-4c91-bfd1-32e127497981', 'Yes.', 1242235221896, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115815, 'user1', '4222797a-6b68-4c91-bfd1-32e127497981', 'No, as I told you I thought it was shingles, but then there was no change in the skin, no rashes, nothing. I was not sure what to take.', 1242235137619, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115816, 'user2', '4222797a-6b68-4c91-bfd1-32e127497981', 'Please confirm for the records, you are a white married man and must be forty nine years old now. Am I right?', 1242235130207, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115817, 'user1', '4222797a-6b68-4c91-bfd1-32e127497981', 'Yes, I do but I try to use as little soap as possible.', 1242235173806, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115818, 'user2', 'acbe0963-590f-4662-8dc4-68c34f337bc0', 'Are you finished with your cancer treatments?', 1474451828632, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115819, 'user1', 'acbe0963-590f-4662-8dc4-68c34f337bc0', 'Yes.  I am in remission now.', 1474451831415, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115820, 'user2', 'acbe0963-590f-4662-8dc4-68c34f337bc0', 'That is great! When was your last radiation treatment?', 1474451835413, 2);
