INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115822, 'user2', '1a447675-791e-491f-bd03-d3f925ddf623', 'Do you smoke?', 1317964755875, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115823, 'user1', '1a447675-791e-491f-bd03-d3f925ddf623', 'Yeah. I smoke about a pack a day.', 1317964761018, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115824, 'user1', '1a447675-791e-491f-bd03-d3f925ddf623', 'Okay. I''ll see what I can do.', 1317964784278, 5);
