INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115828, 'user1', '1a447675-791e-491f-bd03-d3f925ddf623', 'No, but I have two littles ones.', 1317964778327, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115829, 'user2', '1a447675-791e-491f-bd03-d3f925ddf623', 'Aw, how old are they?', 1317964783296, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115830, 'user1', '1a447675-791e-491f-bd03-d3f925ddf623', 'I have a four year old and a six year old.', 1317964780790, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115831, 'user2', '1a447675-791e-491f-bd03-d3f925ddf623', 'That''s great. I''m sure they keep you busy. Any hobbies?', 1317964781975, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115832, 'user1', '1a447675-791e-491f-bd03-d3f925ddf623', 'They really do, especially the four year old. As for hobbies, I like fixing up computers. I also like fishing, hiking, and camping with the family.', 1317964795915, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115833, 'user1', '1a447675-791e-491f-bd03-d3f925ddf623', 'Eh not really.', 1317964764147, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115834, 'user2', '1a447675-791e-491f-bd03-d3f925ddf623', 'As your doctor, I''d advise that you consider nicotine patches and find ways to break your smoking habit.', 1317964774830, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115835, 'user2', '1a447675-791e-491f-bd03-d3f925ddf623', 'Do you have any plans of quitting?', 1317964764291, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115836, 'user3', 'c22ce00a-d259-4d75-8804-fabf8a4a18e0', 'Good morning, ma''am. Before we begin today, can you confirm your age for me?', 1043475192528, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115837, 'user1', 'c22ce00a-d259-4d75-8804-fabf8a4a18e0', 'Good morning, doctor. Sure, I''m seventy nine years old.', 1043475195365, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115838, 'user1', 'c22ce00a-d259-4d75-8804-fabf8a4a18e0', 'Well, at this point I''d say it''s debilitating.', 1043475209181, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115839, 'user3', 'c22ce00a-d259-4d75-8804-fabf8a4a18e0', 'I see, so the antiinflammatories and rest haven''t helped at all?', 1043475213806, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115840, 'user1', 'c22ce00a-d259-4d75-8804-fabf8a4a18e0', 'No, I haven''t had any improvement, doctor. It''s still so bad.', 1043475200239, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115841, 'user3', 'c22ce00a-d259-4d75-8804-fabf8a4a18e0', 'I see, I believe you''d be a good candidate for a knee replacement.', 1043475221161, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115842, 'user1', 'c22ce00a-d259-4d75-8804-fabf8a4a18e0', 'Yes, I thought so. What are the risks of infection for the surgery?', 1043475229798, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115843, 'user3', 'c22ce00a-d259-4d75-8804-fabf8a4a18e0', 'Um, it''s less than one percent, we use prophylactic antibiotics to control for infection the entire time.', 1043475241635, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115844, 'user1', 'c22ce00a-d259-4d75-8804-fabf8a4a18e0', 'That''s great, what about anesthesia, will I be asleep for this?', 1043475229669, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115845, 'user3', 'c22ce00a-d259-4d75-8804-fabf8a4a18e0', 'Yes, you won''t feel a thing.', 1043475242622, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115846, 'user1', 'c22ce00a-d259-4d75-8804-fabf8a4a18e0', 'Great, yes, I''d like to do the surgery, doctor.', 1043475264439, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115847, 'user1', 'c22ce00a-d259-4d75-8804-fabf8a4a18e0', 'Well, I have this arthritis, as you know.', 1043475201886, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115848, 'user3', 'c22ce00a-d259-4d75-8804-fabf8a4a18e0', 'Yes, how would you describe your arthritis?', 1043475212910, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115849, 'user3', 'c22ce00a-d259-4d75-8804-fabf8a4a18e0', 'Great, thank you. What seems to be the problem today, ma''am?', 1043475201870, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115850, 'user2', 'bad8ac95-131e-46e1-8914-3385fb3bc424', 'Welcome to the clinic.', 1120103390765, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115851, 'user1', 'bad8ac95-131e-46e1-8914-3385fb3bc424', 'Thank you.', 1120103394936, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115852, 'user1', 'bad8ac95-131e-46e1-8914-3385fb3bc424', 'Yes! We have two kids.', 1120103415273, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115853, 'user2', 'bad8ac95-131e-46e1-8914-3385fb3bc424', 'Do you have any history or present use of tobacco, alcohol and recreational drugs or substances?', 1120103426281, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115854, 'user1', 'bad8ac95-131e-46e1-8914-3385fb3bc424', 'I have a glass of wine every once and a while but no to the rest.', 1120103404157, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115855, 'user2', 'bad8ac95-131e-46e1-8914-3385fb3bc424', 'Are you from the area?', 1120103401671, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115856, 'user1', 'bad8ac95-131e-46e1-8914-3385fb3bc424', 'I was born and raised in Iowa. My husband and I moved here twenty years ago, and we have been here ever since.', 1120103408429, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115857, 'user2', 'bad8ac95-131e-46e1-8914-3385fb3bc424', 'It is a wonderful city. Do you have kids?', 1120103394913, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115858, 'user3', 'da09fcad-b065-4de2-ad58-21aee4af15d7', 'Any of your family members have issues like seizures?', 1580018713454, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115859, 'user1', 'da09fcad-b065-4de2-ad58-21aee4af15d7', 'None on my father''s side, but, yeah, on my mom''s side some of the family members had seizures. Like, my mom had them during her childhood. I know that my great grandmother had it and so does my great aunt.', 1580018716076, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115860, 'user3', '8c8bef7e-1107-4c3b-a53f-614e2a9329fd', 'Do you have a sore throat, cough or earache?', 1634633809678, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115861, 'user1', '8c8bef7e-1107-4c3b-a53f-614e2a9329fd', 'No.', 1634633812370, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115862, 'user2', 'bdccebbd-4882-415b-b8b3-cb821c6df11e', 'Can you tell me what are the diseases you have been diagnosed with in the past?', 1327438368102, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115863, 'user1', 'bdccebbd-4882-415b-b8b3-cb821c6df11e', 'Sure, I have had hypertension, diabetes, asthma and cholesterol problem.', 1327438369570, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115864, 'user2', 'bdccebbd-4882-415b-b8b3-cb821c6df11e', 'Ok, is there anything else?', 1327438371846, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115865, 'user2', 'bdccebbd-4882-415b-b8b3-cb821c6df11e', 'Thank you!', 1327438381166, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115866, 'user2', 'bdccebbd-4882-415b-b8b3-cb821c6df11e', 'And it is type two diabetes, right?', 1327438389526, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115867, 'user1', 'bdccebbd-4882-415b-b8b3-cb821c6df11e', 'Yes.', 1327438387530, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115868, 'user1', 'bdccebbd-4882-415b-b8b3-cb821c6df11e', 'Nope.', 1327438376382, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115869, 'user2', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'Good afternoon, sir. Do you remember the details of your surgery?', 1172888148336, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115870, 'user1', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'No, can you remind me?', 1172888152487, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115871, 'user1', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'Sure, I have G E R D, and um, I B S.', 1172888159767, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115872, 'user2', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'Thank you, what about allergies, do those bother you?', 1172888177321, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115873, 'user2', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'Good, while you''re here, do you have any other conditions that I should be aware of?', 1172888154420, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115874, 'user2', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'Do you have them in the spring, or in the fall?', 1172888189962, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115875, 'user1', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'Actually, I have them in both. It''s really annoying.', 1172888181008, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115876, 'user2', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'What allergy symptoms do you have usually?', 1172888168707, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115877, 'user1', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'Um, another doctor called it a postnasal drip.', 1172888182581, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115878, 'user2', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'Okay, yes, I''m familiar with that. Have you ever had any other surgeries?', 1172888212966, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115879, 'user1', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'Yeah, um, I had a hernia removed and repaired some time ago.', 1172888226202, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115880, 'user2', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'I see, what about any other major medical conditions?', 1172888221714, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115881, 'user1', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'I''ve had carpal tunnel before.', 1172888230952, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115882, 'user2', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'Which hands did you have it in?', 1172888229355, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115883, 'user1', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'I''ve had it in both.', 1172888205844, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115884, 'user1', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'Um, it was about eighteen years ago now, so that was about nineteen eighty nine.', 1172888163265, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115885, 'user1', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'Yeah, unfortunately I have those.', 1172888157928, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115886, 'user2', 'a8d2b5e8-53cf-4f54-8704-b74b518af540', 'Well, um, we did a right orchiectomy due to your testicular cancer, when did you have that?', 1172888152400, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115887, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Good morning, Miss X Y Z, correct?', 1318796515243, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115888, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Good, thank you. Next, which hand do you write with?', 1318796539228, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115889, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Before we begin, I just need a few pieces of information. How old are you?', 1318796518919, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115890, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Finally, what do you do for a living?', 1318796536032, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115891, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'I''m an aircraft mechanic.', 1318796538521, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115892, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Very nice, so, how did you get hurt?', 1318796558794, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115893, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Um, I was working on repairing an airplane at work when I fell between the plane and one of the stands.', 1318796553082, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115894, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'How big was the gap that you stepped in?', 1318796573544, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115895, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Um, it was about a foot and a half.', 1318796526898, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115896, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Which knee did you hurt?', 1318796531128, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115897, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'It was my left knee.', 1318796567212, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115898, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Did you have surgery after the accident?', 1318796575666, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115899, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Yes I did, I had two arthroscopies, and an, um, patellar replacement after those.', 1318796597053, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115900, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Okay, yes, I see.', 1318796581076, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115901, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Then, I had a left knee replacement on Month D D, Y Y Y Y.', 1318796559763, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115902, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Do you have any imaging of this knee?', 1318796588561, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115903, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'I didn''t have any x rays done, but I have an MRI report and notes from Doctor A B C D.', 1318796572589, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115904, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Can I see that report?', 1318796573486, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115905, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Yes absolutely, here.', 1318796590810, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115906, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Okay, so this M R I from September two thousand six shows some nonspecific edema anterior to the patellar tendon, but thankfully there''s no evidence of fracture of ligamentous avulsion or abnormality.', 1318796643646, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115907, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'What does that mean?', 1318796591025, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115908, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'There''s some bleeding in the bone there, but nothing is broken or out of alignment.', 1318796554605, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115909, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Oh, thank you, that''s good.', 1318796557011, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115910, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Oh certainly, yes, it is. What treatments have you had for this knee, aside from surgery?', 1318796668877, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115911, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'I''ve done a full course of PT for this.', 1318796572435, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115912, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Where is your knee pain?', 1318796604927, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115913, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Mostly, it''s here in the front of the knee, and then on both sides, like the inside and outside.', 1318796688928, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115914, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Does the pain go down your leg at all?', 1318796612992, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115915, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Yes, it goes down my, is this the femur?', 1318796563021, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115916, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Yes, that''s the femur.', 1318796622562, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115917, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Then this must be my tibia, it goes down the front of that too.', 1318796580282, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115918, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Does it go into your thigh at all?', 1318796596223, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115919, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Yes, it goes into the back of my thigh. I feel numbness and tingling back there.', 1318796603421, 35);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115920, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Do you feel anything in the feet?', 1318796595577, 36);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115921, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Nope, my feet are completely normal, thankfully.', 1318796673881, 37);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115922, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Are you having any back pain?', 1318796663956, 38);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115923, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'A little, I feel something in my lower back, I''m not sure if it''s related.', 1318796637671, 39);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115924, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Does anything make your knee pain worse?', 1318796618441, 40);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115925, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Yeah, I can hardly walk anymore, it hurts so bad.', 1318796749327, 41);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115926, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'What kind of symptoms do you see when you walk on this?', 1318796638878, 42);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115927, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'I feel popping and grinding, and my knee swells up.', 1318796584580, 43);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115928, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'That numbness and tingling you feel in the thigh, do you feel that in the knee at all?', 1318796704098, 44);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115929, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Actually yes, it feels like pins and needles there.', 1318796650387, 45);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115930, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'What about this, when I touch the knee do you feel any abnormal discomfort or pain over the rest of the knee?', 1318796730703, 46);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115931, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'No, nothing out of the ordinary there.', 1318796648513, 47);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115932, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'What about this, this is the fibular head, which is where you feel the pins and needles. I''m applying pretty heavy pressure here, how would you describe what you''re feeling?', 1318796770943, 48);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115933, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Um, numbness, tingling, and then that same pins and needles feeling.', 1318796643337, 49);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115934, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Is there any instability?', 1318796631272, 50);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115935, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Yes, and there''s pain with it too.', 1318796655381, 51);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115936, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Are you working right now?', 1318796791682, 52);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115937, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'No, I''m not right now.', 1318796595012, 53);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115938, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Any allergies I should know about?', 1318796821651, 54);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115939, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Yes, actually, I''m allergic to a lot of pain medications.', 1318796810029, 55);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115940, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Okay, have there been any changes in how you''re walking?', 1318796608984, 56);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115941, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Yes, I had to change my walking pattern to take weight off my knee, and I think that has to do with my back pain.', 1318796789369, 57);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115942, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'That''s certainly a possibility. How would you describe your pain?', 1318796823333, 58);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115943, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'I''d say its constant, shooting, cramping, aching, throbbing, feels like it''s being pulled, sharp, and , um, stabbing. All of those words seem fitting.', 1318796772844, 59);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115944, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Okay, does the pain wake you up at night?', 1318796751781, 60);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115945, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Yeah, it does occasionally.', 1318796743719, 61);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115946, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Does anything make this feel better?', 1318796709846, 62);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115947, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Yeah, it gets a little better if I lay down or if I keep my leg elevated.', 1318796772533, 63);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115948, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Out of ten, with ten being the worst pain ever, how would you describe your pain on average?', 1318796579493, 64);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115949, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Um, I''d say six out of ten. That''s how it is right now, too.', 1318796789523, 65);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115950, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'What about at its worst?', 1318796590154, 66);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115951, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Easily, its ten out of ten.', 1318796617499, 67);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115952, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Finally, what about when the pain is at its least?', 1318796613659, 68);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115953, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Um, when it''s not too bad, I''d say it''s a three out of ten. I also have this other M R I report from September of O six, here.', 1318796722687, 69);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115954, 'user2', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Thanks. I see. They said that there is nonspecific edema anterior to the patellar tendon, but there is no acute fracture or any ligament abnormalities. That''s good.', 1318796690122, 70);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115955, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'Yes, that''s me, good morning doctor.', 1318796518948, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115956, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'I write with my right hand.', 1318796541884, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115957, 'user1', '36e0ca35-f74d-4a46-9104-d177073dbb14', 'I''m forty four years young, doctor.', 1318796522154, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115958, 'user3', '420c7b52-1b0c-47cf-99cb-081360e18212', 'How old are you?', 1598344615764, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115959, 'user3', '420c7b52-1b0c-47cf-99cb-081360e18212', 'How long have you had this back and buttock pain?', 1598344627651, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115960, 'user1', '420c7b52-1b0c-47cf-99cb-081360e18212', 'I identify as a female.', 1598344622777, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115961, 'user3', '420c7b52-1b0c-47cf-99cb-081360e18212', 'How have you been managing this?', 1598344627735, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115962, 'user1', '420c7b52-1b0c-47cf-99cb-081360e18212', 'Another doctor called this conservative treatment. I''ve been resting a lot, and using antiinflammatories.', 1598344627415, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115963, 'user3', '420c7b52-1b0c-47cf-99cb-081360e18212', 'Has there been any improvement?', 1598344640489, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115964, 'user1', '420c7b52-1b0c-47cf-99cb-081360e18212', 'Its been several months at this point, and honestly no, there''s been no improvement. I''m still in a lot of pain.', 1598344639381, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115965, 'user3', '420c7b52-1b0c-47cf-99cb-081360e18212', 'This C T Scan you had recently shows sclerosis, with some healing of a L five compression fracture, but if you look here, the healing is not complete.', 1598344648920, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115966, 'user1', '420c7b52-1b0c-47cf-99cb-081360e18212', 'What can we do about this? I''m in so much pain.', 1598344626994, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115967, 'user3', '420c7b52-1b0c-47cf-99cb-081360e18212', 'I believe you''d be a candidate for a bilateral L five kyphoplasty.', 1598344654072, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115968, 'user1', '420c7b52-1b0c-47cf-99cb-081360e18212', 'What''s that?', 1598344669613, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115969, 'user3', '420c7b52-1b0c-47cf-99cb-081360e18212', 'It''s a small procedure on that L five vertebra. Its minimally invasive, and we can actually do it as an outpatient procedure.', 1598344681178, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115970, 'user1', '420c7b52-1b0c-47cf-99cb-081360e18212', 'Oh, wow, that''s good to hear. What are the risks of infection?', 1598344666225, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115971, 'user3', '420c7b52-1b0c-47cf-99cb-081360e18212', 'Very low, historically, they''re less than one percent.', 1598344707846, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115972, 'user1', '420c7b52-1b0c-47cf-99cb-081360e18212', 'How is this possible?', 1598344703881, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115973, 'user3', '420c7b52-1b0c-47cf-99cb-081360e18212', 'We''ll use antibiotics in order to control for infection.', 1598344697260, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115974, 'user1', '420c7b52-1b0c-47cf-99cb-081360e18212', 'That''s great, will I be under anesthesia?', 1598344717160, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115975, 'user3', '420c7b52-1b0c-47cf-99cb-081360e18212', 'Yes, you''ll be asleep for the whole thing.', 1598344698657, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115976, 'user1', '420c7b52-1b0c-47cf-99cb-081360e18212', 'Great, yes, I''d like to have this done, I can''t keep living in this pain.', 1598344662585, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115977, 'user3', '420c7b52-1b0c-47cf-99cb-081360e18212', 'Awesome, I agree. Do you have control over your bladder and bowel movements?', 1598344720431, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115978, 'user1', '420c7b52-1b0c-47cf-99cb-081360e18212', 'Yes, thankfully, I have complete control over everything like that still.', 1598344691140, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115979, 'user3', '420c7b52-1b0c-47cf-99cb-081360e18212', 'Do you wear a brace or corset normally?', 1598344741222, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115980, 'user1', '420c7b52-1b0c-47cf-99cb-081360e18212', 'Yes, I usually wear both.', 1598344752039, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115981, 'user3', '420c7b52-1b0c-47cf-99cb-081360e18212', 'Okay, last question, can you notice any weakness in your body?', 1598344669100, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (115982, 'user1', '420c7b52-1b0c-47cf-99cb-081360e18212', 'No, I''m still very strong, even at my age.', 1598344771543, 27);
