INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116039, 'user2', '2f009e97-0574-42e0-8cff-5f8247c10804', 'What about any heart disease?', 1552066437931, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116040, 'user2', '2f009e97-0574-42e0-8cff-5f8247c10804', 'Can you tell me about any kind of medical traits that run in your family?', 1552066422073, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116041, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Hello, Nurse. Could you give me a run down on the eleven month old patient?', 1632862380437, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116042, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'The patient was presented with stage two neuroblastoma on the left when he was six weeks old. It was completely resected. It was shown not to be N Myc amplified and had some favorable Shimada histology.', 1632862381822, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116043, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'He is now being treated with it per protocol P nine six four one and not on study. His last chemotherapy appointment was on May twenty first two thousand and seven. They used carboplatin, cyclophosphamide, and doxorubicin.', 1632862393999, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116044, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'What did they do after chemotherapy?', 1632862401380, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116045, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'He received G C S F daily because he had neutropenia that delayed his second cycle.', 1632862411738, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116046, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Thank you, Nurse. I''ll go talk to the mother.', 1632862413620, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116047, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'No problem, Doctor.', 1632862401960, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116048, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Hello, ma''am. It''s nice to see you again. How is your little boy doing?', 1632862406597, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116049, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Did he receive any chemotherapy?', 1632862398510, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116050, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Is it getting worse?', 1632862423855, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116051, 'user1', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'I think it''s getting better now. It isn''t as stuffy.', 1632862402868, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116052, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'That''s good to hear. Has he been sick or had any fevers?', 1632862424676, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116053, 'user1', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Nope. Just the stuffy nose.', 1632862445065, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116054, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Has he been able to eat anything?', 1632862404456, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116055, 'user1', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'At times, he didn''t want to eat. It seemed like he wasn''t hungry.', 1632862453980, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116056, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Does he still have a reduced appetite?', 1632862440816, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116057, 'user1', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Not anymore. He''s starting to eat again.', 1632862415480, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116058, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Did he have any nausea or vomiting after he ate?', 1632862450211, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116059, 'user1', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Thankfully, no. I would have made my husband clean up the vomit.', 1632862423424, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116060, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'That''s great. Is he able to pee and poop fine? No diarrhea, right?', 1632862456919, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116061, 'user1', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'His poop has been solid. I haven''t seen anything bad about his pee either.', 1632862463521, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116062, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Great. Would you be able to open his mouth for me? I just want to check if everything''s fine inside.', 1632862432017, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116063, 'user1', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Of course. Say ah.', 1632862454540, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116064, 'user1', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Ah.', 1632862455470, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116065, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Thank you. Oh, wow. It looks like he''s showing some symptoms of thrush again.', 1632862435230, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116066, 'user1', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Oh, no. Should we restart fluconazole?', 1632862427815, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116067, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'It''s just a fungal infection inside the mouth. I''ll prescribe him fluconazole. It should get rid of it.', 1632862490329, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116068, 'user1', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Thank you so much. You all have been so helpful. My little boy is slowly getting better.', 1632862440876, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116069, 'user1', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Not so well. Since out last visit, he had a stuffy nose for a couple of days.', 1632862419210, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116070, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'Great. Did he have a follow up after?', 1632862391623, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116071, 'user3', 'b6fb40c1-bced-46fd-aaa7-0955433ff4b8', 'He did. There was a second primary in his right adrenal gland. They performed a biopsy, which was consistent with neuroblastoma with favorable Shimada histology.', 1632862385475, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116072, 'user2', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'So, how are long have you had pain in this hip?', 994469244231, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116073, 'user2', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'Have you seen another doctor for this, or am I the first?', 994469258124, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116074, 'user2', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'How old are you now?', 994469247796, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116075, 'user2', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'What did those doctors tell you?', 994469277255, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116076, 'user1', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'They thought it was low back pain, and something called, um, radiculopathy.', 994469259478, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116077, 'user2', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'Does your pain radiate into your legs?', 994469280045, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116078, 'user1', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'Yes.', 994469258036, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116079, 'user2', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'Has your pain been present for the eight years, or did it come and go?', 994469273460, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116080, 'user1', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'It''s been persistent, and I''ve had difficulties on and off since then.', 994469292212, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116081, 'user2', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'Okay. The x rays from Doctor A B C show severe degenerative changes as well as avascular necrosis of the femoral head. What else did the Doctor do for you?', 994469265372, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116082, 'user1', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'He gave me some pain medicine, and we talked about going to another specialist for surgery.', 994469272159, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116083, 'user2', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'Do you remember the names of the procedures suggested?', 994469281717, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116084, 'user1', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'Something about resurfacing the hip, or a hip replacement. I''m here for another opinion on that.', 994469322524, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116085, 'user2', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'I saw you come in with a cane, do you have groin pain as well?', 994469331410, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116086, 'user1', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'Yes, and I can''t do any of the activities I used to.', 994469286700, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116087, 'user2', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'Besides the pain medication, have you had anything else?', 994469291610, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116088, 'user1', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'I''ve taken antibiotic steroids before.', 994469337587, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116089, 'user2', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'Okay. Do you drink?', 994469362560, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116090, 'user1', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'Yes, a lot.', 994469336364, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116091, 'user1', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'I''m thirty two now, so I''ve been in pain since I was in my twenties.', 994469259857, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116092, 'user1', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'It''s been about eight or ten years now. It began while I was working in construction.', 994469249052, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116093, 'user1', 'f5eca60f-4dd0-47bb-b128-2c6f755866d3', 'Yeah, um, I''ve actually seen several doctors before, the last I saw was Doctor A B C a few weeks ago.', 994469253407, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116094, 'user2', 'cbe03cf8-90db-4617-9fb7-9e0f9ba511b0', 'Let me examine your skin.', 1578733382844, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116095, 'user1', 'cbe03cf8-90db-4617-9fb7-9e0f9ba511b0', 'Sure.', 1578733385144, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116096, 'user1', 'cbe03cf8-90db-4617-9fb7-9e0f9ba511b0', 'Yeah.', 1578733393390, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116097, 'user2', 'cbe03cf8-90db-4617-9fb7-9e0f9ba511b0', 'Its just a normal protocol to ask these questions for every new patient.', 1578733405878, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116098, 'user1', 'cbe03cf8-90db-4617-9fb7-9e0f9ba511b0', 'I understand.', 1578733404361, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116099, 'user2', 'cbe03cf8-90db-4617-9fb7-9e0f9ba511b0', 'Thank you for your cooperation.', 1578733427578, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116100, 'user2', 'cbe03cf8-90db-4617-9fb7-9e0f9ba511b0', 'It looks normal and well hydrated. Any excessive sweating?', 1578733390644, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116101, 'user1', 'cbe03cf8-90db-4617-9fb7-9e0f9ba511b0', 'No, not really.', 1578733397297, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116102, 'user2', 'cbe03cf8-90db-4617-9fb7-9e0f9ba511b0', 'I don''t see any injury or wounds.', 1578733395489, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116103, 'user3', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'Hi there! I am Doctor Kirkland.', 1374301747191, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116104, 'user3', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'That''s okay. Do you remember what happened to you before you came here?', 1374301767787, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116105, 'user3', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'How are you feeling?', 1374301756144, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116106, 'user3', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'Can you tell me about your past medical history?', 1374301768407, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116107, 'user1', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'Um.', 1374301755790, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116108, 'user3', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'Take your time.', 1374301774970, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116109, 'user1', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'I can''t think of what it is called. It''s something to do with my brain.', 1374301794600, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116110, 'user3', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'Okay.', 1374301759026, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116111, 'user1', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'My doctor knows what it is.', 1374301779562, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116112, 'user3', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'What is the name of your doctor?', 1374301780205, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116113, 'user1', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'No.', 1374301765365, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116114, 'user3', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'Doctor X? Across the street?', 1374301766048, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116115, 'user1', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'Yes, that is his name. I don''t know if that is across the street or not.', 1374301829039, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116116, 'user3', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'I will have your nurse give him a call and get some background information from him.', 1374301827246, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116117, 'user1', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'Okay.', 1374301803648, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116118, 'user3', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'Can you please give Doctor X a call and get mister Jones'' medical history?', 1374301806468, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116119, 'user3', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'Yes, of course.', 1374301811446, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116120, 'user3', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'Thank you.', 1374301840683, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116121, 'user1', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'Doctor Frank.', 1374301801232, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116122, 'user1', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'I feel weird. Like I feel confused. I don''t know how I got here.', 1374301758490, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116123, 'user1', 'f1677b88-5cea-4b69-8b85-c76a81c1e4ed', 'Hi.', 1374301750342, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116124, 'user2', '8d56f265-5cc7-47dc-8acb-2d862b31587e', 'Any issues from head to toe?', 1615743895831, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116125, 'user1', '8d56f265-5cc7-47dc-8acb-2d862b31587e', 'No, everything is fine.', 1615743901637, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116126, 'user3', '75dcc621-1997-4308-b71e-26bb8fb340dd', 'Hello, it''s been two months already?', 1199542275378, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116127, 'user1', '75dcc621-1997-4308-b71e-26bb8fb340dd', 'I know right?', 1199542278730, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116128, 'user3', '75dcc621-1997-4308-b71e-26bb8fb340dd', 'Just feels like yesterday.', 1199542284541, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116129, 'user2', '750c5303-abce-458b-943b-a8399bea7a48', 'Tell me about your family medical history.', 1561696744311, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116130, 'user1', '750c5303-abce-458b-943b-a8399bea7a48', 'No one in my family has any health problems.', 1561696750241, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116131, 'user2', 'd7bd7fd1-4b65-49c1-9a80-35705fe4e129', 'And are you working? What do you do?', 1545617830377, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116132, 'user2', 'd7bd7fd1-4b65-49c1-9a80-35705fe4e129', 'And if you don''t mind me asking, do you drink alcohol?', 1545617836488, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116133, 'user1', 'd7bd7fd1-4b65-49c1-9a80-35705fe4e129', 'Maybe that is something for my confession box but jokes apart I don''t drink.', 1545617842411, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116134, 'user2', 'd7bd7fd1-4b65-49c1-9a80-35705fe4e129', 'Sorry I need to ask these questions it''s a protocol.', 1545617841355, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116135, 'user1', 'd7bd7fd1-4b65-49c1-9a80-35705fe4e129', 'I understand.', 1545617838909, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116136, 'user2', 'd7bd7fd1-4b65-49c1-9a80-35705fe4e129', 'And can I put down here that you don''t smoke or use any kinds of drugs?', 1545617871881, 8);
