INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116142, 'user2', 'b057203c-2070-4b27-beb2-9d9cc5762035', 'Okay, so where do you live?', 1687248531896, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116143, 'user1', 'b057203c-2070-4b27-beb2-9d9cc5762035', 'I live at an old age nursing home.', 1687248536838, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116144, 'user2', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'So, he is Arjun, and he is thirty seven years old and was complaining of chest pain.', 1289984450173, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116145, 'user1', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'Hi Doctors, how are you?', 1289984454087, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116146, 'user2', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'We are good thanks for asking.', 1289984457743, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116147, 'user2', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'Hi there Arjun, I am doctor J and I am assisting Doctor Wilson today. So, chest pain huh?', 1289984461274, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116148, 'user2', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'Okay.', 1289984464542, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116149, 'user2', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'I did run a cardiac enzyme profile and it was negative.', 1289984459175, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116150, 'user2', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'Alright. And he also has hyperlipidemia?', 1289984465520, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116151, 'user2', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'Yes, he does.', 1289984491494, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116152, 'user2', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'Okay and did you order an E K G?', 1289984496088, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116153, 'user2', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'I did, it is normal too.', 1289984488623, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116154, 'user2', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'Don''t worry Arjun, we will take of you.', 1289984522393, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116155, 'user1', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'Thank you.', 1289984480562, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116156, 'user1', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'Yep.', 1289984473194, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116157, 'user2', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'And I see here no cardiac excretion was mentioned.', 1289984463830, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116158, 'user2', '2e54313c-19ac-4e86-9f70-88eede6968d2', 'Yeah. I am suspecting coronary spasm but that''s questionable.', 1289984470180, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116159, 'user2', '924c2d86-251f-4561-bed4-accdd6a6db5f', 'So, do you live in the area?', 1357633328642, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116160, 'user1', '924c2d86-251f-4561-bed4-accdd6a6db5f', 'Yes, my husband and I have lived here for a long time. He died a few years back.', 1357633329841, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116161, 'user1', '924c2d86-251f-4561-bed4-accdd6a6db5f', 'No, I don''t.', 1357633341958, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116162, 'user2', '924c2d86-251f-4561-bed4-accdd6a6db5f', 'Do you use any illicit drugs or substances?', 1357633358073, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116163, 'user2', '924c2d86-251f-4561-bed4-accdd6a6db5f', 'Do you smoke or drink?', 1357633351949, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116164, 'user2', '924c2d86-251f-4561-bed4-accdd6a6db5f', 'I''m sorry to hear that.', 1357633336667, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116165, 'user1', '924c2d86-251f-4561-bed4-accdd6a6db5f', 'It''s alright.', 1357633342922, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116166, 'user1', '924c2d86-251f-4561-bed4-accdd6a6db5f', 'No, I don''t do anything like that.', 1357633336485, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116167, 'user1', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Um, I take the generic for Ultracet. Sometimes I take as many as four times a day.', 1697261812455, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116168, 'user1', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Yes, doctor, that''s correct.', 1697261836192, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116169, 'user3', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'How long have you had this back pain?', 1697261840480, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116170, 'user1', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Well, it''s been a while now.', 1697261830519, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116171, 'user3', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Does the pain go into your legs?', 1697261831685, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116172, 'user1', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Yes, into the left leg, more towards the outside of my leg.', 1697261840025, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116173, 'user3', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Is there any injury that started this pain?', 1697261865503, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116174, 'user1', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Yeah, I was lifting at work on August twenty seventh two thousand three when I lifted something and felt a pretty sharp pain from my back down into my left leg.', 1697261850978, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116175, 'user3', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Have you had back pain or surgeries before this injury?', 1697261825060, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116176, 'user1', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'No, I haven''t.', 1697261882833, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116177, 'user3', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Are you having weakness in the legs?', 1697261889624, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116178, 'user1', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Yes, I am.', 1697261868797, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116179, 'user3', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Okay, I believe you are a good candidate for surgery, sir. It seems like you have a lot of weakness and pain in the S one nerve root distribution.', 1697261835528, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116180, 'user1', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Okay. What are the risks of infection for this surgery?', 1697261839148, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116181, 'user3', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Overall, the risk of infection is very low, less than one percent. We use antibiotics to control for infection the entire time.', 1697261867848, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116182, 'user1', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Will I be asleep for the surgery?', 1697261893126, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116183, 'user3', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Yes, you''ll be under anesthesia. You won''t feel a thing.', 1697261853835, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116184, 'user1', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Okay, yes. I''d like to do the surgery.', 1697261855703, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116185, 'user1', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'No, I''m still in pretty significant pain, doctor.', 1697261817550, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116186, 'user3', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Good morning, sir. My nurse''s chart says that you''re thirty four years old. Is that correct?', 1697261818279, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116187, 'user3', '7b1a55a2-1e7a-4691-9929-0541f166da14', 'Does this help the pain?', 1697261814180, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116188, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Hello, miss. Doctor X and I will be going over your medical history with you. Before we begin, could you confirm your age for me?', 1087847652816, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116189, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'What kind of procedures were done to address it?', 1087847668990, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116190, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'She had undergone a colonoscopy to address secondary diseases that may have been present because of the erythema nodosum, correct miss?', 1087847663823, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116191, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Yeah, that''s correct.', 1087847687472, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116192, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Were there any findings, Doctor X?', 1087847692647, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116193, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'The findings were uncertain if the terminal ileum had abnormal biopsies. However, the skin biopsy mentioned some fibrosis, basal proliferation, and inflammatory cells in the subcutis.', 1087847667703, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116194, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'I see. Her report states something about a tibia and fibula fracture on her right leg before the erythema nodosum. Are these skin lesions due to the fracture?', 1087847670117, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116195, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'The skin lesions are not associated with the fracture, correct ma''am?', 1087847681080, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116196, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'That''s correct. The cuts in my skins are on both legs too. Not just the right.', 1087847718719, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116197, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Thank you. Did anything occur before the skin lesions?', 1087847704439, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116198, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'She had cosmetic surgery done on her jaw.', 1087847717247, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116199, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Ma''am, I see you visited our clinic and the Dermatology several times, correct?', 1087847720533, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116200, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Yeah, that''s correct. I had a rash that I wanted to get checked.', 1087847742386, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116201, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'I remember that. I was here when she presented the rash. We suggested the rash in her lower extremities and ankles was erythema nodosum. She also had discomfort, which could have been inflammatory arthritis.', 1087847683959, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116202, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Doctor X, did you confirm with any tests?', 1087847678903, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116203, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Yes. There was an initial S E D above one hundred and ten and her C P R was increased.', 1087847720169, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116204, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Great. In the visits after, were there any other problems found?', 1087847714255, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116205, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'The reports says that no other abnormalities were found. However, I do see something about her first visit.', 1087847715338, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116206, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Could you explain what it says?', 1087847762719, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116207, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'She has some M T P detected, which could have been signs of erythema nodosum. However, the Dermatology did not agree, and they believed it to be venous stasis.', 1087847761935, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116208, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'The venous stasis could have been related to the fracture, right?', 1087847731753, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116209, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'That is correct.', 1087847709788, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116210, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Her initial visit reports suspicion of I B D, sarcoid inflammatory arthropathy, and lupus. Why was that?', 1087847694129, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116211, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'She had a questionable rheumatoid fracture even though her C C P was negative. Her A N A was positive at one to four zero. There was a persistent speckled pattern. However, the rest of the lupus serologies were negative.', 1087847779344, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116212, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'What lupus serologies were used?', 1087847750073, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116213, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Double stranded D N A, R N P, Smith, R O, and L A were used.', 1087847799052, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116214, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'How did her cardiolipin antibodies panel look?', 1087847815800, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116215, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'They were all negative. We made sure I g M, I g G, and I g A were less than ten.', 1087847736735, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116216, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'I see. Was there anything else in the report?', 1087847807585, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116217, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'She had her beta 2 glycoprotein one or R V V T tested.', 1087847750206, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116218, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'That seems important because of the livedo pattern.', 1087847704207, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116219, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Exactly. That''s why they concluded it was an onset of lupus and not rheumatoid arthritis because the arthritis couldn''t be associated with erythema nodosum.', 1087847735273, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116220, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Why did she undergo a C T scan?', 1087847811581, 35);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116221, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'We feared she had lymphoma. The scan of her chest, abdomen, and pelvis were done to rule out sarcoid.', 1087847744044, 36);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116222, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'I see. The results came out normal, right?', 1087847779739, 37);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116223, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'That''s correct.', 1087847849385, 38);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116224, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Did you change some of you habits to help your bowels, ma''am?', 1087847787406, 39);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116225, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'I tried my best to.', 1087847762353, 40);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116226, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'That''s good. What was found Doctor X?', 1087847766637, 41);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116227, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'There was evidence of B twelve deficiency with a high methylmalonic and high homocystine levels along with a low normal B twelve in addition to iron studies consistent with iron deficiency and an initially low M C V.', 1087847775427, 42);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116228, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'That gives the possibility of inflammatory bowel disease, right?', 1087847898028, 43);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116229, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Correct. That''s stated in the report.', 1087847905803, 44);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116230, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Were there any tests done to confirm this?', 1087847746716, 45);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116231, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'She underwent a colonoscopy, which showed nothing. Her endoscopy was also normal. Recently, she underwent a second coloscopy, and no evidence of inflammatory bowel disease was seen after viewing it microscopically.', 1087847772356, 46);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116232, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Nothing was seen microscopically?', 1087847885359, 47);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116233, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Actually, we determined there were aggregates of eosinophils.', 1087847712215, 48);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116234, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'That sounds important. That could be due to an allergic reaction or an emergence of Crohn Disease. I will have to discuss with Doctor Y from Gastroenterology to see the significance.', 1087847776526, 49);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116235, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Could I interrupt for a second? I don''t think my B twelve and iron deficiency were looked at while I stayed in the United States.', 1087847763957, 50);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116236, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Is that correct, Doctor X?', 1087847855722, 51);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116237, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'That is. I think these details were from somewhere else.', 1087847828364, 52);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116238, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'At least we are aware of it. What medication was provided during her first visit?', 1087847735271, 53);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116239, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'It looks like she was placed on forty milligrams of prednisone. The strength was reduced over time.', 1087847739947, 54);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116240, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'This may be a reason to her acne. Was she taken off this medication?', 1087847974093, 55);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116241, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Yes, she was. There were too many adverse effects.', 1087847879357, 56);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116242, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'What was she places on after?', 1087847747785, 57);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116243, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'It looks like she started a point six m g colchicine, which she took daily.', 1087847887731, 58);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116244, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'How were her inflammatory markers after taking it?', 1087847922347, 59);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116245, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Her markers were under control and positive. She also didn''t have any evidence of erythema nodosum.', 1087847971358, 60);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116246, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'That is great. How did you like that medication, ma''am?', 1087848018370, 61);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116247, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'My ankle would swell up and hurt. There were also some sensitive rashes on the skin of my legs.', 1087847807515, 62);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116248, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'I see. Is that stated on the report, Doctor X?', 1087847728888, 63);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116249, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'It is. I also see that she was reevaluated by Dermatology.', 1087848035064, 64);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116250, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Did they find anything apparent?', 1087848008611, 65);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116251, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'No, they didn''t. They didn''t find any evidence of erythema nodosum.', 1087847794966, 66);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116252, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'What was the plan following that?', 1087847735666, 67);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116253, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'It looks like we proceeded with a D E X A scan and checked her vitamin D levels.', 1087847908776, 68);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116254, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Was there any medication prescribed?', 1087847989081, 69);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116255, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'We ordered vitamin D and calcium to be bought over the counter so that her bones were protected. However, they use of them was stopped until we figured out the underlying cause of her disease.', 1087847802100, 70);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116256, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'I see. Other than the fracture and jaw surgery, was there anything else?', 1087847770351, 71);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116257, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'It shows she had Varicella and Mononucleosis, correct ma''am?', 1087848055564, 72);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116258, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Yeah, that''s correct.', 1087847929392, 73);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116259, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'That''s good. Our recent physical exam with you from last August showed changes in your venous stasis and diffuse periarticular ankle edema. Fortunately, we did not find any erythema nodosum, but the livedo patter was still present.', 1087848043728, 74);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116260, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'I see. Did you find anything else?', 1087847817581, 75);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116261, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'We did find a heart murmur, so we will conduct an echocardiogram. Doctor X, could you confirm all the details form the workup, please?', 1087847946969, 76);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116262, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Of course. Her A C E levels were normal. Her sed rate was around 30, which was high. Before that, it was around one ten, which is even higher. Her R V V T was normal. The rheumatoid factor was negative. The urinalysis was also normal. She had a C R P level of two point three, which was high. Her C C P came out negative. Her C B C displayed microcytosis and hypochromia with hematocrit levels of thirty seven point seven. Her hematocrit levels improved to forty point three later on, and she did not have any hypochromia, microcytosis, or anemia present.', 1087848062167, 77);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116263, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Thank you for all that information. Does all this information and history seem to be correct, ma''am?', 1087848037152, 78);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116264, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Yes. Thank you for going over that in front of me.', 1087848045760, 79);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116265, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'No problem. I see you''re here today regarding some mild but intense skin rashes. You mentioned that you thought it was erythema nodosum, correct?', 1087847789921, 80);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116266, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Yeah, that''s correct. I think it''s on my ankles. I also feel some joint stiffness.', 1087847986676, 81);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116267, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'I will take note of that. You also mentioned something about a rash before. Did you have a rash that was sensitive to U V light, like sunlight?', 1087847875198, 82);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116268, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'That''s right. I had it twice when I was in Europe.', 1087847783547, 83);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116269, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'When did you notice the rashes?', 1087848011335, 84);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116270, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'I was skiing, and my face started to swell up.', 1087847848531, 85);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116271, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'I see. Do you think it had to do anything with your acne?', 1087848019408, 86);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116272, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'No. My acne was stable after I stopped taking that one medicine and started the other.', 1087847821475, 87);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116273, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'The prednisone and colchicine we mentioned earlier, correct?', 1087847897899, 88);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116274, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'That''s correct.', 1087847955142, 89);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116275, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Is there anything else you would like to ask?', 1087847843465, 90);
