INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116277, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'I''ll discus that with you right now.', 1087847806203, 92);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116278, 'user1', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Actually, could you provide me with a pamphlet? I need to go study for my psychology classes. I have a big test tomorrow.', 1087848140053, 93);
