INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116280, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'Thank you. Doctor X, could you go over the diagnosis of erythema nodosum?', 1087847660776, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116281, 'user2', '06cec018-e0f1-4e42-8e4d-b1031c19ff5a', 'She was diagnosed in two thousand and four after a biopsy was done that confirmed erythema nodosum, but the detail from the Netherlands is not that specific.', 1087847664197, 3);
