INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116286, 'user3', 'e30cba61-1d4e-476e-8422-2710955fa2de', 'Mister Sunil, your blood pressure is high, and I am noticing this from past two-three times you have been here. It''s been constantly high, you are not taking it seriously.', 1429903377619, 0);
