INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116292, 'user2', '5bf9bb1b-5cfd-470f-8104-0e25095d0689', 'I am sorry. Do you have any family history of any neurological disorders like, M S, Alzheimer''s, Parkinson''s or epilepsy?', 1199168953230, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116293, 'user2', '5bf9bb1b-5cfd-470f-8104-0e25095d0689', 'Did your dad pass from colon cancer?', 1199168952535, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116294, 'user1', '5bf9bb1b-5cfd-470f-8104-0e25095d0689', 'No. They caught it early. He passed away from old age. My mom passed away when she was in her nineties from a stroke.', 1199168952804, 3);
