INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116297, 'user2', 'c5c967ea-f8a6-49f8-8f96-f4f995da41bc', 'Hello. I see you''re here for a follow up. Did you get your blood work done?', 963024185943, 0);
