INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116419, 'user2', 'b9437545-8e39-40f6-af19-3c53fb7d2526', 'What is the strength of your Omeprazole?', 1612736209941, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116420, 'user1', 'b9437545-8e39-40f6-af19-3c53fb7d2526', 'It is forty M G and I take it just once a day.', 1612736211082, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116421, 'user2', 'b9437545-8e39-40f6-af19-3c53fb7d2526', 'Any herbal medication?', 1612736213667, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116422, 'user1', 'b9437545-8e39-40f6-af19-3c53fb7d2526', 'No I do not take anything like that.', 1612736224540, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116423, 'user2', '46e7cb33-3f5b-4e54-8de4-8daad8cc6a66', 'So, to double check, you have a history of hay fever and asthma, correct?', 1278047924606, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116424, 'user1', '46e7cb33-3f5b-4e54-8de4-8daad8cc6a66', 'Yes. I was also recently diagnosed with cervical dysplasia. I found out shortly after my last O B G Y N visit.', 1278047930494, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116425, 'user2', '46e7cb33-3f5b-4e54-8de4-8daad8cc6a66', 'And are you planning to follow up with your O B G Y N in the upcoming months?', 1278047928732, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116426, 'user1', '46e7cb33-3f5b-4e54-8de4-8daad8cc6a66', 'Yeah, the next visit is scheduled and everything.', 1278047938425, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116427, 'user3', '5458b511-0d92-4372-8769-b55efb683aee', 'So, do you have any family history of arthritis?', 1388786475617, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116428, 'user1', '5458b511-0d92-4372-8769-b55efb683aee', 'Fortunately, no, not that I know of.', 1388786481587, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116429, 'user3', '5458b511-0d92-4372-8769-b55efb683aee', 'So, as far as you know, no one has had a joint replacement?', 1388786479966, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116430, 'user1', '5458b511-0d92-4372-8769-b55efb683aee', 'No, it doesn''t ring any bells.', 1388786492627, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116431, 'user2', '122e7795-37f5-4838-a5d4-6af777d24439', 'Please, tell me about your medical history.', 1031991762580, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116432, 'user1', '122e7795-37f5-4838-a5d4-6af777d24439', 'I''ve been dealing with depression and anxiety for some time now.', 1031991765764, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116433, 'user1', '122e7795-37f5-4838-a5d4-6af777d24439', 'Oh yes, I have arthritis as well. I also had sciatic pain a long time ago, and a herniated disk.', 1031991772315, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116434, 'user2', '122e7795-37f5-4838-a5d4-6af777d24439', 'Have you ever had neurological symptoms, like headaches, blurry vision, or weakness?', 1031991772908, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116435, 'user1', '122e7795-37f5-4838-a5d4-6af777d24439', 'Actually yes, I have migraines when I''m having my period.', 1031991787024, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116436, 'user2', '122e7795-37f5-4838-a5d4-6af777d24439', 'Thank you, and have you had any surgery in the past?', 1031991772198, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116437, 'user1', '122e7795-37f5-4838-a5d4-6af777d24439', 'Yes, I had my appendix out.', 1031991814116, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116438, 'user1', '122e7795-37f5-4838-a5d4-6af777d24439', 'Thank you, it is, but I manage.', 1031991776927, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116439, 'user2', '122e7795-37f5-4838-a5d4-6af777d24439', 'What about your joints? How do you move?', 1031991783620, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116440, 'user2', '122e7795-37f5-4838-a5d4-6af777d24439', 'I''m sorry, that must be difficult.', 1031991766140, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116441, 'user2', '1bccf577-750f-4db7-8ad0-eada54d57b04', 'Do you have any past history of psychiatric treatment of struggles?', 1011710800296, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116442, 'user1', '1bccf577-750f-4db7-8ad0-eada54d57b04', 'I had some extreme fatigue back in nineteen ninety one. I was in therapy for six years. They had me on Prozac. I took in for that whole six years while I was in therapy. When I started the Prozac, I had just started working again. The stress at work was overwhelming.', 1011710803507, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116443, 'user1', '1bccf577-750f-4db7-8ad0-eada54d57b04', 'I get somewhat sad from time to time but I don''t dwell on things anymore.', 1011710828925, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116444, 'user2', '1bccf577-750f-4db7-8ad0-eada54d57b04', 'Do you ever have thoughts of selfharm or suicidal thoughts?', 1011710822644, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116445, 'user1', '1bccf577-750f-4db7-8ad0-eada54d57b04', 'No.', 1011710837792, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116446, 'user2', '1bccf577-750f-4db7-8ad0-eada54d57b04', 'Was this the first time that you had feelings for fatigue and depression?', 1011710811469, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116447, 'user1', '1bccf577-750f-4db7-8ad0-eada54d57b04', 'No. I have always had a little sadness or depressed time in my life but it had been manageable before all the work stress started happening.', 1011710810425, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116448, 'user2', '1bccf577-750f-4db7-8ad0-eada54d57b04', 'How are you feeling these days?', 1011710818270, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116449, 'user2', '929d1a22-cd4c-4d09-b541-7ce08c4fef81', 'How many other children do you have?', 1162268880318, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116450, 'user1', '929d1a22-cd4c-4d09-b541-7ce08c4fef81', 'My husband and I have three children, your patient today, and another boy, and girl.', 1162268885466, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116451, 'user2', '929d1a22-cd4c-4d09-b541-7ce08c4fef81', 'How is everyone else doing?', 1162268890159, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116452, 'user2', '929d1a22-cd4c-4d09-b541-7ce08c4fef81', 'Good, do you have any pets?', 1162268901525, 6);
