INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116454, 'user2', '929d1a22-cd4c-4d09-b541-7ce08c4fef81', 'What, no deer?', 1162268903227, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116455, 'user1', '929d1a22-cd4c-4d09-b541-7ce08c4fef81', 'No, no deer, at least not anymore.', 1162268930015, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116456, 'user2', '929d1a22-cd4c-4d09-b541-7ce08c4fef81', 'What grade are you in, young man?', 1162268904110, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116457, 'user2', '929d1a22-cd4c-4d09-b541-7ce08c4fef81', 'Do you live here in Easton?', 1162268895390, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116458, 'user2', '929d1a22-cd4c-4d09-b541-7ce08c4fef81', 'Good, how do you like P E? Are you able to play no problem?', 1162268931379, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116459, 'user1', '929d1a22-cd4c-4d09-b541-7ce08c4fef81', 'Yes, I love P E. I don''t have any problems there.', 1162268931768, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116460, 'user1', '929d1a22-cd4c-4d09-b541-7ce08c4fef81', 'They''re all doing very well, thank you for asking.', 1162268893768, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116461, 'user1', '929d1a22-cd4c-4d09-b541-7ce08c4fef81', 'I''m in the second grade, doctor.', 1162268934780, 11);
