INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116463, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'So let''s start from the beginning.', 1562407618068, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116464, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Okay.', 1562407621999, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116465, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'You''re seventy nine years old, correct?', 1562407629936, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116466, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Do you remember when you had your first fall?', 1562407639119, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116467, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Hm about a year and a half ago I fell while trying to walk from my bed to the living room.', 1562407659734, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116468, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Did you feel lightheaded prior?', 1562407652694, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116469, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Uh yeah I did have some lightheadedness and I was a bit confused. I was aware of my surroundings though. My legs just gave out and the next thing I knew I was on the floor.', 1562407629806, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116470, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'I see. Did you lose consciousness?', 1562407660303, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116471, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'No, thank goodness.', 1562407653704, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116472, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'He got up by himself and felt fine afterwards. The strangest thing.', 1562407649026, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116473, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Yeah. I was good until my legs gave out on me July third of O eight.', 1562407691125, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116474, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Did you experience the same lightheadedness as before?', 1562407659860, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116475, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Not this time.', 1562407659435, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116476, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'We had to rush him to the hospital after that.', 1562407648692, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116477, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'I was later diagnosed with pneumonia. The fall was blamed on the pneumonia.', 1562407689051, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116478, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Got it.', 1562407715505, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116479, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'To be on the safe side, I started using a walker from then on.', 1562407703143, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116480, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Did you need any type of walking assistance prior to your falls?', 1562407695727, 20);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116481, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Nope. I used to walk about two miles a day before all of this stuff started happening to me. This isn''t even the end of it. My legs gave out on me again August O eight. No lightheadedness beforehand, but they did find that I had pneumonia again.', 1562407688999, 21);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116482, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'They admitted him to the hospital and later sent him for rehab.', 1562407694773, 22);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116483, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Did rehab help?', 1562407650053, 23);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116484, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Yeah. I was able to use my walker after that.', 1562407712620, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116485, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Did you return to your previous health?', 1562407651877, 25);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116486, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Uh not really, no. I had another fall in October O eight.', 1562407690603, 26);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116487, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Did they diagnose you with pneumonia again?', 1562407716389, 27);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116488, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Yeah. I also had shingles.', 1562407653388, 28);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116489, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Are you currently living at home?', 1562407738733, 29);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116490, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'I''m living in a Chronic Rehab Unit. I can''t use my walker anymore. I''m confined to a wheelchair.', 1562407725484, 30);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116491, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'I''m sorry to hear that.', 1562407760860, 31);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116492, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'On top of that, I''ve noticed that my hands have been numb for the past three weeks.', 1562407695859, 32);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116493, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Is it all of your fingers or only some?', 1562407711681, 33);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116494, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'All.', 1562407710362, 34);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116495, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Are you noticing any other symptoms along with the numbness in your fingers?', 1562407697296, 35);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116496, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Yes. I feel like I''ve lost quite a bit of muscle in my hands. They''re also much weaker than before. My strength hasn''t been the same since July O eight. It''s definitely getting worse.', 1562407788995, 36);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116497, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'I see.', 1562407757864, 37);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116498, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'I''ve had muscle twitching in my legs since August O eight.', 1562407784512, 38);
