INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116504, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'No.', 1562407828695, 44);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116505, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Any constipation or diarrhea?', 1562407722440, 45);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116506, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'Both actually. It tends to alternate.', 1562407876030, 46);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116507, 'user2', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'But no loss of bowel or bladder control?', 1562407769459, 47);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116508, 'user1', 'e5219999-8ad2-4471-b374-0024f3b952f7', 'No. I''ve noticed that my blood pressure has been out of whack. I also feel like I''m about to faint anytime I stand.', 1562407823573, 48);
