INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116559, 'user3', '19c6f25d-46d7-450b-8e5b-1dadb776ded9', 'Hello, how are you doing? What brings you here?', 1302702999176, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116560, 'user1', '19c6f25d-46d7-450b-8e5b-1dadb776ded9', 'I think I have allergies. I used to live in Seattle. I had allergies there, but I think they''re getting worse after moving here. You see, I''m twenty three and I am a white female. I was in Seattle, I thought that the weather there is not for me. That''s why I plan to move on here, but my allergies are not leaving me here either.', 1302703004125, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116561, 'user1', '19c6f25d-46d7-450b-8e5b-1dadb776ded9', 'They seemed to be working for some time, but now I feel like nothing is effective anymore.', 1302703015069, 5);
