INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116601, 'user3', '9bfd4839-c2f8-4ae1-8b31-447052b23039', 'Hello, Mister G, how are you today?', 1418233222511, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116602, 'user1', '9bfd4839-c2f8-4ae1-8b31-447052b23039', 'I am good doctor thank you for asking. I am here to talk to you about my will.', 1418233224505, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116603, 'user1', '9bfd4839-c2f8-4ae1-8b31-447052b23039', 'Honestly doctor you have done enough and I am so thankful for that. I just wish to spend my last days at home surrounded with loved ones. I have my nurse, she takes care of me. I think I am fine!', 1418233234069, 5);
