INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116655, 'user2', '3c1bdf59-0469-4335-813a-0b484626189c', 'Okay I am looking at you for multiple issues today. One of the biggest being swelling on your left leg. Can you tell me more about that?', 1444470237963, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116656, 'user1', '3c1bdf59-0469-4335-813a-0b484626189c', 'Yes sure. I got this swelling for almost three years now, and it has been worse for the past two to three months. Sometimes it gets better in the morning when I get up, but then throughout the day it begins to swell again.  Lately it is staying bigger, and it feel uncomfortable with it being so large.  The right leg also swells, but not nearly like the left leg.', 1444470242047, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116657, 'user1', '3c1bdf59-0469-4335-813a-0b484626189c', 'No, I don''t remember hurting shoulder, but gradually I am losing some mobility.  It is hard for me to get my hands behind my back or behind my head.  I am losing strength in the left shoulder gradually for the last year.', 1444470261837, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116658, 'user2', '3c1bdf59-0469-4335-813a-0b484626189c', 'Ok let''s look at your labs.', 1444470264664, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116659, 'user1', '3c1bdf59-0469-4335-813a-0b484626189c', 'So far white counts are high. In April two thousand five Doctor X Y Z was asked to look at my high white count, but she thought it wasn''t a problem and asked me to come for follow up.', 1444470249995, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116660, 'user2', '3c1bdf59-0469-4335-813a-0b484626189c', 'Any other complaints?', 1444470269677, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116661, 'user1', '3c1bdf59-0469-4335-813a-0b484626189c', 'I have a lot of frequency with urination, and I get up to pee at night at least two to three times.   Also, I have gained weight, I think about twelve pounds since March.  Right now, I am two eighty four pounds.', 1444470265995, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116662, 'user2', '3c1bdf59-0469-4335-813a-0b484626189c', 'Okay. So, I can see that your blood pressure is staying stable.  You do take Atenolol twelve point five M G per day and Lasix as needed.', 1444470292320, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116663, 'user1', '3c1bdf59-0469-4335-813a-0b484626189c', 'Yes, that''s correct. It makes me pee so much. I do not take it.', 1444470284070, 11);
