INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116689, 'user1', 'cb2ff278-e3fc-4dfe-8008-5c77d63756b7', 'My father is alive. He is sixty nine right now. He did have some strokes in the past. My mom on the other hand died at the age of sixty two of many kinds of heart diseases.', 1135207586027, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116690, 'user2', 'cb2ff278-e3fc-4dfe-8008-5c77d63756b7', 'What about your grandparents?', 1135207593066, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116691, 'user1', 'cb2ff278-e3fc-4dfe-8008-5c77d63756b7', 'My maternal grandfather he also had heart issues and he died of a heart attack. Both he and my maternal grandma had some heart diseases. Their heart use to beat pretty fast.', 1135207592235, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116692, 'user2', 'c4d25b25-f30a-4dc8-a249-0086e27faa74', 'Hi there! What brings you back to see me so soon?', 1498059868229, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116693, 'user2', 'c4d25b25-f30a-4dc8-a249-0086e27faa74', 'We have been currently treating your rheumatoid arthritis with methotrexate. How much have you been taking?', 1498059887865, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116694, 'user1', 'c4d25b25-f30a-4dc8-a249-0086e27faa74', 'Yes, we have tried lots of different treatments and methotrexate has been working well.  I have been on it for ten years now. I have been taking about twenty or twenty five M G of per week.', 1498059878907, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116695, 'user2', 'c4d25b25-f30a-4dc8-a249-0086e27faa74', 'Did we recently increase your dosage? I see in your chart that we have changed your dosage a few times.', 1498059886171, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116696, 'user1', 'c4d25b25-f30a-4dc8-a249-0086e27faa74', 'About a year ago we lowered the dosage for twenty five M G to twenty but my arthritis flared up so we went to twenty two point five.', 1498059898913, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116697, 'user2', 'c4d25b25-f30a-4dc8-a249-0086e27faa74', 'Have you ever had any side effects from the methotrexate in the past?', 1498059898006, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116698, 'user1', 'c4d25b25-f30a-4dc8-a249-0086e27faa74', 'No. I don''t think so.', 1498059899962, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116699, 'user2', 'c4d25b25-f30a-4dc8-a249-0086e27faa74', 'Are you taking any other medications?', 1498059889286, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116700, 'user1', 'c4d25b25-f30a-4dc8-a249-0086e27faa74', 'I had a sinus infection and the doctor put me on an antibiotic. That was about two weeks ago.', 1498059879821, 11);
