INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116713, 'user2', 'c4d25b25-f30a-4dc8-a249-0086e27faa74', 'Sorry to side track, but where is your accent from? My family is Cuban and my mom and you speak the same.', 1498059916675, 24);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116714, 'user1', 'c4d25b25-f30a-4dc8-a249-0086e27faa74', 'What a surprise! I am Cuban. A proud fifty seven year old Cuban.', 1498059976080, 25);
