INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116718, 'user2', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'Hello, miss. How are you feeling today?', 1410288029487, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116719, 'user1', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'Terrible. My allergies are killing me right now.', 1410288033416, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116720, 'user2', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'Do you have a history of allergies?', 1410288034664, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116721, 'user2', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'That sounds exciting. Back to your allergies now. Do you take any medication to relieve your symptoms?', 1410288035966, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116722, 'user1', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'Here''s a list of past and current medications I''m taking.', 1410288060656, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116723, 'user2', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'Thank you. Let me take a look. I see you took Claritin and Zyrtec in the past, correct? Did those help you?', 1410288047717, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116724, 'user1', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'Yeah, that''s correct. They were working for a bit, but then they stopped working after a while.', 1410288061637, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116725, 'user2', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'I see. Your notes say you took Allegra after, correct?', 1410288057509, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116726, 'user1', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'Correct. I tried out Allegra last summer, but I don''t know if it was doing its job. I tried it again two weeks ago because my allergies were getting bad, but it still didn''t work.', 1410288073371, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116727, 'user2', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'I see. Your notes state you''ve tried some nasal sprays, correct?', 1410288047285, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116728, 'user1', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'Yeah, I did. I wanted to see if they would work.', 1410288069003, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116729, 'user2', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'Were you prescribed these nasal sprays?', 1410288107792, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116730, 'user1', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'Nope. I bought them at my local pharmacy.', 1410288095257, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116731, 'user2', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'Sounds good. I''m looking at your medical history, and it sates here you have asthma too, correct?', 1410288105527, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116732, 'user1', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'Yeah, I''ve had it for a long time, but it hasn''t gotten worse.', 1410288068847, 17);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116733, 'user2', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'I see. Do you think you need any medication to help alleviated your asthma?', 1410288057104, 18);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116734, 'user1', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'No. It doesn''t bother me as much as my allergies.', 1410288118343, 19);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116735, 'user1', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'I wanted to experience different cities since I''m only twenty three.', 1410288040928, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116736, 'user1', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'Yeah, I do. I had them all the time when I lived in Seattle, but they got a lot worse when I moved here. I am a strong German woman and I hate how something as little as allergies gets the best of me.', 1410288043407, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116737, 'user2', '1ebde86e-3d52-421f-9c4b-3dfbd4452285', 'Why did you move here?', 1410288053461, 4);
