INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116903, 'user2', 'd62e387a-fe2e-4d40-8f25-2059de756066', 'How did she do following the second surgery?', 1413865891587, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116904, 'user1', 'd62e387a-fe2e-4d40-8f25-2059de756066', 'Sure, well she''s fourteen now, um, she''s right handed, and she just started high school.', 1413865878706, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116905, 'user2', 'd62e387a-fe2e-4d40-8f25-2059de756066', 'So, what brings you in for a visit today?', 1413865906431, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116906, 'user1', 'd62e387a-fe2e-4d40-8f25-2059de756066', 'Well, I''ve been having some leg pain on the side of my legs.', 1413865911533, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116907, 'user2', 'd62e387a-fe2e-4d40-8f25-2059de756066', 'How long have you had this pain?', 1413865931515, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116908, 'user1', 'd62e387a-fe2e-4d40-8f25-2059de756066', 'It''s been several months at this point.', 1413865937667, 11);
