INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116910, 'user1', 'd62e387a-fe2e-4d40-8f25-2059de756066', 'Um, it''s the worst at night, I have to take medicine for the pain.', 1413865900631, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116911, 'user1', 'd62e387a-fe2e-4d40-8f25-2059de756066', 'Yeah, she had an, um, lipomyomeningocele repair when she was about three days old, and then again when she was three and a half years old.', 1413865889180, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116912, 'user1', 'd62e387a-fe2e-4d40-8f25-2059de756066', 'She takes Advil, Motrin, and Tylenol P M.', 1413865924970, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116913, 'user2', 'd62e387a-fe2e-4d40-8f25-2059de756066', 'Wow, that''s a lot. Looks like you have some patch sensory loss in the L four to S one region. Are you going to the bathroom regularly?', 1413865892734, 16);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116914, 'user1', 'd62e387a-fe2e-4d40-8f25-2059de756066', 'Yeah, there''s no problems there. I do have some loss of feeling in my big toe and calf though.', 1413865917893, 17);
