INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116921, 'user2', '2e988945-80b9-4c4c-a1f7-99664a90bc4b', 'Good morning, ma''am. Can you confirm your age for me, please?', 1663580699559, 0);
