INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116924, 'user2', '2e988945-80b9-4c4c-a1f7-99664a90bc4b', 'Absolutely, do you have the results of your pelvic C T?', 1663580708671, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116925, 'user2', '2e988945-80b9-4c4c-a1f7-99664a90bc4b', 'Um, we did a left upper lobectomy for your stage I A non small cell lung cancer.', 1663580715227, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116926, 'user2', '2e988945-80b9-4c4c-a1f7-99664a90bc4b', 'Thank you, so this shows an enlarging simple cyst of the left kidney.', 1663580724240, 8);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116927, 'user1', '2e988945-80b9-4c4c-a1f7-99664a90bc4b', 'What can we do about this?', 1663580713461, 9);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116928, 'user2', '2e988945-80b9-4c4c-a1f7-99664a90bc4b', 'Well, that''s why we did the barium swallow, which showed a small hiatal hernia with minimal reflux.', 1663580716250, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116929, 'user1', '2e988945-80b9-4c4c-a1f7-99664a90bc4b', 'Oh, yeah, I remember that.', 1663580764625, 11);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116930, 'user2', '2e988945-80b9-4c4c-a1f7-99664a90bc4b', 'So, I have your x rays from November twenty third two thousand nine here, we did an A P and lateral view, and they''re normal.', 1663580771413, 12);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116931, 'user1', '2e988945-80b9-4c4c-a1f7-99664a90bc4b', 'Oh, well that''s good too.', 1663580739247, 13);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116932, 'user2', '2e988945-80b9-4c4c-a1f7-99664a90bc4b', 'Are you having any pain with swallowing food?', 1663580731844, 14);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116933, 'user1', '2e988945-80b9-4c4c-a1f7-99664a90bc4b', 'Yes, I get some chest pain, but I''d say it''s pretty mild. Look at my calf, doctor, it''s much bigger than the right one.', 1663580733430, 15);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116934, 'user2', '2e988945-80b9-4c4c-a1f7-99664a90bc4b', 'Chest pain is probably due to tertiary contractions with some delayed emptying. Is it tender?', 1663580753629, 16);
