INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116954, 'user1', 'd713f688-a97e-44e0-8ccd-efcc69d7634f', 'Hm, well both my father and my brother had colon cancer. My daughter was detected with breast cancer.', 1450323877155, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116955, 'user2', 'd713f688-a97e-44e0-8ccd-efcc69d7634f', 'Do you remember what her age was?', 1450323876251, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116956, 'user1', 'd713f688-a97e-44e0-8ccd-efcc69d7634f', 'Yeah, she was forty.', 1450323887507, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116957, 'user2', 'd713f688-a97e-44e0-8ccd-efcc69d7634f', 'I see. Anything else?', 1450323879672, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116958, 'user1', 'd713f688-a97e-44e0-8ccd-efcc69d7634f', 'Well, I have a heart condition and high blood pressure. I also had a stroke.', 1450323878176, 5);
