INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116977, 'user2', '2fe02a1c-9f25-44e5-b876-ca745b54fb9d', 'How are you doing miss? How are your sugar numbers coming along?', 1546287759371, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116978, 'user1', '2fe02a1c-9f25-44e5-b876-ca745b54fb9d', 'I''m doing good. Thank you. Sugar has consistently been one hundred and thirty five or under it.', 1546287764658, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116979, 'user1', '2fe02a1c-9f25-44e5-b876-ca745b54fb9d', 'No, I''m fasting for my test.', 1546287765003, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (116980, 'user2', '2fe02a1c-9f25-44e5-b876-ca745b54fb9d', 'Okay, let''s see. We have an Accu Chek here in our office. I will do a quick sugar test for you, and this will be a fasting sugar test. It will be just a quick prick on your finger.', 1546287774102, 6);
