INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117007, 'user3', 'dac4334b-c52d-4b89-bc0f-48ee47baafd2', 'Have you ever had an allergic reaction to drugs you''ve taken in the past?', 1226254988574, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117008, 'user1', 'dac4334b-c52d-4b89-bc0f-48ee47baafd2', 'More than once. I''ve reacted poorly to sulfa drugs, penicillin, and some mycins. I also think I''m allergic to contrast medium.', 1226254989794, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117009, 'user2', 'd2f7ce37-cd51-4c17-8ac5-d3efb244f539', 'Hey, do you smoke cigarettes?', 981446987688, 0);
