INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117018, 'user3', '654d93eb-5ab9-4863-8d8a-b5c7cde2765d', 'Nice. How did you enjoy the work?', 1439902360196, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117019, 'user1', '654d93eb-5ab9-4863-8d8a-b5c7cde2765d', 'I liked it a lot, but there came a time where I knew it was the end of the road for me. I''m really enjoying retirement.', 1439902366300, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117020, 'user3', '654d93eb-5ab9-4863-8d8a-b5c7cde2765d', 'I bet. I have cousin who owns a car repair shop. He''s almost always busy.', 1439902379449, 6);
