INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117022, 'user3', '654d93eb-5ab9-4863-8d8a-b5c7cde2765d', 'Any smoking, drinking, or hard drugs?', 1439902373103, 8);
