INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117027, 'user3', '654d93eb-5ab9-4863-8d8a-b5c7cde2765d', 'Great to hear.', 1439902403708, 10);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117028, 'user3', '21afc3f4-18b5-4c1b-bb83-17587d161175', 'Do you have his full medical history?', 1603277690423, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117029, 'user3', '21afc3f4-18b5-4c1b-bb83-17587d161175', 'I think I got it all down.', 1603277699756, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117030, 'user3', '21afc3f4-18b5-4c1b-bb83-17587d161175', 'Any additional surgeries?', 1603277700817, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117031, 'user3', '21afc3f4-18b5-4c1b-bb83-17587d161175', 'Yes. He had lumbar surgery twice before. He suffered from lumbar stenosis many years ago in the sixties and seventies. He''s actually due for another lumbar surgery with Doctor Y. He takes Percocet daily for his back pain.  He also has a history of hypertension and hyperlipidemia.', 1603277697507, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117032, 'user3', '21afc3f4-18b5-4c1b-bb83-17587d161175', 'Yes, I confirmed with his wife. He had a CABG done in ninety one. He has a history of radical prostate cancer for which he underwent a radical prostatectomy and nephrectomy.', 1603277692076, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117033, 'user2', '363a1983-f4d2-4ba8-a1f1-0b21c59c804a', 'Do you have any history of major surgeries?', 957433977033, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117034, 'user1', '363a1983-f4d2-4ba8-a1f1-0b21c59c804a', 'No. Nothing major.', 957433978318, 1);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117035, 'user2', 'e801aa58-220e-424d-9d6a-fe4dfb2d0da8', 'Good morning, sir.', 1578879125542, 0);
