INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117037, 'user1', 'e801aa58-220e-424d-9d6a-fe4dfb2d0da8', 'Yes, I had a vasectomy some time ago.', 1578879130322, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117038, 'user2', 'e801aa58-220e-424d-9d6a-fe4dfb2d0da8', 'Before we begin, have you ever had surgery?', 1578879133063, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117039, 'user2', 'f38113d1-65f7-4ca1-88f4-809abc12f846', 'Okay, so let''s go over your medications. I''d like you to take these to help your muscle spasms.', 1593726458680, 0);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117040, 'user2', 'f38113d1-65f7-4ca1-88f4-809abc12f846', 'Tylenol number three is combined with Codeine.', 1593726462833, 4);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117041, 'user1', 'f38113d1-65f7-4ca1-88f4-809abc12f846', 'Okay, I see.', 1593726485121, 5);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117042, 'user2', 'f38113d1-65f7-4ca1-88f4-809abc12f846', 'And finally, I''m prescribing Methocarbamol seven fifty milligrams which needs to be taken four times a day for maximum relief. Do you have any questions for me?', 1593726485438, 6);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117043, 'user1', 'f38113d1-65f7-4ca1-88f4-809abc12f846', 'No, I think you answered them all.', 1593726468523, 7);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117044, 'user2', 'f38113d1-65f7-4ca1-88f4-809abc12f846', 'I''ve prescribed eight hundred milligrams of Ibuprofen to be taken every eight hours as needed along with Tylenol number three every six hours as needed.', 1593726467975, 2);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117045, 'user1', 'f38113d1-65f7-4ca1-88f4-809abc12f846', 'What does the number three stand for?', 1593726469045, 3);
INSERT INTO messages (id, "userId", "threadId", message, timestamp, "msgIndex") VALUES (117046, 'user1', 'f38113d1-65f7-4ca1-88f4-809abc12f846', 'Sounds good.', 1593726461411, 1);
